<style>
body { background: var(--surface-2); color: var(--text-main); }
.kw-page-summary { font-size:12px; color:var(--text-sub); line-height:1.7; margin-top:4px; }
.kw-admin-footer { padding:16px 20px; border-top:1px solid rgba(200,169,110,0.1); }
.kw-admin-footer-title { font-size:11px; color:var(--text-sub); }
.kw-admin-footer-text { font-size:13px; color:var(--text-main); margin-top:2px; }
.kw-section-grid { display:grid; grid-template-columns:1.15fr 0.85fr; gap:20px; }
.kw-section-stack { display:grid; gap:20px; align-content:start; }
.kw-card {
 background:#FFFFFF;
 border:1px solid rgba(47,116,192,0.10);
 border-radius:16px;
 padding:18px;
 box-shadow:0 8px 24px rgba(31,73,125,0.06);
}
.kw-north-star {
 margin-bottom:20px;
 padding:20px 22px;
 border:1px solid rgba(47,116,192,.16);
 border-radius:16px;
 background:linear-gradient(135deg,#edf6ff,#fffaf0);
}
.kw-north-star-kicker { color:#2f74c0; font-size:11px; font-weight:750; letter-spacing:.08em; text-transform:uppercase; }
.kw-north-star-title { margin-top:6px; color:#163b64; font-size:22px; font-weight:750; line-height:1.35; }
.kw-north-star-copy { max-width:760px; margin-top:6px; color:#52677d; font-size:13px; line-height:1.75; }
.kw-north-star-flow { display:flex; gap:8px; flex-wrap:wrap; margin-top:14px; }
.kw-north-star-step { padding:7px 10px; border-radius:999px; background:#fff; border:1px solid rgba(47,116,192,.14); color:#1f497d; font-size:11px; }
.kw-biz-analysis-panel { display:none; }
.kw-biz-analysis-panel.active { display:block; }
.kw-biz-chart-empty {
 min-height:220px;
 height:100%;
 display:flex;
 align-items:center;
 justify-content:center;
 padding:16px;
 box-sizing:border-box;
 text-align:center;
 color:var(--text-sub);
 font-size:12px;
 line-height:1.7;
 border:1px dashed rgba(47,116,192,0.20);
 border-radius:10px;
 background:rgba(47,116,192,0.025);
}
.kw-card-head { display:flex; justify-content:space-between; align-items:flex-start; gap:12px; margin-bottom:14px; }
.kw-card-title { font-size:16px; font-weight:700; color:var(--text-main); }
.kw-card-desc { font-size:12px; color:var(--text-sub); line-height:1.7; margin-top:4px; }
.kw-tag {
 flex-shrink:0;
 font-size:10px;
 color:var(--gold);
 background:rgba(200,169,110,0.12);
 border:1px solid rgba(200,169,110,0.20);
 border-radius:999px;
 padding:4px 8px;
}
.kw-link-grid,
.kw-mini-grid,
.kw-watch-grid,
.kw-role-grid,
.kw-version-grid,
.kw-review-source-grid,
.kw-cell-grid,
.kw-knowledge-list,
.kw-skill-list,
.kw-fan-list,
.kw-broadcast-list { display:grid; gap:10px; }
.kw-link-grid,
.kw-mini-grid,
.kw-cell-grid,
.kw-review-source-grid { grid-template-columns:1fr 1fr; }
.kw-link-card,
.kw-mini-card,
.kw-watch-card,
.kw-role-card,
.kw-version-card,
.kw-review-source,
.kw-knowledge-item,
.kw-cell-card,
.kw-fan-item,
.kw-broadcast-item,
.kw-side-card {
 background:#F8FBFF;
 border:1px solid rgba(47,116,192,0.10);
 border-radius:14px;
 padding:14px;
}
.kw-link-card { text-decoration:none; }
.kw-link-title,
.kw-mini-title,
.kw-watch-title,
.kw-role-title,
.kw-version-title,
.kw-review-source-title,
.kw-cell-title,
.kw-fan-name,
.kw-broadcast-content,
.kw-knowledge-title { font-size:13px; font-weight:700; color:var(--text-main); }
.kw-link-desc,
.kw-mini-desc,
.kw-watch-desc,
.kw-version-desc,
.kw-review-source-desc,
.kw-cell-desc,
.kw-fan-msg,
.kw-broadcast-meta,
.kw-knowledge-summary,
.kw-side-item,
.kw-side-note { font-size:11px; color:var(--text-sub); line-height:1.7; }
.kw-link-url,
.kw-message-type,
.kw-watch-meta,
.kw-knowledge-meta,
.kw-skill-meta { font-size:11px; color:var(--text-sub); line-height:1.7; margin-top:6px; }
.kw-chip-row,
.kw-watch-chip-row,
.kw-prompt-row,
.kw-review-flow,
.kw-toolbar { display:flex; gap:8px; flex-wrap:wrap; }
.kw-chip,
.kw-watch-chip,
.kw-mode-chip,
.kw-prompt-chip,
.kw-review-flow-step {
 display:inline-flex;
 align-items:center;
 font-size:10px;
 border-radius:999px;
 padding:4px 8px;
}
.kw-chip,
.kw-review-flow-step {
 color:var(--gold);
 background:rgba(200,169,110,0.10);
 border:1px solid rgba(200,169,110,0.18);
}
.kw-sidebar-group {
 margin-top:8px;
 padding-top:8px;
 border-top:1px dashed rgba(200,169,110,0.10);
}
.kw-sidebar-group:first-child {
 margin-top:0;
 padding-top:0;
 border-top:none;
}
.kw-nav-subgroup {
 margin-top:8px;
 padding-top:8px;
 border-top:1px dashed rgba(200,169,110,0.10);
}
.kw-nav-subtitle {
 margin:0 0 8px 14px;
