 letter-spacing:0.08em;
 text-transform:uppercase;
 color:var(--text-sub);
}
.kw-watch-chip,
.kw-mode-chip,
.kw-prompt-chip {
 color:#1F497D;
 background:#EAF3FF;
}
.kw-watch-terminal { display:grid; gap:14px; }
.kw-watch-terminal-head { display:flex; justify-content:space-between; align-items:flex-end; gap:18px; padding:18px 20px; background:#F4F8FC; border:1px solid rgba(47,116,192,.14); border-radius:8px; }
.kw-watch-terminal-kicker { color:#2F74C0; font-size:11px; font-weight:700; }
.kw-watch-terminal-title { margin-top:6px; color:#163B64; font-size:20px; font-weight:700; }
.kw-watch-terminal-copy { max-width:700px; margin-top:6px; color:#5B6B7B; font-size:12px; line-height:1.7; }
.kw-watch-terminal-stat { min-width:120px; text-align:right; }
.kw-watch-terminal-stat-label { color:#6B7785; font-size:11px; }
.kw-watch-terminal-stat-value { margin-top:5px; color:#163B64; font-size:26px; font-weight:700; }
.kw-watch-table-wrap { overflow-x:auto; border:1px solid rgba(47,116,192,.13); border-radius:8px; background:#FFF; }
.kw-watch-table { width:100%; min-width:940px; border-collapse:collapse; }
.kw-watch-table th { padding:11px 12px; background:#F6F9FC; border-bottom:1px solid rgba(47,116,192,.13); color:#647486; font-size:11px; font-weight:600; text-align:left; white-space:nowrap; }
.kw-watch-table td { padding:13px 12px; border-bottom:1px solid rgba(47,116,192,.08); color:#33475B; font-size:12px; vertical-align:top; }
.kw-watch-table tr:last-child td { border-bottom:none; }
.kw-watch-table tr:hover td { background:#FAFCFE; }
.kw-watch-symbol { color:#163B64; font-size:14px; font-weight:700; }
.kw-watch-code { margin-top:3px; color:#7B8998; font-size:10px; }
.kw-watch-focus { color:#355C83; font-size:12px; font-weight:600; }
.kw-watch-thesis { max-width:330px; color:#5B6B7B; line-height:1.6; }
.kw-watch-alert { display:inline-flex; align-items:center; gap:5px; padding:4px 7px; border-radius:4px; font-size:11px; font-weight:600; white-space:nowrap; }
.kw-watch-alert.normal { background:#EDF8F1; color:#217A4A; }
.kw-watch-alert.attention { background:#FFF6E5; color:#A86C16; }
.kw-watch-alert.warning { background:#FDEEEE; color:#B94747; }
.kw-watch-change { font-weight:700; white-space:nowrap; }
.kw-watch-change.up { color:#C0392B; }
.kw-watch-change.down { color:#248F66; }
.kw-watchlist-tabs { display:flex; gap:6px; margin-top:14px; padding:4px; border:1px solid rgba(47,116,192,.12); border-radius:8px; background:#F4F8FC; }
.kw-watchlist-tab { flex:1; min-height:34px; border:0; border-radius:5px; background:transparent; color:#5B6B7B; font-size:12px; font-weight:700; cursor:pointer; }
.kw-watchlist-tab.active { background:#FFF; color:#163B64; box-shadow:0 1px 3px rgba(22,59,100,.10); }
.kw-watchlist-tab-panel { margin-top:14px; }
.kw-watchlist-fan-chart { margin-bottom:14px; padding:14px 16px; border:1px solid rgba(47,116,192,.13); border-radius:8px; background:#FFF; }
.kw-watchlist-fan-chart-title { color:#163B64; font-size:13px; font-weight:700; }
.kw-watchlist-fan-chart-copy { margin-top:4px; color:#6B7785; font-size:11px; line-height:1.6; }
.kw-watchlist-comments { display:grid; gap:10px; margin-top:14px; }
.kw-watchlist-comment { padding:11px 12px; border:1px solid rgba(47,116,192,.10); border-radius:6px; background:#F8FBFF; }
.kw-watchlist-comment-meta { color:#6B7785; font-size:11px; }
.kw-watchlist-comment-text { margin-top:5px; color:#33475B; font-size:12px; line-height:1.65; }
.kw-watchlist-comment-empty { padding:22px 0; color:#6B7785; font-size:12px; text-align:center; }
.kw-watch-signal-list { display:flex; flex-wrap:wrap; gap:6px; }
.kw-watch-signal { padding:4px 7px; border-radius:4px; background:#F1F6FB; border:1px solid rgba(47,116,192,.10); color:#355C83; font-size:11px; }
.kw-watch-insight-shell { display:grid; grid-template-columns:minmax(0,1.22fr) minmax(310px,.78fr); gap:14px; }
.kw-watch-insight-main, .kw-watch-insight-side { display:grid; gap:14px; align-content:start; }
.kw-watch-kpi-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); border:1px solid rgba(47,116,192,.13); border-radius:8px; overflow:hidden; background:#FFF; }
.kw-watch-kpi { padding:15px; border-right:1px solid rgba(47,116,192,.10); }
.kw-watch-kpi:last-child { border-right:none; }
.kw-watch-kpi-label { color:#718194; font-size:11px; }
.kw-watch-kpi-value { margin-top:8px; color:#163B64; font-size:24px; font-weight:700; }
.kw-watch-kpi-note { margin-top:4px; color:#6B7785; font-size:11px; }
.kw-watch-insight-panel { padding:15px; border:1px solid rgba(47,116,192,.13); border-radius:8px; background:#FFF; }
.kw-watch-insight-panel-title { color:#163B64; font-size:13px; font-weight:700; }
