.kw-watch-comment-row { padding:12px 0; border-bottom:1px solid rgba(47,116,192,.09); }
.kw-watch-comment-row:last-child { border-bottom:none; }
@media (max-width:900px) { .kw-watch-insight-shell { grid-template-columns:1fr; } .kw-watch-kpi-grid { grid-template-columns:repeat(2,minmax(0,1fr)); } .kw-watch-kpi:nth-child(2) { border-right:none; } .kw-watch-kpi:nth-child(n+3) { border-top:1px solid rgba(47,116,192,.10); } }
@media (max-width:620px) { .kw-watch-terminal-head { align-items:flex-start; flex-direction:column; } .kw-watch-terminal-stat { text-align:left; } }
.kw-side-title { font-size:13px; font-weight:700; color:var(--gold); margin-bottom:10px; }
.kw-side-item {
