 border-color:rgba(200,169,110,0.18);
}
.kw-kg-entry-card {
 display:flex;
 justify-content:space-between;
 gap:16px;
 align-items:center;
 padding:14px 16px;
 border-radius:16px;
 background:linear-gradient(135deg, rgba(20,54,92,0.18), rgba(10,28,47,0.08));
 border:1px solid rgba(47,116,192,0.14);
 margin-bottom:14px;
}
.kw-kg-entry-title { font-size:15px; font-weight:700; color:var(--text-main); }
.kw-kg-entry-desc { margin-top:6px; font-size:12px; color:var(--text-sub); line-height:1.8; max-width:720px; }
.kw-kg-shell { margin-top:4px; }
.kw-kg-toolbar { display:flex; flex-wrap:wrap; gap:10px; align-items:center; }
.kw-kg-search,
.kw-kg-select {
 border:none;
 outline:none;
