 font-size:13px;
 padding:10px 12px;
 box-sizing:border-box;
}
.kw-kg-search { flex:1; min-width:240px; }
.kw-kg-select { min-width:132px; }
.kw-kg-stage { margin-top:12px; font-size:11px; color:var(--gold); }
.kw-kg-stats {
 margin-top:12px;
 display:grid;
 grid-template-columns:repeat(6, minmax(0, 1fr));
 gap:8px;
}
.kw-kg-stat { padding:10px; border-radius:12px; background:#FFFFFF; border:1px solid rgba(47,116,192,0.10); }
.kw-kg-stat-label { font-size:10px; color:var(--text-sub); }
.kw-kg-stat-value { margin-top:6px; font-size:18px; font-weight:800; color:var(--text-main); }
.kw-kg-legend { margin-top:10px; display:flex; flex-wrap:wrap; gap:8px; }
.kw-kg-legend-chip {
 display:inline-flex;
 align-items:center;
