 height:8px;
 border-radius:50%;
 background:#8FA6C4;
 flex:0 0 auto;
}
.kw-kg-legend-dot.kind-root { background:#C8A96E; }
.kw-kg-legend-dot.kind-topic { background:#8FCCFF; }
.kw-kg-legend-dot.kind-entity { background:#F6D38B; }
.kw-kg-legend-dot.kind-method { background:#B9F0D2; }
.kw-kg-legend-dot.kind-claim { background:#DCEBFA; }
.kw-kg-legend-dot.kind-signal { background:#97B6D9; }
.kw-kg-layout {
 margin-top:14px;
 display:grid;
 grid-template-columns:minmax(0, 1.55fr) minmax(300px, 0.85fr);
 gap:14px;
}
.kw-kg-board-shell,
.kw-kg-detail {
 border-radius:18px;
 border:1px solid rgba(47,116,192,0.10);
}
.kw-kg-board-shell {
 background:
 radial-gradient(circle at top, rgba(47,116,192,0.10), transparent 34%),
 linear-gradient(180deg, #FFFFFF, #F5FAFF);
 overflow:auto;
 box-shadow:0 12px 28px rgba(31,73,125,0.06);
}
.kw-kg-board {
 position:relative;
 min-height:720px;
 background-image:
 linear-gradient(rgba(47,116,192,0.07) 1px, transparent 1px),
 linear-gradient(90deg, rgba(47,116,192,0.07) 1px, transparent 1px);
 background-size:26px 26px;
 overflow:hidden;
}
.kw-kg-svg { position:absolute; inset:0; width:100%; height:100%; pointer-events:none; }
.kw-kg-edge { fill:none; stroke:rgba(47,116,192,0.18); stroke-width:1.2; }
.kw-kg-node {
 position:absolute;
 transform:translate(-50%, -50%);
 border:none;
 cursor:pointer;
 text-align:left;
 color:var(--text-main);
 background:rgba(255,255,255,0.96);
 border:1px solid rgba(47,116,192,0.14);
 border-radius:999px;
 padding:8px 12px;
 min-width:72px;
 max-width:180px;
 box-shadow:0 12px 30px rgba(31,73,125,0.10);
}
.kw-kg-node:hover { transform:translate(-50%, calc(-50% - 1px)); }
.kw-kg-node.is-active {
 border-color:rgba(200,169,110,0.56);
 box-shadow:0 0 0 2px rgba(200,169,110,0.18), 0 16px 34px rgba(31,73,125,0.14);
}
.kw-kg-node.kind-root {
 background:linear-gradient(135deg, #F8FBFF, #EAF3FF);
 color:#1F497D;
 min-width:146px;
 border-color:rgba(47,116,192,0.24);
}
.kw-kg-node.kind-topic { color:#2F74C0; }
.kw-kg-node.kind-entity { color:#A56A00; }
.kw-kg-node.kind-method { color:#1A8F63; }
.kw-kg-node.kind-claim { border-radius:16px; max-width:220px; color:var(--text-main); }
.kw-kg-node.kind-signal {
 padding:7px 10px;
