 color:#1F497D;
}
.kw-kg-node-kind { font-size:10px; opacity:0.74; color:#5B6B7B; }
.kw-kg-node-label { margin-top:4px; font-size:12px; font-weight:700; line-height:1.4; overflow:hidden; text-overflow:ellipsis; }
.kw-kg-detail { background:#FFFFFF; padding:16px; }
.kw-kg-detail-empty {
