}
.kw-kg-detail-kicker { font-size:10px; color:var(--gold); letter-spacing:0.04em; }
.kw-kg-detail-title { margin-top:6px; font-size:18px; font-weight:800; color:var(--text-main); line-height:1.35; }
.kw-kg-detail-summary { margin-top:10px; font-size:12px; color:var(--text-sub); line-height:1.8; }
.kw-kg-chip-row { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; }
.kw-kg-chip {
 display:inline-flex;
 align-items:center;
 gap:6px;
 padding:5px 10px;
 border-radius:999px;
 background:rgba(47,116,192,0.08);
 border:1px solid rgba(47,116,192,0.12);
 color:#245B96;
 font-size:11px;
}
.kw-kg-detail-section { margin-top:16px; }
.kw-kg-detail-section-title { font-size:12px; font-weight:700; color:var(--text-main); }
.kw-kg-detail-list { margin-top:8px; display:flex; flex-direction:column; gap:8px; }
.kw-kg-detail-item { padding:10px 12px; border-radius:12px; background:#F8FBFF; border:1px solid rgba(47,116,192,0.10); }
.kw-kg-detail-item-title { font-size:12px; font-weight:700; color:var(--text-main); }
.kw-kg-detail-item-meta { margin-top:4px; font-size:11px; color:var(--text-sub); line-height:1.7; }
