 gap:8px;
}
.kw-smart-indicator-row {
 display:grid;
 grid-template-columns:minmax(180px,1.5fr) minmax(130px,1fr) minmax(95px,.55fr) auto;
 align-items:center;
 gap:14px;
 padding:13px 14px;
 border:1px solid rgba(47,116,192,0.10);
 border-radius:12px;
 background:#FFFFFF;
}
.kw-smart-indicator-row:hover { border-color:rgba(200,169,110,0.30); }
.kw-smart-indicator-row-name { font-size:13px; font-weight:800; color:var(--text-main); }
.kw-smart-indicator-row-meta { margin-top:4px; font-size:11px; color:var(--text-sub); line-height:1.55; }
.kw-smart-indicator-row-value { font-size:16px; font-weight:800; color:#1F497D; }
.kw-smart-indicator-row-value small { font-size:11px; font-weight:600; color:var(--text-sub); }
.kw-smart-indicator-row-actions { display:flex; justify-content:flex-end; gap:6px; flex-wrap:wrap; }
.kw-smart-indicator-danger { color:#B42318 !important; border-color:rgba(180,35,24,0.20) !important; }
.kw-smart-card-actions { display:flex; justify-content:space-between; align-items:center; gap:8px; margin-top:12px; padding-top:10px; border-top:1px solid rgba(47,116,192,0.10); }
.kw-smart-card-action { border:0; background:transparent; color:#2F74C0; padding:5px 0; font:inherit; font-size:11px; font-weight:700; cursor:pointer; }
.kw-smart-card-action:hover { color:#1F497D; }
.kw-smart-card-action.danger { color:#B42318; }
.kw-smart-card-action.danger:hover { color:#8E1C13; }
.kw-smart-card-action:focus-visible { outline:2px solid rgba(47,116,192,0.35); outline-offset:3px; border-radius:4px; }
.kw-smart-indicator-edit-section { display:grid; gap:10px; }
.kw-smart-indicator-edit-grid { display:grid; grid-template-columns:2fr 1fr 1fr; gap:10px; }
.kw-smart-indicator-edit-label { display:block; margin-bottom:6px; font-size:11px; color:var(--text-sub); font-weight:700; }
.kw-smart-indicator-edit-input,
.kw-smart-indicator-edit-textarea { width:100%; box-sizing:border-box; border:1px solid rgba(47,116,192,0.16); border-radius:10px; background:#F8FBFF; color:var(--text-main); padding:10px 11px; font:inherit; font-size:12px; outline:none; }
.kw-smart-indicator-edit-input:focus,
.kw-smart-indicator-edit-textarea:focus { border-color:rgba(47,116,192,0.45); box-shadow:0 0 0 3px rgba(47,116,192,0.08); }
.kw-smart-indicator-edit-textarea { min-height:88px; resize:vertical; line-height:1.7; }
.kw-smart-indicator-source-list { display:flex; flex-wrap:wrap; gap:6px; }
@media (max-width:760px) {
 .kw-smart-indicator-row { grid-template-columns:1fr auto; gap:8px 12px; }
 .kw-smart-indicator-row-source { grid-column:1/-1; }
 .kw-smart-indicator-row-actions { grid-column:1/-1; justify-content:flex-start; }
 .kw-smart-indicator-edit-grid { grid-template-columns:1fr; }
}
.kw-dashboard-component-library,
.kw-dashboard-component-list {
 display:grid;
 gap:10px;
}
.kw-dashboard-component-option,
.kw-dashboard-component-item {
 border:1px solid rgba(47,116,192,0.10);
 border-radius:14px;
 background:#F8FBFF;
 padding:12px;
}
.kw-dashboard-component-option {
 cursor:pointer;
 transition:transform .18s ease,border-color .18s ease,box-shadow .18s ease;
}
.kw-dashboard-component-option:hover {
 transform:translateY(-1px);
 border-color:rgba(200,169,110,0.24);
 box-shadow:0 8px 18px rgba(31,73,125,0.08);
}
.kw-dashboard-component-option.disabled {
 opacity:0.45;
 cursor:not-allowed;
 box-shadow:none;
}
.kw-dashboard-component-head {
 display:flex;
 justify-content:space-between;
 align-items:flex-start;
 gap:10px;
}
.kw-dashboard-component-title {
 font-size:12px;
 font-weight:800;
 color:var(--text-main);
}
.kw-dashboard-component-meta {
 margin-top:6px;
 font-size:11px;
 color:var(--text-sub);
 line-height:1.7;
}
.kw-dashboard-component-badge {
 display:inline-flex;
 align-items:center;
 padding:4px 8px;
 border-radius:999px;
 background:rgba(200,169,110,0.12);
 color:var(--gold);
 font-size:10px;
 font-weight:800;
}
.kw-dashboard-component-item.dragging {
 opacity:0.55;
 border-style:dashed;
}
.kw-dashboard-component-controls {
 display:grid;
 grid-template-columns:repeat(4, minmax(0, 1fr));
 gap:10px;
 margin-top:10px;
}
.kw-dashboard-component-field label {
 display:block;
 margin-bottom:6px;
 font-size:10px;
 letter-spacing:0.03em;
 text-transform:uppercase;
 color:var(--text-sub);
}
.kw-dashboard-component-field select,
.kw-dashboard-component-field input {
 width:100%;
 box-sizing:border-box;
 border:1px solid rgba(47,116,192,0.12);
 border-radius:10px;
 background:#FFFFFF;
 color:var(--text-main);
 padding:8px 10px;
 font-size:12px;
}
.kw-dashboard-component-actions {
 display:flex;
 gap:8px;
 align-items:flex-end;
 justify-content:flex-end;
}
.kw-dashboard-component-actions button,
.kw-dashboard-component-option button {
 white-space:nowrap;
}
.kw-dashboard-formula-shell {
 margin-top:10px;
 padding:10px 12px;
 border-radius:12px;
 background:#FFFDF7;
 border:1px solid rgba(200,169,110,0.18);
}
.kw-dashboard-formula-title {
 font-size:10px;
 font-weight:800;
 letter-spacing:0.04em;
 text-transform:uppercase;
 color:var(--gold);
}
.kw-dashboard-formula-text {
 margin-top:6px;
 font-size:12px;
 color:var(--text-main);
 line-height:1.8;
}
.kw-dashboard-source-row {
 display:flex;
 gap:8px;
 flex-wrap:wrap;
 margin-top:10px;
}
.kw-dashboard-source-chip {
 display:inline-flex;
 align-items:center;
 min-height:28px;
 padding:0 10px;
 border-radius:999px;
 background:#F8FBFF;
 border:1px solid rgba(47,116,192,0.10);
 color:#1F497D;
 font-size:11px;
 font-weight:700;
}
.kw-dashboard-cell-inline-meta {
 margin-top:10px;
 display:flex;
 gap:8px;
 flex-wrap:wrap;
}
.kw-dashboard-cell-inline-meta .kw-prompt-chip {
 max-width:100%;
}
@media (max-width: 1180px) {
 .kw-dashboard-studio { grid-template-columns:1fr; }
}
@media (max-width: 860px) {
 .kw-dashboard-hero-stats,
 .kw-dashboard-mode-row { grid-template-columns:1fr; }
 .kw-dashboard-component-controls { grid-template-columns:1fr 1fr; }
}
.toast {
 position: fixed;
 left: 50%;
 bottom: 28px;
 transform: translateX(-50%) translateY(12px);
 background: rgba(13, 27, 42, 0.92);
 color: #fff;
 border: 1px solid rgba(200,169,110,0.24);
 border-radius: 999px;
 padding: 10px 16px;
 font-size: 12px;
 box-shadow: 0 12px 32px rgba(13, 27, 42, 0.22);
 opacity: 0;
 pointer-events: none;
 transition: opacity .2s ease, transform .2s ease;
 z-index: 40;
}
.toast.show {
 opacity: 1;
 transform: translateX(-50%) translateY(0);
}
.kw-kpi-row {
 display:grid;
 grid-template-columns:repeat(5,1fr);
 gap:16px;
 margin-bottom:20px;
}
.kw-kpi-card {
 background:var(--navy-mid);
 border:1px solid rgba(47,116,192,0.12);
 border-radius:12px;
 padding:18px;
 position:relative;
 overflow:hidden;
}
.kw-kpi-card::after {
 content:'';
 position:absolute;
 top:0;
 left:0;
 right:0;
 height:2px;
 background:linear-gradient(90deg,var(--gold-dark),var(--gold-light));
 opacity:0.6;
}
.kw-kpi-label { font-size:11px; color:var(--text-sub); margin-bottom:8px; letter-spacing:0.5px; }
.kw-kpi-value { font-size:24px; font-weight:700; color:var(--text-main); margin-bottom:4px; }
.kw-kpi-sub { font-size:12px; color:var(--text-sub); }
.kw-kpi-badge {
 display:inline-block;
 padding:2px 6px;
 border-radius:4px;
 font-size:10px;
 font-weight:600;
 margin-top:6px;
}
.kw-kpi-badge.up { background:rgba(46,204,113,0.15); color:#2ECC71; }
.kw-kpi-badge.down { background:rgba(231,76,60,0.15); color:#E74C3C; }
.kw-chart-grid { display:grid; grid-template-columns:1fr 1fr; gap:20px; }
.kw-analytics-subnav { display:flex; gap:8px; flex-wrap:wrap; margin:0 0 18px; }
.kw-analytics-pill {
 border:1px solid rgba(47,116,192,0.12);
 background:#FFFFFF;
 color:var(--text-sub);
 border-radius:999px;
 padding:7px 12px;
 font-size:12px;
 font-weight:600;
 cursor:pointer;
}
.kw-analytics-pill.active {
 color:var(--gold);
 border-color:rgba(200,169,110,0.26);
 background:rgba(200,169,110,0.10);
}
.kw-chart-card {
 background:#FFFFFF;
 border:1px solid rgba(47,116,192,0.10);
 border-radius:16px;
 padding:18px;
 box-shadow:0 8px 24px rgba(31,73,125,0.06);
}
.kw-chart-title { font-size:15px; font-weight:600; color:var(--text-main); margin-bottom:4px; }
.kw-chart-subtitle { font-size:12px; color:var(--text-sub); margin-bottom:14px; }
.kw-chart-host { width:100%; }
.kw-chart-stack { display:grid; gap:16px; }
.kw-analytics-section { display:none; }
.kw-analytics-section.active { display:block; }
.kw-funnel-list { display:grid; gap:10px; }
.kw-funnel-row { display:grid; grid-template-columns:88px 1fr 70px; gap:12px; align-items:center; }
.kw-funnel-label, .kw-funnel-value,
.kw-quality-table td, .kw-quality-table th,
.kw-cohort-table td, .kw-cohort-table th,
.kw-retention-table td, .kw-retention-table th,
.kw-heatmap-table td, .kw-heatmap-table th { font-size:12px; }
.kw-funnel-bar { height:12px; background:#EEF4FA; border-radius:999px; overflow:hidden; }
.kw-funnel-bar span { display:block; height:100%; background:linear-gradient(90deg,#66A1DF,#2F74C0); border-radius:999px; }
.kw-heatmap-table, .kw-quality-table, .kw-cohort-table, .kw-retention-table { width:100%; border-collapse:collapse; }
.kw-heatmap-table th, .kw-heatmap-table td,
.kw-quality-table th, .kw-quality-table td,
.kw-cohort-table th, .kw-cohort-table td,
.kw-retention-table th, .kw-retention-table td {
 border-bottom:1px solid rgba(47,116,192,0.08);
 padding:10px 8px;
 text-align:left;
}
.kw-heatmap-table th, .kw-quality-table th, .kw-cohort-table th, .kw-retention-table th { color:var(--text-sub); font-size:11px; font-weight:600; }
.kw-heat-cell { text-align:center !important; border-radius:10px; }
.kw-score-bar { display:inline-block; height:8px; border-radius:999px; background:linear-gradient(90deg,#C8A96E,#2F74C0); margin-right:8px; vertical-align:middle; }
.kw-lifecycle-row { display:grid; grid-template-columns:repeat(4,1fr); gap:10px; }
.kw-lifecycle-card {
 background:#F8FBFF;
 border:1px solid rgba(47,116,192,0.10);
 border-radius:14px;
 padding:14px;
 text-align:center;
}
.kw-lifecycle-name { font-size:12px; color:var(--text-sub); }
.kw-lifecycle-value { font-size:22px; font-weight:700; color:var(--text-main); margin-top:8px; }
.kw-chart-svg { width:100%; height:auto; display:block; }
.kw-chart-axis { stroke:rgba(47,116,192,0.18); stroke-width:1; }
.kw-chart-gridline { stroke:rgba(47,116,192,0.10); stroke-width:1; stroke-dasharray:3 3; }
.kw-chart-bar { fill:url(#kwBarGradient); }
.kw-chart-line { fill:none; stroke:url(#kwLineGradient); stroke-width:3; stroke-linecap:round; stroke-linejoin:round; }
.kw-chart-area { fill:url(#kwAreaGradient); opacity:0.24; }
.kw-chart-point { fill:#2F74C0; stroke:#FFFFFF; stroke-width:2; }
.kw-chart-label,
.kw-chart-value,
.kw-chart-tick { font-size:11px; fill:var(--text-sub); }
.kw-chart-value { fill:var(--text-main); font-weight:600; }
.kw-admin-status { font-size:13px; color:var(--text-sub); margin:12px 0 0; min-height:18px; }
.kw-admin-build-tag {
 display:inline-flex;
 align-items:center;
 padding:4px 10px;
 border-radius:999px;
 background:rgba(47,116,192,0.12);
 color:var(--gold);
 font-size:11px;
 font-weight:600;
 white-space:nowrap;
}
.kw-compact-row {
 display:flex;
 justify-content:space-between;
 align-items:center;
 gap:10px;
 padding:12px 14px;
 border:1px solid rgba(47,116,192,0.10);
 border-radius:14px;
 background:#F8FBFF;
 font-size:12px;
 color:var(--text-sub);
}
.kw-compact-row strong { color:var(--text-main); }
.kw-portal-shell {
 display:grid;
 grid-template-columns:280px minmax(0,1fr) 300px;
 gap:16px;
}
.kw-portal-column { display:grid; gap:16px; align-content:start; }
.kw-portal-status-grid,
.kw-portal-preset-grid,
.kw-portal-preview-list,
.kw-portal-module-list,
.kw-portal-outline-list { display:grid; gap:10px; }
.kw-portal-status-grid { grid-template-columns:1fr 1fr; }
.kw-portal-status-card,
.kw-portal-preview-card,
.kw-portal-module-item,
