}
.kw-portal-inspector-card { padding:16px; }
.kw-portal-inspector-grid { display:grid; gap:12px; }
.kw-portal-inspector-label {
 font-size:11px;
 color:var(--text-sub);
}
.kw-portal-inspector-value {
