 color:var(--text-sub);
}
.kw-workflow-shell { display:grid; grid-template-columns:250px minmax(0,1fr) 320px; gap:20px; margin-top:16px; }
.kw-workflow-catalog { display:grid; gap:10px; }
.kw-workflow-catalog-item {
 text-align:left;
 padding:12px 14px;
 border-radius:14px;
 border:1px solid rgba(47,116,192,0.10);
 background:#F8FBFF;
 color:var(--text-main);
 cursor:pointer;
 transition:all .18s ease;
}
.kw-workflow-catalog-item:hover {
 border-color:rgba(47,116,192,0.28);
 box-shadow:0 10px 24px rgba(31,73,125,0.08);
 transform:translateY(-1px);
}
.kw-workflow-catalog-item strong { display:block; font-size:13px; margin-bottom:4px; }
.kw-workflow-catalog-item span { display:block; font-size:11px; line-height:1.6; color:var(--text-sub); }
.kw-workflow-toolbar {
 display:flex;
 justify-content:space-between;
 align-items:center;
 gap:12px;
 flex-wrap:wrap;
 margin-bottom:14px;
}
.kw-workflow-toolbar-left,
.kw-workflow-toolbar-right { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.kw-workflow-stage {
 position:relative;
 overflow:auto;
 border-radius:16px;
 border:1px solid rgba(47,116,192,0.10);
 min-height:760px;
 background:
 linear-gradient(90deg, rgba(47,116,192,0.06) 1px, transparent 1px) 0 0 / 24px 24px,
 linear-gradient(rgba(47,116,192,0.06) 1px, transparent 1px) 0 0 / 24px 24px,
 #F8FBFF;
}
.kw-workflow-stage-viewport {
 position:relative;
 min-width:100%;
 min-height:760px;
 transform-origin:0 0;
 isolation:isolate;
}
.kw-workflow-edge-layer {
 position:absolute;
 top:0;
 left:0;
 pointer-events:none;
 overflow:visible;
 z-index:1;
}
.kw-workflow-edge {
 fill:none;
 stroke:rgba(47,116,192,0.96);
 stroke-width:4;
 stroke-linecap:round;
 stroke-linejoin:round;
 filter:drop-shadow(0 0 10px rgba(47,116,192,0.18));
}
.kw-workflow-edge-shadow {
 fill:none;
 stroke:rgba(255,255,255,0.98);
 stroke-width:8;
 stroke-linecap:round;
 stroke-linejoin:round;
}
.kw-workflow-edge-anchor {
 fill:#FFFFFF;
 stroke:rgba(47,116,192,0.98);
 stroke-width:3;
}
.kw-workflow-board { position:relative; min-height:760px; z-index:2; }
.kw-workflow-node {
 position:absolute;
 width:220px;
 padding:12px;
 background:#FFFFFF;
 border:1px solid rgba(47,116,192,0.12);
 border-radius:14px;
 box-shadow:0 10px 26px rgba(14,33,55,0.08);
 cursor:grab;
 user-select:none;
 z-index:3;
}
.kw-workflow-node.is-selected {
 border-color:var(--gold);
 box-shadow:0 12px 28px rgba(47,116,192,0.15);
}
.kw-workflow-node-head { display:flex; justify-content:space-between; align-items:center; gap:8px; }
.kw-workflow-node-head strong { font-size:13px; color:var(--text-main); }
.kw-workflow-node-type {
 font-size:10px;
 color:var(--gold);
 border:1px solid rgba(47,116,192,0.14);
 border-radius:999px;
 padding:3px 8px;
}
.kw-workflow-node-ports { display:flex; justify-content:space-between; margin-top:12px; }
.kw-workflow-port {
 border:1px solid rgba(47,116,192,0.12);
 background:#F8FBFF;
 color:var(--text-main);
 border-radius:999px;
 padding:4px 10px;
 font-size:11px;
 cursor:pointer;
 font-family:inherit;
}
.kw-workflow-port::before {
 content:"";
 width:8px;
 height:8px;
 border-radius:50%;
 background:var(--gold);
 display:inline-block;
 margin-right:6px;
 box-shadow:0 0 0 3px rgba(47,116,192,0.14);
}
.kw-workflow-tool-button {
