}
.kw-workflow-tool-button:hover {
 color:var(--text-main);
 border-color:rgba(47,116,192,0.22);
 background:#F8FBFF;
}
.kw-forecast-config-board { display:grid; gap:12px; }
.kw-forecast-config-section-title { margin:2px 0 8px; font-size:12px; color:var(--text-main); font-weight:700; }
.kw-forecast-config-field {
