}
.kw-forecast-debug-value,
.kw-forecast-debug-copy,
.kw-forecast-debug-list,
.kw-result-line { font-size:12px; color:var(--text-main); line-height:1.7; }
.kw-result-line strong { color:var(--gold); }
.kw-forecast-inspector-section { display:grid; gap:12px; }
.kw-workflow-guide {
