}
.kw-review-access-scope-tag:hover { border-color:rgba(47,116,192,0.34); transform:translateY(-1px); }
.kw-review-access-scope-tag.active { background:rgba(200,169,110,0.12); border-color:rgba(200,169,110,0.65); box-shadow:0 5px 14px rgba(142,106,30,0.10); }
.kw-review-access-scope-tag-title { display:flex; align-items:center; gap:6px; font-size:12px; font-weight:800; line-height:1.3; }
.kw-review-access-scope-tag.active .kw-review-access-scope-tag-title::before { content:'✓'; display:inline-flex; align-items:center; justify-content:center; width:15px; height:15px; border-radius:50%; color:var(--navy); background:var(--gold); font-size:10px; }
.kw-review-access-scope-tag-desc { display:block; margin-top:5px; color:var(--text-sub); font-size:10px; line-height:1.45; }
@media (max-width: 760px) { .kw-review-access-scope-tags { grid-template-columns:1fr; } }
.kw-review-draft-status {
 display:inline-flex;
