}
.kw-review-rich-editor .ql-container.ql-snow {
 border:none;
 background:#F8FBFF;
}
.kw-review-rich-editor .ql-editor {
 min-height:400px;
 padding:16px 18px;
 font-size:13px;
 line-height:1.8;
 color:var(--text-main);
}
.kw-review-rich-editor .ql-editor.ql-blank::before {
 color:#9AA6B2;
 font-style:normal;
 opacity:1;
 pointer-events:none;
 left:18px;
 right:18px;
}
.kw-review-rich-editor:focus-within .ql-editor.ql-blank::before {
 display:none;
}
.kw-review-prompt-tag.active {
