}
.kw-knowledge-rich-editor .ql-editor th,
.kw-knowledge-rich-editor .ql-editor td,
.kw-knowledge-rendered th,
.kw-knowledge-rendered td {
 border:1px solid rgba(47,116,192,0.16);
