 border-radius:12px;
 background:#0F2542;
 color:#EAF3FF;
}
.kw-knowledge-rich-editor .ql-editor ul,
.kw-knowledge-rich-editor .ql-editor ol,
.kw-knowledge-rendered ul,
.kw-knowledge-rendered ol {
