 justify-content:space-between;
 align-items:flex-start;
 gap:10px;
 margin-bottom:10px;
}
.kw-knowledge-action-row,
.kw-knowledge-chip-row {
 display:flex;
 gap:8px;
 flex-wrap:wrap;
}
.kw-knowledge-chip {
 display:inline-flex;
 align-items:center;
 min-height:30px;
 padding:0 10px;
 border-radius:999px;
 background:#FFFFFF;
 border:1px solid rgba(47,116,192,0.10);
 font-size:11px;
 color:#1F497D;
}
.kw-knowledge-status-chip {
 display:inline-flex;
 align-items:center;
 height:28px;
 padding:0 10px;
 border-radius:999px;
 font-size:11px;
 color:var(--gold);
 background:rgba(200,169,110,0.10);
}
.kw-knowledge-wave {
 display:flex;
 align-items:flex-end;
 gap:4px;
 height:40px;
}
.kw-knowledge-wave span {
 width:5px;
 border-radius:999px;
 background:linear-gradient(180deg,#66A1DF,#2F74C0);
 animation:kwKnowledgePulse 1s ease-in-out infinite;
}
.kw-knowledge-wave span:nth-child(1) { height:16px; animation-delay:0s; }
.kw-knowledge-wave span:nth-child(2) { height:28px; animation-delay:0.12s; }
.kw-knowledge-wave span:nth-child(3) { height:36px; animation-delay:0.24s; }
.kw-knowledge-wave span:nth-child(4) { height:22px; animation-delay:0.36s; }
.kw-knowledge-wave span:nth-child(5) { height:30px; animation-delay:0.48s; }
@keyframes kwKnowledgePulse {
 0%, 100% { opacity:0.45; transform:scaleY(0.88); }
 50% { opacity:1; transform:scaleY(1); }
}
.kw-publish-dots span { display:inline-block; animation:kwPublishDot 1.2s infinite; }
.kw-publish-dots span:nth-child(2) { animation-delay:.2s; }
.kw-publish-dots span:nth-child(3) { animation-delay:.4s; }
@keyframes kwPublishDot { 0%,80%,100% { opacity:.25; } 40% { opacity:1; } }
@media (max-width: 980px) {
 .kw-indicator-hero,
 .kw-section-grid,
 .kw-link-grid,
 .kw-mini-grid,
 .kw-cell-grid,
 .kw-review-source-grid,
