 .kw-knowledge-layout,
 .kw-knowledge-readable-shell,
 .kw-knowledge-source-selector,
 .kw-knowledge-detail-grid,
 .kw-kg-layout,
 .kw-kg-stats { grid-template-columns:1fr; }
 .kw-portal-status-grid { grid-template-columns:1fr; }
 .kw-review-directory-nav { position:static; }
 .kw-review-directory-btn::after { display:none; }
 .kw-review-modal-overlay { padding:12px; }
 .kw-review-modal-sheet { padding:18px; border-radius:18px; }
}
</style>
