<script>
const workbenchSectionMeta = {
 overview: { title: '工作台概览', summary: '和 H5 保持同一套产品口径，但以桌面 web 工作流方式组织大V日常动作。' },
 fans: { title: '粉丝管理', summary: '查看大V自己的粉丝规模、来源、价值标签和分层状态。' },
 portal: { title: '租户门户', summary: '租户门户是大V自定义的对外内容空间，按类似 WordPress 的装修和编排模式维护，不是智能生成区。' },
 'biz-dashboard': { title: '数据分析', summary: '基于当前租户粉丝、用户标签和付费单价生成转化漏斗、来源分布与预计收入。' },
 'forecast-model': { title: '预测模型', summary: '展示目标价是怎么计算出来的，并允许在后台调整自动收敛参数。' },
