function isWorkbenchFeatureEnabled(featureName) {
 const flags = (window.SITE_CONFIG && window.SITE_CONFIG.feature_flags) || {};
 if (featureName === 'knowledge' && flags.knowledge_module_enabled !== true) return false;
 if (featureName === 'core_indicators') return flags.core_indicators === true;
 return flags[featureName] !== false;
}

const SITE_CONFIG_BROADCAST_KEY = 'gangtise-site-config-updated-at';

async function refreshWorkbenchSiteConfig(options = {}) {
 try {
 const res = await fetch('/api/site-config', {cache: 'no-store'});
 if (!res.ok) throw new Error('load_site_config_failed');
 const data = await res.json();
 if (!data || typeof data !== 'object') throw new Error('invalid_site_config');
 window.SITE_CONFIG = data;
 refreshWorkbenchNavVisibility();
 try {
 const tenantSlug = (window.ACTIVE_TENANT && window.ACTIVE_TENANT.slug) || '';
 const workbenchRes = await fetch(`/api/kol/workbench?tenant=${encodeURIComponent(tenantSlug)}`, {cache: 'no-store'});
 if (workbenchRes.ok) {
 const workbenchData = await workbenchRes.json();
 if (workbenchData && typeof workbenchData === 'object') {
 window.WORKBENCH_DATA = workbenchData;
 kwFans = Array.isArray((window.WORKBENCH_DATA && window.WORKBENCH_DATA.fan_management && window.WORKBENCH_DATA.fan_management.fans))
 ? window.WORKBENCH_DATA.fan_management.fans.map((fan) => ({
 id: fan.id || 0,
 username: fan.username || fan.name || '',
 membership: fan.membership || fan.tier || '--',
 is_paid_sample: !!fan.is_paid_sample,
 source: fan.source || '用户导入',
 created_at: fan.created_at || fan.joined || '--',
 paid_sample_note: fan.paid_sample_note || '',
 labels: Array.isArray(fan.labels) ? fan.labels : (fan.is_paid_sample ? ['付费用户'] : []),
 phone_masked: fan.phone_masked || fan.value || '--',
 status: fan.status === '已禁用' ? 'disabled' : (fan.status || 'active'),
 }))
 : [];
 renderKwOpsStats();
 kwRenderPublishedReviewList();
 renderWorkbenchAnnotationViews();
 }
 }
 } catch (e) {}
 const activeSection = new URLSearchParams(window.location.search).get('section') || 'overview';
 if (activeSection && !document.querySelector(`.admin-nav-item[data-section="${activeSection}"]`) && activeSection !== 'overview') {
 showWorkbenchSection('overview');
 }
 } catch (error) {
 if (!options.silent) {
 showToast('工作台功能配置刷新失败');
 }
 }
}

function kwSyncPublishedReviewState(result) {
 const payload = result && typeof result === 'object' ? result : {};
 const tenantSlug = String(((window.ACTIVE_TENANT || {}).slug) || '').trim().toLowerCase();
 const nextState = {};
 if (Array.isArray(payload.snapshots)) nextState.review_snapshots = payload.snapshots.slice(0, 20);
 if (payload.message_center_state && typeof payload.message_center_state === 'object') {
 nextState.message_center_state = payload.message_center_state;
 }
 if (!tenantSlug || !Object.keys(nextState).length) return;
 if (window.SITE_CONFIG && Array.isArray(window.SITE_CONFIG.tenants)) {
 window.SITE_CONFIG.tenants = window.SITE_CONFIG.tenants.map((tenant) => {
 const itemSlug = String((tenant && tenant.slug) || '').trim().toLowerCase();
 return itemSlug === tenantSlug ? { ...tenant, ...nextState } : tenant;
 });
 }
 if (window.ACTIVE_TENANT) {
 window.ACTIVE_TENANT = { ...window.ACTIVE_TENANT, ...nextState };
 }
}

function refreshWorkbenchNavVisibility() {
 document.querySelectorAll('.admin-nav-item[data-feature]').forEach((node) => {
 const featureName = node.dataset.feature;
 node.style.display = isWorkbenchFeatureEnabled(featureName) ? '' : 'none';
 });
 document.querySelectorAll('.admin-nav-group').forEach((group) => {
 const items = Array.from(group.querySelectorAll('.admin-nav-item'));
 const visibleItems = items.filter((item) => item.style.display !== 'none');
 group.style.display = visibleItems.length ? '' : 'none';
 });
 const portalSection = document.getElementById('workbench-section-portal');
 if (portalSection && !isWorkbenchFeatureEnabled('tenant_portal')) {
 portalSection.style.display = 'none';
 }
 const activeSection = document.querySelector('.admin-nav-item.active[data-section]');
 if (activeSection && activeSection.style.display === 'none') {
 showWorkbenchSection('overview', document.querySelector('.admin-nav-item[data-section="overview"]'));
 }
}

function renderWorkbenchBarChart(hostId, items) {
 const host = document.getElementById(hostId);
 const list = Array.isArray(items) ? items : [];
 if (!host || !list.length) return;
 window.GangtiseEcharts.render(host, {
 color: ['#2F74C0'],
 tooltip: window.GangtiseEcharts.tooltipBase((params) => `${params.name}<br>数量：${params.value}`),
 grid: window.GangtiseEcharts.gridBase({ top: 22, left: 18, right: 18, bottom: 34 }),
 xAxis: {
 type: 'category',
 data: list.map((item) => item.label),
 ...window.GangtiseEcharts.axisBase({ splitLine: { show: false }, axisLabel: { color: '#445468', fontSize: 11 } }),
 },
 yAxis: {
 type: 'value',
 ...window.GangtiseEcharts.axisBase({ axisLabel: { color: '#445468', fontSize: 11 } }),
 },
 series: [{
 name: '数量',
 type: 'bar',
 barWidth: '46%',
 itemStyle: { color: 'rgba(47,116,192,0.78)', borderRadius: [8, 8, 0, 0] },
 label: { show: true, position: 'top', color: '#2F74C0', fontSize: 11 },
 data: list.map((item) => Number(item.value || 0)),
 }],
 });
}

function renderWorkbenchActivityBarChart(hostId, items, onClick) {
 const host = document.getElementById(hostId);
 const list = Array.isArray(items) ? items : [];
 if (!host) return;
 if (!list.length) {
 host.innerHTML = '<div class="kw-watch-insight-panel-desc" style="padding:42px 12px;text-align:center">当前暂无可统计的用户活动</div>';
 return;
 }
 window.GangtiseEcharts.render(host, {
 color: ['#2F74C0', '#C8A96E'],
 tooltip: window.GangtiseEcharts.tooltipBase((params) => `${params[0].name}<br>${params.map((item) => `${item.seriesName}：${item.value}`).join('<br>')}`),
 legend: { top: 0, right: 8, textStyle: { color: '#64748B', fontSize: 11 } },
 grid: window.GangtiseEcharts.gridBase({ top: 34, left: 18, right: 18, bottom: 42 }),
 xAxis: { type: 'category', data: list.map((item) => item.label), ...window.GangtiseEcharts.axisBase({ axisLabel: { color: '#445468', fontSize: 10, rotate: list.length > 8 ? 28 : 0 } }) },
 yAxis: { type: 'value', ...window.GangtiseEcharts.axisBase({ axisLabel: { color: '#445468', fontSize: 10 } }) },
 series: [
 { name: '评论', type: 'bar', barMaxWidth: 18, itemStyle: { color: 'rgba(47,116,192,0.78)', borderRadius: [6, 6, 0, 0] }, data: list.map((item) => Number(item.comments || 0)) },
 { name: '标注', type: 'bar', barMaxWidth: 18, itemStyle: { color: 'rgba(200,169,110,0.82)', borderRadius: [6, 6, 0, 0] }, data: list.map((item) => Number(item.annotations || 0)) },
 ],
 }, { onClick: (params) => { if (params && params.name && typeof onClick === 'function') onClick(String(params.name)); } });
}

function openWorkbenchActivityBucketModal(kind, label) {
 const analytics = (window.WORKBENCH_DATA && window.WORKBENCH_DATA.watchlist_comment_analytics) || {};
 const bucketKey = kind === 'sector' ? 'sector' : 'day';
 const allRecords = (Array.isArray(analytics.activity_records) ? analytics.activity_records : []).filter((item) => item && String(item[bucketKey] || '') === String(label || ''));
 const comments = allRecords.filter((item) => item.type === 'comment');
 const annotations = allRecords.filter((item) => item.type === 'annotation');
 const modal = document.getElementById('kw-watchlist-comments-modal');
 const host = document.getElementById('kw-watchlist-comments-content');
 if (!modal || !host) return;
 const scopeLabel = kind === 'sector' ? '行业板块' : '日期';
 const renderRecords = (records, emptyText) => {
 const sorted = records.slice().sort((a, b) => String(b.timestamp || '').localeCompare(String(a.timestamp || '')));
 return sorted.length ? sorted.map((item) => `<div class="kw-watchlist-comment"><div class="kw-watchlist-comment-meta">${escapeHtml(item.author_role || '')} · ${escapeHtml(item.author || '')} · ${escapeHtml(item.timestamp || '')}</div><div class="kw-watchlist-comment-meta" style="margin-top:4px">${escapeHtml(item.stock_name || '')}</div><div class="kw-watchlist-comment-text">${escapeHtml(item.content || '未填写内容')}</div></div>`).join('') : `<div class="kw-watchlist-comment-empty">${emptyText}</div>`;
 };
 host.innerHTML = `
 <div class="kw-review-modal-title">${escapeHtml(label)} · 活动明细</div>
 <div class="kw-dashboard-panel-note" style="margin-top:6px">${scopeLabel}范围内共 ${allRecords.length} 条活动，按最新时间排序。</div>
 <div class="kw-watch-activity-modal-tabs" style="display:flex;gap:6px;margin-top:14px;border-bottom:1px solid rgba(47,116,192,0.12);padding-bottom:10px">
 <button class="btn-outline active" type="button" style="padding:7px 10px;font-size:11px" data-activity-modal-tab="comments" onclick="switchWorkbenchActivityModalTab('comments')">评论 ${comments.length}</button>
 <button class="btn-outline" type="button" style="padding:7px 10px;font-size:11px" data-activity-modal-tab="annotations" onclick="switchWorkbenchActivityModalTab('annotations')">标注 ${annotations.length}</button>
 </div>
 <div id="kw-watch-activity-modal-comments" class="kw-watchlist-comments" style="margin-top:12px">${renderRecords(comments, '该范围暂无评论。')}</div>
 <div id="kw-watch-activity-modal-annotations" class="kw-watchlist-comments" style="margin-top:12px;display:none">${renderRecords(annotations, '该范围暂无标注。')}</div>
 `;
 modal.classList.add('show');
}

function switchWorkbenchActivityModalTab(tab) {
 const showAnnotations = tab === 'annotations';
 const comments = document.getElementById('kw-watch-activity-modal-comments');
 const annotations = document.getElementById('kw-watch-activity-modal-annotations');
 if (comments) comments.style.display = showAnnotations ? 'none' : '';
 if (annotations) annotations.style.display = showAnnotations ? '' : 'none';
 document.querySelectorAll('.kw-watch-activity-modal-tabs [data-activity-modal-tab]').forEach((button) => {
 button.classList.toggle('active', button.dataset.activityModalTab === (showAnnotations ? 'annotations' : 'comments'));
 });
}

function buildCommentSectorDistributionFallback(comments) {
 const detailMap = window.WATCHLIST_DETAILS_MAP || {};
 const counter = new Map();
 (Array.isArray(comments) ? comments : []).forEach((item) => {
 const code = String(item && item.stock_code ? item.stock_code : '').trim().toUpperCase();
 if (!code) return;
 const detail = detailMap[code] || {};
 const sector = String(detail.industry || detail.focus || detail.board || '未分类').trim() || '未分类';
 counter.set(sector, (counter.get(sector) || 0) + 1);
 });
 return Array.from(counter.entries())
 .sort((a, b) => (b[1] - a[1]) || String(a[0]).localeCompare(String(b[0]), 'zh-Hans-CN'))
 .map(([label, value]) => ({ label, value }));
}

