 <div class="kw-watch-kpi"><div class="kw-watch-kpi-label">涉及标的</div><div class="kw-watch-kpi-value">${Number(summary.stock_count || 0)}</div><div class="kw-watch-kpi-note">有讨论的个股</div></div>
 <div class="kw-watch-kpi"><div class="kw-watch-kpi-label">K线标注</div><div class="kw-watch-kpi-value">${Number(summary.total_annotations || 0)}</div><div class="kw-watch-kpi-note">粉丝标注 ${Number(summary.investor_annotations || 0)} 条</div></div>
 </div>
 <div class="kw-watch-insight-shell">
