function switchWorkbenchActivityTab(tab) {
 const sector = document.getElementById('kw-watchlist-activity-sector');
 const date = document.getElementById('kw-watchlist-activity-date');
 const buttons = document.querySelectorAll('.kw-watch-activity-tabs button');
 const isDate = tab === 'date';
 if (sector) sector.style.display = isDate ? 'none' : '';
 if (date) date.style.display = isDate ? '' : 'none';
 buttons.forEach((button) => button.classList.toggle('active', button.textContent.trim() === (isDate ? '日期趋势' : '行业板块')));
 const analytics = (window.WORKBENCH_DATA && window.WORKBENCH_DATA.watchlist_comment_analytics) || {};
 window.requestAnimationFrame(() => renderWorkbenchActivityBarChart(
 isDate ? 'kw-watchlist-activity-date' : 'kw-watchlist-activity-sector',
 isDate ? (analytics.date_activity_distribution || []) : (analytics.sector_activity_distribution || []),
 (label) => openWorkbenchActivityBucketModal(isDate ? 'date' : 'sector', label),
 ));
}

function kwSwitchWatchlistPoolTab(name) {
 const isFan = name === 'fan';
 const advisorPanel = document.getElementById('kw-watchlist-advisor-panel');
 const fanPanel = document.getElementById('kw-watchlist-fan-panel');
 const advisorTab = document.getElementById('kw-watchlist-advisor-tab');
 const fanTab = document.getElementById('kw-watchlist-fan-tab');
 if (advisorPanel) advisorPanel.style.display = isFan ? 'none' : '';
 if (fanPanel) fanPanel.style.display = isFan ? '' : 'none';
 if (advisorTab) { advisorTab.classList.toggle('active', !isFan); advisorTab.setAttribute('aria-selected', String(!isFan)); }
 if (fanTab) { fanTab.classList.toggle('active', isFan); fanTab.setAttribute('aria-selected', String(isFan)); }
 if (isFan) {
 const distribution = (((window.WORKBENCH_DATA || {}).fan_stock_observation || {}).fan_watchlist_sector_distribution || []);
 renderWorkbenchBarChart('kw-fan-watchlist-sector-chart', distribution.map((item) => ({ label: item.label, value: item.value })));
 }
}

function closeKwWatchlistComments() {
 const modal = document.getElementById('kw-watchlist-comments-modal');
 if (modal) modal.classList.remove('show');
}

async function openKwWatchlistComments(stockCode, stockName) {
 const modal = document.getElementById('kw-watchlist-comments-modal');
 const host = document.getElementById('kw-watchlist-comments-content');
 const tenantSlug = String(((window.ACTIVE_TENANT || {}).slug) || '').trim();
 if (!modal || !host || !tenantSlug || !stockCode) return;
 host.innerHTML = `<div class="kw-review-modal-title">${escapeHtml(stockName || stockCode)} · 评论</div><div class="kw-watchlist-comment-empty">正在读取当前租户的评论...</div>`;
 modal.classList.add('show');
 try {
 const response = await fetch(`/api/watchlist/${encodeURIComponent(stockCode)}/comments?tenant_slug=${encodeURIComponent(tenantSlug)}&user_role=dav&stock_name=${encodeURIComponent(stockName || '')}`);
 const payload = await response.json();
 if (!response.ok || !payload.ok) throw new Error((payload && payload.error) || 'watchlist_comments_load_failed');
 const items = Array.isArray(payload.items) ? payload.items : [];
 host.innerHTML = `
 <div class="kw-review-modal-title">${escapeHtml(stockName || stockCode)} · 评论</div>
 <div class="kw-dashboard-panel-note" style="margin-top:6px">仅展示当前租户已发布的该标的评论，按最新更新时间排序。</div>
 <div class="kw-watchlist-comments">
 ${items.length ? items.map((item) => `
 <div class="kw-watchlist-comment">
 <div class="kw-watchlist-comment-meta">${escapeHtml(item.created_by_role_label || '')} · ${escapeHtml(item.created_by_name || '')} · ${escapeHtml(item.updated_at || item.created_at || '')}${item.is_simulated ? ` · ${escapeHtml(item.simulation_label || '模拟数据')}` : ''}</div>
 <div class="kw-watchlist-comment-text">${escapeHtml(item.comment_text || '')}</div>
 </div>
 `).join('') : '<div class="kw-watchlist-comment-empty">该标的暂无评论。</div>'}
 </div>
 `;
 } catch (error) {
 host.innerHTML = `<div class="kw-review-modal-title">${escapeHtml(stockName || stockCode)} · 评论</div><div class="kw-watchlist-comment-empty">${escapeHtml(error.message || '评论加载失败')}</div>`;
 }
}

function kwNormalizeDashboardLayout(layout) {
 if (layout === '3x3') return '2x3';
 if (layout === '4x4' || layout === '2x4') return '4x2';
 if (layout === '2x5') return '5x2';
 if (layout === '2x2' || layout === '2x3' || layout === '4x2' || layout === '5x2') return layout;
 return '2x2';
}

function kwGetDashboardCardTarget(layout) {
 if (layout === '2x3') return 6;
 if (layout === '4x2') return 8;
 if (layout === '5x2') return 10;
 return 4;
}

function kwGetDashboardComponentLibrary(mode) {
 const resolvedMode = String(mode || '').trim() || 'market';
 const libraries = {
 market: [
 { id: 'market_breadth', label: '广度改善分', source: '全市场行情库', metric: '上涨/下跌家数、站上MA20占比、新高-新低差', window: '1D', aggregation: '0-100评分', defaultWeight: 0.35, defaultOperator: 'base', defaultSelected: true },
 { id: 'northbound_flow', label: '资金回流分', source: '北向/南向资金库', metric: '净流入占成交比、3日累计、连续净流入天数', window: '1D / 3D', aggregation: '0-100评分', defaultWeight: 0.25, defaultOperator: '+', defaultSelected: true },
 { id: 'turnover_structure', label: '主线参与分', source: '成交结构库', metric: '主线成交占比、5日变化、拥挤度惩罚', window: '1D / 5D', aggregation: '0-100评分', defaultWeight: 0.25, defaultOperator: '+', defaultSelected: true },
 { id: 'style_rotation', label: '防御压力分', source: '风格因子库', metric: '银行/红利相对成长超额、低波ETF净流入', window: '1D / 5D', aggregation: '0-100评分', defaultWeight: 0.15, defaultOperator: '-', defaultSelected: true },
 { id: 'policy_heat', label: '政策温度参考分', source: '政策新闻流', metric: '宏观政策热度与边际变化', window: '3D', aggregation: '辅助评分', defaultWeight: 0.1, defaultOperator: '+', defaultSelected: false },
 ],
 industry: [
 { id: 'industry_orders', label: '订单景气分', source: '行业指标库', metric: '新增订单同比、在手订单覆盖、开工率', window: '1W / 1M', aggregation: '0-100评分', defaultWeight: 0.3, defaultOperator: 'base', defaultSelected: true },
 { id: 'industry_price', label: '价格景气分', source: '产业链价格库', metric: '产品价格指数、价差、提价持续性', window: '1W / 1M', aggregation: '0-100评分', defaultWeight: 0.25, defaultOperator: '+', defaultSelected: true },
 { id: 'industry_inventory', label: '库存去化分', source: '行业库存库', metric: '库存天数、主动/被动补库、去库斜率', window: '1M', aggregation: '0-100评分', defaultWeight: 0.2, defaultOperator: '+', defaultSelected: true },
 { id: 'industry_policy', label: '政策催化分', source: '行业新闻流', metric: '政策热度、落地级别、持续性', window: '5D / 20D', aggregation: '0-100评分', defaultWeight: 0.15, defaultOperator: '+', defaultSelected: true },
 { id: 'industry_capex', label: '资本开支确认分', source: '财报与经营数据', metric: 'Capex指引、扩产计划、设备招标', window: '1Q', aggregation: '0-100评分', defaultWeight: 0.1, defaultOperator: '+', defaultSelected: true },
 ],
 'signal-stock': [
 { id: 'leader_strength', label: '龙头强度分', source: '个股行情库', metric: '相对行业超额收益、回撤控制、成交额排名', window: '5D / 20D', aggregation: '0-100评分', defaultWeight: 0.35, defaultOperator: 'base', defaultSelected: true },
 { id: 'earnings_delivery', label: '业绩兑现分', source: '财报与预期库', metric: '营收/利润兑现率、指引上修、订单兑现', window: '1Q', aggregation: '0-100评分', defaultWeight: 0.3, defaultOperator: '+', defaultSelected: true },
 { id: 'support_flow', label: '资金承接分', source: '盘口与成交数据', metric: '回调缩量、尾盘净流入、换手承接', window: '3D / 5D', aggregation: '0-100评分', defaultWeight: 0.2, defaultOperator: '+', defaultSelected: true },
 { id: 'valuation_band', label: '估值安全分', source: '估值与财报库', metric: 'PE/PS分位、PEG、相对历史分位', window: '1Q / 3Y', aggregation: '0-100评分', defaultWeight: 0.15, defaultOperator: '+', defaultSelected: true },
 { id: 'catalyst_window', label: '催化窗口参考分', source: '公司新闻流', metric: '新品、财报、订单公告、政策催化时点', window: '10D / 30D', aggregation: '辅助评分', defaultWeight: 0.1, defaultOperator: '+', defaultSelected: false },
 ],
 };
 return JSON.parse(JSON.stringify(libraries[resolvedMode] || libraries.market));
}

function kwBuildDefaultDashboardComponents(mode) {
 return kwGetDashboardComponentLibrary(mode).filter(item => item.defaultSelected !== false).slice(0, 5).map((item, index) => ({
 id: item.id,
 label: item.label,
 source: item.source,
 metric: item.metric,
 window: item.window,
 aggregation: item.aggregation,
 weight: item.defaultWeight,
 operator: item.defaultOperator || (index === 0 ? 'base' : '+'),
 }));
}

function kwNormalizeDashboardComponents(components, mode) {
 const library = kwGetDashboardComponentLibrary(mode);
 const libraryMap = Object.fromEntries(library.map(item => [item.id, item]));
 const rawList = Array.isArray(components) && components.length ? components : kwBuildDefaultDashboardComponents(mode);
 return rawList.slice(0, 6).map((item, index) => {
 const raw = item && typeof item === 'object' ? item : {};
 const template = libraryMap[raw.id || raw.componentId] || library[Math.min(index, library.length - 1)];
 const nextWeight = Number(raw.weight);
 return {
 id: template.id,
 label: String(raw.label || template.label || '').trim() || template.label,
 source: String(raw.source || template.source || '').trim() || template.source,
 metric: String(raw.metric || template.metric || '').trim() || template.metric,
 window: String(raw.window || template.window || '').trim() || template.window,
 aggregation: String(raw.aggregation || template.aggregation || '').trim() || template.aggregation,
 weight: Number.isFinite(nextWeight) ? Number(nextWeight.toFixed(2)) : template.defaultWeight,
 operator: index === 0 ? 'base' : (String(raw.operator || template.defaultOperator || '+').trim() || '+'),
 };
 });
}

function kwBuildDashboardFormulaText(mode, components) {
 const list = Array.isArray(components) ? components : [];
 const fallback = kwGetDashboardSegmentConfig(mode).formula || '';
 if (!list.length) return fallback;
 return list.map((item, index) => {
 const weightText = Math.abs(Number(item.weight || 1) - 1) < 0.01 ? '' : ` x ${Number(item.weight || 1)}`;
 const prefix = index > 0 && item.operator && item.operator !== 'base' ? ` ${item.operator} ` : '';
 return `${prefix}${item.label || `组件 ${index + 1}`}${weightText}`;
 }).join('').trim() || fallback;
}

function kwBuildDashboardSourceList(mode, components, explicitSources) {
 const deduped = [];
 const pushSource = (source) => {
 const text = String(source || '').trim();
 if (text && !deduped.includes(text)) deduped.push(text);
 };
 (Array.isArray(explicitSources) ? explicitSources : []).forEach(pushSource);
 (Array.isArray(components) ? components : []).forEach(item => pushSource(item.source));
 if (!deduped.length) {
 kwGetDashboardComponentLibrary(mode).slice(0, 3).forEach(item => pushSource(item.source));
 }
 return deduped;
}

function kwSummarizeDashboardComponents(components) {
 return (Array.isArray(components) ? components : [])
 .map((item) => `${item.label || '组件'}${Math.abs(Number(item.weight || 1) - 1) < 0.01 ? '' : ` x${Number(item.weight || 1)}`}`)
 .join(' · ');
}

function kwBuildDashboardMetricSummaryList(components, limit) {
 const list = Array.isArray(components) ? components : [];
 const maxItems = Number(limit || 2);
 return list.slice(0, maxItems).map((item) => ({
 label: item.label || '组件',
 metric: item.metric || '--',
 }));
}

function kwBuildDashboardMetricCompactText(components, limit) {
 const list = Array.isArray(components) ? components : [];
 if (!list.length) return '点击查看详细指标构成';
 const maxItems = Number(limit || 2);
 const names = list.slice(0, maxItems).map((item) => item.label || '组件');
 const suffix = list.length > maxItems ? `等${list.length}项` : '';
 return `指标：${names.join('、')}${suffix}`;
}

function kwGetIndicatorDashboardSeedCards() {
 const items = ((window.WORKBENCH_DATA && window.WORKBENCH_DATA.indicator_hub && window.WORKBENCH_DATA.indicator_hub.smart_items) || [])
 .concat((window.WORKBENCH_DATA && window.WORKBENCH_DATA.indicator_hub && window.WORKBENCH_DATA.indicator_hub.lake_items) || []);
 return items.map((item) => ({
 name: item.name || '核心指标',
 value: item.value !== null && item.value !== undefined && String(item.value).trim() ? item.value : '--',
 assessment: item.assessment || item.alert || '继续观察',
 status: item.status || 'attention',
 alert: item.alert || '',
 hint: item.alert || item.assessment || '',
 prompt: `直接引用指标湖信号：${item.name || '核心指标'}，用于工作台和前台基本面首页。`,
 }));
}

function kwBuildFallbackDashboardCard(index) {
 const segment = kwGetDashboardSegmentConfig(kwDashboardStudioState.mode);
 const template = segment.cards[index % segment.cards.length];
 const components = kwBuildDefaultDashboardComponents(segment.id);
 return {
 mode: segment.id,
 segmentId: segment.id,
 name: template.name || `核心指标 ${index + 1}`,
 value: template.value || '待跟踪',
 assessment: template.assessment || '继续观察',
 status: template.status || 'attention',
 alert: '',
 hint: template.assessment || '',
 prompt: template.prompt || `围绕核心指标 ${index + 1} 生成适合普通投资者看的核心指标卡。`,
 components,
 formula: kwBuildDashboardFormulaText(segment.id, components),
 sources: kwBuildDashboardSourceList(segment.id, components),
 isEmpty: false,
 };
}

function kwGetDefaultDashboardCardMode(index) {
 const sequence = ['market', 'industry', 'signal-stock', 'signal-stock', 'market', 'industry', 'signal-stock', 'market'];
 return sequence[index % sequence.length];
}

function kwInferDashboardCardMode(card, fallbackMode) {
 const raw = card && typeof card === 'object' ? card : {};
 const explicit = raw.mode || raw.segmentId;
 if (explicit) {
 const normalized = String(explicit || '').trim().toLowerCase();
 return ['market', 'industry', 'signal-stock'].includes(normalized) ? normalized : 'market';
 }
 const text = [
 raw.name,
 raw.title,
 raw.prompt,
 raw.assessment,
 raw.hint,
 raw.alert,
 ].map(item => String(item || '').trim()).join(' ');
 if (/行业景气|行业订单|价格景气|库存节奏|景气验证|资本开支|竞争格局/.test(text)) return 'industry';
 if (/信号个股|龙头强度|业绩兑现|相对行业|催化临近|资金承接|估值位置/.test(text)) return 'signal-stock';
 if (/风险偏好|流动性|政策温度|市场广度|风格轮动|波动压力|主线热度/.test(text)) return 'market';
 return fallbackMode || 'market';
}

function kwBuildDashboardModeBreakdown(cards) {
 const counts = { market: 0, industry: 0, 'signal-stock': 0 };
 (Array.isArray(cards) ? cards : []).forEach((card, index) => {
 const mode = kwInferDashboardCardMode(card, kwGetDefaultDashboardCardMode(index));
 counts[mode] += 1;
 });
 return counts;
}

function kwBuildDashboardCompositionSummary(cards) {
 return Object.entries(kwBuildDashboardModeBreakdown(cards))
 .filter(([, count]) => count > 0)
 .map(([mode, count]) => `${kwGetDashboardSegmentConfig(mode).title} ${count}`)
 .join(' · ') || '市场状态卡 0';
}

function kwIsMixedDashboard(cards) {
 return Object.values(kwBuildDashboardModeBreakdown(cards)).filter(Boolean).length > 1;
}

function kwGetPrimaryDashboardMode(cards) {
 const ordered = Object.entries(kwBuildDashboardModeBreakdown(cards)).sort((a, b) => b[1] - a[1]);
 return ordered[0] && ordered[0][1] ? ordered[0][0] : 'market';
}

function kwBuildDashboardCardFromPrompt(promptText, index, mode) {
 const resolvedMode = mode || kwGetDefaultDashboardCardMode(index);
 const segment = kwGetDashboardSegmentConfig(resolvedMode);
 const base = segment.cards[index % segment.cards.length] || kwBuildFallbackDashboardCard(index);
 const components = kwNormalizeDashboardComponents(base.components, resolvedMode);
 return {
 mode: resolvedMode,
 segmentId: resolvedMode,
 name: base.name,
 value: base.value,
 assessment: base.assessment,
 status: base.status || 'attention',
 alert: '',
 hint: base.assessment || '',
 prompt: String(promptText || base.prompt || '').trim(),
 components,
 formula: kwBuildDashboardFormulaText(resolvedMode, components),
 sources: kwBuildDashboardSourceList(resolvedMode, components, base.sources),
 isEmpty: false,
 };
}

function kwEnsureDashboardStudioState() {
 const segment = kwGetDashboardSegmentConfig(kwDashboardStudioState.mode);
 if (!Array.isArray(kwDashboardStudioState.tags) || !kwDashboardStudioState.tags.length) {
 kwDashboardStudioState.tags = segment.tags.slice(0, 3);
 }
 kwDashboardStudioState.tags = kwDashboardStudioState.tags.filter((item) => segment.tags.includes(item));
 if (!kwDashboardStudioState.tags.length) kwDashboardStudioState.tags = segment.tags.slice(0, 3);
 if (!Array.isArray(kwDashboardStudioState.outputs) || !kwDashboardStudioState.outputs.length) {
 kwDashboardStudioState.outputs = segment.outputs.slice(0);
 }
 kwDashboardStudioState.outputs = segment.outputs.slice(0);
 kwDashboardStudioState.promptText = kwDashboardStudioState.promptText || segment.prompt;
}

function kwSelectDashboardMode(mode) {
 if (!KW_DASHBOARD_MODES.some((item) => item.id === mode)) return;
 kwDashboardStudioState.mode = mode;
 const segment = kwGetDashboardSegmentConfig(mode);
 kwDashboardStudioState.tags = segment.tags.slice(0, 3);
 kwDashboardStudioState.outputs = segment.outputs.slice(0);
 kwDashboardStudioState.promptText = segment.prompt;
 kwRenderDashboardPreview();
}

function kwGetDashboardSegmentConfig(mode) {
 return KW_DASHBOARD_MODES.find((item) => item.id === mode) || KW_DASHBOARD_MODES[0];
}

function kwToggleDashboardTag(tag) {
 const segment = kwGetDashboardSegmentConfig(kwDashboardStudioState.mode);
 if (!segment.tags.includes(tag)) return;
 const current = new Set(kwDashboardStudioState.tags || []);
 if (current.has(tag)) current.delete(tag); else current.add(tag);
 kwDashboardStudioState.tags = segment.tags.filter((item) => current.has(item));
 if (!kwDashboardStudioState.tags.length) kwDashboardStudioState.tags = segment.tags.slice(0, 1);
 kwRenderDashboardPreview();
}

function kwSetDashboardPromptText(value) {
 kwDashboardStudioState.promptText = String(value || '').trim();
}

function kwBuildDashboardCardsFromPrompts(layout, prompts, mode) {
 const target = kwGetDashboardCardTarget(layout);
 return Array.from({ length: target }, (_, index) => {
 const resolvedMode = mode || kwDashboardStudioState.mode;
 const segment = kwGetDashboardSegmentConfig(resolvedMode);
 const base = segment.cards[index % segment.cards.length];
 const prompt = String((prompts && prompts[index]) || base.prompt || '').trim();
 return kwBuildDashboardCardFromPrompt(prompt, index, resolvedMode);
 });
}

function kwBuildDashboardPromptPlan(layout) {
 kwEnsureDashboardStudioState();
 const segment = kwGetDashboardSegmentConfig(kwDashboardStudioState.mode);
 const target = kwGetDashboardCardTarget(layout);
 const tags = (kwDashboardStudioState.tags || []).join('、') || segment.tags.slice(0, 3).join('、');
 const outputs = (kwDashboardStudioState.outputs || []).join('、') || segment.outputs.join('、');
 return Array.from({ length: target }, (_, index) => {
 const card = segment.cards[index % segment.cards.length];
 return `${segment.title} · ${card.name} · 组合信号：${tags} · 输出：${outputs}`;
 });
}

function kwRenderDashboardModeRow() {
 const host = document.getElementById('kw-dashboard-mode-row');
 if (!host) return;
 host.innerHTML = KW_DASHBOARD_MODES.map((item) => `
 <button class="kw-dashboard-mode-card ${kwDashboardStudioState.mode === item.id ? 'active' : ''}" type="button" onclick="kwSelectDashboardMode('${item.id}')">
 <div class="kw-dashboard-mode-kicker">${escapeHtml(item.kicker || '')}</div>
 <div class="kw-dashboard-mode-title">${escapeHtml(item.title)}</div>
 <div class="kw-dashboard-mode-desc">${escapeHtml(item.desc)}</div>
 </button>
 `).join('');
}

