 const host = document.getElementById('kw-dashboard-config-panel');
 if (!host) return;
 const segment = kwGetDashboardSegmentConfig(kwDashboardStudioState.mode);
 host.innerHTML = `
 <div class="kw-dashboard-config-grid">
 <div>
 <div class="kw-dashboard-section-title">当前层问题</div>
