 <div class="kw-dashboard-section-title">重点信号</div>
 <div class="kw-dashboard-chip-row">
 ${segment.tags.map((item) => `
 <button class="kw-dashboard-chip ${(kwDashboardStudioState.tags || []).includes(item) ? 'active' : ''}" type="button" onclick="kwToggleDashboardTag('${item}')">${escapeHtml(item)}</button>
 `).join('')}
 </div>
 </div>
