 <textarea class="kw-dashboard-textarea" placeholder="${escapeAttr(segment.prompt)}" oninput="kwSetDashboardPromptText(this.value)">${escapeHtml(kwDashboardStudioState.promptText || '')}</textarea>
 </div>
