 <div class="kw-dashboard-section-title">当前结构化结果</div>
 <div class="kw-dashboard-logic-note">
 问题定义：${escapeHtml(segment.question || segment.title)}<br>
 评分口径：${escapeHtml(segment.scoreMethod || segment.formula)}<br>
 数据源：${escapeHtml(segment.sources.join(' / '))}<br>
 组合方式：${escapeHtml(segment.formula)}<br>
 输出口径：${escapeHtml(segment.outputs.join(' / '))}<br>
 分数映射：${escapeHtml((segment.thresholds || []).join(' / ') || '未设置')}
 </div>
