 ${escapeHtml((segment.factorRules || []).join('；') || '当前没有因子拆解说明。')}
 </div>
 <div class="kw-toolbar" style="margin-top:12px">
 <button class="btn-outline" type="button" onclick="kwGenerateFundDashboard(kwDashboardCurrentLayout || '2x2')">按当前配置生成草案</button>
 </div>
 </div>
 </div>
 `;
}

function kwRenderDashboardStrategyList() {
 const host = document.getElementById('kw-dashboard-strategy-list');
 if (!host) return;
 host.innerHTML = kwDashboardCurrentCards.map((card, index) => {
 const mode = kwInferDashboardCardMode(card, kwGetDefaultDashboardCardMode(index));
 const segment = kwGetDashboardSegmentConfig(mode);
 const formula = String(card.formula || '').trim() || kwBuildDashboardFormulaText(mode, card.components || []);
 const sources = kwBuildDashboardSourceList(mode, card.components || [], card.sources || []);
 return `
 <div class="kw-dashboard-strategy-card">
 <div class="kw-dashboard-strategy-title">${escapeHtml(segment.title)} · 组合单元 ${index + 1}</div>
 <div class="kw-dashboard-strategy-desc">${escapeHtml(card.prompt || `${segment.title} 提示词待补充`)}</div>
 <div class="kw-dashboard-strategy-meta">组件：${escapeHtml(kwSummarizeDashboardComponents(card.components || []) || '未配置')} · 数据源：${escapeHtml(sources.join(' / '))} · 算法块：${escapeHtml(formula)} · 输出：${escapeHtml(segment.outputs.join(' / '))}</div>
 </div>
 `;
 }).join('');
}

function kwRenderDashboardPublicPreview() {
 const host = document.getElementById('kw-dashboard-public-preview');
 if (!host) return;
 const cards = Array.isArray(kwDashboardCurrentCards) ? kwDashboardCurrentCards.slice(0, 3) : [];
 host.innerHTML = `
 <div class="kw-dashboard-public-list">
 ${cards.map((item, index) => `
 ${(() => {
 const mode = kwInferDashboardCardMode(item, kwGetDefaultDashboardCardMode(index));
 const segment = kwGetDashboardSegmentConfig(mode);
 return `
 <div class="kw-dashboard-public-card">
 <div class="kw-dashboard-public-title">${escapeHtml(item.name || `结果卡 ${index + 1}`)}</div>
 <div class="kw-dashboard-public-copy">${escapeHtml(item.assessment || '这是给粉丝直接看的算法结果卡。')}</div>
 <div class="kw-dashboard-public-value">${escapeHtml(item.value || '--')}</div>
 <div class="kw-dashboard-public-tag">${escapeHtml(segment.title)}${item.status === 'warning' ? ' · 警惕' : (item.status === 'normal' ? ' · 稳定' : ' · 关注')}</div>
 <div class="kw-dashboard-public-reasons">
 <div class="kw-dashboard-public-reason">• 当前卡片已按 ${escapeHtml(segment.title)} 口径生成结果</div>
 </div>
 <div class="kw-dashboard-public-meta">更新时间：刚刚 · ${escapeHtml(segment.fanNote)}</div>
 </div>
 `;
 })()}
 `).join('')}
 </div>
 `;
}

function kwHydrateDashboardConfig(config) {
 const source = config && typeof config === 'object' ? config : {};
 const layout = kwNormalizeDashboardLayout(source.layout || '2x2');
 const cards = Array.from({ length: kwGetDashboardCardTarget(layout) }, (_, index) => {
 const item = Array.isArray(source.cards) ? source.cards[index] : null;
 const mode = kwInferDashboardCardMode(item, kwGetDefaultDashboardCardMode(index));
 const segment = kwGetDashboardSegmentConfig(mode);
 const fallback = {
 ...segment.cards[index % segment.cards.length],
 mode,
 segmentId: mode,
 alert: '',
 hint: segment.cards[index % segment.cards.length].assessment || '',
 components: kwBuildDefaultDashboardComponents(mode),
 formula: kwBuildDashboardFormulaText(mode, kwBuildDefaultDashboardComponents(mode)),
 sources: kwBuildDashboardSourceList(mode, kwBuildDefaultDashboardComponents(mode)),
 isEmpty: false,
 };
 if (!item) return { ...fallback };
 const components = kwNormalizeDashboardComponents(item.components, mode);
 return {
 mode,
 segmentId: mode,
 name: item.name || fallback.name,
 value: item.value || fallback.value,
 assessment: item.assessment || fallback.assessment,
 status: item.status || fallback.status,
 alert: item.alert || fallback.alert,
 hint: item.hint || fallback.hint,
 prompt: item.prompt || fallback.prompt,
 components,
 formula: item.formula || kwBuildDashboardFormulaText(mode, components),
 sources: kwBuildDashboardSourceList(mode, components, item.sources || fallback.sources),
 isEmpty: !!item.isEmpty,
 };
 });
 const primaryMode = kwGetPrimaryDashboardMode(cards);
 const primarySegment = kwGetDashboardSegmentConfig(primaryMode);
 return {
 layout,
 mode: primaryMode,
 title: source.title || (kwIsMixedDashboard(cards) ? `今日核心指标面板 · 混合策略 · ${layout.toUpperCase()}` : `${primarySegment.title} · 今日核心指标面板`),
 note: source.note || source.summary || `当前面板支持按格子混搭。组合结构：${kwBuildDashboardCompositionSummary(cards)}。`,
 summary: source.summary || source.note || `当前面板支持按格子混搭。组合结构：${kwBuildDashboardCompositionSummary(cards)}。`,
 updatedAt: source.updatedAt || '刚刚同步',
 publisher: source.publisher || '系统',
 cards,
 };
}

function kwGetFundDashboardPublished() {
 return kwHydrateDashboardConfig((kwFundDashboardState && kwFundDashboardState.published) || (window.WORKBENCH_DATA && window.WORKBENCH_DATA.fund_dashboard) || {});
}

function kwGetFundDashboardDraft() {
 return kwFundDashboardState && kwFundDashboardState.draft ? kwHydrateDashboardConfig(kwFundDashboardState.draft) : null;
}

function kwRenderDashboardPreview() {
 const host = document.getElementById('kw-dashboard-preview');
 const metaHost = document.getElementById('kw-dashboard-meta');
 const tag = document.getElementById('kw-dashboard-layout-tag');
 if (!host) return;
 kwEnsureDashboardStudioState();
 const draft = kwGetFundDashboardDraft();
 const published = kwGetFundDashboardPublished();
 const active = draft || published;
 kwDashboardCurrentLayout = kwNormalizeDashboardLayout(active.layout || '2x2');
 kwDashboardCurrentCards = active && Array.isArray(active.cards) && active.cards.length
 ? active.cards.slice()
 : kwBuildDashboardCardsFromPrompts(kwDashboardCurrentLayout, [], kwDashboardStudioState.mode);
 const composition = kwBuildDashboardCompositionSummary(kwDashboardCurrentCards);
 if (tag) tag.textContent = `${kwDashboardCurrentLayout} · ${kwIsMixedDashboard(kwDashboardCurrentCards) ? '混合策略' : kwGetDashboardSegmentConfig(kwGetPrimaryDashboardMode(kwDashboardCurrentCards)).title}`;
 if (metaHost) {
 metaHost.textContent = draft
 ? `当前预览的是草稿版本 · ${composition} · ${kwDashboardCurrentLayout.toUpperCase()} · 前台 H5 基本面仍只展示已发布版本`
 : `当前展示已发布版本 · ${composition} · ${(published && published.updatedAt) || '刚刚同步'} · ${(published && published.publisher) || '系统发布'}`;
 }
 host.innerHTML = `
 <div class="kw-dashboard-canvas-note">当前仪表盘支持市场状态卡、行业景气卡、信号个股卡按格子混搭。组合结构：${escapeHtml(composition)}。</div>
 <div class="kw-cell-grid">
 ${kwDashboardCurrentCards.map((cell, index) => {
 const mode = kwInferDashboardCardMode(cell, kwGetDefaultDashboardCardMode(index));
 const segment = kwGetDashboardSegmentConfig(mode);
 const metricCompactText = kwBuildDashboardMetricCompactText(cell.components || [], 2);
 return `
 <div class="kw-cell-card" onclick="kwOpenDashboardCellModal(${index})" style="cursor:pointer">
 <div class="kw-cell-title">${escapeHtml(cell.name || `核心指标 ${index + 1}`)}</div>
 ${cell.value ? `<div class="kw-cell-value">${escapeHtml(cell.value)}</div>` : '<div class="kw-empty-plus">+</div>'}
 <div class="kw-cell-desc">${escapeHtml(cell.assessment || '每个格子是一个智能定义单元；点击后按独立提示词重新生成。')}</div>
 <div class="kw-dashboard-cell-inline-meta">
 <span class="kw-prompt-chip">${escapeHtml(segment.title)}</span>
 <span class="kw-prompt-chip">${escapeHtml(metricCompactText)}</span>
 </div>
 </div>
 `;
 }).join('')}
 </div>
 `;
 kwRenderDashboardModeRow();
 kwRenderDashboardConfigPanel();
 kwRenderDashboardStrategyList();
 kwRenderDashboardPublicPreview();
}

function kwOpenDashboardCellModal(index) {
 kwDashboardCurrentCards = Array.isArray(kwDashboardCurrentCards) ? kwDashboardCurrentCards : [];
 const card = kwDashboardCurrentCards[index];
 if (!card) return;
 kwDashboardCellEditingIndex = index;
 kwDashboardCellDraftMode = kwInferDashboardCardMode(card, kwGetDefaultDashboardCardMode(index));
 kwDashboardCellDraftPrompt = String(card.prompt || '').trim();
 kwDashboardCellDraftComponents = kwNormalizeDashboardComponents(card.components, kwDashboardCellDraftMode);
 kwRenderDashboardCellModal();
}

function kwSetDashboardCellMode(mode) {
 kwCaptureDashboardCellPromptDraft();
 if (kwDashboardCellDraftMode !== mode) {
 kwDashboardCellDraftMode = mode;
 kwDashboardCellDraftComponents = kwBuildDefaultDashboardComponents(mode);
 }
 kwRenderDashboardCellModal();
}

function kwCloseDashboardCellModal() {
 const modal = document.getElementById('kw-dashboard-cell-modal');
 if (modal) modal.classList.remove('show');
 kwDashboardCellEditingIndex = -1;
 kwDashboardCellDragIndex = -1;
}

function kwCaptureDashboardCellPromptDraft() {
 const input = document.getElementById('kw-dashboard-cell-prompt-input');
 if (input) kwDashboardCellDraftPrompt = input.value.trim();
}

