 `).join('');
 const componentLibrary = kwGetDashboardComponentLibrary(kwDashboardCellDraftMode);
 const selectedIds = kwDashboardCellDraftComponents.map(item => item.id);
 const formula = kwBuildDashboardFormulaText(kwDashboardCellDraftMode, kwDashboardCellDraftComponents);
 const sources = kwBuildDashboardSourceList(kwDashboardCellDraftMode, kwDashboardCellDraftComponents);
 host.innerHTML = `
 <div class="kw-review-modal-title">编辑智能格子</div>
 <div class="kw-review-runtime-desc" style="margin-top:6px">当前摘要：${escapeHtml(card.name || '未命名指标')} · ${escapeHtml(card.value || '--')}</div>
 <div class="kw-dashboard-cell-modal-grid">
 <div class="kw-dashboard-cell-summary">
 <div class="kw-dashboard-cell-summary-title">${escapeHtml(currentSegment.title)} · 白盒配置</div>
 <div class="kw-dashboard-cell-summary-desc">先选格子类型，再看组件库。提示词负责帮助系统判断该用哪一类组合模式；当前真正发布到 H5 的，是下面这套组件组合、公式和数据源。</div>
 </div>
 <div class="kw-dashboard-cell-block">
 <div class="kw-dashboard-section-title">格子类型</div>
 <div class="kw-dashboard-chip-row">${modeOptions}</div>
 </div>
 <div class="kw-dashboard-cell-block">
 <div class="kw-dashboard-section-title">白盒提示词</div>
 <div class="kw-dashboard-panel-note">提示词仍然保留，但不再是唯一配置。下面的组件组合可以直接点选、排序和微调。</div>
 <textarea id="kw-dashboard-cell-prompt-input" class="kw-knowledge-modal-textarea" placeholder="${escapeHtml(currentSegment.prompt)}">${escapeHtml(kwDashboardCellDraftPrompt || '')}</textarea>
 </div>
 <div class="kw-dashboard-cell-block">
 <div class="kw-dashboard-section-title">组件库</div>
 <div class="kw-dashboard-component-library">
 ${componentLibrary.map((item) => {
 const disabled = selectedIds.includes(item.id);
 return `
 <div class="kw-dashboard-component-option ${disabled ? 'disabled' : ''}">
 <div class="kw-dashboard-component-head">
 <div>
 <div class="kw-dashboard-component-title">${escapeHtml(item.label)}</div>
 <div class="kw-dashboard-component-meta">指标：${escapeHtml(item.metric)} · 窗口：${escapeHtml(item.window)} · 聚合：${escapeHtml(item.aggregation)}</div>
 </div>
 <span class="kw-dashboard-component-badge">${escapeHtml(item.source)}</span>
 </div>
 <div class="kw-dashboard-component-actions" style="margin-top:10px">
 <button class="btn-outline" type="button" ${disabled ? 'disabled' : ''} onclick="kwAddDashboardComponent('${escapeAttr(item.id)}')">${disabled ? '已加入' : '加入组合'}</button>
 </div>
 </div>
 `;
 }).join('')}
 </div>
 </div>
 <div class="kw-dashboard-cell-block">
 <div class="kw-dashboard-section-title">当前组合</div>
 <div class="kw-dashboard-panel-note">支持拖拽排序，也可以直接改组合符和权重。第一个组件固定为起始项。</div>
 <div class="kw-dashboard-component-list">
 ${kwDashboardCellDraftComponents.map((item, index) => `
 <div class="kw-dashboard-component-item" draggable="true" ondragstart="kwHandleDashboardComponentDragStart(${index})" ondragover="kwHandleDashboardComponentDragOver(event)" ondrop="kwHandleDashboardComponentDrop(${index})" ondragend="kwHandleDashboardComponentDragEnd()">
 <div class="kw-dashboard-component-head">
 <div>
 <div class="kw-dashboard-component-title">${escapeHtml(item.label || `组件 ${index + 1}`)}</div>
 <div class="kw-dashboard-component-meta">数据源：${escapeHtml(item.source || '--')} · 指标：${escapeHtml(item.metric || '--')} · 窗口：${escapeHtml(item.window || '--')}</div>
 </div>
 <span class="kw-dashboard-component-badge">${index === 0 ? '起始组件' : `第 ${index + 1} 项`}</span>
 </div>
 <div class="kw-dashboard-component-controls">
 <div class="kw-dashboard-component-field">
 <label>组合符</label>
 <select onchange="kwUpdateDashboardComponentField(${index}, 'operator', this.value)" ${index === 0 ? 'disabled' : ''}>
 <option value="+" ${item.operator === '+' ? 'selected' : ''}>+</option>
 <option value="-" ${item.operator === '-' ? 'selected' : ''}>-</option>
 <option value="*" ${item.operator === '*' ? 'selected' : ''}>*</option>
 <option value="/" ${item.operator === '/' ? 'selected' : ''}>/</option>
 </select>
 </div>
 <div class="kw-dashboard-component-field">
 <label>权重</label>
 <input type="number" min="0.1" max="3" step="0.1" value="${escapeAttr(item.weight)}" onchange="kwUpdateDashboardComponentField(${index}, 'weight', this.value)">
 </div>
 <div class="kw-dashboard-component-field">
 <label>窗口</label>
 <input type="text" value="${escapeAttr(item.window || '')}" onchange="kwUpdateDashboardComponentField(${index}, 'window', this.value)">
 </div>
 <div class="kw-dashboard-component-actions">
 <button class="btn-outline" type="button" onclick="kwMoveDashboardComponent(${index}, -1)" ${index === 0 ? 'disabled' : ''}>上移</button>
 <button class="btn-outline" type="button" onclick="kwMoveDashboardComponent(${index}, 1)" ${index === kwDashboardCellDraftComponents.length - 1 ? 'disabled' : ''}>下移</button>
 <button class="btn-outline" type="button" onclick="kwRemoveDashboardComponent(${index})" ${kwDashboardCellDraftComponents.length <= 1 ? 'disabled' : ''}>移除</button>
 </div>
 </div>
 </div>
 `).join('')}
 </div>
 <div class="kw-dashboard-formula-shell">
 <div class="kw-dashboard-formula-title">当前组合公式</div>
 <div class="kw-dashboard-formula-text">${escapeHtml(formula)}</div>
 <div class="kw-dashboard-source-row">
 ${sources.map((item) => `<span class="kw-dashboard-source-chip">${escapeHtml(item)}</span>`).join('')}
 </div>
 </div>
 </div>
 <div class="kw-toolbar" style="justify-content:flex-end">
 <button class="btn-outline" type="button" onclick="kwCloseDashboardCellModal()">取消</button>
 <button class="btn-gold" type="button" onclick="kwSaveDashboardCellPrompt()">保存并生成</button>
 </div>
 </div>
 `;
 modal.classList.add('show');
}

function kwAddDashboardComponent(componentId) {
 kwCaptureDashboardCellPromptDraft();
 const library = kwGetDashboardComponentLibrary(kwDashboardCellDraftMode);
 const template = library.find(item => item.id === componentId);
 if (!template || kwDashboardCellDraftComponents.some(item => item.id === componentId)) return;
 kwDashboardCellDraftComponents = kwNormalizeDashboardComponents([
 ...kwDashboardCellDraftComponents,
 {
 id: template.id,
 label: template.label,
 source: template.source,
 metric: template.metric,
 window: template.window,
 aggregation: template.aggregation,
 weight: template.defaultWeight,
 operator: kwDashboardCellDraftComponents.length ? '+' : 'base',
 },
 ], kwDashboardCellDraftMode);
 kwRenderDashboardCellModal();
}

function kwRemoveDashboardComponent(index) {
 if (kwDashboardCellDraftComponents.length <= 1) return;
 kwCaptureDashboardCellPromptDraft();
 kwDashboardCellDraftComponents = kwNormalizeDashboardComponents(
 kwDashboardCellDraftComponents.filter((_, componentIndex) => componentIndex !== index),
 kwDashboardCellDraftMode,
 );
 kwRenderDashboardCellModal();
}

function kwMoveDashboardComponent(index, direction) {
 const nextIndex = index + direction;
 if (nextIndex < 0 || nextIndex >= kwDashboardCellDraftComponents.length) return;
 kwCaptureDashboardCellPromptDraft();
 const nextList = kwDashboardCellDraftComponents.slice();
 const [moved] = nextList.splice(index, 1);
 nextList.splice(nextIndex, 0, moved);
 kwDashboardCellDraftComponents = kwNormalizeDashboardComponents(nextList, kwDashboardCellDraftMode);
 kwRenderDashboardCellModal();
}

function kwUpdateDashboardComponentField(index, field, value) {
 kwCaptureDashboardCellPromptDraft();
 kwDashboardCellDraftComponents = kwNormalizeDashboardComponents(
 kwDashboardCellDraftComponents.map((item, componentIndex) => {
 if (componentIndex !== index) return item;
 if (field === 'weight') return { ...item, weight: Number(value || item.weight || 1) };
 return { ...item, [field]: value };
 }),
 kwDashboardCellDraftMode,
 );
 kwRenderDashboardCellModal();
}

function kwHandleDashboardComponentDragStart(index) {
 kwDashboardCellDragIndex = index;
}

function kwHandleDashboardComponentDragOver(event) {
 if (event) event.preventDefault();
}

function kwHandleDashboardComponentDrop(index) {
 if (kwDashboardCellDragIndex < 0 || kwDashboardCellDragIndex === index) return;
 kwCaptureDashboardCellPromptDraft();
 const nextList = kwDashboardCellDraftComponents.slice();
 const [moved] = nextList.splice(kwDashboardCellDragIndex, 1);
 nextList.splice(index, 0, moved);
 kwDashboardCellDraftComponents = kwNormalizeDashboardComponents(nextList, kwDashboardCellDraftMode);
 kwDashboardCellDragIndex = -1;
 kwRenderDashboardCellModal();
}

function kwHandleDashboardComponentDragEnd() {
 kwDashboardCellDragIndex = -1;
}

async function kwSaveDashboardCellPrompt() {
 if (kwDashboardCellEditingIndex < 0) return;
 kwCaptureDashboardCellPromptDraft();
 const prompt = kwDashboardCellDraftPrompt;
 const layout = kwDashboardCurrentLayout || '2x2';
 const cards = kwDashboardCurrentCards.map((item, index) => {
 if (index === kwDashboardCellEditingIndex) {
 const nextCard = kwBuildDashboardCardFromPrompt(prompt, index, kwDashboardCellDraftMode);
 const components = kwNormalizeDashboardComponents(kwDashboardCellDraftComponents, kwDashboardCellDraftMode);
 return {
 ...nextCard,
 components,
 formula: kwBuildDashboardFormulaText(kwDashboardCellDraftMode, components),
 sources: kwBuildDashboardSourceList(kwDashboardCellDraftMode, components),
 };
 }
 return {
 ...item,
 mode: kwInferDashboardCardMode(item, kwGetDefaultDashboardCardMode(index)),
 segmentId: kwInferDashboardCardMode(item, kwGetDefaultDashboardCardMode(index)),
 };
 });
 const composition = kwBuildDashboardCompositionSummary(cards);
 const primaryMode = kwGetPrimaryDashboardMode(cards);
 const primarySegment = kwGetDashboardSegmentConfig(primaryMode);
 const nextDraft = {
 mode: primaryMode,
 layout,
 title: kwIsMixedDashboard(cards) ? `今日核心指标面板 · 混合策略 · ${layout.toUpperCase()}` : `${primarySegment.title} · 今日核心指标面板 · ${layout.toUpperCase()}`,
 note: `当前面板支持按格子混搭。组合结构：${composition}。`,
 summary: `当前面板支持按格子混搭。组合结构：${composition}。`,
 cards,
 updatedAt: '刚刚生成',
 publisher: (window.WORKBENCH_DATA && window.WORKBENCH_DATA.kol_name) || '当前大V',
 };
 await kwSyncFundDashboard('save_draft', nextDraft, '草稿已保存');
 kwCloseDashboardCellModal();
}

async function kwGenerateFundDashboard(layout) {
 // Compatibility bridge for the retired white-box editor. Dashboard cards
 // must now be created through the same smart-indicator flow as H5.
 const normalizedLayout = kwNormalizeDashboardLayout(layout || '2x2');
 await kwSelectSmartDashboardLayout(normalizedLayout);
 showToast('请点击空白格新增智能指标');
}

async function kwPublishFundDashboard() {
 const draft = kwGetFundDashboardDraft();
 if (!draft) {
 showToast('请先生成一个指标面板草稿');
 return;
 }
 await kwSyncFundDashboard('publish', draft, '已发布到前台 H5 和租户门户');
}

async function kwResetFundDashboardDraft() {
 await kwSyncFundDashboard('reset_draft', null, '已恢复到当前发布版');
}

async function kwSyncFundDashboard(action, dashboard, successMessage) {
 const tenantSlug = (window.ACTIVE_TENANT && window.ACTIVE_TENANT.slug) || '';
 if (!tenantSlug) throw new Error('tenant_missing');
 const resp = await fetch(`/api/tenant/${encodeURIComponent(tenantSlug)}/dashboard`, {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify({
 action,
 dashboard: dashboard || null,
 }),
 });
 const payload = await resp.json();
 if (!resp.ok || !payload.success) throw new Error(payload.error || 'dashboard_sync_failed');
 kwFundDashboardState = JSON.parse(JSON.stringify(payload.fund_dashboard_state || ((payload.dashboard || {}).fund_dashboard_state) || {}));
 if (window.WORKBENCH_DATA) {
 window.WORKBENCH_DATA.fund_dashboard_state = JSON.parse(JSON.stringify(kwFundDashboardState || {}));
 if (payload.dashboard && payload.dashboard.fund_dashboard) {
 window.WORKBENCH_DATA.fund_dashboard = JSON.parse(JSON.stringify(payload.dashboard.fund_dashboard));
 } else if (kwFundDashboardState.published) {
 window.WORKBENCH_DATA.fund_dashboard = JSON.parse(JSON.stringify(kwFundDashboardState.published));
 }
 }
 kwRenderDashboardPreview();
 try {
 window.localStorage?.setItem(SITE_CONFIG_BROADCAST_KEY, String(Date.now()));
 } catch (error) {}
 showToast(successMessage || '已同步');
 return payload;
}

function renderWorkbenchBizCharts() {
 if (window.initDashboardCharts) {
 window.initDashboardCharts(window.dashboardDefaultSection || 'funnel');
 }
}

function showWorkbenchAnalyticsSection(section) {
 if (document.getElementById('kw-biz-dynamic-root')) {
 window.dashboardDefaultSection = section;
 renderKwBizDashboardCharts(section);
 return;
 }
 document.querySelectorAll('.dash-section').forEach(node => node.classList.remove('active'));
 const target = document.getElementById('ds-' + section);
 if (target) target.classList.add('active');
 document.querySelectorAll('#nav-funnel, #nav-channel, #nav-revenue, #nav-segment').forEach(node => node.classList.remove('active'));
 const nav = document.getElementById('nav-' + section);
 if (nav) nav.classList.add('active');
 const topbar = document.getElementById('topbar-title');
 const titleMap = {
 funnel: '多渠道多圈层转化分析',
 channel: '渠道分析',
 revenue: '营收趋势',
 segment: '用户分层分析',
 };
 if (topbar) topbar.textContent = titleMap[section] || '多渠道多圈层转化分析';
 window.dashboardDefaultSection = section;
 if (window.initDashboardCharts) {
 window.initDashboardCharts(section);
 }
}

function escapeHtml(value) {
 return String(value || '')
 .replace(/&/g, '&amp;')
 .replace(/</g, '&lt;')
 .replace(/>/g, '&gt;')
 .replace(/"/g, '&quot;')
 .replace(/'/g, '&#39;');
}

function formatDashboardDataDate(value) {
 const text = String(value || '').trim();
 if (!text) return '未记录';
 const compact = text.match(/^(\d{4})(\d{2})(\d{2})(?:\s+\d+)?$/);
 if (compact) return `${compact[1]}-${compact[2]}-${compact[3]}`;
 const separated = text.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);
 if (separated) return `${separated[1]}-${String(separated[2]).padStart(2, '0')}-${String(separated[3]).padStart(2, '0')}`;
 return text;
}

function escapeAttr(value) {
 return escapeHtml(value);
}

function kwGetPortalModuleLabel(moduleId) {
 const map = {
 hero: '门户介绍区',
 dashboard: '固定 Dashboard',
 'custom-copy': '自定义文案区',
 contact: '扫码与联系方式',
 };
 return map[moduleId] || moduleId || '模块';
}

