let kwPortalFocusedEditor = null;
let kwFans = Array.isArray((window.WORKBENCH_DATA && window.WORKBENCH_DATA.fan_management && window.WORKBENCH_DATA.fan_management.fans))
 ? window.WORKBENCH_DATA.fan_management.fans.map((fan) => ({
