function kwGetPortalBlocks() {
 if (!Array.isArray(kwPortalWorkspaceDraft.page_blocks)) kwPortalWorkspaceDraft.page_blocks = [];
 return kwPortalWorkspaceDraft.page_blocks;
}

function kwGetPortalBlockById(blockId) {
 return kwGetPortalBlocks().find((item) => item.id === blockId) || null;
}

function kwEnsurePortalSelection() {
 const blocks = kwGetPortalBlocks();
 const enabledBlocks = blocks.filter((item) => item.enabled !== false);
 if (!enabledBlocks.length) {
 kwPortalSelectedBlockId = null;
 return null;
 }
 if (!kwPortalSelectedBlockId || !enabledBlocks.some((item) => item.id === kwPortalSelectedBlockId)) {
 kwPortalSelectedBlockId = enabledBlocks[0].id;
 }
 return kwPortalSelectedBlockId;
}

function kwSelectPortalBlock(blockId) {
 kwPortalSelectedBlockId = blockId;
 if (document.getElementById('workbench-section-portal')) kwRenderPortalWorkspace();
}

function kwHandlePortalBlockClick(event, blockId) {
 if (event && event.target && event.target.closest && event.target.closest('.kw-portal-editable')) return;
 kwSelectPortalBlock(blockId);
}

function kwHandlePortalEditableFocus(event, el) {
 if (event && typeof event.stopPropagation === 'function') event.stopPropagation();
 kwPortalFocusedEditor = el || null;
}

function kwPortalMarkDraft(status) {
 kwPortalWorkspaceDraft.draft_status = status || '草稿编辑中';
}

function kwGetPortalSubscriptionPromo() {
 if (!kwPortalWorkspaceDraft.subscription_promo || typeof kwPortalWorkspaceDraft.subscription_promo !== 'object') {
 kwPortalWorkspaceDraft.subscription_promo = {};
 }
 const promo = kwPortalWorkspaceDraft.subscription_promo;
 if (!Array.isArray(promo.benefits)) promo.benefits = ['', '', ''];
 while (promo.benefits.length < 3) promo.benefits.push('');
 if (!promo.primary_cta_label) promo.primary_cta_label = '立即订阅';
 return promo;
}

function kwUpdatePortalSubscriptionEnabled(enabled) {
 kwGetPortalSubscriptionPromo().enabled = !!enabled;
 kwPortalMarkDraft(enabled ? '订阅宣传待完善' : '草稿编辑中');
