}

function kwUpdatePortalSubscriptionRichHtml(value) {
 kwGetPortalSubscriptionPromo().rich_html = kwNormalizePortalHtml(value);
 kwPortalMarkDraft('订阅宣传编辑中');
 kwPortalSyncPanels();
}

function kwPortalHandleSubscriptionPaste(event) {
 const editor = event.currentTarget;
 const clipboard = event.clipboardData;
 if (!editor || !clipboard) return;
 const imageItem = Array.from(clipboard.items || []).find((item) => item.type && item.type.startsWith('image/'));
 const insert = (html) => {
 editor.focus();
 document.execCommand('insertHTML', false, html);
 kwUpdatePortalSubscriptionRichHtml(editor.innerHTML);
 };
 if (imageItem) {
 event.preventDefault();
 const file = imageItem.getAsFile();
 if (!file) return;
 const reader = new FileReader();
 reader.onload = () => insert(`<p><img src="${reader.result}" alt="订阅宣传海报"></p>`);
 reader.readAsDataURL(file);
 return;
 }
 const html = clipboard.getData('text/html');
 const text = clipboard.getData('text/plain');
 if (html || text) {
 event.preventDefault();
 insert(html || `<p>${escapeHtml(text).replace(/\n/g, '<br>')}</p>`);
 }
}

function kwRenderPortalSubscriptionPromo() {
 const host = document.getElementById('kw-portal-subscription-editor');
 const summaryHost = document.getElementById('kw-portal-subscription-summary');
 const enabledInput = document.getElementById('kw-portal-subscription-enabled');
 const promo = kwGetPortalSubscriptionPromo();
 const products = Array.isArray((window.WORKBENCH_DATA || {}).subscription_products)
 ? window.WORKBENCH_DATA.subscription_products : [];
 if (enabledInput) enabledInput.checked = !!promo.enabled;
 if (summaryHost) {
 const product = products.find((item) => Number(item.id) === Number(promo.product_id));
 summaryHost.textContent = promo.enabled
 ? (product ? `已开启 · ${product.name} · ¥${Number(product.price_yuan).toFixed(2)} / ${product.billing_period_days}天` : '已开启 · 请先选择一个已启用订阅套餐')
 : '未开启。开启后将在公开门户展示订阅权益和购买入口。';
 }
 if (!host) return;
 host.innerHTML = `
 <label><div class="kw-portal-inspector-label">订阅标题</div><input class="kw-portal-inspector-input" value="${escapeAttr(promo.headline || '')}" placeholder="例如：订阅后，持续获得更完整的研究洞见" oninput="kwUpdatePortalSubscriptionField('headline', this.value)"></label>
 <label><div class="kw-portal-inspector-label">定位与适合人群</div><textarea class="kw-portal-inspector-textarea" placeholder="说明你提供什么、适合谁订阅" oninput="kwUpdatePortalSubscriptionField('positioning', this.value)">${escapeHtml(promo.positioning || '')}</textarea></label>
 <div><div class="kw-portal-inspector-label">订阅权益（至少三项）</div><div style="display:grid;gap:8px;margin-top:7px">${[0, 1, 2].map((index) => `<input class="kw-portal-inspector-input" value="${escapeAttr(promo.benefits[index] || '')}" placeholder="权益 ${index + 1}" oninput="kwUpdatePortalSubscriptionBenefit(${index}, this.value)">`).join('')}</div></div>
 <label><div class="kw-portal-inspector-label">推广套餐</div><select class="kw-portal-inspector-input" onchange="kwUpdatePortalSubscriptionProduct(this.value)"><option value="">请选择已启用订阅套餐</option>${products.map((item) => `<option value="${Number(item.id)}" ${Number(item.id) === Number(promo.product_id) ? 'selected' : ''}>${escapeHtml(item.name)} · ¥${Number(item.price_yuan).toFixed(2)} / ${Number(item.billing_period_days)}天</option>`).join('')}</select></label>
 <label><div class="kw-portal-inspector-label">订阅按钮文案</div><input class="kw-portal-inspector-input" value="${escapeAttr(promo.primary_cta_label || '立即订阅')}" oninput="kwUpdatePortalSubscriptionField('primary_cta_label', this.value)"></label>
 <div><div class="kw-portal-inspector-label">宣传富文本 / 海报</div><div class="kw-portal-empty-note">可直接粘贴知识星球海报截图，或编辑标题、段落、列表和链接。发布时会进行安全清洗。</div><div class="kw-portal-rich-editor kw-portal-editable" contenteditable="true" data-placeholder="粘贴宣传海报，或写订阅介绍和服务说明" oninput="kwUpdatePortalSubscriptionRichHtml(this.innerHTML)" onpaste="kwPortalHandleSubscriptionPaste(event)">${promo.rich_html || ''}</div></div>
 ${!products.length ? '<div class="kw-portal-empty-note">当前没有已启用的订阅套餐。请先到“粉丝订阅与收款”创建并启用套餐。</div>' : ''}
 `;
}

function kwPortalGetBlockSummary(block) {
 if (!block) return '';
 if (block.type === 'hero') {
 const hero = kwPortalWorkspaceDraft.hero || {};
 return hero.description || hero.audience || '请先维护门户导语。';
 }
 if (block.type === 'dashboard') return '固定展示核心指标、Dashboard 面板和代表性内容。';
 if (block.type === 'contact') {
 const contact = kwPortalWorkspaceDraft.contact || {};
 return `${contact.wechat || '未设置微信'} / ${contact.phone || '未设置电话'} / ${contact.email || '未设置邮箱'}`;
 }
 const temp = document.createElement('div');
 temp.innerHTML = block.html || '';
 return (temp.textContent || temp.innerText || '').trim() || '请补充正文内容。';
}

