 <button class="kw-portal-mini-btn" type="button" onclick="event.stopPropagation();kwMovePortalBlock(${index}, 1)">下移</button>
 <button class="kw-portal-mini-btn" type="button" onclick="event.stopPropagation();kwTogglePortalBlock(${index})">${item.enabled === false ? '重新展示' : '暂时隐藏'}</button>
 </div>
 </div>
 `).join('');
}

function kwPortalRenderHeroBlock(block) {
 const hero = kwPortalWorkspaceDraft.hero || {};
 const cta = kwPortalWorkspaceDraft.cta || {};
 const props = Array.isArray(hero.value_props) ? hero.value_props : [];
 return `
 <div class="kw-portal-block-head">
 <div>
 <div class="kw-portal-block-title">${escapeHtml(block.title || '门户介绍')}</div>
