 <div class="kw-portal-hero-title kw-portal-editable" contenteditable="true" data-placeholder="输入门户标题" onfocus="kwHandlePortalEditableFocus(event, this)" oninput="kwUpdatePortalDraft('headline', this.textContent)" onblur="kwPortalSyncPanels()">${escapeHtml(hero.headline || '')}</div>
 <div class="kw-portal-hero-desc kw-portal-editable" contenteditable="true" data-placeholder="输入门户导语" onfocus="kwHandlePortalEditableFocus(event, this)" oninput="kwUpdatePortalDraft('description', this.textContent)" onblur="kwPortalSyncPanels()">${escapeHtml(hero.description || '')}</div>
 <div class="kw-portal-hero-audience kw-portal-editable" contenteditable="true" data-placeholder="输入适合谁先看" onfocus="kwHandlePortalEditableFocus(event, this)" oninput="kwUpdatePortalDraft('audience', this.textContent)" onblur="kwPortalSyncPanels()">${escapeHtml(hero.audience || '')}</div>
 <div class="kw-portal-hero-props">
 ${[0, 1, 2].map((index) => `
 <div class="kw-portal-hero-prop kw-portal-editable" contenteditable="true" data-placeholder="输入价值主张" onfocus="kwHandlePortalEditableFocus(event, this)" oninput="kwUpdatePortalArrayField('value_props', ${index}, this.textContent)" onblur="kwPortalSyncPanels()">${escapeHtml(props[index] || '')}</div>
 `).join('')}
 </div>
 <div class="kw-portal-hero-cta-row">
 <div class="kw-portal-cta-chip kw-portal-editable" contenteditable="true" data-placeholder="主 CTA" onfocus="kwHandlePortalEditableFocus(event, this)" oninput="kwUpdatePortalDraft('primaryCta', this.textContent)" onblur="kwPortalSyncPanels()">${escapeHtml(cta.primary_label || '')}</div>
 <div class="kw-portal-cta-chip kw-portal-editable" contenteditable="true" data-placeholder="次 CTA" onfocus="kwHandlePortalEditableFocus(event, this)" oninput="kwUpdatePortalDraft('secondaryCta', this.textContent)" onblur="kwPortalSyncPanels()">${escapeHtml(cta.secondary_label || '')}</div>
 </div>
 `;
}

function kwPortalRenderDashboardBlock(block) {
 const metrics = ((window.WORKBENCH_DATA || {}).dashboard_metrics || {}).kpis || [];
 const fundDashboard = (window.WORKBENCH_DATA || {}).fund_dashboard || {};
 const cells = Array.isArray(fundDashboard.cells) ? fundDashboard.cells : [];
 const reviews = ((window.WORKBENCH_DATA || {}).published_reviews || []).slice(0, 2);
 return `
 <div class="kw-portal-block-head">
 <div>
 <div class="kw-portal-block-title">${escapeHtml(block.title || '固定 Dashboard')}</div>
