 <div class="kw-portal-rich-editor kw-portal-editable" contenteditable="true" data-placeholder="输入正文内容，可插入段落、小标题、表格和截图" onfocus="kwHandlePortalEditableFocus(event, this)" oninput="kwUpdatePortalBlockHtml('${escapeAttr(block.id)}', this.innerHTML)" onpaste="kwPortalHandlePaste(event, '${escapeAttr(block.id)}')" onblur="kwPortalSyncPanels()">${block.html || ''}</div>
