function kwPortalRenderCanvas() {
 const canvas = document.getElementById('kw-portal-page-canvas');
 if (!canvas) return;
 const blocks = kwGetPortalBlocks().filter((item) => item.enabled !== false);
 kwEnsurePortalSelection();
 canvas.innerHTML = blocks.map((block) => {
 let content = '';
 if (block.type === 'hero') content = kwPortalRenderHeroBlock(block);
 if (block.type === 'dashboard') content = kwPortalRenderDashboardBlock(block);
 if (block.type === 'rich_text') content = kwPortalRenderRichTextBlock(block);
 if (block.type === 'contact') content = kwPortalRenderContactBlock(block);
 return `
 <div class="kw-portal-page-block ${block.id === kwPortalSelectedBlockId ? 'active' : ''} ${block.type !== 'rich_text' ? 'is-fixed' : ''}" onclick="kwHandlePortalBlockClick(event, '${escapeAttr(block.id)}')">
 ${content}
 </div>
 `;
 }).join('');
}

function kwPortalRenderInspector() {
 const host = document.getElementById('kw-portal-inspector');
 if (!host) return;
 const block = kwGetPortalBlockById(kwEnsurePortalSelection());
 if (!block) {
 host.innerHTML = '<div class="kw-portal-empty-note">当前没有可编辑区块。</div>';
 return;
 }
 const hero = kwPortalWorkspaceDraft.hero || {};
 const contact = kwPortalWorkspaceDraft.contact || {};
 if (block.type === 'rich_text') {
 host.innerHTML = `
 <div>
