 <input class="kw-portal-inspector-input" type="text" value="${escapeAttr(block.title || '')}" oninput="kwUpdatePortalBlockTitle('${escapeAttr(block.id)}', this.value)">
 </label>
 <label>
 <div class="kw-portal-inspector-label">HTML 结构</div>
 <textarea class="kw-portal-inspector-textarea" oninput="kwUpdatePortalBlockHtml('${escapeAttr(block.id)}', this.value)">${escapeHtml(block.html || '')}</textarea>
 </label>
 <div class="kw-portal-empty-note">支持 p、h2、h3、ul、ol、li、strong、em、blockquote、a。</div>
 `;
 return;
 }
 if (block.type === 'hero') {
 host.innerHTML = `
 <div>
 <div class="kw-portal-inspector-label">当前区块</div>
 <div class="kw-portal-inspector-value">门户介绍区</div>
 </div>
 <div>
 <div class="kw-portal-inspector-label">当前标题</div>
 <div class="kw-portal-inspector-value">${escapeHtml(hero.headline || '')}</div>
 </div>
 <div class="kw-portal-empty-note">首屏建议先讲“你是谁、看什么、为什么值得关注”。标题和导语请直接在中间画布修改。</div>
 `;
 return;
 }
 if (block.type === 'dashboard') {
 host.innerHTML = `
 <div>
 <div class="kw-portal-inspector-label">当前区块</div>
 <div class="kw-portal-inspector-value">固定 Dashboard</div>
 </div>
 <div class="kw-portal-empty-note">这一段不开放自由编辑，固定承接研究和经营摘要，避免门户和 Dashboard 概念混淆。</div>
 `;
 return;
 }
 host.innerHTML = `
 <div>
 <div class="kw-portal-inspector-label">当前区块</div>
 <div class="kw-portal-inspector-value">扫码与联系方式</div>
 </div>
 <div>
 <div class="kw-portal-inspector-label">微信助手</div>
 <div class="kw-portal-inspector-value">${escapeHtml(contact.wechat || '')}</div>
 </div>
 <div>
 <div class="kw-portal-inspector-label">联系电话</div>
 <div class="kw-portal-inspector-value">${escapeHtml(contact.phone || '')}</div>
 </div>
 <div>
 <div class="kw-portal-inspector-label">联系邮箱</div>
 <div class="kw-portal-inspector-value">${escapeHtml(contact.email || '')}</div>
 </div>
 `;
}

function kwRenderPortalWorkspace() {
 const moduleHost = document.getElementById('kw-portal-module-list');
 const previewHost = document.getElementById('kw-portal-preview-list');
 const draftStatus = document.getElementById('kw-portal-draft-status');
 if (!moduleHost || !previewHost) return;
 if (draftStatus) draftStatus.textContent = kwPortalWorkspaceDraft.draft_status || '草稿待发布';
 kwRenderPortalSubscriptionPromo();
 kwPortalRenderOutline(moduleHost);
 kwPortalRenderCanvas();
 kwPortalRenderInspector();
 const hero = kwPortalWorkspaceDraft.hero || {};
 const cta = kwPortalWorkspaceDraft.cta || {};
 const blocks = kwGetPortalBlocks().filter((item) => item.enabled !== false);
 previewHost.innerHTML = [
 {
 title: hero.headline || '未设置门户标题',
 label: '粉丝打开后看到的首屏',
 copy: hero.description || '请先补充门户说明。',
 extra: hero.audience || '适合谁先看',
 chip: `${cta.primary_label || '主 CTA'} / ${cta.secondary_label || '次 CTA'}`,
 },
 ...(kwGetPortalSubscriptionPromo().enabled ? [{
 title: kwGetPortalSubscriptionPromo().headline || '订阅宣传待完善',
 label: '公开订阅转化区',
 copy: kwGetPortalSubscriptionPromo().positioning || '请补充订阅定位与适合人群。',
 extra: `${kwGetPortalSubscriptionPromo().benefits.filter(Boolean).length} / 3 项权益已填写`,
 chip: '订阅 CTA',
 }] : []),
 ...blocks.map(item => ({
 title: item.title || kwGetPortalModuleLabel(item.type),
 label: item.type === 'rich_text' ? '富文本内容区' : '固定门户结构',
 copy: kwPortalGetBlockSummary(item),
 extra: item.type === 'dashboard' ? '固定中段展示' : kwGetPortalModuleLabel(item.type),
 chip: item.type === 'rich_text' ? '可编辑文案' : (item.type || '模块'),
 })),
 ].map((item, index) => `
 <div class="kw-portal-preview-card ${index === 0 ? 'active' : ''}">
 <div class="kw-portal-preview-top">
 <div>
 <div class="kw-portal-preview-title">${escapeHtml(item.title)}</div>
 <div class="kw-portal-preview-label">${escapeHtml(item.label)}</div>
 </div>
 <span class="kw-tag">${escapeHtml(item.chip)}</span>
 </div>
 <div class="kw-portal-preview-copy">${escapeHtml(item.copy)}</div>
 <div class="kw-portal-preview-chip">${escapeHtml(item.extra)}</div>
 ${index === 0 ? `<div class="kw-portal-preview-route">当前路由：/tenant/${escapeHtml((window.ACTIVE_TENANT && window.ACTIVE_TENANT.slug) || '')}</div>` : ''}
 </div>
 `).join('');
}

function kwUpdatePortalDraft(field, value) {
 if (!kwPortalWorkspaceDraft.hero) kwPortalWorkspaceDraft.hero = {};
 if (!kwPortalWorkspaceDraft.cta) kwPortalWorkspaceDraft.cta = {};
 if (field === 'headline') kwPortalWorkspaceDraft.hero.headline = value;
 if (field === 'description') kwPortalWorkspaceDraft.hero.description = value;
 if (field === 'audience') kwPortalWorkspaceDraft.hero.audience = value;
 if (field === 'primaryCta') kwPortalWorkspaceDraft.cta.primary_label = value;
 if (field === 'secondaryCta') kwPortalWorkspaceDraft.cta.secondary_label = value;
 kwPortalMarkDraft('草稿编辑中');
}

function kwUpdatePortalArrayField(field, index, value) {
 if (!kwPortalWorkspaceDraft.hero) kwPortalWorkspaceDraft.hero = {};
 if (!Array.isArray(kwPortalWorkspaceDraft.hero[field])) kwPortalWorkspaceDraft.hero[field] = [];
 kwPortalWorkspaceDraft.hero[field][index] = value;
 kwPortalMarkDraft('草稿编辑中');
}

function kwUpdatePortalBlockTitle(blockId, value) {
 const block = kwGetPortalBlockById(blockId);
 if (!block) return;
 block.title = value;
 kwPortalMarkDraft('草稿编辑中');
}

function kwNormalizePortalHtml(html) {
 return String(html || '')
 .replace(/<div>/gi, '<p>')
 .replace(/<\/div>/gi, '</p>')
 .replace(/<p><br><\/p>/gi, '<p></p>');
}

function kwPortalGetFocusedBlockId() {
 if (!kwPortalFocusedEditor || !kwPortalFocusedEditor.closest) return '';
 const card = kwPortalFocusedEditor.closest('.kw-portal-page-block');
 if (!card) return '';
 const raw = card.getAttribute('onclick') || '';
 const match = /kwHandlePortalBlockClick\(event, '([^']+)'\)/.exec(raw);
 return match && match[1] ? match[1] : '';
}

function kwPortalCommitFocusedEditor() {
 const blockId = kwPortalGetFocusedBlockId();
 if (!blockId || !kwPortalFocusedEditor) return;
 if (kwPortalFocusedEditor.classList.contains('kw-portal-rich-title')) {
 kwUpdatePortalBlockTitle(blockId, kwPortalFocusedEditor.textContent);
 } else if (kwPortalFocusedEditor.classList.contains('kw-portal-rich-editor')) {
 kwUpdatePortalBlockHtml(blockId, kwPortalFocusedEditor.innerHTML);
 }
}

function kwPortalInsertHtml(html) {
 if (!kwPortalFocusedEditor) return;
 kwPortalFocusedEditor.focus();
 document.execCommand('insertHTML', false, html);
 kwPortalCommitFocusedEditor();
 kwPortalSyncPanels();
}

function kwPortalInsertTable() {
 kwPortalInsertHtml('<table><thead><tr><th>列 1</th><th>列 2</th></tr></thead><tbody><tr><td>内容</td><td>内容</td></tr><tr><td>内容</td><td>内容</td></tr></tbody></table>');
}

function kwPortalInsertLink() {
 if (!kwPortalFocusedEditor) return;
 const url = window.prompt('输入链接地址');
 if (!url) return;
 kwPortalFocusedEditor.focus();
 document.execCommand('createLink', false, url);
 kwPortalCommitFocusedEditor();
 kwPortalSyncPanels();
}

function kwPortalHandlePaste(event, blockId) {
 const clipboard = event.clipboardData;
 if (!clipboard) return;
 const items = Array.from(clipboard.items || []);
 const imageItem = items.find((item) => item.type && item.type.startsWith('image/'));
 if (imageItem) {
 event.preventDefault();
 const file = imageItem.getAsFile();
 if (!file) return;
 const reader = new FileReader();
 reader.onload = () => {
 kwPortalInsertHtml(`<p><img src="${reader.result}" alt="pasted-image"></p>`);
 };
 reader.readAsDataURL(file);
 return;
 }
 const html = clipboard.getData('text/html');
 if (html) {
 event.preventDefault();
 kwPortalInsertHtml(html);
 return;
 }
 const text = clipboard.getData('text/plain');
 if (text) {
 event.preventDefault();
 kwPortalInsertHtml(`<p>${escapeHtml(text).replace(/\n/g, '<br>')}</p>`);
 }
}

function kwUpdatePortalBlockHtml(blockId, html) {
 const block = kwGetPortalBlockById(blockId);
 if (!block) return;
 block.html = kwNormalizePortalHtml(html);
 kwPortalMarkDraft('草稿编辑中');
}

function kwUpdatePortalContact(field, value) {
 if (!kwPortalWorkspaceDraft.contact) kwPortalWorkspaceDraft.contact = {};
 kwPortalWorkspaceDraft.contact[field] = value;
 kwPortalMarkDraft('草稿编辑中');
}

function kwPortalSyncPanels() {
 const draftStatus = document.getElementById('kw-portal-draft-status');
 if (draftStatus) draftStatus.textContent = kwPortalWorkspaceDraft.draft_status || '草稿待发布';
 const previewHost = document.getElementById('kw-portal-preview-list');
 const moduleHost = document.getElementById('kw-portal-module-list');
 if (moduleHost) kwPortalRenderOutline(moduleHost);
 if (!previewHost) return;
 const hero = kwPortalWorkspaceDraft.hero || {};
 const cta = kwPortalWorkspaceDraft.cta || {};
 const blocks = kwGetPortalBlocks().filter((item) => item.enabled !== false);
 previewHost.innerHTML = [
 {
 title: hero.headline || '未设置门户标题',
 label: '粉丝打开后看到的首屏',
 copy: hero.description || '请先补充门户说明。',
 extra: hero.audience || '适合谁先看',
 chip: `${cta.primary_label || '主 CTA'} / ${cta.secondary_label || '次 CTA'}`,
 },
 ...blocks.map(item => ({
 title: item.title || kwGetPortalModuleLabel(item.type),
 label: item.type === 'rich_text' ? '富文本内容区' : '固定门户结构',
 copy: kwPortalGetBlockSummary(item),
 extra: item.type === 'dashboard' ? '固定中段展示' : kwGetPortalModuleLabel(item.type),
 chip: item.type === 'rich_text' ? '可编辑文案' : (item.type || '模块'),
 })),
 ].map((item, index) => `
 <div class="kw-portal-preview-card ${index === 0 ? 'active' : ''}">
 <div class="kw-portal-preview-top">
 <div>
 <div class="kw-portal-preview-title">${escapeHtml(item.title)}</div>
 <div class="kw-portal-preview-label">${escapeHtml(item.label)}</div>
 </div>
 <span class="kw-tag">${escapeHtml(item.chip)}</span>
 </div>
 <div class="kw-portal-preview-copy">${escapeHtml(item.copy)}</div>
 <div class="kw-portal-preview-chip">${escapeHtml(item.extra)}</div>
 ${index === 0 ? `<div class="kw-portal-preview-route">当前路由：/tenant/${escapeHtml((window.ACTIVE_TENANT && window.ACTIVE_TENANT.slug) || '')}</div>` : ''}
 </div>
 `).join('');
 kwPortalRenderInspector();
}

function kwMovePortalBlock(index, offset) {
 const blocks = kwGetPortalBlocks();
 const target = index + offset;
 if (index < 0 || index >= blocks.length || target < 0 || target >= blocks.length) return;
 const current = blocks[index];
 blocks[index] = blocks[target];
 blocks[target] = current;
 kwPortalMarkDraft('草稿已调整排序');
 if (document.getElementById('workbench-section-portal')) kwRenderPortalWorkspace();
}

function kwTogglePortalBlock(index) {
 const blocks = kwGetPortalBlocks();
 const item = blocks[index];
 if (!item) return;
 item.enabled = item.enabled === false;
 kwPortalMarkDraft(item.enabled === false ? '草稿中有隐藏模块' : '草稿编辑中');
 kwRenderPortalWorkspace();
}

function kwBuildPortalCustomSectionsFromBlocks() {
 return kwGetPortalBlocks()
 .filter((item) => item.type === 'rich_text')
 .map((item) => {
 const temp = document.createElement('div');
 temp.innerHTML = item.html || '';
 return {
 title: item.title || '未命名文案区',
 body: (temp.textContent || temp.innerText || '').trim(),
 };
 });
}

function kwResetPortalEditorState() {
 kwPortalSelectedBlockId = null;
 kwPortalFocusedEditor = null;
}

function kwResetPortalDraft() {
 kwPortalWorkspaceDraft = JSON.parse(JSON.stringify(kwPortalWorkspaceBase || {}));
 kwResetPortalEditorState();
 kwRenderPortalWorkspace();
 showToast('已恢复为当前线上门户版本');
}

function kwPortalExec(command, value) {
 if (!kwPortalFocusedEditor) return;
 kwPortalFocusedEditor.focus();
 document.execCommand(command, false, value || null);
 if (kwPortalFocusedEditor.classList.contains('kw-portal-rich-editor')) {
 const blockId = kwPortalFocusedEditor.parentElement && kwPortalFocusedEditor.parentElement.parentElement
 ? kwPortalFocusedEditor.parentElement.parentElement.getAttribute('onclick')
 : '';
 const card = kwPortalFocusedEditor.closest('.kw-portal-page-block');
 if (card) {
 const match = /kwSelectPortalBlock\('([^']+)'\)/.exec(card.getAttribute('onclick') || '');
 if (match && match[1]) kwUpdatePortalBlockHtml(match[1], kwPortalFocusedEditor.innerHTML);
 }
 }
}

async function kwPublishPortalDraft() {
 kwPortalWorkspaceDraft.custom_sections = kwBuildPortalCustomSectionsFromBlocks();
 kwPortalWorkspaceDraft.published_status = '线上已发布';
 kwPortalWorkspaceDraft.last_published_at = new Date().toLocaleString('zh-CN', { hour12: false }).replace(/\//g, '-');
 kwPortalMarkDraft('发布中');
 kwRenderPortalWorkspace();
 const tenantSlug = (window.ACTIVE_TENANT && window.ACTIVE_TENANT.slug) || '';
 try {
 const resp = await fetch(`/api/kol/portal-cms?tenant=${encodeURIComponent(tenantSlug)}`, {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify({ portal_cms: kwPortalWorkspaceDraft }),
 });
 const payload = await resp.json();
 if (!resp.ok || !payload.ok) throw new Error(payload.error || 'save_failed');
 kwPortalWorkspaceBase = JSON.parse(JSON.stringify(payload.portal_workspace || {}));
 kwPortalWorkspaceDraft = JSON.parse(JSON.stringify(payload.portal_workspace || {}));
 if (window.WORKBENCH_DATA) window.WORKBENCH_DATA.portal_workspace = JSON.parse(JSON.stringify(payload.portal_workspace || {}));
 kwResetPortalEditorState();
 kwRenderPortalWorkspace();
 showToast('门户草稿已发布到粉丝端门户');
 } catch (error) {
 kwPortalMarkDraft('发布失败，请重试');
 kwRenderPortalWorkspace();
 showToast('门户发布失败，请稍后重试');
 }
}

const kwIndicatorHub = JSON.parse(JSON.stringify((window.WORKBENCH_DATA && window.WORKBENCH_DATA.indicator_hub) || {summary: {}, items: [], anomalies: []}));

function kwGetIndicatorItemById(indicatorId) {
 return (kwIndicatorHub.items || []).find((item) => item.id === indicatorId) || null;
}

function kwIndicatorStatusBadge(status) {
 if (status === 'warning') return '<span class="tag tag-red">预警</span>';
 if (status === 'attention') return '<span class="tag tag-gold">关注</span>';
 return '<span class="tag tag-green">正常</span>';
}

function kwIndicatorStatusLabel(status) {
 if (status === 'warning') return '预警';
 if (status === 'attention') return '关注';
 return '正常';
}

function kwBuildInlineChartShell(prefix, height, mountFn) {
 const chartId = window.GangtiseEcharts ? window.GangtiseEcharts.nextId(prefix) : `${prefix}-${Date.now()}`;
 if (window.GangtiseEcharts && typeof mountFn === 'function') {
 window.GangtiseEcharts.enqueue(chartId, mountFn);
 }
 return `<div id="${chartId}" style="width:100%;height:${height};min-height:${height}"></div>`;
}

function kwBuildIndicatorKlineSvg(klinePayload) {
 const candles = Array.isArray(klinePayload?.candles) ? klinePayload.candles : [];
 if (!candles.length) {
 return '<div class="kw-knowledge-detail-copy">暂无趋势数据。</div>';
 }
 const chartHtml = kwBuildInlineChartShell('kw-indicator-kline', '220px', (element) => {
 window.GangtiseEcharts.render(element, window.GangtiseEcharts.buildKlineOption({
 candles,
 ma5: Array.isArray(klinePayload?.ma5) ? klinePayload.ma5 : [],
 ma10: Array.isArray(klinePayload?.ma10) ? klinePayload.ma10 : [],
 ma20: Array.isArray(klinePayload?.ma20) ? klinePayload.ma20 : [],
 anomalies: Array.isArray(klinePayload?.anomalies) ? klinePayload.anomalies : [],
 }, {
 candleLabel: '指标K线',
 }));
 });
 return `
 <div style="background:var(--navy);border:1px solid rgba(200,169,110,0.08);border-radius:12px;padding:12px">
 <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:8px">
 <div style="font-size:12px;font-weight:700;color:var(--white)">K线走势</div>
 <div style="display:flex;gap:8px;flex-wrap:wrap;font-size:10px;color:var(--gray-400)">
 <span style="display:inline-flex;align-items:center;gap:4px"><span style="width:10px;height:2px;background:#F6C453;display:inline-block"></span>MA5</span>
 <span style="display:inline-flex;align-items:center;gap:4px"><span style="width:10px;height:2px;background:#5DADE2;display:inline-block"></span>MA10</span>
 <span style="display:inline-flex;align-items:center;gap:4px"><span style="width:10px;height:2px;background:#AF7AC5;display:inline-block"></span>MA20</span>
 </div>
 </div>
 ${chartHtml}
 </div>
 `;
}

function kwBuildIndicatorTrendSummary(series) {
 const list = Array.isArray(series) ? series : [];
 if (!list.length) return [];
 return list.map((entry, index) => {
 const numeric = Number(entry.value || 0);
 const previous = index > 0 ? Number(list[index - 1].value || 0) : numeric;
 const delta = Number((numeric - previous).toFixed(2));
 return {
 date: entry.date || '--',
 value: entry.value || '--',
 status: entry.status || 'good',
 delta,
 direction: delta > 0 ? '上行' : delta < 0 ? '下行' : '持平',
 };
 });
}

function kwCloseIndicatorModal() {
 const modal = document.getElementById('kw-indicator-modal');
 if (modal) modal.classList.remove('show');
}

function kwOpenIndicatorHistory(indicatorId) {
 const item = kwGetIndicatorItemById(indicatorId);
 const host = document.getElementById('kw-indicator-modal-content');
 const modal = document.getElementById('kw-indicator-modal');
 if (!item || !host || !modal) {
 showToast('未找到指标详情');
 return;
