 const historySeries = Array.isArray(item.history_series) ? item.history_series : [];
 const klinePayload = item.history_kline || {};
 const anomalyPoints = Array.isArray(klinePayload.anomalies) ? klinePayload.anomalies : [];
 const trendSummary = kwBuildIndicatorTrendSummary(historySeries);
 const currentValue = String(item.value || '--');
 const valueClass = /[A-Za-z]/.test(currentValue) || currentValue.length >= 9 ? 'kw-detail-stat-value compact' : 'kw-detail-stat-value';
 host.innerHTML = `
