function kwAppendTranscribedText(existingText, incomingText) {
 const current = String(existingText || '').trim();
 const next = String(incomingText || '').trim();
 if (!next) return current;
 return current ? `${current}\n\n${next}` : next;
}

function getKwReviewPeriodMeta(period) {
 return KW_REVIEW_PERIOD_CONFIG[period] || KW_REVIEW_PERIOD_CONFIG.day;
}

function initializeKwKnowledgeStore() {
 if (kwKnowledgeStore.length) return;
 const items = window.WORKBENCH_DATA && window.WORKBENCH_DATA.knowledge_hub && Array.isArray(window.WORKBENCH_DATA.knowledge_hub.items)
 ? window.WORKBENCH_DATA.knowledge_hub.items
 : [];
 kwKnowledgeStore = items.map(item => ({...item}));
}

function getKwKnowledgeEntryById(entryId) {
 initializeKwKnowledgeStore();
 return kwKnowledgeStore.find(item => item.id === entryId) || null;
}

function kwNormalizeKnowledgeHtml(html) {
 return String(html || '')
 .replace(/<p><br><\/p>/gi, '<p></p>')
 .trim();
}

function kwKnowledgeHtmlToPlainText(html) {
 const temp = document.createElement('div');
 temp.innerHTML = String(html || '');
 return (temp.textContent || temp.innerText || '').replace(/\u00a0/g, ' ').trim();
}

function kwPlainTextToKnowledgeHtml(text) {
 const normalized = String(text || '').trim();
 if (!normalized) return '';
 return normalized
 .split(/\n{2,}/)
 .map((block) => `<p>${escapeHtml(block).replace(/\n/g, '<br>')}</p>`)
 .join('');
}

function kwMergePlainTextIntoKnowledgeHtml(existingHtml, incomingText) {
 const existingText = kwKnowledgeHtmlToPlainText(existingHtml || '');
 const mergedText = kwAppendTranscribedText(existingText, incomingText || '');
 return kwPlainTextToKnowledgeHtml(mergedText);
}

function kwBuildKnowledgeRenderedHtml(value, fallback) {
 const html = kwNormalizeKnowledgeHtml(value);
 if (!html) return `<div class="kw-knowledge-rendered is-empty">${escapeHtml(fallback || '暂无内容')}</div>`;
 return `<div class="kw-knowledge-rendered">${html}</div>`;
}

function kwBuildKnowledgeStatusMeta(status) {
 const text = String(status || '').trim();
 if (!text) return { label: '待同步', className: 'syncing' };
 if (/(同步|已|可微调|ready|Hermes)/i.test(text) && !/中/.test(text)) {
 return { label: text, className: 'ready' };
 }
 return { label: text, className: 'syncing' };
}

function kwGetKnowledgeSyncMeta(item) {
 const syncStatus = item && item.sync_status && typeof item.sync_status === 'object' ? item.sync_status : null;
 if (syncStatus) {
 return {
 label: syncStatus.label || '待同步',
 className: syncStatus.class_name || 'syncing',
 detail: syncStatus.detail || '',
 target: syncStatus.target || '',
 queuedAt: syncStatus.queued_at || '',
 syncedAt: syncStatus.synced_at || '',
 failedAt: syncStatus.failed_at || '',
 };
 }
 const fallback = kwBuildKnowledgeStatusMeta(item && item.status);
 const targets = item && Array.isArray(item.sync_targets) ? item.sync_targets : [];
 return {
 label: fallback.label,
 className: fallback.className,
 detail: targets.length ? `同步去向：${targets.join(' / ')}` : '',
 target: targets[1] || targets[0] || '知识专区',
 queuedAt: item && item.queued_at ? item.queued_at : '',
 syncedAt: item && item.synced_at ? item.synced_at : '',
 failedAt: item && item.failed_at ? item.failed_at : '',
 };
}

function kwDestroyKnowledgeEditors() {
 kwKnowledgeEditors = { raw: null, notes: null };
}

function kwSyncKnowledgeDraftFromEditors() {
 if (kwKnowledgeEditors.raw) {
 kwKnowledgeDraft.rawHtml = kwNormalizeKnowledgeHtml(kwKnowledgeEditors.raw.root.innerHTML);
 kwKnowledgeDraft.rawInput = kwKnowledgeHtmlToPlainText(kwKnowledgeDraft.rawHtml);
 }
 if (kwKnowledgeEditors.notes) {
 kwKnowledgeDraft.notesHtml = kwNormalizeKnowledgeHtml(kwKnowledgeEditors.notes.root.innerHTML);
 kwKnowledgeDraft.notes = kwKnowledgeHtmlToPlainText(kwKnowledgeDraft.notesHtml);
 }
}

function kwSyncKnowledgeDraftFromModal() {
 kwSyncKnowledgeDraftFromEditors();
 const titleInput = document.getElementById('kw-knowledge-title-input');
 const summaryInput = document.getElementById('kw-knowledge-summary-input');
 const urlInput = document.getElementById('kw-knowledge-url-input');
 const processingModeInput = document.getElementById('kw-knowledge-processing-mode');
 kwKnowledgeDraft = {
 ...kwKnowledgeDraft,
 title: titleInput ? titleInput.value : kwKnowledgeDraft.title,
 summary: summaryInput ? summaryInput.value : kwKnowledgeDraft.summary,
 processingMode: processingModeInput ? (processingModeInput.value || 'algorithm') : (kwKnowledgeDraft.processingMode || 'algorithm'),
 url: urlInput ? urlInput.value : kwKnowledgeDraft.url,
 };
}

function kwInstallKnowledgeImagePaste(quill) {
 if (!quill || !quill.root) return;
 quill.root.addEventListener('paste', (event) => {
 const clipboard = event.clipboardData;
 if (!clipboard) return;
 const items = Array.from(clipboard.items || []);
 const imageItem = items.find((item) => item.type && item.type.startsWith('image/'));
 if (!imageItem) return;
 event.preventDefault();
 const file = imageItem.getAsFile();
 if (!file) return;
 const reader = new FileReader();
 reader.onload = () => {
 const range = quill.getSelection(true) || { index: quill.getLength(), length: 0 };
 quill.insertEmbed(range.index, 'image', reader.result, 'user');
 quill.setSelection(range.index + 1, 0, 'silent');
 kwSyncKnowledgeDraftFromEditors();
 showToast('截图已插入正文');
 };
 reader.readAsDataURL(file);
 });
}

function kwCreateKnowledgeQuill(containerId, placeholder, html) {
 const host = document.getElementById(containerId);
 if (!host || typeof window.Quill === 'undefined') return null;
 host.innerHTML = '';
 const quill = new window.Quill(host, {
 theme: 'snow',
 placeholder,
 modules: {
 toolbar: [
 [{ header: [1, 2, false] }],
 ['bold', 'italic', 'underline', 'blockquote'],
 [{ list: 'ordered' }, { list: 'bullet' }],
 ['link', 'image'],
 ['clean'],
 ],
 },
 });
 const normalizedHtml = kwNormalizeKnowledgeHtml(html);
 if (normalizedHtml) {
 quill.clipboard.dangerouslyPasteHTML(normalizedHtml);
 }
 quill.on('text-change', () => {
 kwSyncKnowledgeDraftFromEditors();
 });
 kwInstallKnowledgeImagePaste(quill);
 return quill;
}

function kwSyncReviewDraftFromEditors() {
 if (kwReviewEditors.manual) {
 kwReviewDraft.manualHtml = kwNormalizeKnowledgeHtml(kwReviewEditors.manual.root.innerHTML);
 }
}

function kwEnsureReviewEditors() {
 kwReviewEditors = { manual: null };
 if (kwReviewDraft.sourceMode !== 'manual') return;
 if (typeof window.Quill === 'undefined') {
 const manualHost = document.getElementById('kw-review-manual-editor');
 if (manualHost) manualHost.innerHTML = '<div class="kw-knowledge-editor-loading">编辑器加载失败，请刷新后重试。</div>';
 return;
 }
 kwReviewEditors.manual = kwCreateKnowledgeQuill(
 'kw-review-manual-editor',
 '在这里直接手写洞见正文。手动撰写模式下，后续不会再改写这份文案。',
 kwReviewDraft.manualHtml || '',
 );
 if (kwReviewEditors.manual) {
 kwReviewEditors.manual.on('text-change', () => {
 kwSyncReviewDraftFromEditors();
 });
 }
}

function kwEnsureKnowledgeEditors() {
 kwDestroyKnowledgeEditors();
 if (typeof window.Quill === 'undefined') {
 const rawHost = document.getElementById('kw-knowledge-raw-editor');
 const notesHost = document.getElementById('kw-knowledge-notes-editor');
 if (rawHost) rawHost.innerHTML = '<div class="kw-knowledge-editor-loading">编辑器加载失败，请刷新后重试。</div>';
 if (notesHost) notesHost.innerHTML = '<div class="kw-knowledge-editor-loading">编辑器加载失败，请刷新后重试。</div>';
 return;
 }
 kwKnowledgeEditors.raw = kwCreateKnowledgeQuill(
 'kw-knowledge-raw-editor',
 '补充原始材料中的关键上下文、贴入截图、表格或段落，让知识条目更接近 CMS 正文。',
 kwKnowledgeDraft.rawHtml || kwKnowledgeDraft.rawInput,
 );
 kwKnowledgeEditors.notes = kwCreateKnowledgeQuill(
 'kw-knowledge-notes-editor',
 '记录本次微调原则，例如保留大V语气、强调验证节点、删掉口语噪音。',
 kwKnowledgeDraft.notesHtml || kwKnowledgeDraft.notes,
 );
}

function buildKwKnowledgeDraft(entry) {
 return {
 title: entry && entry.title ? entry.title : '',
 summary: entry && entry.summary ? entry.summary : '',
 rawInput: entry && (entry.raw_input || entry.body) ? (entry.raw_input || entry.body) : '',
 rawHtml: entry && entry.raw_html ? entry.raw_html : (entry && (entry.raw_input || entry.body) ? `<p>${escapeHtml(entry.raw_input || entry.body).replace(/\n/g, '<br>')}</p>` : ''),
 notes: entry && entry.notes ? entry.notes : '',
 notesHtml: entry && entry.notes_html ? entry.notes_html : (entry && entry.notes ? `<p>${escapeHtml(entry.notes).replace(/\n/g, '<br>')}</p>` : ''),
 processingMode: entry && entry.processing_mode ? entry.processing_mode : ((entry && Object.prototype.hasOwnProperty.call(entry, 'skip_ai_processing') && entry.skip_ai_processing) ? 'none' : 'algorithm'),
 url: entry && entry.url ? entry.url : '',
 useVoiceLlmEnhancement: entry && Object.prototype.hasOwnProperty.call(entry, 'use_voice_llm_enhancement') ? !!entry.use_voice_llm_enhancement : true,
 };
}

function kwKnowledgeTypeLabel(type) {
 const normalized = String(type || '').trim().toLowerCase();
 if (normalized === 'voice') return '语音资料';
 if (normalized === 'file') return '文件资料';
 if (normalized === 'url') return '网页资料';
 return '手写观点';
}

function kwOpenLatestKnowledgeEntryEditor() {
 initializeKwKnowledgeStore();
 const latestEntry = Array.isArray(kwKnowledgeStore) && kwKnowledgeStore.length ? kwKnowledgeStore[0] : null;
 if (!latestEntry || !latestEntry.id) {
 showToast('当前还没有历史知识可微调');
 return;
 }
 kwOpenKnowledgeEntryEditor(latestEntry.id);
}

function kwKnowledgeMapKindLabel(kind) {
 if (kind === 'root') return '租户根节点';
 if (kind === 'topic') return '主题';
 if (kind === 'entity') return '实体';
 if (kind === 'method') return '方法';
 if (kind === 'claim') return '观点';
 if (kind === 'signal') return '验证信号';
 return '知识节点';
}

function kwKnowledgeMapNodeWidth(kind) {
 if (kind === 'root') return 168;
 if (kind === 'claim') return 192;
 if (kind === 'signal') return 132;
 return 142;
}

function kwHandleKnowledgeMapSearch(value) {
 kwKnowledgeMapState.query = String(value || '').trim();
 kwRenderKnowledgeMap();
}

function kwHandleKnowledgeMapTypeChange(value) {
 kwKnowledgeMapState.type = value || 'all';
 kwRenderKnowledgeMap();
}

function kwAdjustKnowledgeMapDepth(delta) {
 const payload = kwKnowledgeMapState.payload || {};
 const maxDepth = Number(payload.max_depth || 4);
 kwKnowledgeMapState.depth = Math.max(2, Math.min(maxDepth, Number(kwKnowledgeMapState.depth || payload.default_depth || 3) + Number(delta || 0)));
 kwRenderKnowledgeMap();
}

function kwExpandKnowledgeMapAll() {
 const payload = kwKnowledgeMapState.payload || {};
 kwKnowledgeMapState.depth = Number(payload.max_depth || 4);
 kwRenderKnowledgeMap();
}

function kwCollapseKnowledgeMap() {
 const payload = kwKnowledgeMapState.payload || {};
 kwKnowledgeMapState.depth = Number(payload.default_depth || 3);
 kwRenderKnowledgeMap();
}

function kwSelectKnowledgeMapNode(nodeId) {
 kwKnowledgeMapState.selectedNodeId = nodeId || '';
 kwKnowledgeMapState.centerNodeId = nodeId || '';
 kwRenderKnowledgeMap();
}

function kwOpenKnowledgeMapSource(entryId) {
 if (!entryId) return;
 showWorkbenchSection('knowledge-encyclopedia', document.querySelector('.admin-nav-item[data-section="knowledge-encyclopedia"]'));
 kwOpenKnowledgeEncyclopediaDetail(entryId);
}

function kwGetKnowledgeMapNodeRelations(nodeId) {
 const payload = kwKnowledgeMapState.payload || {};
 const nodes = Array.isArray(payload.nodes) ? payload.nodes : [];
 const edges = Array.isArray(payload.edges) ? payload.edges : [];
 const nodeMap = new Map(nodes.map((node) => [node.id, node]));
 const parents = [];
 const children = [];
 edges.forEach((edge) => {
 if (edge.to === nodeId && nodeMap.has(edge.from)) parents.push(nodeMap.get(edge.from));
 if (edge.from === nodeId && nodeMap.has(edge.to)) children.push(nodeMap.get(edge.to));
 });
 return {
 parents: parents.filter(Boolean).slice(0, 8),
 children: children.filter(Boolean).slice(0, 8),
 };
}

function kwCenterKnowledgeMapNode(nodeId, positions) {
 const shell = document.querySelector('.kw-kg-board-shell');
 const point = positions && positions[nodeId];
 if (!shell || !point) return;
 shell.scrollTo({
 left: Math.max(0, Math.round(point.x - shell.clientWidth / 2)),
 top: Math.max(0, Math.round(point.y - shell.clientHeight / 2)),
 behavior: 'smooth',
 });
}

function kwGetFilteredKnowledgeMapPayload() {
 const payload = kwKnowledgeMapState.payload || {};
 const allNodes = Array.isArray(payload.nodes) ? payload.nodes : [];
 const allEdges = Array.isArray(payload.edges) ? payload.edges : [];
 const depth = Math.max(2, Math.min(Number(payload.max_depth || 4), Number(kwKnowledgeMapState.depth || payload.default_depth || 3)));
 const type = kwKnowledgeMapState.type || 'all';
 const query = String(kwKnowledgeMapState.query || '').trim().toLowerCase();
 const depthNodes = allNodes.filter((node) => Number(node.level || 99) <= depth);
 const visibleIds = new Set();
 const matches = [];
 depthNodes.forEach((node) => {
 const kind = String(node.kind || '').trim();
 if (kind !== 'root' && type !== 'all' && kind !== type) {
 return;
 }
 const haystack = [
 node.label,
 node.full_label,
 node.summary,
 Array.isArray(node.keywords) ? node.keywords.join(' ') : '',
 ].join(' ').toLowerCase();
 if (query && !haystack.includes(query)) {
 return;
 }
 visibleIds.add(node.id);
 matches.push(node.id);
 });
 const rootNode = depthNodes.find((node) => node.kind === 'root');
 if (rootNode) visibleIds.add(rootNode.id);
 if (query) {
 allEdges.forEach((edge) => {
 if (visibleIds.has(edge.from) || visibleIds.has(edge.to)) {
 visibleIds.add(edge.from);
 visibleIds.add(edge.to);
 }
 });
 } else if (type !== 'all') {
 allEdges.forEach((edge) => {
 if (visibleIds.has(edge.to)) visibleIds.add(edge.from);
 });
 } else {
 depthNodes.forEach((node) => visibleIds.add(node.id));
 }
 const nodes = depthNodes.filter((node) => visibleIds.has(node.id));
 const edges = allEdges.filter((edge) => visibleIds.has(edge.from) && visibleIds.has(edge.to));
 return { payload, nodes, edges, depth, rootNode: rootNode || null };
}

function kwRenderKnowledgeMapDetail(node) {
 const host = document.getElementById('kw-kg-detail');
 if (!host) return;
 if (!node) {
 host.innerHTML = '<div class="kw-kg-detail-empty">点击图谱节点后，这里查看知识摘要、QKV 和来源证据。</div>';
 return;
 }
 const qkv = node.qkv || {};
 const keywords = Array.isArray(node.keywords) ? node.keywords : [];
 const sources = Array.isArray(node.source_entries) ? node.source_entries : [];
 const relations = kwGetKnowledgeMapNodeRelations(node.id);
 host.innerHTML = `
 <div class="kw-kg-detail-kicker">${escapeHtml(kwKnowledgeMapKindLabel(node.kind || ''))}</div>
 <div class="kw-kg-detail-title">${escapeHtml(node.full_label || node.label || '')}</div>
 <div class="kw-kg-detail-summary">${escapeHtml(node.summary || '当前节点暂无摘要。')}</div>
 ${keywords.length ? `<div class="kw-kg-chip-row">${keywords.slice(0, 10).map((item) => `<span class="kw-kg-chip">${escapeHtml(item)}</span>`).join('')}</div>` : ''}
 <div class="kw-kg-detail-section">
 <div class="kw-kg-detail-section-title">图谱关系</div>
 <div class="kw-kg-detail-list">
 <div class="kw-kg-detail-item">
 <div class="kw-kg-detail-item-title">上游节点</div>
 <div class="kw-kg-detail-item-meta">${relations.parents.length ? relations.parents.map((item) => escapeHtml(item.full_label || item.label || '')).join(' / ') : '当前节点位于最上层，暂无上游关系。'}</div>
 </div>
 <div class="kw-kg-detail-item">
 <div class="kw-kg-detail-item-title">下游节点</div>
 <div class="kw-kg-detail-item-meta">${relations.children.length ? relations.children.map((item) => escapeHtml(item.full_label || item.label || '')).join(' / ') : '当前节点暂无继续展开的下游关系。'}</div>
 </div>
 <div class="kw-kg-detail-item">
 <div class="kw-kg-detail-item-title">来源规模</div>
 <div class="kw-kg-detail-item-meta">当前节点关联 ${Number(node.source_count || sources.length || 0)} 条知识来源。</div>
 </div>
 </div>
 </div>
 <div class="kw-kg-detail-section">
 <div class="kw-kg-detail-section-title">QKV 视角</div>
 <div class="kw-kg-detail-list">
 ${(Array.isArray(qkv.questions) ? qkv.questions : []).slice(0, 2).map((item) => `<div class="kw-kg-detail-item"><div class="kw-kg-detail-item-title">Q</div><div class="kw-kg-detail-item-meta">${escapeHtml(item)}</div></div>`).join('')}
 ${(Array.isArray(qkv.values) ? qkv.values : []).slice(0, 2).map((item) => `<div class="kw-kg-detail-item"><div class="kw-kg-detail-item-title">V</div><div class="kw-kg-detail-item-meta">${escapeHtml(item)}</div></div>`).join('') || '<div class="kw-kg-detail-item"><div class="kw-kg-detail-item-title">V</div><div class="kw-kg-detail-item-meta">当前节点暂无可展示的知识值。</div></div>'}
 </div>
 </div>
 <div class="kw-kg-detail-section">
 <div class="kw-kg-detail-section-title">来源证据</div>
 <div class="kw-kg-detail-list">
 ${sources.length ? sources.slice(0, 5).map((entry) => `
 <div class="kw-kg-detail-item">
 <div class="kw-kg-detail-item-title">${escapeHtml(entry.title || '知识条目')}</div>
 <div class="kw-kg-detail-item-meta">${escapeHtml(entry.summary || '暂无摘要')}${entry.time ? ` · ${escapeHtml(entry.time)}` : ''}</div>
 <div class="kw-toolbar" style="margin-top:8px">
 <button class="btn-outline" type="button" style="padding:7px 10px;font-size:11px" onclick="kwOpenKnowledgeMapSource('${escapeAttr(entry.id || '')}')">查看知识详情</button>
 </div>
 </div>
 `).join('') : '<div class="kw-kg-detail-item"><div class="kw-kg-detail-item-meta">当前节点暂无来源证据。</div></div>'}
 </div>
 </div>
 `;
}

function kwRenderKnowledgeMap() {
 const board = document.getElementById('kw-kg-board');
 const stage = document.getElementById('kw-kg-stage');
 const stats = document.getElementById('kw-kg-stats');
 const legend = document.getElementById('kw-kg-legend');
 if (!board || !stage || !stats || !legend) return;
 if (!kwKnowledgeMapState.payload) {
 board.innerHTML = '<div class="kw-kg-detail-empty" style="min-height:720px;background:transparent;color:var(--text-sub)">知识图谱尚未加载。</div>';
 kwRenderKnowledgeMapDetail(null);
 return;
 }
 const filtered = kwGetFilteredKnowledgeMapPayload();
 const payload = filtered.payload;
 const maxDepth = Number(payload.max_depth || 4);
 kwKnowledgeMapState.depth = filtered.depth;
 kwKnowledgeMapState.defaultDepth = Number(payload.default_depth || 3);
 stage.textContent = `当前显示 ${filtered.depth} 层 / 共 ${maxDepth} 层。默认优先展示主题、实体、方法和观点，验证信号需要继续展开。`;
 const statPayload = payload.stats || {};
 stats.innerHTML = `
 <div class="kw-kg-stat"><div class="kw-kg-stat-label">知识条目</div><div class="kw-kg-stat-value">${statPayload.artifact_count || 0}</div></div>
 <div class="kw-kg-stat"><div class="kw-kg-stat-label">主题</div><div class="kw-kg-stat-value">${statPayload.topic_count || 0}</div></div>
 <div class="kw-kg-stat"><div class="kw-kg-stat-label">实体</div><div class="kw-kg-stat-value">${statPayload.entity_count || 0}</div></div>
 <div class="kw-kg-stat"><div class="kw-kg-stat-label">方法</div><div class="kw-kg-stat-value">${statPayload.method_count || 0}</div></div>
 <div class="kw-kg-stat"><div class="kw-kg-stat-label">观点</div><div class="kw-kg-stat-value">${statPayload.claim_count || 0}</div></div>
 <div class="kw-kg-stat"><div class="kw-kg-stat-label">验证信号</div><div class="kw-kg-stat-value">${statPayload.signal_count || 0}</div></div>
 `;
 legend.innerHTML = [
 ['root', '根节点'],
 ['topic', '主题'],
 ['entity', '实体'],
 ['method', '方法'],
 ['claim', '观点'],
 ['signal', '验证信号'],
 ].map(([kind, label]) => `<span class="kw-kg-legend-chip"><span class="kw-kg-legend-dot kind-${kind}"></span>${escapeHtml(label)}</span>`).join('');
 if (!filtered.nodes.length) {
 board.innerHTML = '<div class="kw-kg-detail-empty" style="min-height:720px;background:transparent;color:var(--text-sub)">当前没有匹配的知识对象。可以清空搜索词，或先补充结构化知识内容。</div>';
 kwRenderKnowledgeMapDetail(null);
 return;
 }
 const shell = document.querySelector('.kw-kg-board-shell');
 const groups = {};
 filtered.nodes.forEach((node) => {
 const level = Number(node.level || 1);
 if (!groups[level]) groups[level] = [];
 groups[level].push(node);
 });
 Object.keys(groups).forEach((key) => {
 groups[key].sort((a, b) => String(a.label || '').localeCompare(String(b.label || ''), 'zh-Hans-CN'));
 });
 const levelList = Object.keys(groups).map(Number).sort((a, b) => a - b);
 const perRing = 16;
 const baseRadius = 140;
 const levelGap = 110;
 const ringGap = 56;
 let maxRadius = 0;
 levelList.forEach((level) => {
 if (level <= 1) return;
 const groupSize = (groups[level] || []).length;
 const ringIndex = Math.max(0, Math.ceil(groupSize / perRing) - 1);
 maxRadius = Math.max(maxRadius, baseRadius + (level - 2) * levelGap + ringIndex * ringGap);
 });
 const viewportWidth = Math.max(960, shell ? shell.clientWidth : 960);
 const viewportHeight = Math.max(720, shell ? shell.clientHeight : 720);
 const width = Math.max(viewportWidth, maxRadius * 2 + 360);
 const height = Math.max(viewportHeight, maxRadius * 2 + 300);
 const centerX = width / 2;
 const centerY = height / 2;
 const positions = {};
 levelList.forEach((level) => {
 const group = groups[level] || [];
 if (level === 1) {
 const rootNode = group[0];
 if (rootNode) positions[rootNode.id] = { x: centerX, y: centerY };
 return;
 }
 group.forEach((node, index) => {
 const ringIndex = Math.floor(index / perRing);
 const ringRadius = baseRadius + (level - 2) * levelGap + ringIndex * ringGap;
 const ringSize = Math.min(perRing, Math.max(group.length - ringIndex * perRing, 1));
 const angle = ((index % perRing) / ringSize) * Math.PI * 2 - Math.PI / 2;
 positions[node.id] = {
 x: centerX + Math.cos(angle) * ringRadius,
 y: centerY + Math.sin(angle) * ringRadius,
 };
 });
 });
 const nodeMap = new Map(filtered.nodes.map((node) => [node.id, node]));
 const edgeMarkup = filtered.edges.map((edge) => {
 const from = positions[edge.from];
 const to = positions[edge.to];
 if (!from || !to) return '';
 return `<line class="kw-kg-edge" x1="${Math.round(from.x)}" y1="${Math.round(from.y)}" x2="${Math.round(to.x)}" y2="${Math.round(to.y)}"></line>`;
 }).join('');
 board.innerHTML = `
 <svg class="kw-kg-svg" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none">${edgeMarkup}</svg>
 ${filtered.nodes.map((node) => {
 const pos = positions[node.id] || { x: centerX, y: centerY };
 return `
 <button
 type="button"
 class="kw-kg-node kind-${escapeAttr(node.kind || 'topic')}${kwKnowledgeMapState.selectedNodeId === node.id ? ' is-active' : ''}"
 style="left:${Math.round(pos.x)}px;top:${Math.round(pos.y)}px;width:${kwKnowledgeMapNodeWidth(node.kind)}px"
 data-node-id="${escapeAttr(node.id || '')}"
 >
 <div class="kw-kg-node-kind">${escapeHtml(kwKnowledgeMapKindLabel(node.kind || ''))}</div>
 <div class="kw-kg-node-label">${escapeHtml(node.full_label || node.label || '')}</div>
 </button>
 `;
 }).join('')}
 `;
 board.style.width = `${Math.round(width)}px`;
 board.style.height = `${Math.round(height)}px`;
 Array.from(board.querySelectorAll('[data-node-id]')).forEach((nodeEl) => {
 nodeEl.addEventListener('click', () => kwSelectKnowledgeMapNode(nodeEl.getAttribute('data-node-id') || ''));
 });
 const activeNode = nodeMap.get(kwKnowledgeMapState.selectedNodeId) || filtered.nodes.find((node) => node.kind === 'root') || filtered.nodes[0];
 kwKnowledgeMapState.selectedNodeId = activeNode ? activeNode.id : '';
 kwRenderKnowledgeMapDetail(activeNode || null);
 const centerTarget = kwKnowledgeMapState.centerNodeId || '';
 if (centerTarget && positions[centerTarget]) kwCenterKnowledgeMapNode(centerTarget, positions);
 kwKnowledgeMapState.centerNodeId = '';
}

async function loadWorkbenchKnowledgeMap(forceMessage = false) {
 const stage = document.getElementById('kw-kg-stage');
 if (stage) stage.textContent = '正在加载知识图谱…';
 try {
 const tenantSlug = (window.WORKBENCH_DATA && window.WORKBENCH_DATA.tenant && window.WORKBENCH_DATA.tenant.slug) || '';
 const resp = await fetch(`/api/kol/knowledge-graph?tenant=${encodeURIComponent(tenantSlug)}`);
 const data = await resp.json();
 if (!resp.ok || !data.ok) throw new Error((data && data.error) || 'knowledge_graph_load_failed');
 kwKnowledgeMapState.loaded = true;
 kwKnowledgeMapState.payload = data.graph || {};
 kwKnowledgeMapState.depth = Number((data.graph && data.graph.default_depth) || 3);
 kwKnowledgeMapState.defaultDepth = Number((data.graph && data.graph.default_depth) || 3);
 if (!kwKnowledgeMapState.selectedNodeId) {
 kwKnowledgeMapState.selectedNodeId = String((data.graph && data.graph.root_id) || '');
 kwKnowledgeMapState.centerNodeId = kwKnowledgeMapState.selectedNodeId;
 }
 kwRenderKnowledgeMap();
 if (forceMessage) showToast('知识图谱已刷新');
 } catch (error) {
 if (stage) stage.textContent = '知识图谱加载失败，当前无法展示。';
 const board = document.getElementById('kw-kg-board');
 if (board) board.innerHTML = '<div class="kw-kg-detail-empty" style="min-height:720px;background:transparent;color:var(--text-sub)">知识图谱加载失败。请稍后重试，或先检查知识条目是否已成功同步。</div>';
 kwRenderKnowledgeMapDetail(null);
 showToast(error.message || '知识图谱加载失败');
 }
}

