 <div class="kw-knowledge-zone-origin">${escapeHtml(cfg.icon)} ${escapeHtml(item.source || '')} · ${escapeHtml(item.source_detail || '')} · ${escapeHtml(status.detail || `同步去向：${status.target || '知识专区'}`)}${status.queuedAt ? ` · 入队 ${escapeHtml(status.queuedAt)}` : ''}${status.syncedAt && status.label === '已同步' ? ` · 完成 ${escapeHtml(status.syncedAt)}` : ''}${status.failedAt ? ` · 失败 ${escapeHtml(status.failedAt)}` : ''}</div>
 </div>
 <span class="kw-knowledge-status ${status.className}">${escapeHtml(status.label)}</span>
 </div>
 <div class="kw-knowledge-zone-summary">${escapeHtml(item.summary || '')}</div>
 <div class="kw-watch-chip-row" style="margin-top:10px">
 ${(item.tags || []).map(tag => `<span class="kw-watch-chip">${escapeHtml(tag)}</span>`).join('')}
 </div>
 <div class="kw-knowledge-entry-hint">点击弹框微调</div>
 </div>
 `;
 }).join('');
 }
 kwRenderKnowledgeChatResult();
}

function kwRenderKnowledgeChatResult() {
 const answerHost = document.getElementById('kw-knowledge-chat-answer');
 const matchesHost = document.getElementById('kw-knowledge-chat-matches');
 if (answerHost) {
 const prefix = kwKnowledgeChatState.llmNotice ? `${kwKnowledgeChatState.llmNotice}\n\n` : '';
 answerHost.textContent = `${prefix}${kwKnowledgeChatState.answer || '还没有发起查询。'}`;
 }
 if (matchesHost) {
 const matches = Array.isArray(kwKnowledgeChatState.matches) ? kwKnowledgeChatState.matches : [];
 matchesHost.innerHTML = matches.length ? matches.map((item) => `
 <div class="kw-knowledge-chat-match" onclick="kwOpenKnowledgeEntryEditor('${escapeAttr(item.id || '')}')">
 <div class="kw-knowledge-chat-match-title">${escapeHtml(item.title || '未命名知识')}</div>
 <div class="kw-knowledge-chat-match-meta">相关度 ${escapeHtml(String(item.score || 0))} · ${escapeHtml(item.source_detail || item.source || '')}</div>
 <div class="kw-knowledge-chat-match-body">${escapeHtml(item.summary || item.body || item.raw_input || '')}</div>
 </div>
 `).join('') : '<div class="kw-knowledge-chat-match"><div class="kw-knowledge-chat-match-meta">当前还没有命中结果。</div></div>';
 }
}

function kwRenderKnowledgeAssets() {
