 const relationHost = document.getElementById('kw-knowledge-assets-relationships');
 const entriesHost = document.getElementById('kw-knowledge-assets-entries');
 const payload = kwKnowledgeAssetState.payload || {};
 const summary = payload.summary || {};
 if (summaryHost) {
 const cards = [
 ['知识词条', summary.entry_count || 0, `已成型 ${summary.ready_count || 0}`],
 ['平均成熟度', summary.avg_maturity_score || 0, '用于衡量是否可复用'],
 ['平均关系数', summary.avg_relation_count || 0, '每条知识的关系丰富度'],
 ['主题数', summary.topic_count || 0, `实体 ${summary.entity_count || 0}`],
 ['方法数', summary.method_count || 0, `信号 ${summary.signal_count || 0}`],
 ['来源类型', summary.source_type_count || 0, payload.mode === 'platform' ? `租户 ${summary.tenant_count || 0}` : `平均关键词 ${summary.avg_keyword_count || 0}`],
 ];
 summaryHost.innerHTML = cards.map(([label, value, meta]) => `
