 </div>
 `).join('');
 }
 if (relationHost) {
 const sourceRows = Array.isArray(payload.source_breakdown) ? payload.source_breakdown : [];
 const groups = payload.relationship_groups || {};
 const sections = [
 { title: '来源分布', rows: sourceRows, labelKey: 'label', countKey: 'count' },
 { title: '高频主题', rows: Array.isArray(groups.topics) ? groups.topics.slice(0, 5) : [], labelKey: 'label', countKey: 'count' },
 { title: '高频实体', rows: Array.isArray(groups.entities) ? groups.entities.slice(0, 5) : [], labelKey: 'label', countKey: 'count' },
 { title: '高频方法', rows: Array.isArray(groups.methods) ? groups.methods.slice(0, 4) : [], labelKey: 'label', countKey: 'count' },
 { title: '高频验证信号', rows: Array.isArray(groups.signals) ? groups.signals.slice(0, 5) : [], labelKey: 'label', countKey: 'count' },
 ];
 relationHost.innerHTML = sections.map((section) => `
 <div class="kw-ka-rel-list">
 <div class="kw-ka-panel-title">${escapeHtml(section.title)}</div>
 ${(section.rows || []).length ? section.rows.map((item) => `
 <div class="kw-ka-rel-item">
 <div class="kw-ka-rel-top">
 <div class="kw-ka-rel-title">${escapeHtml(item[section.labelKey] || '--')}</div>
 <span class="kw-ka-rel-count">${escapeHtml(String(item[section.countKey] || 0))} 条</span>
 </div>
 ${Array.isArray(item.entry_titles) && item.entry_titles.length ? `<div class="kw-ka-meta">${escapeHtml(item.entry_titles.slice(0, 3).join(' / '))}</div>` : ''}
 ${Array.isArray(item.keywords) && item.keywords.length ? `<div class="kw-ka-chip-row">${item.keywords.slice(0, 5).map((keyword) => `<span class="kw-ka-chip">${escapeHtml(keyword)}</span>`).join('')}</div>` : ''}
 </div>
 `).join('') : '<div class="kw-ka-rel-item"><div class="kw-ka-meta">当前还没有形成稳定关系。</div></div>'}
 </div>
 `).join('');
 }
 kwRenderKnowledgeAssetCharts(payload);
 if (entriesHost) {
 const entries = Array.isArray(payload.entries) ? payload.entries.slice(0, 12) : [];
 entriesHost.innerHTML = entries.length ? entries.map((entry) => `
 <div class="kw-knowledge-readable-item" onclick="kwOpenKnowledgeEncyclopediaDetail('${escapeAttr(entry.id || '')}')">
 <div class="kw-ka-entry-top">
 <div>
 <div class="kw-knowledge-readable-item-title">${escapeHtml(entry.title || '未命名知识')}</div>
 <div class="kw-knowledge-readable-item-meta">${escapeHtml(entry.source || '--')} · ${escapeHtml(entry.time || '--')}</div>
 </div>
 <span class="kw-ka-maturity tone-${escapeAttr(entry.maturity_tone || 'seed')}">${escapeHtml(entry.maturity_label || '种子')} ${escapeHtml(String(entry.maturity_score || 0))}</span>
 </div>
 <div class="kw-knowledge-readable-item-summary">${escapeHtml(entry.summary || '暂无摘要')}</div>
 <div class="kw-ka-chip-row">
 ${(((entry.relations || {}).topics || []).slice(0, 2)).map((item) => `<span class="kw-ka-chip">${escapeHtml(item)}</span>`).join('')}
 ${(((entry.relations || {}).entities || []).slice(0, 2)).map((item) => `<span class="kw-ka-chip">${escapeHtml(item)}</span>`).join('')}
 ${(((entry.relations || {}).methods || []).slice(0, 1)).map((item) => `<span class="kw-ka-chip">${escapeHtml(item)}</span>`).join('')}
 </div>
 <div class="kw-knowledge-readable-item-foot">点击查看词条详情</div>
 </div>
 `).join('') : '<div class="kw-knowledge-readable-item"><div class="kw-knowledge-readable-item-meta">当前还没有可展示的知识词条，请先完成知识录入。</div></div>';
