 </div>
 </div>
 <div class="kw-knowledge-detail-card">
 <div class="kw-knowledge-detail-title">验证节点</div>
 <div class="kw-knowledge-bullet-list">
 ${(validationNodes.length ? validationNodes : ['当前还没有补充验证节点。']).map((item) => `<div class="kw-knowledge-bullet-item">${escapeHtml(item)}</div>`).join('')}
 </div>
 </div>
 </div>
 <div class="kw-knowledge-detail-stack">
 <div class="kw-knowledge-detail-card">
 <div class="kw-knowledge-detail-title">词条分类</div>
 <div class="kw-knowledge-chip-row" style="margin-top:10px">
 ${topics.map((item) => `<span class="kw-knowledge-chip">${escapeHtml(item)}</span>`).join('')}
 ${entities.map((item) => `<span class="kw-knowledge-chip">${escapeHtml(item)}</span>`).join('')}
