 kwKnowledgeEditingId = '';
 kwKnowledgeIntakeType = KW_KNOWLEDGE_INPUT_TYPES[type] ? type : 'voice';
 kwKnowledgeRecording = false;
 kwKnowledgeUploadSamples = [];
 kwKnowledgeUrlPreview = null;
