function kwOpenKnowledgeEntryEditor(entryId) {
 initializeKwKnowledgeStore();
 const entry = getKwKnowledgeEntryById(entryId);
 if (!entry) return;
 kwKnowledgeEditingId = entry.id;
 kwKnowledgeIntakeType = KW_KNOWLEDGE_INPUT_TYPES[entry.type] ? entry.type : 'voice';
 kwKnowledgeRecording = false;
 kwKnowledgeDraft = buildKwKnowledgeDraft(entry);
 kwKnowledgeUploadSamples = Array.isArray(entry.files) ? entry.files.slice(0) : [];
 kwKnowledgeUrlPreview = entry.url ? {
 url: entry.url,
 domain: (() => {
 try {
 return new URL(entry.url).host || 'example.com';
 } catch (e) {
 return 'example.com';
 }
 })(),
 title: entry.title || '',
 summary: entry.summary || '',
 } : null;
 kwRenderKnowledgeModal();
 const modal = document.getElementById('kw-knowledge-modal');
 if (modal) modal.classList.add('show');
}

