function kwRenderKnowledgeTypePanel() {
 if (kwKnowledgeIntakeType === 'voice') {
 return `
 <div class="kw-knowledge-modal-block">
 <label class="kw-knowledge-modal-label">录音面板</label>
 <div class="kw-knowledge-type-panel">
 <div class="kw-knowledge-type-toolbar">
 <div class="kw-review-runtime-meta">${kwKnowledgeVoiceUploading ? '正在转写刚才的语音，请稍候。' : (kwKnowledgeRecording ? '正在录音，系统会自动转写' : '准备录音，可继续口述新的判断和补充说明。')}</div>
 <div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end">
 <button class="btn-outline" type="button" ${kwKnowledgeRecording || kwKnowledgeVoiceUploading || (!String(kwKnowledgeDraft.rawInput || '').trim() && !String(kwKnowledgeDraft.summary || '').trim()) ? 'disabled' : ''} style="padding:7px 12px;font-size:12px" onclick="kwClearKnowledgeVoiceDraft()">清空</button>
 <button class="${kwKnowledgeRecording ? 'btn-gold' : 'btn-outline'}" type="button" ${kwKnowledgeVoiceUploading ? 'disabled' : ''} style="padding:7px 12px;font-size:12px" onclick="kwToggleKnowledgeVoiceCapture()">${kwKnowledgeVoiceUploading ? '转写中...' : (kwKnowledgeRecording ? '结束录音' : '开始录音')}</button>
 </div>
 </div>
 <label class="knowledge-check-row" style="margin-top:10px;display:flex;align-items:flex-start;gap:8px;font-size:12px;color:#6b7280">
 <input type="checkbox" id="kw-knowledge-voice-llm-enhancement" ${kwKnowledgeDraft.useVoiceLlmEnhancement ? 'checked' : ''} onchange="kwToggleKnowledgeVoiceLlmEnhancement(this.checked)" ${kwKnowledgeRecording || kwKnowledgeVoiceUploading ? 'disabled' : ''} />
 <span>启用大模型深度整理。关闭后仍会保留基础规则纠错、术语清洗和可编辑转写文本。</span>
 </label>
 <div style="margin-top:8px;font-size:11px;line-height:1.7;color:#9B7A1C;background:rgba(200,169,110,0.10);border:1px solid rgba(200,169,110,0.16);border-radius:10px;padding:8px 10px">
 口述录制功能当前处于测试阶段，建议在安静环境下分段录入，并在提交前简单检查转写结果。
 </div>
 <div class="kw-knowledge-wave"><span></span><span></span><span></span><span></span><span></span></div>
 </div>
 </div>
 `;
 }
 if (kwKnowledgeIntakeType === 'file') {
 return `
 <div class="kw-knowledge-modal-block">
 <label class="kw-knowledge-modal-label">文件面板</label>
 <div class="kw-knowledge-type-panel">
 <div class="kw-review-runtime-meta">这里可以继续追加示例文件，让知识条目重新抽取和清洗。</div>
 <div class="kw-knowledge-action-row" style="margin-top:10px">
 <button class="btn-outline" type="button" style="padding:8px 10px;font-size:12px" onclick="kwOpenKnowledgeFilePicker(false)">选择文件</button>
 <button class="btn-gold" type="button" style="padding:8px 10px;font-size:12px" onclick="kwOpenKnowledgeFilePicker(true)">批量导入</button>
 </div>
 <div class="kw-knowledge-chip-row" style="margin-top:10px">
 ${kwKnowledgeUploadSamples.length ? kwKnowledgeUploadSamples.map(file => `<span class="kw-knowledge-chip">${escapeHtml(file)}</span>`).join('') : '<span class="kw-knowledge-chip">尚未选择文件</span>'}
 </div>
 </div>
 </div>
 `;
 }
 if (kwKnowledgeIntakeType === 'manual') {
 return `
 <div class="kw-knowledge-modal-block">
 <label class="kw-knowledge-modal-label">纯文本面板</label>
 <div class="kw-knowledge-type-panel">
 <div class="kw-review-runtime-meta">这里适合直接编写结构化知识，不依赖语音、文件或网页抓取。</div>
 </div>
 </div>
 `;
 }
 return `
 <div class="kw-knowledge-modal-block">
 <label class="kw-knowledge-modal-label">网页 URL 面板</label>
 <div class="kw-knowledge-type-panel">
 <input id="kw-knowledge-url-input" class="kw-knowledge-modal-input" placeholder="https://example.com/research-note" value="${escapeHtml(kwKnowledgeDraft.url || '')}" />
 <div class="kw-knowledge-action-row" style="margin-top:10px">
 <button class="btn-gold" type="button" style="padding:8px 10px;font-size:12px" onclick="kwPreviewKnowledgeUrl()">抓取网页摘要</button>
 </div>
 <div style="margin-top:10px">${kwRenderKnowledgeUrlPreview()}</div>
 </div>
 </div>
 `;
}

function kwRenderKnowledgeUrlPreview() {
 if (!kwKnowledgeUrlPreview) {
 return '<div class="kw-knowledge-detail-card"><div class="kw-knowledge-detail-note">输入网页 URL 后可预览将被沉淀的标题、来源域名和摘要。</div></div>';
 }
 const modeText = Array.isArray(kwKnowledgeUrlPreview.extraction_modes) && kwKnowledgeUrlPreview.extraction_modes.length
 ? ` · 解析方式：${kwKnowledgeUrlPreview.extraction_modes.join(', ')}`
 : '';
 return `
 <div class="kw-knowledge-detail-card">
 <div class="kw-knowledge-detail-title">${escapeHtml(kwKnowledgeUrlPreview.title || '')}</div>
 <div class="kw-knowledge-detail-note">${escapeHtml(kwKnowledgeUrlPreview.domain || '')}${escapeHtml(modeText)} · ${escapeHtml(kwKnowledgeUrlPreview.summary || '')}</div>
 </div>
 `;
}

