 const entry = kwKnowledgeEditingId ? getKwKnowledgeEntryById(kwKnowledgeEditingId) : null;
 const cfg = KW_KNOWLEDGE_INPUT_TYPES[kwKnowledgeIntakeType] || KW_KNOWLEDGE_INPUT_TYPES.voice;
 if (!host) return;
 host.innerHTML = `
 <div class="kw-review-modal-head">
 <div>
 <div class="kw-review-modal-title">${entry ? '微调知识内容' : '新增知识内容'}</div>
 <div class="kw-review-modal-subtitle">${entry ? '左侧用于说明这条知识建议如何微调，右侧直接修改标题、正文、摘要和补充备注。保存后会重新同步到知识专区和 Hermes 上下文。' : cfg.desc}</div>
 </div>
 <button class="kw-review-modal-close" type="button" onclick="kwCloseKnowledgeModal()">×</button>
 </div>
 <div class="kw-knowledge-source-selector" style="margin-bottom:16px">
