async function kwGenerateReviewDraftWithLlm() {
 const tenant = window.ACTIVE_TENANT || {};
 const resp = await fetch('/api/review/generate-draft', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({
 tenant_slug: tenant.slug || '',
 period: kwReviewDraft.period || 'day',
 source_mode: kwReviewDraft.sourceMode || 'manual',
 source_text: kwGetReviewDraftContentText(),
 prompt_text: kwReviewDraft.aiPrompt || '',
 prompt_tags: kwReviewDraft.promptTags || [],
 // Stage one only optimizes the user's own review text. Stock analysis is
 // submitted later, after an explicit decision and stock confirmation.
 selected_watchlist: [],
 speaker_name: tenant.advisor || '',
 entry_point: 'workbench_review_draft',
 }),
 });
 const data = await resp.json();
 if (!resp.ok || !data.ok) {
 throw new Error((data && data.error) || 'review_draft_generation_failed');
 }
 return data;
}

async function kwRequestReviewStructuredPreview() {
