async function kwPublishReviewContent(text, transcriptionEngine, transcriptModel, extras) {
 const tenant = window.ACTIVE_TENANT || {};
 await kwSyncLocalWatchlistAnnotationsToServer(kwReviewDraft.selectedWatchlist || []);
 const payload = extras && typeof extras === 'object' ? extras : {};
 const resp = await fetch('/api/review/publish', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({
 text,
 tenant_slug: tenant.slug || '',
 period: kwReviewDraft.period || 'day',
 review_title: String(kwReviewDraft.reviewTitle || '').trim(),
 access_mode: kwReviewDraft.accessMode === 'subscriber' ? 'subscriber' : 'public',
 entry_point: 'web_publish',
 speaker_name: tenant.advisor || '',
 transcription_engine: transcriptionEngine || 'manual',
 transcript_model: transcriptModel || 'manual_input',
 source_mode: kwReviewDraft.sourceMode || 'manual',
 paragraph_mode: kwReviewDraft.paragraphMode || 'manual',
 selected_watchlist: kwReviewDraft.selectedWatchlist || [],
 prompt_tags: kwReviewDraft.promptTags || [],
 review_summary: payload.review_summary || '',
 user_input_section: payload.user_input_section || {},
 watchlist_analysis_section: payload.watchlist_analysis_section || {},
 llm_models: Array.isArray(payload.llm_models) ? payload.llm_models : [],
 }),
 });
 const data = await resp.json();
 if (!resp.ok || !data.success) {
 throw new Error((data && data.error) || 'publish_failed');
 }
 return data;
}

function kwGetReviewStudioConfig() {
