 return kwGetReviewSmartCards().filter((item) => selected.has(item.id)).map((item) => ({
 ...item,
 prompt: kwReviewDraft.cardPromptOverrides[item.id] || item.prompt || '',
 }));
}

function kwGetReviewSelectedKnowledge() {
 return [];
