function kwSetReviewAccessMode(accessMode) {
 const normalized = accessMode === 'subscriber' ? 'subscriber' : 'public';
 kwReviewDraft.accessMode = normalized;
 const group = document.getElementById('kw-review-access-mode');
 if (!group) return;
 group.dataset.accessMode = normalized;
 group.querySelectorAll('[role="radio"]').forEach((item) => {
 const selected = item.getAttribute('onclick').includes(`'${normalized}'`);
 item.classList.toggle('active', selected);
 item.setAttribute('aria-checked', selected ? 'true' : 'false');
 });
}

function kwSyncReviewTextInputs() {
 const titleInput = document.getElementById('kw-review-title-input');
 const accessModeInput = document.getElementById('kw-review-access-mode');
 const urlInput = document.getElementById('kw-review-url-input');
 const urlTitleInput = document.getElementById('kw-review-url-title');
 const finalEditor = document.getElementById('kw-review-final-editor');
 if (titleInput) kwReviewDraft.reviewTitle = String(titleInput.value || '').trim();
 if (accessModeInput) kwReviewDraft.accessMode = accessModeInput.dataset.accessMode === 'subscriber' ? 'subscriber' : 'public';
 if (urlInput) kwReviewDraft.urlValue = String(urlInput.value || '').trim();
 if (urlTitleInput) kwReviewDraft.urlTitle = String(urlTitleInput.value || '').trim();
 if (finalEditor) kwReviewDraft.finalDraftText = String(finalEditor.value || '').trim();
}

