 if (!host || !modal) return;
 host.innerHTML = `
 <div class="kw-review-modal-title">选择洞见素材</div>
 <div class="kw-review-runtime-desc" style="margin-top:6px">这里选择智能仪表盘卡片，作为本次洞见的辅助素材。</div>
