function kwUseCurrentReviewDraftAsFinal() {
 kwSyncReviewTextInputs();
 kwReviewDraft.finalDraftText = String(kwGetReviewPreviewText() || kwReviewDraft.generatedPreviewText || kwGetReviewDraftContentText() || '').trim();
 const editor = document.getElementById('kw-review-final-editor');
 if (editor) editor.value = kwReviewDraft.finalDraftText;
}

async function kwPreviewReviewUrl() {
 kwSyncReviewTextInputs();
 if (!kwReviewDraft.urlValue) {
 showToast('请先输入 URL');
 return;
 }
 try {
 const resp = await fetch('/api/kol/knowledge/url-preview', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({ url: kwReviewDraft.urlValue }),
 });
 const data = await resp.json();
 if (!resp.ok || !data.ok) throw new Error((data && data.error) || '网页抓取失败');
 const preview = data.preview || {};
 const extractedText = String(preview.body || preview.summary || '').trim();
 if (!extractedText) throw new Error('网页未提取到可用文本，请确认链接内容');
 kwReviewDraft.urlTitle = kwReviewDraft.urlTitle || String(preview.title || '');
 kwReviewDraft.urlText = extractedText;
 kwReviewDraft.manualHtml = kwMergePlainTextIntoKnowledgeHtml(kwReviewDraft.manualHtml || '', extractedText);
 kwReviewDraft.sourceMode = 'manual';
 kwReviewDraft.previewReady = false;
 kwReviewDraft.generatedPreviewText = '';
 kwReviewDraft.draftReviewText = '';
 kwReviewDraft.flowStage = 'intake';
 kwReviewStructuredPreview = null;
 showToast('网页内容已提取为文本，可继续编辑后生成 Draft');
 } catch (error) {
 showToast(error.message || '网页抓取失败');
 } finally {
 kwRenderReviewStudio();
 }
}

function kwCaptureReviewFileInput() {
 if (kwReviewFileUploading) return;
 const input = document.createElement('input');
 input.type = 'file';
 input.accept = '.pdf,.docx,.xlsx,.xlsm,.txt,.md,.csv,.html,.htm,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/plain,text/csv,text/html';
 input.onchange = async () => {
 const file = input.files && input.files[0];
 if (!file) return;
 kwReviewFileUploading = true;
 kwRenderReviewStudio();
 try {
 const formData = new FormData();
 formData.append('file', file, file.name);
 const resp = await fetch('/api/kol/knowledge/file-preview', {
 method: 'POST',
 body: formData,
 });
 const data = await resp.json();
 if (!resp.ok || !data.ok) throw new Error((data && data.error) || `文件解析失败：${file.name}`);
 const preview = data.preview || {};
 const extractedText = String(preview.body || preview.summary || '').trim();
 if (!extractedText) throw new Error('文件未提取到可用文本，请更换文件或检查文件内容');
 kwReviewDraft.fileName = String(preview.filename || file.name);
 kwReviewDraft.fileText = extractedText;
 kwReviewDraft.manualHtml = kwMergePlainTextIntoKnowledgeHtml(kwReviewDraft.manualHtml || '', extractedText);
 kwReviewDraft.sourceMode = 'manual';
 kwReviewDraft.previewReady = false;
 kwReviewDraft.generatedPreviewText = '';
 kwReviewDraft.draftReviewText = '';
 kwReviewDraft.flowStage = 'intake';
 kwReviewStructuredPreview = null;
 showToast('文件已解析为文本，可继续编辑后生成 Draft');
 } catch (error) {
 showToast(error.message || '文件解析失败');
 } finally {
 kwReviewFileUploading = false;
 kwRenderReviewStudio();
 }
 };
 input.click();
}

function kwSyncReviewDraftFromModal() {
 const promptInput = document.getElementById('kw-review-ai-prompt-input');
 const draftReviewInput = document.getElementById('kw-review-draft-review-input');
 const structuredUserInput = document.getElementById('kw-review-structured-user-input');
 const structuredSectorSummary = document.getElementById('kw-review-structured-sector-summary');
 const skipAiInput = document.getElementById('kw-review-skip-ai-processing');
 kwSyncReviewDraftFromEditors();
 kwSyncReviewTextInputs();
 if (promptInput) kwReviewDraft.aiPrompt = promptInput.value;
 if (skipAiInput) kwReviewDraft.skipAiProcessing = !!skipAiInput.checked;
 if (draftReviewInput) kwReviewDraft.draftReviewText = draftReviewInput.value;
 if (structuredUserInput || structuredSectorSummary) {
 kwReviewStructuredPreview = kwNormalizeReviewStructuredPreview(kwReviewStructuredPreview || {});
 if (structuredUserInput) {
 kwReviewStructuredPreview.user_input_section = kwReviewStructuredPreview.user_input_section || {};
 kwReviewStructuredPreview.user_input_section.display_text = structuredUserInput.value;
 kwReviewDraft.draftReviewText = structuredUserInput.value;
 }
 if (structuredSectorSummary) {
 kwReviewStructuredPreview.watchlist_analysis_section = kwReviewStructuredPreview.watchlist_analysis_section || {};
 if (String(kwReviewStructuredPreview.watchlist_analysis_section.combined_text || '').trim()) {
 kwReviewStructuredPreview.watchlist_analysis_section.combined_text = structuredSectorSummary.value;
 } else {
 kwReviewStructuredPreview.watchlist_analysis_section.sector_summary = structuredSectorSummary.value;
 }
 }
 const itemNodes = Array.from(document.querySelectorAll('[data-kw-review-watchlist-analysis-index]'));
 const items = ((kwReviewStructuredPreview.watchlist_analysis_section || {}).items || []);
 itemNodes.forEach((node) => {
 const index = Number(node.getAttribute('data-kw-review-watchlist-analysis-index'));
 if (!Number.isInteger(index) || !items[index]) return;
 items[index].analysis_text = node.value;
 });
 }
}

function kwValidateReviewIntakeReady(requireMaterials = false) {
 kwSyncReviewDraftFromModal();
 if (!String(kwReviewDraft.reviewTitle || '').trim()) {
 showToast('请先填写洞见主题');
 return false;
 }
 if (!kwGetReviewDraftContentText()) {
 showToast('请先补充输入内容');
 return false;
 }
 if (requireMaterials && !(kwReviewDraft.selectedCardIds || []).length && !(kwReviewDraft.selectedKnowledgeIds || []).length) {
 showToast('请先至少选择一张智能卡片或一份知识材料');
 return false;
 }
 return true;
}

function kwOpenReviewOptimizeRuleStep() {
 if (!kwValidateReviewIntakeReady()) return;
 kwReviewDraft.flowStage = 'optimize_rule';
 kwReviewDraft.paragraphMode = 'ai';
 kwReviewDraft.skipAiProcessing = false;
 kwReviewDraft.previewReady = false;
 kwReviewStructuredPreview = null;
 kwReviewWorkspacePanel = 'generation';
 kwRenderReviewStudio();
}

function kwBackToReviewIntake() {
 kwSyncReviewDraftFromModal();
 kwReviewDraft.flowStage = 'intake';
 kwReviewDraft.previewReady = false;
 kwReviewStructuredPreview = null;
 kwReviewWorkspacePanel = 'input';
 kwRenderReviewStudio();
}

function kwBackToReviewDraftEdit() {
 kwSyncReviewDraftFromModal();
 kwReviewDraft.previewReady = false;
 if (kwReviewDraft.flowStage === 'preview' && kwReviewStructuredPreview) {
 kwReviewDraft.flowStage = 'structured_review';
 } else if (kwReviewDraft.flowStage === 'watchlist_select') {
 kwReviewDraft.flowStage = 'stage1_preview';
 } else if (kwReviewDraft.flowStage === 'stage1_preview') {
 kwReviewDraft.flowStage = 'draft_review';
 } else {
 kwReviewStructuredPreview = null;
 kwReviewDraft.flowStage = kwReviewDraft.generatedPreviewText ? 'draft_review' : 'intake';
 }
 kwReviewWorkspacePanel = kwReviewDraft.flowStage === 'intake' ? 'input' : 'generation';
 kwRenderReviewStudio();
}

function kwConfirmReviewDraftToPreview() {
 kwSyncReviewDraftFromModal();
 if (!String(kwReviewDraft.draftReviewText || '').trim()) {
 showToast('请先确认或填写 Draft 正文');
 return;
 }
 kwReviewDraft.paragraphMode = 'ai';
 kwReviewDraft.skipAiProcessing = false;
 kwReviewDraft.watchlistDecision = 'not_applicable';
 kwReviewDraft.selectedWatchlist = [];
 kwReviewStructuredPreview = null;
 kwReviewDraft.finalDraftText = String(kwReviewDraft.draftReviewText || '').trim();
 kwReviewDraft.previewReady = true;
 kwReviewDraft.flowStage = 'preview';
 kwReviewWorkspacePanel = 'preview';
 kwRenderReviewStudio();
 showToast('洞见草稿已确认，可预览或发布');
}

function kwChooseReviewWatchlistAnalysis(decision) {
 showToast('洞见发布不再包含独立的股票分析阶段，请直接审核洞见草稿。');
 kwPrepareReviewDirectPreview();
 return;
 kwSyncReviewDraftFromModal();
 if (decision === 'no') {
 kwReviewDraft.watchlistDecision = 'no';
 kwReviewDraft.selectedWatchlist = [];
 kwReviewDraft.previewReady = true;
 kwReviewDraft.flowStage = 'preview';
 kwReviewWorkspacePanel = 'preview';
 kwRenderReviewStudio();
 showToast('已跳过旧版分析步骤，可直接发布');
 return;
 }
 kwReviewDraft.watchlistDecision = 'yes';
 kwReviewDraft.selectedWatchlist = [];
 kwReviewDraft.previewReady = false;
 kwReviewDraft.flowStage = 'watchlist_select';
 kwReviewWatchlistSearchItems = [];
 kwReviewWatchlistSearchQuery = '';
 kwReviewWatchlistAddedItems = [];
 kwReviewWorkspacePanel = 'input';
 kwRenderReviewStudio();
}

function kwConfirmReviewWatchlistSelection() {
 kwSyncReviewDraftFromModal();
 if (!(kwReviewDraft.selectedWatchlist || []).length) {
 showToast('请至少选择一只股票');
 return;
 }
 kwPrepareReviewStructuredPreview();
}

function kwConfirmStructuredReviewToPreview() {
 kwSyncReviewDraftFromModal();
 kwReviewStructuredPreview = kwNormalizeReviewStructuredPreview(kwReviewStructuredPreview || {});
 if (!String((((kwReviewStructuredPreview.user_input_section || {}).display_text) || '')).trim()) {
 showToast('请先确认或填写用户洞见');
 return;
 }
 kwReviewDraft.previewReady = true;
 kwReviewDraft.flowStage = 'preview';
 kwReviewDraft.finalDraftText = kwBuildReviewStructuredFinalText(kwReviewStructuredPreview);
 kwReviewWorkspacePanel = 'preview';
 kwRenderReviewStudio();
 showToast('已进入最终预览');
}

function kwPrepareReviewDirectPreview() {
 if (!kwValidateReviewIntakeReady()) return;
 kwReviewDraft.paragraphMode = 'manual';
 kwReviewDraft.skipAiProcessing = true;
 kwReviewDraft.generatedPreviewText = '';
 kwReviewDraft.draftReviewText = kwGetReviewDraftContentText();
 kwReviewDraft.watchlistDecision = 'not_applicable';
 kwReviewDraft.selectedWatchlist = [];
 kwReviewStructuredPreview = null;
 kwReviewDraft.previewReady = true;
 kwReviewDraft.flowStage = 'preview';
 kwReviewWorkspacePanel = 'preview';
 kwRenderReviewStudio();
 showToast('已进入洞见发布预览');
}

async function kwPrepareReviewStructuredPreview() {
 // Old browser bookmarks are handled by the current Insight draft route.
 kwPrepareReviewDirectPreview();
 return;
 const runtime = ensureKwReviewRuntime();
 if (!kwValidateReviewIntakeReady()) return;
 kwSyncReviewDraftFromModal();
 kwReviewStructuredPreview = null;
 kwReviewPreviewGenerating = true;
 kwReviewCancellationRequested = false;
 kwReviewPreviewJobState = {
 status: 'running',
 progress_stage: 'queued',
 progress_percent: 8,
 summary: '已提交预览任务，正在准备洞见预览',
 result: { live_log: [] },
 };
 kwReviewDraft.flowStage = 'preview_generating';
 kwReviewDraft.previewReady = false;
 kwReviewWorkspacePanel = 'generation';
 kwRenderReviewStudio();
 try {
 const previewResult = await kwRequestReviewStructuredPreview();
 if (!previewResult.async || !previewResult.job_code) throw new Error('review_prepare_preview_job_missing');
 kwReviewPreviewJobState = {
 ...kwReviewPreviewJobState,
 job_code: previewResult.job_code,
 job_type: 'review_prepare_preview',
 };
 kwRegisterActiveReviewJob(previewResult.job_code, 'review_prepare_preview', {
 tenant_slug: (window.ACTIVE_TENANT || {}).slug || '',
 period: kwReviewDraft.period || 'day',
 review_title: kwReviewDraft.reviewTitle || '',
 source_mode: kwReviewDraft.sourceMode || 'manual',
 source_text: kwGetReviewUserInputDisplayText(),
 selected_watchlist: (kwReviewDraft.selectedWatchlist || []).slice(0),
 });
 if (kwReviewCancellationRequested) {
 await fetch(`/api/review/jobs/${encodeURIComponent(previewResult.job_code)}/cancel`, {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 }).catch(() => {});
 kwReviewPreviewJobState = null;
 kwRemoveActiveReviewJob(previewResult.job_code);
 return;
 }
 let completed = false;
 await new Promise((resolve, reject) => {
 kwStartAsyncJobPolling(previewResult.job_code, {
 onProgress(job) {
 kwReviewPreviewJobState = job || kwReviewPreviewJobState;
 kwRenderReviewStudio();
 },
 onSuccess(job) {
 const result = job.result || {};
 kwReviewStructuredPreview = kwNormalizeReviewStructuredPreview(result);
 kwReviewPreviewGenerating = false;
 kwReviewPreviewJobState = job;
 kwReviewDraft.previewReady = false;
 kwReviewDraft.flowStage = 'structured_review';
 runtime.kolGeneratedAt = '刚刚生成';
 kwReviewWorkspacePanel = 'generation';
 completed = true;
 kwRemoveActiveReviewJob(previewResult.job_code);
 resolve();
 },
 onFailed(job) {
 kwReviewPreviewGenerating = false;
 kwReviewPreviewJobState = job;
 kwReviewDraft.flowStage = 'preview_failed';
 kwReviewWorkspacePanel = 'generation';
 kwRemoveActiveReviewJob(previewResult.job_code);
 kwRenderReviewStudio();
 showToast(job.error_message || job.summary || '洞见预览生成失败');
 resolve();
 },
 onCancelled(job) {
 kwReviewPreviewGenerating = false;
 kwReviewPreviewJobState = job;
 kwReviewDraft.flowStage = 'draft_review';
 kwReviewWorkspacePanel = 'generation';
 kwRemoveActiveReviewJob(previewResult.job_code);
 kwRenderReviewStudio();
 resolve();
 },
 onError(error) {
 reject(error);
 },
 });
 });
 if (!completed) return;
 } catch (error) {
 kwReviewPreviewGenerating = false;
 if (kwReviewDraft.flowStage !== 'preview_failed') {
 kwReviewPreviewJobState = null;
 kwReviewDraft.flowStage = kwReviewDraft.generatedPreviewText ? 'draft_review' : 'intake';
 }
 kwReviewWorkspacePanel = kwReviewDraft.flowStage === 'intake' ? 'input' : 'generation';
 kwRenderReviewStudio();
 showToast(kwGetReviewDraftGenerationErrorMessage(error));
 return;
 } finally {
 kwReviewPreviewGenerating = false;
 if (kwReviewPreviewJobState && kwReviewPreviewJobState.status === 'success') {
 kwReviewPreviewJobState = null;
 }
 }
 kwRenderReviewStudio();
 showToast('洞见预览已生成，请审核后发布');
}

async function kwSubmitReviewSmartOptimize() {
 kwSyncReviewDraftFromModal();
 if (!kwValidateReviewIntakeReady()) return;
 if (!kwHasConfiguredGeneralLlm()) {
 showToast('当前还没有配置可用的大模型。请先到 Admin 的系统专区 · 大模型专区配置一个通用模型。');
 return;
 }
 const runtime = ensureKwReviewRuntime();
 const tenant = window.ACTIVE_TENANT || {};
 kwReviewDraft.paragraphMode = 'ai';
 kwReviewDraft.skipAiProcessing = false;
 if (kwReviewDraft.optimizeRuleMode !== 'custom') {
 kwReviewDraft.aiPrompt = '';
 kwReviewDraft.promptTags = [];
 }
 kwReviewStructuredPreview = null;
 kwReviewDraft.flowStage = 'draft_generating';
 kwReviewDraft.previewReady = false;
 kwReviewWorkspacePanel = 'generation';
 kwReviewDraftGenerating = true;
 kwReviewCancellationRequested = false;
 kwReviewDraftJobState = {
 status: 'running',
 progress_stage: 'queued',
 progress_percent: 6,
 summary: '已提交任务，正在进入大模型处理队列',
 result: { live_log: [] },
 };
 kwRenderReviewStudio();
 try {
 const draftResult = await kwGenerateReviewDraftWithLlm();
 if (!draftResult.async || !draftResult.job_code) throw new Error('review_draft_job_missing');
 kwReviewDraftJobState = {
 ...kwReviewDraftJobState,
 job_code: draftResult.job_code,
 job_type: 'review_generate_draft',
 };
 kwRegisterActiveReviewJob(draftResult.job_code, 'review_generate_draft', {
 tenant_slug: tenant.slug || '',
 period: kwReviewDraft.period || 'day',
 source_mode: kwReviewDraft.sourceMode || 'manual',
 source_text: kwGetReviewDraftContentText(),
 prompt_text: kwReviewDraft.aiPrompt || '',
 prompt_tags: (kwReviewDraft.promptTags || []).slice(0),
 selected_watchlist: [],
 });
 if (kwReviewCancellationRequested) {
 await fetch(`/api/review/jobs/${encodeURIComponent(draftResult.job_code)}/cancel`, {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 }).catch(() => {});
 kwReviewDraftJobState = null;
 kwRemoveActiveReviewJob(draftResult.job_code);
 return;
 }
 let completed = false;
 await new Promise((resolve, reject) => {
 kwStartAsyncJobPolling(draftResult.job_code, {
 onProgress(job) {
 kwReviewDraftJobState = job || kwReviewDraftJobState;
 kwRenderReviewStudio();
 },
 onSuccess(job) {
 const result = job.result || {};
 kwReviewDraft.generatedPreviewText = result.text || '';
 kwReviewDraft.draftReviewText = result.text || kwGetReviewDraftContentText();
 kwReviewIngestResult = {
 ...(kwReviewIngestResult || {}),
 review_draft_llm: result.llm_model || null,
 };
 kwReviewDraftGenerating = false;
 kwReviewDraftJobState = job;
 completed = true;
 kwRemoveActiveReviewJob(draftResult.job_code);
 resolve();
 },
 onFailed(job) {
 kwReviewDraftGenerating = false;
 kwReviewDraftJobState = job;
 kwReviewDraft.flowStage = 'optimize_rule';
 kwRemoveActiveReviewJob(draftResult.job_code);
 kwRenderReviewStudio();
 showToast(job.error_message || job.summary || '大模型洞见草稿生成失败');
 resolve();
 },
 onCancelled(job) {
 kwReviewDraftGenerating = false;
 kwReviewDraftJobState = job;
 kwReviewDraft.flowStage = 'optimize_rule';
 kwRemoveActiveReviewJob(draftResult.job_code);
 kwRenderReviewStudio();
 resolve();
 },
 onError(error) {
 reject(error);
 },
 });
 });
 if (!completed) return;
 } catch (error) {
 kwReviewDraftGenerating = false;
 if (kwReviewDraft.flowStage !== 'optimize_rule') kwReviewDraftJobState = null;
 kwReviewDraft.flowStage = 'optimize_rule';
 kwReviewWorkspacePanel = 'generation';
 kwRenderReviewStudio();
 showToast(kwGetReviewDraftGenerationErrorMessage(error));
 return;
 } finally {
 kwReviewDraftGenerating = false;
 if (kwReviewDraftJobState && kwReviewDraftJobState.status === 'success') {
 kwReviewDraftJobState = null;
 }
 }
 kwReviewDraft.flowStage = 'draft_review';
 kwReviewDraft.previewReady = false;
 kwReviewWorkspacePanel = 'generation';
 runtime.kolGeneratedAt = '刚刚生成';
 runtime.kolSourceMode = kwReviewDraft.sourceMode;
 runtime.paragraphMode = kwReviewDraft.paragraphMode;
 runtime.lastReviewPeriod = kwReviewDraft.period;
 runtime.latestVoiceTranscript = kwReviewDraft.voiceTranscript;
 runtime.latestManualHtml = kwReviewDraft.manualHtml;
 runtime.latestFileText = kwReviewDraft.fileText;
 runtime.latestReviewTitle = kwReviewDraft.reviewTitle || '';
 runtime.latestAiPrompt = kwReviewDraft.aiPrompt;
 runtime.latestPromptTags = (kwReviewDraft.promptTags || []).slice(0);
 runtime.latestGeneratedPreviewText = kwReviewDraft.generatedPreviewText || '';
 runtime.latestDraftReviewText = kwReviewDraft.draftReviewText || '';
 runtime.draftReady = true;
 kwRenderReviewStudio();
 showToast('优化成稿已完成，请先审核用户内容 Draft');
}

