function kwAppendTranscribedText(existingText, incomingText) {
 const current = String(existingText || '').trim();
 const next = String(incomingText || '').trim();
 if (!next) return current;
 return current ? `${current}\n\n${next}` : next;
}

function kwRenderReviewInputPanel() {
 const titleField = `
 <div style="margin-bottom:12px">
 <label class="kw-knowledge-modal-label" style="display:block;margin-bottom:6px">洞见主题</label>
 <input id="kw-review-title-input" class="kw-knowledge-modal-input" placeholder="输入本次洞见主题，发布后会直接作为文章标题" value="${escapeAttr(kwReviewDraft.reviewTitle || '')}" />
 </div>
 `;
 const accessModeField = `
 <div style="margin-bottom:12px">
 <label class="kw-knowledge-modal-label" style="display:block;margin-bottom:6px">发布范围</label>
 <div id="kw-review-access-mode" class="kw-review-access-scope-tags" role="radiogroup" aria-label="选择洞见发布范围" data-access-mode="${kwReviewDraft.accessMode === 'subscriber' ? 'subscriber' : 'public'}">
 <button type="button" class="kw-review-access-scope-tag ${kwReviewDraft.accessMode === 'public' ? 'active' : ''}" role="radio" aria-checked="${kwReviewDraft.accessMode === 'public'}" aria-label="常规笔记，所有粉丝可查看" onclick="kwSetReviewAccessMode('public')"><span class="kw-review-access-scope-tag-title">常规笔记</span><span class="kw-review-access-scope-tag-desc">所有粉丝可查看完整正文</span></button>
 <button type="button" class="kw-review-access-scope-tag ${kwReviewDraft.accessMode === 'subscriber' ? 'active' : ''}" role="radio" aria-checked="${kwReviewDraft.accessMode === 'subscriber'}" aria-label="订阅专享，仅有效订阅用户查看正文" onclick="kwSetReviewAccessMode('subscriber')"><span class="kw-review-access-scope-tag-title">订阅专享</span><span class="kw-review-access-scope-tag-desc">仅有效订阅用户查看正文</span></button>
 </div>
 <div class="kw-review-runtime-desc" style="margin-top:6px">访问范围按每篇洞见单独生效，不会影响其他已发布笔记。</div>
 </div>
 `;
 if (kwReviewDraft.sourceMode === 'voice') {
 return `
 <div class="kw-review-intake-panel">
 ${titleField}${accessModeField}
 <div class="kw-review-intake-toolbar">
 <div class="kw-review-runtime-meta">${kwGetReviewVoiceStatusText()}</div>
 <div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end">
 <button class="btn-outline" type="button" ${kwReviewVoiceRecording || kwReviewVoiceUploading || !String(kwReviewDraft.voiceTranscript || '').trim() ? 'disabled' : ''} style="padding:7px 12px;font-size:12px" onclick="kwClearReviewVoiceTranscript()">清空</button>
 <button class="kw-review-input-button" type="button" ${kwReviewVoiceUploading ? 'disabled' : ''} onclick="kwCaptureReviewVoiceInput()">${kwGetReviewVoiceButtonLabel()}</button>
 </div>
 </div>
 <label class="knowledge-check-row" style="margin-top:10px;display:flex;align-items:flex-start;gap:8px;font-size:12px;color:#6b7280">
 <input type="checkbox" id="kw-review-voice-llm-enhancement" ${kwReviewDraft.useVoiceLlmEnhancement ? 'checked' : ''} onchange="kwToggleReviewVoiceLlmEnhancement(this.checked)" ${kwReviewVoiceRecording || kwReviewVoiceUploading ? 'disabled' : ''} />
 <span>启用大模型深度整理。关闭后仍会保留基础规则纠错、术语清洗和可编辑转写文本。</span>
 </label>
 <div style="margin-top:8px;font-size:11px;line-height:1.7;color:#9B7A1C;background:rgba(200,169,110,0.10);border:1px solid rgba(200,169,110,0.16);border-radius:10px;padding:8px 10px">
 口述录制功能当前处于测试阶段，建议在安静环境下分段录入，并在提交前简单检查转写结果。
 </div>
 <div class="kw-review-intake-result">
 <div class="kw-review-intake-result-title">转写文案</div>
 <div class="kw-review-intake-result-text">${escapeHtml(kwReviewDraft.voiceTranscript || '录音结束后，这里会立即展示转写后的洞见文案；支持多次录制并按顺序追加。')}</div>
 </div>
 </div>
 `;
 }
 if (kwReviewDraft.sourceMode === 'file') {
 return `
 <div class="kw-review-intake-panel">
 ${titleField}${accessModeField}
 <div class="kw-review-intake-toolbar">
 <div class="kw-review-runtime-meta">${kwReviewFileUploading ? '正在解析文件...' : '支持 PDF、Word、Excel，解析后可继续编辑'}</div>
 <button class="kw-review-input-button" type="button" ${kwReviewFileUploading ? 'disabled' : ''} onclick="kwCaptureReviewFileInput()">${kwReviewFileUploading ? '解析中...' : '点击上传文件'}</button>
 </div>
 <div class="kw-review-intake-result">
