 <div style="flex:1;display:grid;gap:10px">
 <input id="kw-review-url-input" type="text" value="${escapeAttr(kwReviewDraft.urlValue || '')}" placeholder="输入网页 URL 作为本次洞见补充素材" class="kw-review-final-editor" style="min-height:auto;height:40px">
 <input id="kw-review-url-title" type="text" value="${escapeAttr(kwReviewDraft.urlTitle || '')}" placeholder="可选：自定义这份 URL 材料标题" class="kw-review-final-editor" style="min-height:auto;height:40px">
