 网页 URL 解析功能当前处于测试阶段，请确认链接可公开访问，并在提交前简单检查抓取内容和来源是否完整。
 </div>
 <div class="kw-review-intake-result">
 <div class="kw-review-intake-result-title">网页提炼结果</div>
 <div class="kw-review-intake-result-text">${escapeHtml(kwReviewDraft.urlText || '抓取网页后，这里会展示正文摘要，可作为洞见素材。')}</div>
 </div>
 </div>
 `;
 }
 return `
 <div class="kw-review-intake-panel">
 ${titleField}${accessModeField}
 <div class="kw-knowledge-rich-shell">
 <div class="kw-knowledge-editor-loading">支持加粗、列表、引用、链接、贴图，和知识正文使用同一套 Quill 编辑器。</div>
 <div id="kw-review-manual-editor" class="kw-review-rich-editor"></div>
 <div class="kw-knowledge-rich-help">这里和 H5 端使用同一套富文本编辑器 Quill。</div>
 </div>
 </div>
 `;
}

function kwRenderInsightDraftLibrary() {
 if (kwInsightDraftsLoading) {
 return '<div class="kw-knowledge-modal-block"><div class="kw-review-runtime-desc">正在加载洞见草稿...</div></div>';
 }
 if (!kwInsightDrafts.length) return '';
 return `
 <div class="kw-knowledge-modal-block">
 <label class="kw-knowledge-modal-label">已保存草稿</label>
 <div style="display:grid;gap:8px">
 ${kwInsightDrafts.map((draft) => `
 <div style="padding:10px;border:1px solid rgba(47,116,192,0.12);border-radius:10px;background:#F8FBFF">
 <div style="display:flex;justify-content:space-between;gap:8px;align-items:flex-start">
 <div style="min-width:0">
 <div style="font-size:12px;font-weight:700;color:var(--text-main);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escapeHtml(draft.title || '未命名洞见草稿')}</div>
 <div style="font-size:10px;color:var(--gray-400);margin-top:4px">更新于 ${escapeHtml(draft.updated_at || '--')}</div>
 </div>
 <div style="display:flex;gap:6px;flex-shrink:0">
 <button class="btn-outline" type="button" style="padding:5px 8px;font-size:11px" onclick="kwEditInsightDraft('${escapeAttr(draft.id)}')">编辑</button>
 <button class="btn-outline" type="button" style="padding:5px 8px;font-size:11px;color:#B42318;border-color:rgba(180,35,24,0.24)" onclick="kwDeleteInsightDraft('${escapeAttr(draft.id)}')">删除</button>
 </div>
 </div>
 </div>
 `).join('')}
 </div>
 </div>
 `;
}

async function kwLoadInsightDrafts() {
 const tenant = window.ACTIVE_TENANT || {};
 if (kwInsightDraftsLoading || kwInsightDraftsLoaded || !tenant.slug) return;
 kwInsightDraftsLoading = true;
 try {
 const response = await fetch(`/api/tenant/${encodeURIComponent(tenant.slug)}/insight-drafts`);
 const data = await response.json();
 if (!response.ok || !data.ok) throw new Error(data.error || 'insight_drafts_unavailable');
 kwInsightDrafts = Array.isArray(data.drafts) ? data.drafts : [];
 kwInsightDraftsLoaded = true;
 kwRenderReviewStudio();
 } catch (error) {
 console.warn('Insight drafts unavailable', error);
 } finally {
 kwInsightDraftsLoading = false;
 }
}

function kwEditInsightDraft(draftId) {
 const draft = kwInsightDrafts.find((item) => String((item || {}).id || '') === String(draftId || ''));
 if (!draft) return;
 kwReviewDraft.insightDraftId = String(draft.id || '');
 kwReviewDraft.reviewTitle = String(draft.title || '').trim();
 kwReviewDraft.accessMode = draft.access_mode === 'subscriber' ? 'subscriber' : 'public';
 kwReviewDraft.sourceMode = String(draft.source_mode || 'manual').trim() || 'manual';
 kwReviewDraft.manualHtml = kwMergePlainTextIntoKnowledgeHtml('', String(draft.content_text || '').trim());
 kwReviewDraft.draftReviewText = String(draft.content_text || '').trim();
 kwReviewDraft.generatedPreviewText = '';
 kwReviewDraft.previewReady = false;
 kwReviewDraft.flowStage = 'intake';
 kwReviewWorkspacePanel = 'input';
 kwRenderReviewStudio();
}

async function kwSaveReviewDraft() {
 const tenant = window.ACTIVE_TENANT || {};
 if (!tenant.slug) return;
 kwSyncReviewDraftFromModal();
 const text = kwGetReviewPreviewText() || kwGetReviewDraftContentText();
 if (!String(kwReviewDraft.reviewTitle || '').trim()) {
 showToast('请先填写洞见主题');
 return;
 }
 if (!String(text || '').trim()) {
 showToast('请先补充洞见内容');
 return;
 }
 try {
 const response = await fetch(`/api/tenant/${encodeURIComponent(tenant.slug)}/insight-drafts`, {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({
 id: kwReviewDraft.insightDraftId || undefined,
 title: String(kwReviewDraft.reviewTitle || '').trim(),
 content_text: String(text).trim(),
 source_mode: kwReviewDraft.sourceMode || 'manual',
 access_mode: kwReviewDraft.accessMode === 'subscriber' ? 'subscriber' : 'public',
 }),
 });
 const data = await response.json();
 if (!response.ok || !data.ok) throw new Error(data.error || 'insight_draft_storage_failed');
 kwReviewDraft.insightDraftId = String((data.draft || {}).id || kwReviewDraft.insightDraftId || '');
 kwInsightDrafts = Array.isArray(data.drafts) ? data.drafts : kwInsightDrafts;
 kwInsightDraftsLoaded = true;
 kwRenderReviewStudio();
 showToast('洞见草稿已保存，可随时继续编辑或发布');
 } catch (error) {
 showToast(error.message || '洞见草稿保存失败');
 }
}

async function kwDeleteInsightDraft(draftId) {
 const tenant = window.ACTIVE_TENANT || {};
 if (!draftId || !tenant.slug || !window.confirm('确认删除这篇洞见草稿吗？删除后无法恢复。')) return;
 try {
 const response = await fetch(`/api/tenant/${encodeURIComponent(tenant.slug)}/insight-drafts/${encodeURIComponent(draftId)}`, {method: 'DELETE'});
 const data = await response.json();
 if (!response.ok || !data.ok) throw new Error(data.error || 'insight_draft_delete_failed');
 kwInsightDrafts = Array.isArray(data.drafts) ? data.drafts : [];
 if (kwReviewDraft.insightDraftId === draftId) kwReviewDraft.insightDraftId = '';
 kwRenderReviewStudio();
 showToast('洞见草稿已删除');
 } catch (error) {
 showToast(error.message || '洞见草稿删除失败');
 }
}

function kwRenderReviewPromptPanel() {
 if (kwReviewDraft.flowStage !== 'optimize_rule') return '';
 const useCustomRule = kwReviewDraft.optimizeRuleMode === 'custom';
 return `
 <div class="kw-knowledge-modal-block">
 <label class="kw-knowledge-modal-label">智能优化规则</label>
 <div class="kw-review-runtime-desc" style="margin-top:6px;margin-bottom:10px">默认优化会保留用户观点并整理表达；也可以补充具体规则。这里不会直接发布，结果会先进入 Draft 审核。</div>
 <div class="kw-knowledge-source-selector" style="grid-template-columns:repeat(2,1fr)">
 <button class="kw-knowledge-source-pill ${kwReviewDraft.optimizeRuleMode === 'default' ? 'active' : ''}" type="button" onclick="kwSetReviewOptimizeRuleMode('default')">忽略规则，默认优化</button>
 <button class="kw-knowledge-source-pill ${useCustomRule ? 'active' : ''}" type="button" onclick="kwSetReviewOptimizeRuleMode('custom')">输入规则后优化</button>
 </div>
 ${useCustomRule ? `
 <textarea id="kw-review-ai-prompt-input" class="kw-review-final-editor" style="margin-top:10px;min-height:100px" placeholder="例如：更口语化，但保留原始观点，不要写买卖建议。">${escapeHtml(kwReviewDraft.aiPrompt || '')}</textarea>
 <div class="kw-review-prompt-tag-row" style="margin-top:10px">
 ${KW_REVIEW_PROMPT_TAGS.map(tag => `
 <button class="kw-review-prompt-tag ${kwReviewDraft.promptTags.includes(tag) ? 'active' : ''}" type="button" onclick="kwToggleReviewPromptTag('${tag}')">${escapeHtml(tag)}</button>
 `).join('')}
 </div>
 ` : ''}
 </div>
 `;
}

function kwRenderReviewPreviewPanel() {
 if (!kwReviewDraft.previewReady) return '';
 const periodMeta = getKwReviewPeriodMeta(kwReviewDraft.period || 'day');
 const structured = kwNormalizeReviewStructuredPreview(kwReviewStructuredPreview || {});
 const title = String(kwReviewDraft.reviewTitle || '').trim() || '洞见预览';
 const userInput = String((structured.user_input_section || {}).display_text || '').trim() || kwGetReviewUserInputDisplayText();
 const watchlistText = '';
 return `
 <div class="kw-review-preview-panel">
 <div class="kw-review-preview-head">
 <div>
 <div class="kw-review-preview-title">${escapeHtml(title)}</div>
 <div class="kw-review-runtime-meta">${escapeHtml(kwReviewDraft.sourceMode === 'voice' ? '语音口述' : (kwReviewDraft.sourceMode === 'file' ? '文件上传' : (kwReviewDraft.sourceMode === 'url' ? '网页 URL' : '手写正文')))} · 预览态</div>
 </div>
 <span class="kw-review-draft-status">待发布</span>
 </div>
 <div class="kw-review-preview-copy" style="margin-top:14px">
 ${structured.review_summary ? `<div><strong>摘要</strong><div style="white-space:pre-wrap;margin-top:6px">${escapeHtml(structured.review_summary)}</div></div>` : ''}
 ${userInput ? `<div style="margin-top:${structured.review_summary ? '16px' : '0'}"><strong>用户洞见</strong><div style="white-space:pre-wrap;margin-top:6px">${escapeHtml(userInput)}</div></div>` : ''}
 ${watchlistText ? `<div style="margin-top:16px"><strong>历史附加内容</strong><div style="white-space:pre-wrap;margin-top:6px">${escapeHtml(watchlistText)}</div></div>` : ''}
 ${!structured.review_summary && !userInput && !watchlistText ? `<div style="white-space:pre-wrap">${escapeHtml(kwGetReviewPreviewText())}</div>` : ''}
 </div>
 ${(kwReviewDraft.selectedWatchlist || []).length ? `<div class="kw-chip-row" style="margin-top:14px">${kwReviewDraft.selectedWatchlist.map((name) => `<span class="kw-chip">${escapeHtml(name)}</span>`).join('')}</div>` : ''}
 </div>
 `;
}

function kwRenderReviewStageOnePreviewPanel() {
 return '';
}

function kwSetReviewCardPrompt(cardId, value) {
 const normalizedId = String(cardId || '').trim();
 if (!normalizedId) return;
 kwReviewDraft.cardPromptOverrides = {
 ...(kwReviewDraft.cardPromptOverrides || {}),
 [normalizedId]: String(value || '').trim(),
 };
}

function kwGetReviewCurrentStageLabel() {
 const stage = kwReviewDraft.flowStage || 'intake';
 return {
 intake: '内容录入',
 optimize_rule: '优化规则确认',
 draft_generating: 'Draft 生成中',
 draft_review: 'Draft 审核',
 preview_generating: '洞见预览生成中',
 structured_review: '洞见草稿审核',
 preview_failed: '洞见预览失败',
 stage1_preview: '洞见草稿审核',
 watchlist_select: '洞见草稿审核',
 preview: '最终预览',
 }[stage] || '内容录入';
}

function kwGetReviewWorkspacePanelIndex(panelId) {
 return KW_REVIEW_WORKSPACE_PANELS.findIndex((item) => item.id === panelId);
}

function kwGetReviewWizardStepState(panelId) {
 const stage = kwReviewDraft.flowStage || 'intake';
 const hasInput = !!kwGetReviewDraftContentText();
 const hasCards = !!(kwGetReviewSelectedCards().length + kwGetReviewSelectedKnowledge().length);
 const hasDraft = !!String(kwReviewDraft.draftReviewText || kwReviewDraft.generatedPreviewText || '').trim();
 const hasStructured = !!kwReviewStructuredPreview;
 const hasPreview = !!String(kwGetReviewPreviewText() || '').trim();
 if (panelId === 'overview') {
 return kwReviewWorkspacePanel === panelId ? 'active' : 'done';
 }
 if (panelId === 'cards') {
 if (kwReviewWorkspacePanel === panelId) return 'active';
 return hasCards ? 'done' : 'todo';
 }
 if (panelId === 'input') {
 if (kwReviewWorkspacePanel === panelId) return 'active';
 return hasInput ? 'done' : 'todo';
 }
 if (panelId === 'generation') {
 if (kwReviewWorkspacePanel === panelId) return 'active';
 if (stage === 'draft_generating' || stage === 'draft_review' || stage === 'preview_generating' || stage === 'structured_review' || stage === 'preview_failed') return 'done';
 return hasDraft || hasStructured ? 'done' : 'todo';
 }
 if (panelId === 'preview') {
 if (kwReviewWorkspacePanel === panelId) return 'active';
 return hasPreview ? 'done' : 'todo';
 }
 return 'todo';
}

function kwCanOpenReviewWorkspacePanel(panelId) {
 const targetIndex = kwGetReviewWorkspacePanelIndex(panelId);
 if (targetIndex <= 0) return true;
 if (panelId === 'cards') return true;
 if (panelId === 'input') return true;
 if (panelId === 'generation') {
 return !!kwGetReviewDraftContentText();
 }
 if (panelId === 'preview') {
 return !!String(kwGetReviewPreviewText() || '').trim();
 }
 return true;
}

function kwTryOpenReviewWorkspacePanel(panelId) {
 if (!kwCanOpenReviewWorkspacePanel(panelId)) {
 if (panelId === 'generation') {
 showToast('先完成用户洞见输入');
 return;
 }
 if (panelId === 'preview') {
 showToast('先完成用户洞见，再进入最终预览');
 return;
 }
 }
 kwSetReviewWorkspacePanel(panelId);
}

function kwInferReviewWorkspacePanel() {
 const stage = kwReviewDraft.flowStage || 'intake';
 if (kwReviewDraft.previewReady || stage === 'preview') return 'preview';
 if (stage === 'draft_generating' || stage === 'draft_review' || stage === 'optimize_rule' || stage === 'preview_generating' || stage === 'structured_review' || stage === 'preview_failed') {
 return 'generation';
 }
 return 'input';
}

function kwSetReviewWorkspacePanel(panelId, options) {
 const target = KW_REVIEW_WORKSPACE_PANELS.find((item) => item.id === panelId);
 if (!target) return;
 kwReviewWorkspacePanel = target.id;
 if (!options || options.render !== false) kwRenderReviewStudio();
}

function kwApplyReviewWorkspacePanelState() {
 document.querySelectorAll('[data-kw-review-panel]').forEach((node) => {
 node.classList.toggle('active', node.getAttribute('data-kw-review-panel') === kwReviewWorkspacePanel);
 });
}

function kwRenderReviewTopPeriodRow() {
 const host = document.getElementById('kw-review-top-period-row');
 if (!host) return;
 host.innerHTML = '';
}

function kwRenderReviewDirectoryNav() {
 const host = document.getElementById('kw-review-directory-nav-list');
 if (!host) return;
 host.innerHTML = KW_REVIEW_WORKSPACE_PANELS.map((panel, index) => {
 const state = kwGetReviewWizardStepState(panel.id);
 const badge = state === 'done' ? '已完成' : (state === 'active' ? '进行中' : '待开始');
 const badgeClass = state === 'active' ? 'is-gold' : '';
 return `
 <button class="kw-review-directory-btn ${kwReviewWorkspacePanel === panel.id ? 'active' : ''} ${state === 'done' ? 'is-done' : ''}" type="button" onclick="kwTryOpenReviewWorkspacePanel('${panel.id}')">
 <div class="kw-review-directory-btn-top">
 <div style="display:flex;gap:10px;align-items:flex-start">
 <span class="kw-review-directory-step">${index + 1}</span>
 <div class="kw-review-directory-btn-title">${escapeHtml(panel.label)}</div>
 </div>
 <span class="kw-review-directory-pill ${badgeClass}">${escapeHtml(badge)}</span>
 </div>
 <div class="kw-review-directory-btn-copy">${escapeHtml(panel.desc)}</div>
 </button>
 `;
 }).join('');
}

