function kwRenderReviewOverviewSummary() {
 const host = document.getElementById('kw-review-overview-summary');
 if (!host) return;
 const latestPublished = (window.WORKBENCH_DATA && window.WORKBENCH_DATA.published_reviews && window.WORKBENCH_DATA.published_reviews[0]) || null;
 const cards = [
 ['当前阶段', kwGetReviewCurrentStageLabel(), '和 H5 保持同一条洞见工作流'],
 ['洞见素材', String(kwGetReviewSelectedCards().length + kwGetReviewSelectedKnowledge().length), '可选智能卡片和知识材料'],
 ['输入状态', kwGetReviewDraftContentText() ? '已录入' : '待录入', '支持手写、语音、文件和网页 URL'],
 ['用户内容', kwGetReviewDraftContentText() ? '已录入' : '待录入', '支持语音、手写、文件和网页 URL'],
 ['优化成稿', String(kwReviewDraft.draftReviewText || kwReviewDraft.generatedPreviewText || '').trim() ? '已生成' : '未生成', '先形成用户洞见草稿'],
 ['发布状态', kwReviewDraft.previewReady ? '可发布' : '编辑中', '确认草稿后进入最终预览'],
 ['最近发布', latestPublished ? String(latestPublished.time || '--') : '暂无', latestPublished ? String(latestPublished.title || '').slice(0, 36) : '发布后这里会同步更新'],
 ];
 host.innerHTML = cards.map(([label, value, note]) => `
 <div class="kw-review-overview-stat">
 <div class="kw-review-overview-stat-label">${escapeHtml(label)}</div>
 <div class="kw-review-overview-stat-value">${escapeHtml(value)}</div>
 <div class="kw-review-overview-stat-note">${escapeHtml(note)}</div>
 </div>
 `).join('');
}

