 </div>
 `;
}

function kwRenderReviewWizardFooter() {
 const host = document.getElementById('kw-review-wizard-footer');
 if (!host) return;
 const currentIndex = Math.max(0, kwGetReviewWorkspacePanelIndex(kwReviewWorkspacePanel));
 const total = KW_REVIEW_WORKSPACE_PANELS.length;
 const step = KW_REVIEW_WORKSPACE_PANELS[currentIndex] || KW_REVIEW_WORKSPACE_PANELS[0];
 const isGenerating = kwReviewDraftGenerating || kwReviewPreviewGenerating || kwReviewPublishSubmitting;
 let desc = step.desc || '';
 let actions = '';
 if (kwReviewWorkspacePanel === 'input') {
 desc = '确认输入内容后，可以直接预览，也可以进入优化规则。';
 actions = `
 <button class="btn-outline" type="button" ${isGenerating ? 'disabled' : ''} onclick="kwSaveReviewDraft()">保存草稿</button>
 <button class="btn-outline" type="button" ${isGenerating ? 'disabled' : ''} onclick="kwPrepareReviewDirectPreview()">直接预览</button>
 <button class="btn-gold" type="button" ${isGenerating ? 'disabled' : ''} onclick="kwOpenReviewOptimizeRuleStep()">优化成稿</button>
 `;
 } else if (kwReviewWorkspacePanel === 'generation') {
 const stage = kwReviewDraft.flowStage || 'intake';
 if (stage === 'optimize_rule') {
 desc = '确认优化规则后，开始生成用户洞见草稿。';
 actions = `
 <button class="btn-outline" type="button" onclick="kwBackToReviewIntake()">回到用户洞见</button>
 <button class="btn-gold" type="button" ${isGenerating ? 'disabled' : ''} onclick="kwSubmitReviewSmartOptimize()">${isGenerating ? '生成中...' : '开始优化'}</button>
 `;
 } else if (stage === 'draft_review') {
 desc = '草稿已生成。先审核小金智能体整理的用户洞见，再进入最终预览。';
 actions = `
 <button class="btn-outline" type="button" onclick="kwBackToReviewIntake()">回到用户洞见</button>
 <button class="btn-gold" type="button" ${isGenerating ? 'disabled' : ''} onclick="kwConfirmReviewDraftToPreview()">确认并进入预览</button>
 `;
 } else if (stage === 'stage1_preview') {
 desc = '洞见草稿已完成，可进入最终预览。';
 actions = `
 <button class="btn-outline" type="button" onclick="kwBackToReviewDraftEdit()">返回修改</button>
 `;
 } else if (stage === 'watchlist_select' || stage === 'structured_review' || stage === 'preview_failed') {
 desc = '当前浏览器仍保留旧状态，请返回洞见草稿。';
 actions = `
 <button class="btn-outline" type="button" onclick="kwBackToReviewDraftEdit()">返回洞见草稿</button>
 <button class="btn-gold" type="button" onclick="kwConfirmReviewDraftToPreview()">进入最终预览</button>
 `;
 } else if (stage === 'draft_generating' || stage === 'preview_generating') {
 desc = '系统正在处理中。这里会持续刷新进度，处理完成后可以继续下一步。';
 actions = `
 <button class="btn-outline" type="button" onclick="kwCancelReviewAsyncJob()">停止生成</button>
 <button class="btn-gold" type="button" disabled>处理中...</button>
 `;
 } else {
 desc = '当前内容还没有进入生成阶段。';
 actions = `
 <button class="btn-outline" type="button" onclick="kwSetReviewWorkspacePanel('input')">返回输入</button>
 `;
 }
 } else if (kwReviewWorkspacePanel === 'preview') {
 desc = kwReviewPublishSubmitting ? '系统正在发布洞见，请等待结果返回。' : '确认最终阅读态和发布正文后，再正式发布给粉丝。';
 actions = `
 <button class="btn-outline" type="button" ${kwReviewPublishSubmitting ? 'disabled' : ''} onclick="kwBackToReviewDraftEdit()">回退修改</button>
 <button class="btn-gold" type="button" ${kwReviewPublishSubmitting ? 'disabled' : ''} onclick="kwPublishReviewDraft()">${kwReviewPublishSubmitting ? '发布中...' : '确认发布'}</button>
 `;
 }
 host.innerHTML = `
 <div class="kw-review-wizard-footer-meta">
 <div class="kw-review-wizard-footer-title">Step ${currentIndex + 1} / ${total} · ${escapeHtml(step.label || '')}</div>
 <div class="kw-review-wizard-footer-desc">${escapeHtml(desc)}</div>
 </div>
 <div class="kw-review-wizard-footer-actions">
 ${actions}
 </div>
 `;
}

function kwRenderReviewFlowNav() {
 const host = document.getElementById('kw-review-flow-nav');
 const flowNodes = [
 { id: 'input', label: '输入内容' },
 { id: 'draft', label: '优化成稿' },
 { id: 'preview', label: '最终预览' },
 ];
 if (!host) return;
 const sourceReady = !!kwGetReviewDraftContentText();
 const draftReady = !!String(kwReviewDraft.draftReviewText || kwReviewDraft.generatedPreviewText || '').trim();
 const finalReady = !!String(kwGetReviewPreviewText() || '').trim();
 host.innerHTML = flowNodes.map((node) => {
 const nodeId = String(node.id || '').trim();
 const active = (kwReviewDraft.flowStage === 'draft_generating' && nodeId === 'draft')
 || (kwReviewDraft.flowStage === 'draft_review' && nodeId === 'draft')
 || (kwReviewDraft.flowStage === 'preview' && nodeId === 'preview');
 const done = (nodeId === 'input' && sourceReady)
 || (nodeId === 'draft' && draftReady)
 || (nodeId === 'preview' && finalReady);
 const style = active
 ? 'background:#1F497D;color:#fff;border-color:#1F497D;'
 : (done ? 'background:rgba(47,116,192,0.10);color:#1F497D;border-color:rgba(47,116,192,0.20);' : '');
 return `<span class="kw-review-flow-step" style="${style}">${escapeHtml(node.label || '')}</span>`;
 }).join('');
}

