 </div>
 ` : ''}
 ${false && showStructuredReview && kwReviewStructuredPreview ? `
 <div class="kw-review-runtime-item" style="margin-top:12px">
 <strong>用户洞见</strong>
 <textarea id="kw-review-structured-user-input" class="kw-knowledge-modal-textarea" style="margin-top:10px;min-height:180px">${escapeHtml((((structured.user_input_section || {}).display_text) || ''))}</textarea>
 </div>
 ${hasWatchlistAnalysis ? `
 <div class="kw-review-runtime-item" style="margin-top:12px">
 <strong>历史附加内容</strong>
 ${structured.watchlist_analysis_section.provider ? `<div class="kw-review-runtime-desc" style="margin-top:6px">来源：${escapeHtml(structured.watchlist_analysis_section.provider)} · 可编辑后合并发布</div>` : ''}
 <textarea id="kw-review-structured-sector-summary" class="kw-knowledge-modal-textarea" style="margin-top:10px;min-height:220px">${escapeHtml((structured.watchlist_analysis_section.combined_text || structured.watchlist_analysis_section.sector_summary || ''))}</textarea>
 ${(((structured.watchlist_analysis_section || {}).items) || []).map((item, index) => `
 <div style="margin-top:10px">
 <div class="kw-review-runtime-desc" style="margin-bottom:6px">${escapeHtml(item.stock_name || '股票')} · ${escapeHtml(item.board_role || item.sector || '归纳样本')}</div>
 <textarea data-kw-review-watchlist-analysis-index="${index}" class="kw-knowledge-modal-textarea" style="min-height:110px">${escapeHtml(item.analysis_text || '')}</textarea>
 </div>
 `).join('')}
 </div>
 ` : `
 <div class="kw-review-runtime-item" style="margin-top:12px">
 <strong>历史附加内容</strong>
 <div class="kw-review-runtime-desc" style="margin-top:8px">当前没有选择自选股，本轮没有额外归纳内容。摘要会在最终发布时自动生成。</div>
 </div>
 `}
 ` : ''}
 ${stage === 'intake' || stage === 'optimize_rule' ? `
 <div class="kw-review-runtime-item" style="margin-top:12px">
 <strong>当前输入状态</strong>
 <div class="kw-review-runtime-desc" style="margin-top:6px">${kwGetReviewDraftContentText() ? '用户洞见内容已录入。' : '等待录入用户洞见内容。'}</div>
 </div>
