function kwOpenReviewTriggerModal(sourceMode) {
 // Keep the Web workbench aligned with H5: every new review starts with an
 // explicit user input and an empty watchlist selection.
 kwReviewDraft.period = 'day';
 kwReviewDraft.reviewTitle = '';
 kwReviewDraft.accessMode = 'public';
 kwReviewDraft.insightDraftId = '';
 kwReviewDraft.selectedWatchlist = [];
 kwReviewDraft.watchlistDecision = '';
 kwReviewDraft.paragraphMode = 'manual';
 kwReviewDraft.skipAiProcessing = true;
 kwReviewDraft.optimizeRuleMode = 'default';
 kwReviewDraft.voiceTranscript = '';
 kwReviewDraft.manualText = '';
 kwReviewDraft.manualHtml = '';
 kwReviewDraft.fileText = '';
 kwReviewDraft.fileName = '';
 kwReviewDraft.urlValue = '';
 kwReviewDraft.urlTitle = '';
 kwReviewDraft.urlText = '';
 kwReviewDraft.aiPrompt = '';
 kwReviewDraft.promptTags = [];
 kwReviewDraft.generatedPreviewText = '';
 kwReviewDraft.draftReviewText = '';
 kwReviewDraft.finalDraftText = '';
 kwReviewDraft.previewReady = false;
 kwReviewDraft.flowStage = 'intake';
 kwReviewStructuredPreview = null;
 if (sourceMode && KW_REVIEW_SOURCE_OPTIONS.some(item => item.value === sourceMode)) {
 kwReviewDraft.sourceMode = sourceMode;
 }
 if (!getAvailableKwReviewSourceOptions().some(item => item.value === kwReviewDraft.sourceMode)) {
 kwReviewDraft.sourceMode = 'manual';
 }
 kwSetReviewWorkspacePanel('input', { render: false });
 kwRenderReviewStudio();
}

function kwCloseReviewTriggerModal() {
 const modal = document.getElementById('kw-review-trigger-modal');
 if (modal) modal.classList.remove('show');
}

function kwSetReviewTriggerPeriod(period) {
 if (!KW_REVIEW_PERIOD_CONFIG[period]) return;
 kwReviewDraft.period = period;
 kwReviewDraft.generatedPreviewText = '';
 kwReviewDraft.previewReady = false;
 kwReviewStructuredPreview = null;
 kwRenderReviewStudio();
}

function kwSetReviewTriggerSourceMode(mode) {
 if (!getAvailableKwReviewSourceOptions().some(item => item.value === mode)) return;
 kwSyncReviewDraftFromModal();
 if (mode === 'manual' && !String(kwKnowledgeHtmlToPlainText(kwReviewDraft.manualHtml || '')).trim()) {
 const voiceText = String(kwReviewDraft.voiceTranscript || '').trim();
 if (voiceText) {
 kwReviewDraft.manualHtml = kwPlainTextToKnowledgeHtml(voiceText);
 }
 }
 kwReviewDraft.sourceMode = mode;
 kwReviewDraft.generatedPreviewText = '';
 kwReviewDraft.draftReviewText = '';
 kwReviewDraft.previewReady = false;
 kwReviewDraft.flowStage = 'intake';
 kwReviewStructuredPreview = null;
 kwSetReviewWorkspacePanel('input', { render: false });
 kwRenderReviewStudio();
}

function kwSetReviewTriggerParagraphMode(mode) {
 if (!KW_REVIEW_PARAGRAPH_OPTIONS.some(item => item.value === mode)) return;
 kwSyncReviewDraftFromModal();
 kwReviewDraft.paragraphMode = mode;
 kwReviewDraft.previewReady = false;
 kwReviewStructuredPreview = null;
 kwRenderReviewStudio();
}

function kwSetReviewOptimizeRuleMode(mode) {
 kwSyncReviewDraftFromModal();
 kwReviewDraft.optimizeRuleMode = mode === 'custom' ? 'custom' : 'default';
 if (kwReviewDraft.optimizeRuleMode === 'default') {
 kwReviewDraft.aiPrompt = '';
 kwReviewDraft.promptTags = [];
 }
 kwRenderReviewStudio();
}

function kwToggleReviewSkipAiProcessing(checked) {
 kwSyncReviewDraftFromModal();
 kwReviewDraft.skipAiProcessing = !!checked;
 if (kwReviewDraft.skipAiProcessing) {
 kwReviewDraft.paragraphMode = 'manual';
 kwReviewDraft.aiPrompt = '';
 kwReviewDraft.promptTags = [];
 kwReviewDraft.generatedPreviewText = '';
 }
 kwReviewDraft.previewReady = false;
 kwReviewStructuredPreview = null;
 kwRenderReviewStudio();
}

function kwToggleReviewTriggerWatchlist(name) {
 const fullList = getKwTenantWatchlistFocus();
 if (!fullList.includes(name)) return;
 const current = new Set(kwReviewDraft.selectedWatchlist || []);
 if (current.has(name)) current.delete(name); else current.add(name);
 kwReviewDraft.selectedWatchlist = fullList.filter(item => current.has(item));
 kwReviewDraft.previewReady = false;
 kwReviewStructuredPreview = null;
 kwSetReviewWorkspacePanel('input', { render: false });
 kwRenderReviewStudio();
}

function kwCaptureReviewVoiceInput() {
 if (kwReviewVoiceUploading) return;
 if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia || typeof MediaRecorder === 'undefined') {
 showToast('当前浏览器不支持录音');
 return;
 }
 if (kwReviewVoiceRecording && kwReviewVoiceRecorder) {
 kwReviewVoiceRecorder.stop();
 return;
 }
 navigator.mediaDevices.getUserMedia({ audio: true }).then((stream) => {
 const mimeType = MediaRecorder.isTypeSupported('audio/webm') ? 'audio/webm' : '';
 kwReviewVoiceChunks = [];
 kwReviewVoiceRecorder = new MediaRecorder(stream, mimeType ? { mimeType } : undefined);
 kwReviewVoiceRecording = true;
 kwReviewDraft.previewReady = false;
 kwReviewVoiceRecorder.ondataavailable = (event) => {
 if (event.data && event.data.size > 0) {
 kwReviewVoiceChunks.push(event.data);
 }
 };
 kwReviewVoiceRecorder.onerror = () => {
 kwReviewVoiceRecording = false;
 kwReviewVoiceUploading = false;
 stream.getTracks().forEach((track) => track.stop());
 kwRenderReviewStudio();
 showToast('录音失败，请重试');
 };
 kwReviewVoiceRecorder.onstop = async () => {
 kwReviewVoiceRecording = false;
 kwReviewVoiceUploading = true;
 kwRenderReviewStudio();
 const blob = new Blob(kwReviewVoiceChunks, { type: kwReviewVoiceRecorder.mimeType || 'audio/webm' });
 stream.getTracks().forEach((track) => track.stop());
 try {
 const data = await kwUploadReviewVoiceBlob(blob);
 if (!data.async || !data.job_code) throw new Error('voice_transcribe_job_missing');
 showToast('语音已提交，正在后台转写');
 kwStartAsyncJobPolling(data.job_code, {
 onSuccess(job) {
 const result = job.result || {};
 const hadTranscript = !!String(kwReviewDraft.voiceTranscript || '').trim();
 kwReviewDraft.voiceTranscript = kwAppendTranscribedText(
 kwReviewDraft.voiceTranscript,
 result.display_transcript || result.enhanced_transcript || result.transcript || ''
 );
 kwReviewDraft.previewReady = false;
 kwReviewIngestResult = result;
 kwRenderReviewStudio();
 showToast(hadTranscript ? '语音已追加到文案' : '语音已转成文案，待确认发布');
 },
 onFailed(job) {
 showToast(job.error_message || '语音转写失败');
 },
 });
 } catch (error) {
 showToast(error.message || '语音转写失败');
 } finally {
 kwReviewVoiceUploading = false;
 kwReviewVoiceRecorder = null;
 kwReviewVoiceChunks = [];
 kwRenderReviewStudio();
 }
 };
 kwReviewVoiceRecorder.start();
 kwRenderReviewStudio();
 }).catch(() => {
 showToast('未获得麦克风权限');
 });
}

function kwCaptureReviewFileInputLegacy() {
 const input = document.createElement('input');
 input.type = 'file';
 input.accept = '.pdf,.docx,.xlsx,.xlsm,.txt,.md,.csv,.html,.htm,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/plain,text/csv,text/html';
 input.onchange = async () => {
 const file = input.files && input.files[0];
 if (!file) return;
 const formData = new FormData();
 formData.append('file', file, file.name);
 const resp = await fetch('/api/kol/knowledge/file-preview', {
 method: 'POST',
 body: formData,
 });
 const data = await resp.json();
 if (!resp.ok || !data.ok) {
 showToast((data && data.error) || '文件解析失败');
 return;
 }
 const preview = data.preview || {};
 kwReviewDraft.fileName = preview.filename || file.name;
 kwReviewDraft.fileText = preview.body || preview.summary || '';
 kwReviewDraft.manualHtml = kwMergePlainTextIntoKnowledgeHtml(kwReviewDraft.manualHtml || '', kwReviewDraft.fileText || '');
 kwReviewDraft.sourceMode = 'manual';
 kwReviewDraft.previewReady = false;
 kwReviewStructuredPreview = null;
 kwRenderReviewStudio();
 showToast('文件已转成文案，可继续手动修改');
 };
 input.click();
}

function kwToggleReviewPromptTag(tag) {
 kwSyncReviewDraftFromModal();
 const current = new Set(kwReviewDraft.promptTags || []);
 if (current.has(tag)) current.delete(tag); else current.add(tag);
 kwReviewDraft.promptTags = KW_REVIEW_PROMPT_TAGS.filter(item => current.has(item));
 kwReviewDraft.previewReady = false;
 kwReviewStructuredPreview = null;
 kwRenderReviewStudio();
}

function kwBuildPublishedReviewFromDraft() {
 const periodMeta = getKwReviewPeriodMeta(kwReviewDraft.period);
 const contentText = kwGetReviewPreviewText() || kwGetReviewDraftContentText();
 const title = String(kwReviewDraft.reviewTitle || '').trim() || `${contentText.split(/[。！？\n]/).map(item => item.trim()).find(Boolean) || '洞见已完成'}`;
 const tags = kwReviewDraft.paragraphMode === 'manual' ? ['用户直发'] : ['优化成稿'];
 return {
 title: title.slice(0, 40),
 period: '洞见',
 time: new Date().toLocaleString('zh-CN', { hour12: false }),
 tags,
 watchlist: kwReviewDraft.selectedWatchlist.slice(0),
 summary: kwGetReviewPreviewText().replace(/\n+/g, ' ').slice(0, 120),
 };
}

function kwPublishReviewDraft() {
 const runtime = ensureKwReviewRuntime();
 if (kwReviewPublishSubmitting) return;
 kwSyncReviewTextInputs();
 const item = kwBuildPublishedReviewFromDraft();
 const finalText = kwGetReviewPreviewText();
 const transcriptionEngine = kwReviewDraft.sourceMode === 'voice'
 ? ((kwReviewIngestResult && kwReviewIngestResult.transcript_engine) || 'local')
 : 'manual';
 const transcriptModel = kwReviewDraft.sourceMode === 'voice'
 ? ((kwReviewIngestResult && kwReviewIngestResult.transcript_model) || '')
 : 'manual_input';
 const previewPayload = kwReviewStructuredPreview && typeof kwReviewStructuredPreview === 'object' ? kwReviewStructuredPreview : {};
 const llmModels = [];
 if (kwReviewIngestResult && kwReviewIngestResult.review_draft_llm) {
 llmModels.push({
 stage: 'draft',
 key: kwReviewIngestResult.review_draft_llm.key || '',
 label: kwReviewIngestResult.review_draft_llm.label || '',
 provider: kwReviewIngestResult.review_draft_llm.provider || '',
 model_name: kwReviewIngestResult.review_draft_llm.model_name || '',
 purpose: kwReviewIngestResult.review_draft_llm.purpose || '',
 });
 }
 (previewPayload.llm_models || []).forEach((item) => {
 if (item && !llmModels.some((row) => row.stage === item.stage && row.key === item.key && row.model_name === item.model_name)) {
 llmModels.push(item);
 }
 });
 kwReviewPublishSubmitting = true;
 kwRenderReviewStudio();
 showToast('正在发布洞见，请稍候');
 kwPublishReviewContent(finalText, transcriptionEngine, transcriptModel, {
 review_summary: previewPayload.review_summary || '',
 user_input_section: previewPayload.user_input_section || {
 source_mode: kwReviewDraft.sourceMode || 'manual',
 source_mode_label: (KW_REVIEW_SOURCE_OPTIONS.find((option) => option.value === kwReviewDraft.sourceMode) || {}).label || '用户输入',
 display_text: kwGetReviewUserInputDisplayText(),
 summary_source: 'llm_user_input_only',
 },
 watchlist_analysis_section: previewPayload.watchlist_analysis_section || {},
 llm_models: llmModels,
 }).then((publishResult) => {
 kwReviewPublishSubmitting = false;
 kwReviewIngestResult = publishResult || {};
 runtime.kolPublishedAt = '刚刚发布';
 runtime.kolGeneratedAt = '刚刚发布';
 runtime.latestReviewTitle = kwReviewDraft.reviewTitle || '';
 runtime.draftReady = false;
 kwSyncPublishedReviewState(publishResult);
 if (window.WORKBENCH_DATA) {
 if (Array.isArray(publishResult.snapshots) && publishResult.snapshots.length) {
 window.WORKBENCH_DATA.published_reviews = publishResult.snapshots.slice(0, 20);
 } else {
 const reviews = Array.isArray(window.WORKBENCH_DATA.published_reviews) ? window.WORKBENCH_DATA.published_reviews : [];
 reviews.unshift(publishResult.snapshot || item);
 window.WORKBENCH_DATA.published_reviews = reviews.slice(0, 20);
 }
 if (publishResult.message_center_state) {
 const threadItems = Array.isArray(publishResult.message_center_state.threads) ? publishResult.message_center_state.threads : [];
 window.WORKBENCH_DATA.message_center = {
 summary: publishResult.message_center_state.summary || ((window.WORKBENCH_DATA.message_center || {}).summary) || '',
 items: threadItems.slice(0, 6).map((thread) => ({
 name: thread.name || thread.user_name || '',
 type: thread.type === 'review_notification' ? '系统消息' : (thread.status === '待回复' ? '粉丝提问' : '追问消息'),
 time: thread.time || '--',
 content: thread.content || '',
 status: thread.status || '待处理',
 })),
 threads: threadItems,
 };
 }
 }
 kwCloseReviewTriggerModal();
 kwRenderReviewStudio();
 kwRenderPublishedReviewList();
 renderWorkbenchAnnotationViews();
 showToast((publishResult && publishResult.message) || '洞见已发布');
 }).catch((error) => {
 kwReviewPublishSubmitting = false;
 kwRenderReviewStudio();
 showToast(error.message || '发布入库失败');
 });
}

function kwRenderPublishedReviewList() {
 const host = document.getElementById('kw-published-review-list');
 const reviews = (window.WORKBENCH_DATA && window.WORKBENCH_DATA.published_reviews) || [];
 if (!host) return;
 host.innerHTML = reviews.map((item, index) => `
 <div class="kw-broadcast-item">
 <div class="kw-broadcast-top">
 <div class="kw-broadcast-content">${escapeHtml(item.title || '')}</div>
 <span class="kw-tag">${escapeHtml(item.period || '')}</span>
 </div>
 <div class="kw-broadcast-meta">${escapeHtml(item.time || '')} · ${escapeHtml(item.summary || '')}</div>
 <div data-workbench-review-annotation="${index}" style="margin-top:10px"></div>
 <div class="kw-chip-row" style="margin-top:10px">
 ${Array.isArray(item.tags) ? item.tags.map(tag => `<span class="kw-chip">${escapeHtml(tag)}</span>`).join('') : ''}
 </div>
 <div style="display:flex;justify-content:flex-end;margin-top:10px">
 <button class="btn-outline" type="button" style="padding:5px 9px;font-size:11px;color:#B42318;border-color:rgba(180,35,24,0.24)" onclick="kwDeletePublishedReview('${escapeAttr(item.id || '')}')">删除洞见</button>
 </div>
 </div>
 `).join('');
}

async function kwDeletePublishedReview(reviewId) {
 const normalizedReviewId = String(reviewId || '').trim();
 const tenantSlug = String(((window.ACTIVE_TENANT || {}).slug) || '').trim().toLowerCase();
 if (!normalizedReviewId || !tenantSlug) {
 showToast('当前洞见缺少有效标识，无法删除');
 return;
 }
 if (!window.confirm('确认删除这篇已发布洞见吗？删除后将不再对前台用户展示，且无法撤销。')) return;
 try {
 const response = await fetch(`/api/tenant/${encodeURIComponent(tenantSlug)}/reviews/${encodeURIComponent(normalizedReviewId)}`, {
 method: 'DELETE',
 });
 const payload = await response.json();
 if (!response.ok || !payload.ok) throw new Error(payload.error || 'review_delete_failed');
 kwSyncPublishedReviewState(payload);
 if (window.WORKBENCH_DATA) {
 window.WORKBENCH_DATA.published_reviews = Array.isArray(payload.snapshots) ? payload.snapshots.slice(0, 20) : [];
 }
 kwRenderPublishedReviewList();
 kwRenderReviewStudio();
 showToast(payload.message || '洞见已删除');
 } catch (error) {
 showToast(error.message || '洞见删除失败');
 }
}

function kwRenderReviewStudio() {
 const runtime = ensureKwReviewRuntime();
 const periodHost = document.getElementById('kw-review-top-period-row');
 const directoryHost = document.getElementById('kw-review-directory-nav-list');
 const flowHost = document.getElementById('kw-review-flow-nav');
 const overviewHost = document.getElementById('kw-review-overview-summary');
 const cardSlotHost = document.getElementById('kw-review-card-slot-grid');
 const cardDetailHost = document.getElementById('kw-review-card-detail-list');
 const inputModeHost = document.getElementById('kw-review-input-mode-row');
 const watchlistHost = document.getElementById('kw-review-watchlist-selector');
 const intakeHost = document.getElementById('kw-review-intake-workspace');
 const stageActionsHost = document.getElementById('kw-review-stage-actions');
 const progressHost = document.getElementById('kw-review-progress-host');
 const stageResultsHost = document.getElementById('kw-review-stage-results');
 const previewHost = document.getElementById('kw-review-preview-article');
 const wizardFooterHost = document.getElementById('kw-review-wizard-footer');
 const runtimeHost = document.getElementById('kw-review-runtime-panel');
 const latestHost = document.getElementById('kw-review-latest-published');
 const latestPublished = (window.WORKBENCH_DATA && window.WORKBENCH_DATA.published_reviews && window.WORKBENCH_DATA.published_reviews[0]) || null;
 const sourceCfg = KW_REVIEW_SOURCE_OPTIONS.find(item => item.value === runtime.kolSourceMode) || KW_REVIEW_SOURCE_OPTIONS[0];
 const paragraphCfg = KW_REVIEW_PARAGRAPH_OPTIONS.find(item => item.value === runtime.paragraphMode) || KW_REVIEW_PARAGRAPH_OPTIONS[0];
 const selectedKnowledge = kwGetReviewSelectedKnowledge();
 const selectedCards = kwGetReviewSelectedCards();
 // A new review must start with a blank title; the last published title is
 // runtime history, not input for the next review.
 kwReviewDraft.reviewTitle = kwReviewDraft.reviewTitle || '';
 if (['watchlist_select', 'structured_review', 'stage1_preview'].includes(String(kwReviewDraft.flowStage || '').trim().toLowerCase())) {
 // Migrate stale browser state from the removed stock-analysis stages.
 kwReviewDraft.selectedWatchlist = [];
 kwReviewDraft.watchlistDecision = 'not_applicable';
 kwReviewDraft.flowStage = kwReviewDraft.previewReady ? 'preview' : (kwReviewDraft.draftReviewText ? 'draft_review' : 'intake');
 kwReviewStructuredPreview = null;
 }
 if (!KW_REVIEW_WORKSPACE_PANELS.some((item) => item.id === kwReviewWorkspacePanel)) {
 kwReviewWorkspacePanel = kwInferReviewWorkspacePanel();
 }
 if (periodHost) kwRenderReviewTopPeriodRow();
 if (directoryHost) kwRenderReviewDirectoryNav();
 if (flowHost) kwRenderReviewFlowNav();
 if (overviewHost) kwRenderReviewOverviewSummary();
 if (cardSlotHost) kwRenderReviewCardSlotGrid();
 if (cardDetailHost) kwRenderReviewCardDetailList();
 if (inputModeHost) kwRenderReviewInputModeRow();
 if (watchlistHost) kwRenderReviewWatchlistSelector();
 if (intakeHost) {
 intakeHost.innerHTML = kwRenderReviewInputPanel();
 if (kwReviewWorkspacePanel === 'input') intakeHost.insertAdjacentHTML('beforeend', kwRenderInsightDraftLibrary());
 }
 if (stageActionsHost) kwRenderReviewStageActions();
 if (progressHost) progressHost.innerHTML = kwRenderReviewDraftProgressPanel();
 if (stageResultsHost) kwRenderReviewStageResults();
 if (previewHost) kwRenderReviewPreviewWorkspace();
 if (wizardFooterHost) kwRenderReviewWizardFooter();
 if (runtimeHost) {
 runtimeHost.innerHTML = `
 <div class="kw-review-runtime-item">
 <strong>${escapeHtml(getKwReviewPeriodMeta(runtime.lastReviewPeriod).label)} · ${escapeHtml(sourceCfg.label)} · ${escapeHtml(paragraphCfg.label)}</strong>
 <div class="kw-review-runtime-desc">最近一次生成：${escapeHtml(runtime.kolGeneratedAt || '--')}｜最近一次发布：${escapeHtml(runtime.kolPublishedAt || '--')}</div>
 </div>
 <div class="kw-review-runtime-item">
 <strong>本次纳入洞见的自选股</strong>
 <div class="kw-watch-chip-row" style="margin-top:8px">${kwGetSelectedWatchlist().map(name => `<span class="kw-watch-chip">${escapeHtml(name)}</span>`).join('')}</div>
 </div>
 <div class="kw-review-runtime-item">
 <strong>当前修改规则</strong>
 <div class="kw-review-runtime-desc">${escapeHtml(runtime.latestAiPrompt || '当前未填写修改规则')}</div>
 </div>
 <div class="kw-review-runtime-item">
 <strong>本次已选素材</strong>
 <div class="kw-review-runtime-desc">智能卡片 ${selectedCards.length} 张，知识材料 ${selectedKnowledge.length} 份。</div>
 </div>
 `;
 }
 if (latestHost) {
 latestHost.innerHTML = latestPublished ? `
 <div class="kw-review-runtime-item">
 <strong>${escapeHtml(latestPublished.title || '')}</strong>
 <div class="kw-review-runtime-desc">${escapeHtml(latestPublished.time || '--')} · ${escapeHtml(latestPublished.period || '')}</div>
 <div class="kw-review-runtime-desc" style="margin-top:6px">${escapeHtml(latestPublished.summary || '')}</div>
 <div class="kw-watch-chip-row" style="margin-top:8px">
 ${(latestPublished.watchlist || []).map(name => `<span class="kw-watch-chip">${escapeHtml(name)}</span>`).join('')}
 </div>
 </div>
 ` : '<div class="kw-review-runtime-item"><strong>暂无已发布洞见</strong><div class="kw-review-runtime-desc">生成草稿并确认发布后，这里会同步显示最新结果。</div></div>';
 }
 const finalEditor = document.getElementById('kw-review-final-editor');
 if (finalEditor) {
 const nextValue = String(kwReviewDraft.finalDraftText || kwGetReviewPreviewText() || kwReviewDraft.generatedPreviewText || kwGetReviewDraftContentText() || '').trim();
 if (finalEditor.value !== nextValue) finalEditor.value = nextValue;
 }
 kwApplyReviewWorkspacePanelState();
 kwEnsureReviewEditors();
 if (!kwInsightDraftsLoaded && !kwInsightDraftsLoading) kwLoadInsightDrafts();
}

function loadWorkbenchWatchlistAnnotations() {
 return kwWatchlistAnnotationStore;
}

function replaceWorkbenchStockAnnotations(stockCode, items) {
 const tenantId = window.ACTIVE_TENANT && window.ACTIVE_TENANT.id;
 if (!tenantId) return;
 const storage = loadWorkbenchWatchlistAnnotations();
 if (!storage[tenantId]) storage[tenantId] = {};
 storage[tenantId][String(stockCode || '').toUpperCase()] = (Array.isArray(items) ? items : []).map((item) => ({
 id: item.id,
 candleIndex: Number(item.candleIndex ?? item.candle_index ?? 0),
 dateLabel: item.dateLabel || item.candle_date || '',
 title: item.title || '',
 note: item.note || '',
 trigger: item.trigger || '',
 updatedAt: item.updatedAt || item.updated_at || item.createdAt || item.created_at || '刚刚',
 }));
}

function kwGetWatchlistTenantPayload() {
 const tenant = window.ACTIVE_TENANT || {};
 return {
 tenant_slug: String(tenant.slug || '').trim().toLowerCase(),
 user_role: 'dav',
 user_profile_id: String(tenant.advisor || '').trim(),
 user_name: String(tenant.advisor || '').trim(),
 };
}

async function kwSyncLocalWatchlistAnnotationsToServer(stockRefs) {
 // Annotation writes are sent to the server at creation time. There is no
 // browser-side queue to replay before preview or publish.
 return Promise.resolve();
}

async function kwLoadWatchlistAnnotationsFromServer(stockRefs) {
 const tenant = window.ACTIVE_TENANT || {};
 if (!tenant.slug) return;
 const detailsMap = window.WATCHLIST_DETAILS_MAP || {};
 const codes = (Array.isArray(stockRefs) ? stockRefs : [stockRefs]).map((item) => {
 const raw = String(item || '').trim();
 if (!raw) return '';
 const detail = Object.values(detailsMap).find((row) => row && (row.code === raw || row.name === raw));
 return String((detail && detail.code) || raw).trim().toUpperCase();
 }).filter(Boolean);
 await Promise.all(codes.map(async (stockCode) => {
 try {
 const resp = await fetch(`/api/watchlist/${encodeURIComponent(stockCode)}/annotations?tenant_slug=${encodeURIComponent(String(tenant.slug || '').trim().toLowerCase())}`);
 const data = await resp.json();
 if (resp.ok && data.ok) {
 replaceWorkbenchStockAnnotations(stockCode, data.items || []);
 kwLoadedWatchlistAnnotationCodes[`${String(tenant.slug || '').trim().toLowerCase()}:${stockCode}`] = true;
 }
 } catch (e) {}
 }));
}

function getWorkbenchStockAnnotations(stockCode) {
 const tenantId = window.ACTIVE_TENANT && window.ACTIVE_TENANT.id;
 const storage = loadWorkbenchWatchlistAnnotations();
 const bucket = tenantId && storage[tenantId] && storage[tenantId][String(stockCode || '').toUpperCase()];
 return Array.isArray(bucket) ? bucket.slice().sort((a, b) => Number(a.candleIndex || 0) - Number(b.candleIndex || 0)) : [];
}

function getWorkbenchReviewAnnotations(reviewItem) {
 const detailsMap = window.WATCHLIST_DETAILS_MAP || {};
 const watchlist = Array.isArray(reviewItem.watchlist) ? reviewItem.watchlist : [];
 return watchlist.map((name) => {
 const detail = Object.values(detailsMap).find(item => item && item.name === name);
 if (!detail) return null;
 const annotations = getWorkbenchStockAnnotations(detail.code);
 if (!annotations.length) return null;
 return {
 name,
 summary: annotations.slice(0, 2).map(item => `${item.dateLabel} ${item.note}`).join('；'),
 };
 }).filter(Boolean);
}

function renderWorkbenchAnnotationViews() {
 const tenant = window.ACTIVE_TENANT || {};
 const tenantSlug = String(tenant.slug || '').trim().toLowerCase();
 const watchNodeCodes = Array.from(document.querySelectorAll('[data-workbench-watch-annotation]')).map((node) => String(node.getAttribute('data-workbench-watch-annotation') || '').trim().toUpperCase()).filter(Boolean);
 const reviews = (window.WORKBENCH_DATA && window.WORKBENCH_DATA.published_reviews) || [];
 const reviewCodes = reviews.flatMap((reviewItem) => {
 const watchlist = Array.isArray(reviewItem.watchlist) ? reviewItem.watchlist : [];
 return watchlist.map((name) => {
 const detail = Object.values(window.WATCHLIST_DETAILS_MAP || {}).find((item) => item && item.name === name);
 return String((detail && detail.code) || '').trim().toUpperCase();
 }).filter(Boolean);
 });
 const codesToHydrate = Array.from(new Set(watchNodeCodes.concat(reviewCodes))).filter((code) => tenantSlug && !kwLoadedWatchlistAnnotationCodes[`${tenantSlug}:${code}`]);
 if (codesToHydrate.length) {
 kwLoadWatchlistAnnotationsFromServer(codesToHydrate).then(() => {
 renderWorkbenchAnnotationViews();
 }).catch(() => null);
 }
 document.querySelectorAll('[data-workbench-watch-annotation]').forEach((node) => {
 const stockCode = node.getAttribute('data-workbench-watch-annotation') || '';
 const annotations = getWorkbenchStockAnnotations(stockCode);
 if (!annotations.length) {
 node.innerHTML = '<div class="kw-side-note">当前还没有 K 线标注，H5 里的大V视角新增后会同步显示在这里。</div>';
 return;
 }
 const latest = annotations[annotations.length - 1];
 node.innerHTML = `
 <div class="kw-watch-chip-row" style="margin-bottom:8px">
 <span class="kw-watch-chip">K线标注 ${annotations.length} 条</span>
 </div>
 <div class="kw-side-card">
 <div class="kw-knowledge-title">${escapeHtml(latest.title || '最新标注')}</div>
 <div class="kw-knowledge-meta">${escapeHtml(latest.dateLabel || '--')} · 最新洞见</div>
 <div class="kw-side-note" style="margin-top:6px">${escapeHtml(latest.note || '')}${latest.trigger ? `｜验证节点：${escapeHtml(latest.trigger)}` : ''}</div>
 </div>
 `;
 });

 document.querySelectorAll('[data-workbench-review-annotation]').forEach((node) => {
 const index = Number(node.getAttribute('data-workbench-review-annotation') || 0);
 const reviewItem = reviews[index];
 const annotations = reviewItem ? getWorkbenchReviewAnnotations(reviewItem) : [];
 if (!annotations.length) {
 node.innerHTML = '';
 return;
 }
 node.innerHTML = `
 <div class="kw-side-card">
 <div class="kw-side-title" style="margin-bottom:8px">本篇洞见引用的 K 线标注</div>
 ${annotations.map(item => `
 <div class="kw-side-item" style="display:block;border-bottom:none;padding:0 0 8px">
 <div class="kw-knowledge-title">${escapeHtml(item.name)}</div>
 <div class="kw-side-note" style="margin-top:4px">${escapeHtml(item.summary)}</div>
 </div>
 `).join('')}
 </div>
 `;
 });
}

let kwForecastConfig = {};
let kwForecastWorkflowMeta = {};
let kwForecastGraph = {nodes: [], edges: [], tuning: {}};
let kwSelectedForecastNodeId = '';
let kwForecastDragState = null;
let kwForecastLinkState = null;
let kwForecastZoom = 1;
let kwForecastEditorBootstrapped = false;
let kwForecastLoaded = false;

function renderWorkbenchForecastWorkflow() {
 const board = document.getElementById('kw-forecast-workflow-board');
 const summary = document.getElementById('kw-forecast-workflow-summary');
 const stats = document.getElementById('kw-forecast-graph-stats');
 const preview = kwForecastWorkflowMeta.preview || {};
 if (summary) {
 const result = preview.result || {};
 summary.textContent = result.predicted_change_pct !== undefined
 ? `当前示例预览目标 ${Number(result.predicted_change_pct || 0).toFixed(2)}%，波动上限 ${Number(result.volatility_cap || 0).toFixed(2)}%。`
 : (kwForecastWorkflowMeta.summary || '展示目标价是怎么计算出来的，并允许在后台调整自动收敛参数。');
 }
 if (stats) {
 stats.textContent = `${(kwForecastGraph.nodes || []).length} 节点 · ${(kwForecastGraph.edges || []).length} 连线 · 当前算法`;
 }
 if (!board) return;
 const graph = kwForecastWorkflowMeta.graph || kwForecastGraph;
 const nodes = Array.isArray(graph.nodes) ? graph.nodes : [];
 applyWorkbenchForecastZoom();
 if (!nodes.length) {
 board.innerHTML = `<div class="kw-compact-row"><strong>暂无工作流节点</strong><span>0</span></div>`;
 const edgeLayer = document.getElementById('kw-forecast-edge-layer');
 if (edgeLayer) edgeLayer.innerHTML = '';
 return;
 }
 board.innerHTML = nodes.map((item) => `
 <article class="kw-workflow-node ${item.id === kwSelectedForecastNodeId ? 'is-selected' : ''} ${kwForecastLinkState?.from === item.id ? 'is-link-source' : ''}" data-node-id="${escapeAttr(item.id || '')}" style="left:${Number(item.x || 0)}px;top:${Number(item.y || 0)}px;">
 <div class="kw-workflow-node-head">
 <strong>${escapeHtml(item.label || item.id || '-')}</strong>
 <span class="kw-workflow-node-type">${escapeHtml(item.processor || '')}</span>
 </div>
 <div class="kw-workflow-node-ports">
 <button type="button" class="kw-workflow-port" data-port-action="select" data-node-id="${escapeAttr(item.id || '')}">接入</button>
 <button type="button" class="kw-workflow-port" data-port-action="link" data-node-id="${escapeAttr(item.id || '')}">连出</button>
 </div>
 </article>
 `).join('');
 bindWorkbenchForecastGraphEvents();
 renderWorkbenchForecastEdges();
 renderWorkbenchForecastCatalog();
}

function renderWorkbenchForecastConfigBoard() {
 const board = document.getElementById('kw-forecast-config-board');
 if (!board) return;
 const selectedNode = (kwForecastGraph.nodes || []).find((item) => item.id === kwSelectedForecastNodeId) || null;
 const catalog = Array.isArray(kwForecastWorkflowMeta.catalog) ? kwForecastWorkflowMeta.catalog : [];
 const nodeSpec = selectedNode ? catalog.find((item) => item.processor === selectedNode.processor) : null;
 const tuningEntries = Object.entries(kwForecastConfig || {});
 const paramFields = Array.isArray(nodeSpec?.params) ? nodeSpec.params : [];
 const debugBlock = renderWorkbenchForecastNodeDebug();
 const selectedBlock = selectedNode ? `
 <div class="kw-forecast-inspector-section">
 <div class="kw-forecast-config-section-title">节点参数</div>
 <label class="kw-forecast-config-field">
 <span>节点名称</span>
 <div class="kw-forecast-config-input">
 <input data-kw-node-label value="${escapeAttr(String(selectedNode.label || ''))}">
 <em>label</em>
 </div>
 </label>
 ${paramFields.length ? paramFields.map((field) => `
 <label class="kw-forecast-config-field">
 <span>${escapeHtml(field.label || field.key || '-')}</span>
 <div class="kw-forecast-config-input">
 <input data-kw-node-param="${escapeAttr(field.key || '')}" value="${escapeAttr(String(selectedNode.params?.[field.key] ?? ''))}">
 <em>${escapeHtml(field.kind || '')}</em>
 </div>
 </label>
 `).join('') : `<div class="kw-compact-row"><strong>当前节点无独立参数</strong><span>${escapeHtml(selectedNode.processor || '')}</span></div>`}
 </div>
 ` : `<div class="kw-compact-row"><strong>未选中节点</strong><span>点击画布节点后编辑参数</span></div>`;
 board.innerHTML = `
 ${selectedBlock}
 <div class="kw-forecast-inspector-section">
 <div class="kw-forecast-config-section-title">节点预览</div>
 ${debugBlock}
 </div>
 <details class="kw-forecast-inspector-section">
 <summary class="kw-forecast-advanced-toggle">高级参数</summary>
 ${tuningEntries.map(([key, value]) => `
 <label class="kw-forecast-config-field">
 <span>${escapeHtml(key)}</span>
 <div class="kw-forecast-config-input">
 <input data-kw-forecast-field="${escapeAttr(key)}" inputmode="decimal" step="0.05" value="${escapeAttr(String(value ?? ''))}">
 <em>tuning</em>
 </div>
 </label>
 `).join('')}
 </details>
 ${selectedNode ? `
 <div style="display:flex;justify-content:flex-end;margin-top:4px">
 <button type="button" class="btn-outline kw-workflow-tool-button" id="kw-forecast-delete-node">删除节点</button>
 </div>
 ` : ''}
 `;
 document.getElementById('kw-forecast-delete-node')?.addEventListener('click', deleteWorkbenchForecastNode);
}

function renderWorkbenchForecastNodeDebug() {
 const selectedNode = (kwForecastGraph.nodes || []).find((item) => item.id === kwSelectedForecastNodeId) || null;
 const nodeResults = kwForecastWorkflowMeta.preview?.node_results || kwForecastWorkflowMeta.graph?.node_results || {};
 if (!selectedNode) {
 return `<div class="kw-compact-row"><strong>未选中节点</strong><span>暂无调试信息</span></div>`;
 }
 const debug = nodeResults[selectedNode.id];
 if (!debug) {
 return `<div class="kw-compact-row"><strong>${escapeHtml(selectedNode.label || selectedNode.id || '-')}</strong><span>暂无运行结果</span></div>`;
 }
 const preview = debug.context_preview && typeof debug.context_preview === 'object'
 ? Object.entries(debug.context_preview).map(([key, value]) => `<div class="kw-result-line"><strong>${escapeHtml(key)}</strong> · ${escapeHtml(String(value))}</div>`).join('')
 : `<div class="kw-result-line">暂无上下文预览</div>`;
 return `
 <div class="kw-forecast-config-field">
 <span>当前输出</span>
 <div class="kw-forecast-debug-value">${escapeHtml(String(debug.value ?? '--'))}</div>
 </div>
 <div class="kw-forecast-config-field">
 <span>计算公式</span>
 <div class="kw-forecast-debug-copy">${escapeHtml(debug.formula || '暂无')}</div>
 </div>
 <div class="kw-forecast-config-field">
 <span>说明</span>
 <div class="kw-forecast-debug-copy">${escapeHtml(debug.note || '暂无')}</div>
 </div>
 <div class="kw-forecast-config-field">
 <span>上下文预览</span>
 <div class="kw-forecast-debug-list">${preview}</div>
 </div>
 `;
}

function renderWorkbenchForecastCatalog() {
 const host = document.getElementById('kw-forecast-node-catalog');
 if (!host) return;
 const catalog = Array.isArray(kwForecastWorkflowMeta.catalog) ? kwForecastWorkflowMeta.catalog : [];
 host.innerHTML = catalog.map((item) => `
 <button type="button" class="kw-workflow-catalog-item" data-add-processor="${escapeAttr(item.processor || '')}">
 <strong>${escapeHtml(item.label || item.processor || '-')}</strong>
 <span>${escapeHtml(item.description || '')}</span>
 </button>
 `).join('');
 host.querySelectorAll('[data-add-processor]').forEach((node) => {
 node.addEventListener('click', () => addWorkbenchForecastNode(node.dataset.addProcessor || 'source'));
 });
}

function renderWorkbenchForecastEdges() {
 const layer = document.getElementById('kw-forecast-edge-layer');
 const board = document.getElementById('kw-forecast-workflow-board');
 const viewport = document.getElementById('kw-forecast-stage-viewport');
 if (!layer || !board) return;
 const nodes = Array.isArray(kwForecastGraph.nodes) ? kwForecastGraph.nodes : [];
 const edges = Array.isArray(kwForecastGraph.edges) ? kwForecastGraph.edges : [];
 const width = Math.max(1800, ...nodes.map((item) => Number(item.x || 0) + 280));
 const height = Math.max(760, ...nodes.map((item) => Number(item.y || 0) + 180));
 board.style.width = `${width}px`;
 board.style.height = `${height}px`;
 if (viewport) {
 viewport.style.width = `${width}px`;
 viewport.style.height = `${height}px`;
 }
 layer.setAttribute('width', String(width));
 layer.setAttribute('height', String(height));
 layer.setAttribute('viewBox', `0 0 ${width} ${height}`);
 layer.innerHTML = `
 <defs>
 <marker id="kw-workflow-arrowhead" viewBox="0 0 12 12" refX="10" refY="6" markerWidth="12" markerHeight="12" markerUnits="userSpaceOnUse" orient="auto">
 <path d="M 0 1 L 11 6 L 0 11 z" fill="rgba(47, 116, 192, 0.96)"></path>
 </marker>
 </defs>
 ${edges.map((edge) => {
 const fromNode = nodes.find((item) => item.id === edge.from);
 const toNode = nodes.find((item) => item.id === edge.to);
 if (!fromNode || !toNode) return '';
 const startX = Number(fromNode.x || 0) + 220;
 const startY = Number(fromNode.y || 0) + 52;
 const endX = Number(toNode.x || 0);
 const endY = Number(toNode.y || 0) + 52;
 const deltaX = endX - startX;
 const controlOffset = Math.max(80, Math.min(180, Math.abs(deltaX) * 0.45));
 const controlA = startX + (deltaX >= 0 ? controlOffset : -controlOffset);
 const controlB = endX - (deltaX >= 0 ? controlOffset : -controlOffset);
 const path = `M ${startX} ${startY} C ${controlA} ${startY}, ${controlB} ${endY}, ${endX} ${endY}`;
 return `
 <g data-edge-id="${escapeAttr(edge.id || '')}">
 <path class="kw-workflow-edge-shadow" d="${path}"></path>
 <path class="kw-workflow-edge" d="${path}" marker-end="url(#kw-workflow-arrowhead)"></path>
 <circle class="kw-workflow-edge-anchor" cx="${startX}" cy="${startY}" r="5"></circle>
 <circle class="kw-workflow-edge-anchor" cx="${endX}" cy="${endY}" r="5"></circle>
 </g>
 `;
 }).join('')}
 `;
}

function applyWorkbenchForecastZoom() {
 const viewport = document.getElementById('kw-forecast-stage-viewport');
 if (!viewport) return;
 viewport.style.transform = `scale(${kwForecastZoom})`;
 viewport.dataset.zoom = String(kwForecastZoom);
}

function bindWorkbenchForecastGraphEvents() {
 document.querySelectorAll('.kw-workflow-node').forEach((node) => {
 node.addEventListener('click', (event) => {
 if (event.target instanceof HTMLElement && event.target.dataset.portAction) return;
 kwSelectedForecastNodeId = node.dataset.nodeId || '';
 renderWorkbenchForecastWorkflow();
 renderWorkbenchForecastConfigBoard();
 renderWorkbenchForecastNodeDebug();
 });
 node.addEventListener('pointerdown', (event) => {
 if (event.target instanceof HTMLElement && event.target.dataset.portAction) return;
 const nodeId = node.dataset.nodeId || '';
 const item = (kwForecastGraph.nodes || []).find((row) => row.id === nodeId);
 if (!item) return;
 kwSelectedForecastNodeId = nodeId;
 kwForecastDragState = {
 nodeId,
 startX: event.clientX,
 startY: event.clientY,
 originX: Number(item.x || 0),
 originY: Number(item.y || 0),
 };
 node.setPointerCapture?.(event.pointerId);
 });
 });
 document.querySelectorAll('[data-port-action="link"]').forEach((node) => {
 node.addEventListener('pointerdown', (event) => {
 const target = event.currentTarget;
 if (!(target instanceof HTMLElement) || !target.closest('.kw-workflow-node')) return;
 kwForecastLinkState = {from: target.dataset.nodeId || ''};
 renderWorkbenchForecastWorkflow();
 renderWorkbenchForecastConfigBoard();
 event.preventDefault();
 });
 node.addEventListener('click', (event) => {
 const target = event.currentTarget;
 if (!(target instanceof HTMLElement) || !target.closest('.kw-workflow-node')) return;
 kwForecastLinkState = {from: target.dataset.nodeId || ''};
 renderWorkbenchForecastWorkflow();
 renderWorkbenchForecastConfigBoard();
 });
 });
 document.querySelectorAll('[data-port-action="select"]').forEach((node) => {
 node.addEventListener('pointerup', (event) => {
 const target = event.currentTarget;
 if (!(target instanceof HTMLElement) || !target.closest('.kw-workflow-node')) return;
 const nodeId = target.dataset.nodeId || '';
 if (kwForecastLinkState?.from && kwForecastLinkState.from !== nodeId) {
 addWorkbenchForecastEdge(kwForecastLinkState.from, nodeId);
 kwForecastLinkState = null;
 renderWorkbenchForecastWorkflow();
 renderWorkbenchForecastConfigBoard();
 renderWorkbenchForecastNodeDebug();
 showToast('连线已完成');
 event.preventDefault();
 }
 });
 node.addEventListener('click', (event) => {
 const target = event.currentTarget;
 if (!(target instanceof HTMLElement) || !target.closest('.kw-workflow-node')) return;
 const nodeId = target.dataset.nodeId || '';
 if (kwForecastLinkState?.from && kwForecastLinkState.from !== nodeId) {
 addWorkbenchForecastEdge(kwForecastLinkState.from, nodeId);
 kwForecastLinkState = null;
 renderWorkbenchForecastWorkflow();
 renderWorkbenchForecastConfigBoard();
 renderWorkbenchForecastNodeDebug();
 showToast('连线已完成');
 return;
 }
 kwSelectedForecastNodeId = nodeId;
 renderWorkbenchForecastWorkflow();
 renderWorkbenchForecastConfigBoard();
 renderWorkbenchForecastNodeDebug();
 });
 });
}

window.addEventListener('pointermove', (event) => {
 if (!kwForecastDragState) return;
 const item = (kwForecastGraph.nodes || []).find((row) => row.id === kwForecastDragState.nodeId);
 if (!item) return;
 const zoom = kwForecastZoom || 1;
 item.x = Math.max(8, kwForecastDragState.originX + (event.clientX - kwForecastDragState.startX) / zoom);
 item.y = Math.max(8, kwForecastDragState.originY + (event.clientY - kwForecastDragState.startY) / zoom);
 renderWorkbenchForecastWorkflow();
 renderWorkbenchForecastConfigBoard();
 renderWorkbenchForecastNodeDebug();
});

window.addEventListener('pointerup', () => {
 kwForecastDragState = null;
});

function addWorkbenchForecastNode(processor) {
 const catalog = Array.isArray(kwForecastWorkflowMeta.catalog) ? kwForecastWorkflowMeta.catalog : [];
 const spec = catalog.find((item) => item.processor === processor) || {label: processor, params: []};
 const nextIndex = (kwForecastGraph.nodes || []).length + 1;
 const nodeId = `${processor}_${Date.now()}_${nextIndex}`;
 const params = {};
 (spec.params || []).forEach((item) => {
 params[item.key] = '';
 });
 kwForecastGraph.nodes.push({
 id: nodeId,
 label: spec.label || processor,
 processor,
 x: 120 + (nextIndex % 3) * 260,
 y: 120 + Math.floor(nextIndex / 3) * 120,
 params,
 });
 kwSelectedForecastNodeId = nodeId;
 renderWorkbenchForecastWorkflow();
 renderWorkbenchForecastConfigBoard();
 renderWorkbenchForecastNodeDebug();
}

function addWorkbenchForecastEdge(fromId, toId) {
 if (!fromId || !toId || fromId === toId) return;
 if ((kwForecastGraph.edges || []).some((item) => item.from === fromId && item.to === toId)) return;
 kwForecastGraph.edges.push({id: `edge_${Date.now()}_${kwForecastGraph.edges.length + 1}`, from: fromId, to: toId});
}

function deleteWorkbenchForecastNode() {
 if (!kwSelectedForecastNodeId) return;
 kwForecastGraph.nodes = (kwForecastGraph.nodes || []).filter((item) => item.id !== kwSelectedForecastNodeId);
 kwForecastGraph.edges = (kwForecastGraph.edges || []).filter((item) => item.from !== kwSelectedForecastNodeId && item.to !== kwSelectedForecastNodeId);
 kwSelectedForecastNodeId = (kwForecastGraph.nodes || [])[0]?.id || '';
 renderWorkbenchForecastWorkflow();
 renderWorkbenchForecastConfigBoard();
 renderWorkbenchForecastNodeDebug();
}

function centerWorkbenchForecastView() {
 const stage = document.querySelector('#workbench-section-forecast-model .kw-workflow-stage');
 const viewport = document.getElementById('kw-forecast-stage-viewport');
 if (!stage) return;
 const targetWidth = viewport ? viewport.offsetWidth * kwForecastZoom : stage.scrollWidth;
 const targetHeight = viewport ? viewport.offsetHeight * kwForecastZoom : stage.scrollHeight;
 stage.scrollLeft = Math.max(0, (targetWidth - stage.clientWidth) / 2);
 stage.scrollTop = Math.max(0, (targetHeight - stage.clientHeight) / 2);
}

function collectWorkbenchForecastConfig() {
 document.querySelectorAll('[data-kw-forecast-field]').forEach((fieldNode) => {
 const field = fieldNode.dataset.kwForecastField;
 if (!field) return;
 kwForecastConfig[field] = Number(fieldNode.value || 0);
 });
 const selectedNode = (kwForecastGraph.nodes || []).find((item) => item.id === kwSelectedForecastNodeId);
 if (selectedNode) {
 const labelNode = document.querySelector('[data-kw-node-label]');
 if (labelNode instanceof HTMLInputElement) {
 selectedNode.label = labelNode.value || selectedNode.label;
 }
 document.querySelectorAll('[data-kw-node-param]').forEach((fieldNode) => {
 const field = fieldNode.dataset.kwNodeParam;
 if (!field) return;
 selectedNode.params = selectedNode.params || {};
 selectedNode.params[field] = fieldNode.value;
 });
 }
 kwForecastGraph.tuning = {...kwForecastConfig};
}

async function loadWorkbenchForecastModel(forceReload) {
 if (kwForecastLoaded && !forceReload && kwForecastEditorBootstrapped) return;
 const res = await fetch('/api/admin/forecast-config');
 const data = await res.json();
 if (!res.ok || data.ok === false) throw new Error(data.error || 'forecast_config_failed');
 kwForecastConfig = data.config || {};
 kwForecastWorkflowMeta = data.workflow_meta || {};
 kwForecastGraph = kwForecastWorkflowMeta.graph || {nodes: [], edges: [], tuning: kwForecastConfig};
 kwForecastGraph.tuning = {...kwForecastConfig};
 kwSelectedForecastNodeId = (kwForecastGraph.nodes || [])[0]?.id || '';
 kwForecastLoaded = true;
 renderWorkbenchForecastWorkflow();
 renderWorkbenchForecastConfigBoard();
 renderWorkbenchForecastNodeDebug();
 centerWorkbenchForecastView();
}

async function resetWorkbenchForecastGraph() {
 const statusNode = document.getElementById('kw-forecast-save-status');
 if (statusNode) statusNode.textContent = '正在恢复推荐模板...';
 const res = await fetch('/api/admin/forecast-config', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({reset_default: true}),
 });
 const data = await res.json();
 if (!res.ok || data.ok === false) throw new Error(data.error || 'reset_failed');
 kwForecastConfig = data.config || {};
 kwForecastWorkflowMeta = data.workflow_meta || {};
 kwForecastGraph = kwForecastWorkflowMeta.graph || {nodes: [], edges: [], tuning: kwForecastConfig};
 kwForecastGraph.tuning = {...kwForecastConfig};
 kwSelectedForecastNodeId = (kwForecastGraph.nodes || [])[0]?.id || '';
 kwForecastLoaded = true;
 renderWorkbenchForecastWorkflow();
 renderWorkbenchForecastConfigBoard();
 renderWorkbenchForecastNodeDebug();
 centerWorkbenchForecastView();
 if (statusNode) statusNode.textContent = '已恢复推荐模板';
 showToast('已恢复推荐模板');
}

async function saveWorkbenchForecastConfigs() {
 collectWorkbenchForecastConfig();
 const statusNode = document.getElementById('kw-forecast-save-status');
 if (statusNode) statusNode.textContent = '保存中...';
 const res = await fetch('/api/admin/forecast-config', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({graph: {...kwForecastGraph, tuning: kwForecastConfig}, config: kwForecastConfig}),
 });
 const data = await res.json();
 if (!res.ok || data.ok === false) throw new Error(data.error || 'save_failed');
 kwForecastConfig = data.config || {};
 kwForecastWorkflowMeta = data.workflow_meta || {};
 kwForecastGraph = kwForecastWorkflowMeta.graph || kwForecastGraph;
 kwForecastGraph.tuning = {...kwForecastConfig};
 kwSelectedForecastNodeId = (kwForecastGraph.nodes || [])[0]?.id || '';
 renderWorkbenchForecastWorkflow();
 renderWorkbenchForecastConfigBoard();
 renderWorkbenchForecastNodeDebug();
 if (statusNode) statusNode.textContent = '预测算法配置已保存';
 showToast('预测算法配置已保存');
}

function initWorkbenchForecastEditorEvents() {
 if (kwForecastEditorBootstrapped) return;
 kwForecastEditorBootstrapped = true;
 document.getElementById('kw-save-forecast-configs')?.addEventListener('click', async () => {
 try {
 await saveWorkbenchForecastConfigs();
 } catch (error) {
 showToast(error.message || '保存失败');
 }
 });
 document.getElementById('kw-forecast-reset-graph')?.addEventListener('click', async () => {
 try {
 await resetWorkbenchForecastGraph();
 } catch (error) {
 showToast(error.message || '恢复失败');
 }
 });
 document.getElementById('kw-forecast-center-view')?.addEventListener('click', () => {
 centerWorkbenchForecastView();
 });
 document.getElementById('kw-forecast-zoom-in')?.addEventListener('click', () => {
 kwForecastZoom = Math.min(1.8, Number((kwForecastZoom + 0.1).toFixed(2)));
 applyWorkbenchForecastZoom();
 });
 document.getElementById('kw-forecast-zoom-out')?.addEventListener('click', () => {
 kwForecastZoom = Math.max(0.6, Number((kwForecastZoom - 0.1).toFixed(2)));
 applyWorkbenchForecastZoom();
 });
}

function showWorkbenchSection(name, navEl) {
 if (name === 'indicator-hub') {
 name = 'indicator-overview';
 }
 if (name === 'indicator-lake') {
 name = 'lake-market';
 }
 if (name === 'knowledge') {
 name = 'knowledge-overview';
 }
 if (name.indexOf('knowledge-') === 0 && !isWorkbenchFeatureEnabled('knowledge')) {
 showToast('知识专区当前暂不开放');
 name = 'overview';
 navEl = document.querySelector('.admin-nav-item[data-section="overview"]');
 }
 if (name === 'hermes') {
 name = 'hermes-overview';
 }
 if (name === 'watchlist') {
 name = 'watchlist-pool';
 }
 if (name === 'forecast-model' && !isWorkbenchFeatureEnabled('stock_forecast')) {
 showToast('预测功能当前未开放');
 return;
 }
 if (name === 'hermes' && !isWorkbenchFeatureEnabled('hermes')) {
 showToast('Hermes 专区当前未开放');
 return;
 }
 document.querySelectorAll('[id^="workbench-section-"]').forEach(el => {
 el.style.display = 'none';
 });
 const target = document.getElementById('workbench-section-' + name);
 if (target) target.style.display = 'block';
 document.querySelectorAll('.admin-nav-item').forEach(el => el.classList.remove('active'));
 const activeNav = navEl || document.querySelector(`.admin-nav-item[data-section="${name}"]`);
 if (activeNav) {
 activeNav.classList.add('active');
 const groupEl = activeNav.closest('.admin-nav-group');
 if (groupEl) {
 setWorkbenchNavGroupCollapsed(groupEl, false);
 const state = readWorkbenchNavState();
 const key = groupEl.dataset.navGroup;
 if (key) {
 state[key] = false;
 writeWorkbenchNavState(state);
 }
 }
 }
 const meta = workbenchSectionMeta[name] || workbenchSectionMeta.overview;
 const title = document.getElementById('workbench-page-title');
 const summary = document.getElementById('workbench-page-summary');
 if (title) title.textContent = meta.title;
 if (summary) summary.textContent = meta.summary;
 if (name === 'biz-dashboard') {
 renderKwBizDashboard();
 refreshKwBusinessAnalytics();
 }
 if (name === 'dashboard') {
 kwRenderDashboardPreview();
 }
 if (name === 'watchlist-pool' || name === 'published' || name === 'review') {
 renderWorkbenchAnnotationViews();
 }
 if (name === 'watchlist-insights') {
 renderWorkbenchWatchlistCommentAnalytics();
 }
 if (name === 'review') {
 kwRenderReviewStudio();
 kwLoadActiveReviewJobs();
 }
 if (name === 'knowledge-overview') {
 loadWorkbenchKnowledgeAssets(false).then(() => {
 kwRenderKnowledgeOverview();
 }).catch((error) => showToast(error.message || '加载失败'));
 }
 if (name === 'knowledge-intake') {
 kwRenderKnowledgeList();
 }
 if (name === 'knowledge-encyclopedia') {
 loadWorkbenchKnowledgeAssets(false).catch((error) => showToast(error.message || '加载失败'));
 }
 if (name === 'knowledge-entries') {
 loadWorkbenchKnowledgeAssets(false).catch((error) => showToast(error.message || '加载失败'));
 }
 if (name === 'knowledge-graph') {
 loadWorkbenchKnowledgeMap(false);
 }
 if (name === 'hermes-overview') {
 loadWorkbenchHermesUsageStats();
 }
 if (name === 'hermes-memory') {
 loadWorkbenchHermesMemorySummary(false).catch((error) => showToast(error.message || '加载失败'));
 }
 if (name === 'hermes-capability') {
 loadWorkbenchHermesCapabilityGrowth(false);
 }
 if (name === 'published') {
 kwRenderPublishedReviewList();
 }
 if (name === 'forecast-model') {
 initWorkbenchForecastEditorEvents();
 loadWorkbenchForecastModel().catch((error) => showToast(error.message || '加载失败'));
 }
 if (window.GangtiseEcharts && typeof window.GangtiseEcharts.resizeAll === 'function') {
 window.requestAnimationFrame(() => window.GangtiseEcharts.resizeAll());
 }
 const url = new URL(window.location.href);
 url.searchParams.set('section', name);
 window.history.replaceState({}, '', url);
}

const WORKBENCH_NAV_STORAGE_KEY = 'gangtise-workbench-nav-groups-v1';

function readWorkbenchNavState() {
 try {
 return JSON.parse(localStorage.getItem(WORKBENCH_NAV_STORAGE_KEY) || '{}');
 } catch (error) {
 return {};
 }
}

function writeWorkbenchNavState(state) {
 try {
 localStorage.setItem(WORKBENCH_NAV_STORAGE_KEY, JSON.stringify(state || {}));
 } catch (error) {
 // ignore storage write failures
 }
}

function setWorkbenchNavGroupCollapsed(groupEl, collapsed) {
 if (!groupEl) return;
 groupEl.classList.toggle('is-collapsed', !!collapsed);
 const toggle = groupEl.querySelector('.admin-nav-group-toggle');
 if (toggle) toggle.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
}

function toggleWorkbenchNavGroup(toggleEl) {
 const groupEl = toggleEl ? toggleEl.closest('.admin-nav-group') : null;
 if (!groupEl) return;
 const collapsed = !groupEl.classList.contains('is-collapsed');
 setWorkbenchNavGroupCollapsed(groupEl, collapsed);
 const state = readWorkbenchNavState();
 const key = groupEl.dataset.navGroup;
 if (key) {
 state[key] = collapsed;
 writeWorkbenchNavState(state);
 }
}

function initWorkbenchNavGroups() {
 const state = readWorkbenchNavState();
 document.querySelectorAll('.admin-nav-group[data-nav-group]').forEach((groupEl) => {
 const key = groupEl.dataset.navGroup;
 const collapsed = !!state[key];
 setWorkbenchNavGroupCollapsed(groupEl, collapsed);
 });
}

function showToast(message) {
 const toast = document.getElementById('toast');
 if (!toast) return;
 toast.textContent = message;
 toast.classList.add('show');
 clearTimeout(window.__kwToastTimer);
 window.__kwToastTimer = setTimeout(() => toast.classList.remove('show'), 1800);
}

function getKwWorkbenchStats() {
 return (window.WORKBENCH_DATA && window.WORKBENCH_DATA.stats) || {};
}

function renderKwOpsStats() {
 const stats = getKwWorkbenchStats();
 const revenueValue = document.getElementById('kw-stat-revenue-value');
 const revenueMeta = document.getElementById('kw-stat-revenue-meta');
 const paidValue = document.getElementById('kw-stat-paid-value');
 const paidMeta = document.getElementById('kw-stat-paid-meta');
 const commentValue = document.getElementById('kw-stat-comments-value');
 const commentMeta = document.getElementById('kw-stat-comments-meta');
 const viewValue = document.getElementById('kw-stat-views-value');
 const viewMeta = document.getElementById('kw-stat-views-meta');
 if (revenueValue) revenueValue.textContent = `¥${Number(stats.monthly_revenue || 0).toLocaleString('zh-CN')}`;
 if (revenueMeta) {
 const price = Number(stats.registration_price || 0);
 revenueMeta.textContent = price > 0
 ? `单价 ¥${price.toLocaleString('zh-CN')} · 环比 ${Number(stats.revenue_change || 0).toFixed(1)}%`
 : '请先设置注册定价';
 }
 if (paidValue) paidValue.textContent = String(Number(stats.vip_subscribers || 0));
 if (paidMeta) paidMeta.textContent = `本月新增 ${Number(stats.new_paid_samples_month || 0)} 位`;
 if (commentValue) commentValue.textContent = String(Number(stats.stock_comment_count || 0));
 if (commentMeta) commentMeta.textContent = `覆盖 ${Number(stats.stock_comment_stock_count || 0)} 只股票`;
 if (viewValue) viewValue.textContent = String(Number(stats.today_views || 0));
 if (viewMeta) viewMeta.textContent = `活跃粉丝 ${Number(stats.today_active_viewers || 0)} 位`;
}

function kwFormatCurrency(value) {
 return `¥${Number(value || 0).toLocaleString('zh-CN')}`;
}

