 const sourceRows = Array.isArray(analytics.source_rows) ? analytics.source_rows : [];
 const labelDistribution = Array.isArray(analytics.label_distribution) ? analytics.label_distribution : [];
 const monthlySeries = Array.isArray(analytics.monthly_series) ? analytics.monthly_series : [];
 const segments = Array.isArray(analytics.segments) ? analytics.segments : [];
 host.innerHTML = `
