 </div>
 <button class="btn-gold" type="button" style="padding:9px 14px;font-size:12px" onclick="saveKwFanPricing()">保存</button>
 <div id="kw-fan-pricing-meta" style="font-size:12px;color:var(--gray-400);align-self:center">保存后即时重算收入和漏斗。</div>
 </div>
 </div>
 <div class="kw-kpi-row" style="margin-bottom:20px">
 <div class="kw-kpi-card"><div class="kw-kpi-label">总粉丝</div><div class="kw-kpi-value">${totalFans.toLocaleString('zh-CN')}</div><div class="kw-kpi-sub">当前租户全部粉丝</div></div>
 <div class="kw-kpi-card"><div class="kw-kpi-label">付费用户</div><div class="kw-kpi-value">${paidFans.toLocaleString('zh-CN')}</div><div class="kw-kpi-sub">以“付费用户”标签为准</div></div>
 <div class="kw-kpi-card"><div class="kw-kpi-label">当前单价</div><div class="kw-kpi-value">${kwFormatCurrency(pricing)}</div><div class="kw-kpi-sub">每位付费用户</div></div>
 <div class="kw-kpi-card"><div class="kw-kpi-label">预计收入</div><div class="kw-kpi-value">${kwFormatCurrency(estimatedRevenue)}</div><div class="kw-kpi-sub">${paidFans} 位付费用户 × ${kwFormatCurrency(pricing)}</div></div>
 </div>
 <div class="table-wrap" style="margin-bottom:20px">
