 <div class="table-wrap"><div class="table-header"><div><div class="table-title">渠道质量明细</div><div class="chart-subtitle" style="margin:6px 0 0">不展示未采集的 CAC、LTV，避免使用模拟经营数据。</div></div></div><table><thead><tr><th>来源</th><th>粉丝数</th><th>付费用户</th><th>付费转化率</th><th>预计收入</th></tr></thead><tbody>${sourceRows.length ? sourceRows.map((row) => `<tr><td>${escapeHtml(row.label || '未标注来源')}</td><td>${Number(row.fans || 0).toLocaleString('zh-CN')}</td><td>${Number(row.paid || 0).toLocaleString('zh-CN')}</td><td>${Number(row.conversion_rate || 0).toFixed(1)}%</td><td>${kwFormatCurrency(row.revenue)}</td></tr>`).join('') : '<tr><td colspan="5" style="text-align:center;color:var(--gray-400);padding:20px 0">暂无粉丝数据</td></tr>'}</tbody></table></div>
 </section>
