 <div class="chart-card full"><div class="chart-title">渠道营收对比</div><div class="chart-subtitle">当前单价下各来源的收入贡献</div><div id="kw-biz-revenue-source-bar" class="chart-container"></div></div>
 </section>
 <section id="kw-biz-section-segment" class="kw-biz-analysis-panel">
