 };
}

function renderKwBizDashboardCharts(section) {
 const state = window.__kwBusinessAnalyticsView || {};
 const analytics = state.analytics || {};
 const sourceRows = state.sourceRows || [];
 const labels = state.labelDistribution || [];
 const monthly = state.monthlySeries || [];
 const segments = state.segments || [];
 const funnel = state.funnel || [];
 const palette = kwBizPalette();
 document.querySelectorAll('.kw-biz-analysis-panel').forEach((node) => node.classList.remove('active'));
 const panel = document.getElementById(`kw-biz-section-${section}`);
 if (panel) panel.classList.add('active');
 ['funnel', 'channel', 'revenue', 'segment'].forEach((name) => {
 const button = document.getElementById(`kw-biz-nav-${name}`);
 if (button) button.classList.toggle('active', name === section);
 });
 const titles = { funnel: '租户粉丝转化漏斗', channel: '来源渠道经营分析', revenue: '收入与付费用户趋势', segment: '基于标签的用户分层' };
 const title = document.getElementById('kw-biz-topbar-title');
 if (title) title.textContent = titles[section] || titles.funnel;
 const months = monthly.map((item) => String(item.month || '').slice(5));
 const sourceNames = sourceRows.map((item) => item.label || '未标注来源');
 const base = kwBizBaseOption();
 if (section === 'funnel') {
 kwBizChart('kw-biz-funnel-chart', { ...base, tooltip: { trigger: 'item' }, xAxis: { type: 'value', ...base.xAxis }, yAxis: { type: 'category', data: funnel.map((item) => item.label), ...base.yAxis, splitLine: { show: false } }, series: [{ type: 'bar', data: funnel.map((item) => item.count), barWidth: 22, itemStyle: { color: palette.blue, borderRadius: [0, 8, 8, 0] }, label: { show: true, position: 'right', color: '#182132' } }] });
 kwBizChart('kw-biz-source-pie', { tooltip: { trigger: 'item' }, legend: { bottom: 0, textStyle: { color: '#5A6572', fontSize: 11 } }, series: [{ type: 'pie', radius: ['48%', '72%'], center: ['50%', '44%'], label: { show: false }, itemStyle: { borderColor: '#fff', borderWidth: 2 }, data: sourceRows.map((item) => ({ name: item.label, value: item.fans })) }] });
 kwBizChart('kw-biz-revenue-trend', { ...base, legend: { top: 0, textStyle: { color: '#5A6572', fontSize: 11 } }, xAxis: { type: 'category', data: months, ...base.xAxis }, yAxis: [{ type: 'value', ...base.yAxis, axisLabel: { formatter: '¥{value}', color: '#5A6572', fontSize: 11 } }, { type: 'value', ...base.yAxis, splitLine: { show: false } }], series: [{ name: '收入', type: 'bar', data: monthly.map((item) => item.revenue), itemStyle: { color: palette.gold, borderRadius: [7, 7, 0, 0] } }, { name: '累计付费用户', type: 'line', yAxisIndex: 1, data: monthly.map((item) => item.paid_cumulative), smooth: true, itemStyle: { color: palette.blue }, lineStyle: { color: palette.blue, width: 2 } }] });
 kwBizChart('kw-biz-label-pie', { tooltip: { trigger: 'item' }, legend: { bottom: 0, textStyle: { color: '#5A6572', fontSize: 11 } }, series: [{ type: 'pie', radius: ['48%', '72%'], center: ['50%', '44%'], label: { show: false }, itemStyle: { borderColor: '#fff', borderWidth: 2 }, data: labels.map((item) => ({ name: item.label, value: item.value })) }] });
 }
 if (section === 'channel') {
 kwBizChart('kw-biz-channel-users', { ...base, legend: { top: 0, textStyle: { color: '#5A6572', fontSize: 11 } }, xAxis: { type: 'category', data: sourceNames, ...base.xAxis }, yAxis: { type: 'value', ...base.yAxis }, series: [{ name: '粉丝数', type: 'bar', data: sourceRows.map((item) => item.fans), itemStyle: { color: palette.blue, borderRadius: [7, 7, 0, 0] } }, { name: '付费用户', type: 'bar', data: sourceRows.map((item) => item.paid), itemStyle: { color: palette.gold, borderRadius: [7, 7, 0, 0] } }] });
 kwBizChart('kw-biz-channel-revenue', { ...base, xAxis: { type: 'category', data: sourceNames, ...base.xAxis }, yAxis: { type: 'value', ...base.yAxis, axisLabel: { formatter: '¥{value}', color: '#5A6572', fontSize: 11 } }, series: [{ name: '预计收入', type: 'bar', data: sourceRows.map((item) => item.revenue), itemStyle: { color: palette.gold, borderRadius: [7, 7, 0, 0] } }] });
 }
 if (section === 'revenue') {
 kwBizChart('kw-biz-monthly-revenue', { ...base, legend: { top: 0, textStyle: { color: '#5A6572', fontSize: 11 } }, xAxis: { type: 'category', data: months, ...base.xAxis }, yAxis: [{ type: 'value', ...base.yAxis, axisLabel: { formatter: '¥{value}', color: '#5A6572', fontSize: 11 } }, { type: 'value', ...base.yAxis, splitLine: { show: false } }], series: [{ name: '收入', type: 'bar', data: monthly.map((item) => item.revenue), itemStyle: { color: palette.gold, borderRadius: [7, 7, 0, 0] } }, { name: '付费用户', type: 'line', yAxisIndex: 1, data: monthly.map((item) => item.paid_cumulative), smooth: true, itemStyle: { color: palette.blue }, lineStyle: { color: palette.blue, width: 2 } }] });
 kwBizChart('kw-biz-monthly-growth', { ...base, legend: { top: 0, textStyle: { color: '#5A6572', fontSize: 11 } }, xAxis: { type: 'category', data: months, ...base.xAxis }, yAxis: { type: 'value', ...base.yAxis }, series: [{ name: '新增粉丝', type: 'bar', data: monthly.map((item) => item.fans_added), itemStyle: { color: palette.blue, borderRadius: [7, 7, 0, 0] } }, { name: '新增付费用户', type: 'bar', data: monthly.map((item) => item.paid_added), itemStyle: { color: palette.green, borderRadius: [7, 7, 0, 0] } }] });
 kwBizChart('kw-biz-revenue-source-bar', { ...base, xAxis: { type: 'category', data: sourceNames, ...base.xAxis }, yAxis: { type: 'value', ...base.yAxis, axisLabel: { formatter: '¥{value}', color: '#5A6572', fontSize: 11 } }, series: [{ name: '渠道收入', type: 'bar', data: sourceRows.map((item) => item.revenue), itemStyle: { color: palette.blue, borderRadius: [7, 7, 0, 0] } }] });
 }
 if (section === 'segment') {
 const maxCount = Math.max(...segments.map((item) => Number(item.count || 0)), 1);
 const funnelHost = document.getElementById('kw-biz-segment-funnel');
 if (funnelHost) funnelHost.innerHTML = segments.map((item, index) => { const count = Number(item.count || 0); const width = Math.max(22, Math.round((count / maxCount) * 78) + 22); return `<div style="margin:8px auto;width:${width}%;max-width:760px;background:${[palette.gray, palette.blue, palette.gold][index]}18;border:1px solid ${[palette.gray, palette.blue, palette.gold][index]}55;border-radius:7px;padding:12px 18px;display:flex;justify-content:space-between"><span style="font-weight:600;color:${[palette.gray, palette.blue, palette.gold][index]}">${escapeHtml(item.label)}</span><strong>${count.toLocaleString('zh-CN')}</strong><span style="color:var(--text-sub);font-size:12px">${kwFormatCurrency(item.revenue)}</span></div>`; }).join('') || '<div style="color:var(--gray-400);padding:16px">暂无用户分层数据</div>';
 kwBizChart('kw-biz-segment-pie', { tooltip: { trigger: 'item' }, legend: { bottom: 0, textStyle: { color: '#5A6572', fontSize: 11 } }, series: [{ type: 'pie', radius: ['48%', '72%'], center: ['50%', '44%'], label: { show: false }, itemStyle: { borderColor: '#fff', borderWidth: 2 }, data: segments.map((item) => ({ name: item.label, value: item.count })) }] });
 kwBizChart('kw-biz-label-bar', { ...base, xAxis: { type: 'category', data: labels.map((item) => item.label), ...base.xAxis }, yAxis: { type: 'value', ...base.yAxis }, series: [{ name: '标签人数', type: 'bar', data: labels.map((item) => item.value), itemStyle: { color: palette.blue, borderRadius: [7, 7, 0, 0] } }] });
 }
}

async function refreshKwBusinessAnalytics() {
 const tenantSlug = (window.ACTIVE_TENANT && window.ACTIVE_TENANT.slug) || '';
 if (!tenantSlug) return;
 try {
 const res = await fetch(`/api/kol/business-analytics?tenant=${encodeURIComponent(tenantSlug)}`, {cache: 'no-store'});
 const data = await res.json();
 if (!res.ok || data.ok === false) throw new Error(data.error || 'load_business_analytics_failed');
 window.WORKBENCH_DATA = window.WORKBENCH_DATA || {};
 window.WORKBENCH_DATA.stats = data.stats || window.WORKBENCH_DATA.stats || {};
 window.WORKBENCH_DATA.business_analytics = data.analytics || {};
 renderKwOpsStats();
 const section = document.getElementById('workbench-section-biz-dashboard');
 if (section && section.style.display !== 'none') renderKwBizDashboard();
 } catch (error) {
 showToast(error.message || '数据分析加载失败');
 }
}

function renderKwFans() {
 const body = document.getElementById('kw-fans-table-body');
 const meta = document.getElementById('kw-fans-table-meta');
 const summary = document.getElementById('kw-fans-summary');
 if (!body) return;
 body.innerHTML = kwFans.length ? kwFans.map((fan) => {
 const labels = Array.isArray(fan.labels) ? fan.labels : (fan.is_paid_sample ? ['付费用户'] : []);
 const userId = Number(fan.id || 0);
 return `
 <tr>
 <td><input type="checkbox" ${userId ? '' : 'disabled'} ${kwSelectedFanIds.has(userId) ? 'checked' : ''} onchange="toggleKwFanSelection(${userId}, this.checked)" title="选择粉丝"></td>
 <td><span style="color:var(--text-main);font-weight:600">${escapeHtml(fan.username || '--')}</span></td>
 <td>${escapeHtml(fan.membership || '投资者视角')}</td>
 <td>${escapeHtml(fan.source || '用户导入')}</td>
 <td>${escapeHtml(String(fan.created_at || '--').slice(0, 10))}</td>
 <td>${escapeHtml(fan.paid_sample_note || fan.phone_masked || '--')}</td>
 <td><span class="tag ${fan.status === 'pending_approval' ? 'tag-blue' : 'tag-gold'}">${escapeHtml(fan.status === 'disabled' ? '已禁用' : (fan.status === 'pending_approval' ? '待审批' : '活跃'))}</span></td>
 <td><div style="display:flex;gap:5px;flex-wrap:wrap">${labels.length ? labels.map((label) => `<span class="tag ${label === '付费用户' ? 'tag-gold' : 'tag-blue'}">${escapeHtml(label)}</span>`).join('') : '<span style="color:#8899aa">--</span>'}</div></td>
 <td><button class="btn-outline" type="button" style="padding:4px 9px;font-size:11px;color:${fan.status === 'disabled' ? '#9DE0BE' : '#F2B8B5'};border-color:${fan.status === 'disabled' ? 'rgba(22,112,74,0.28)' : 'rgba(180,35,24,0.28)'}" onclick="requestKwFanStatusChange(${userId})">${fan.status === 'disabled' ? '启用' : (fan.status === 'pending_approval' ? '审批通过' : '停用')}</button></td>
 </tr>
 `;
 }).join('') : '<tr><td colspan="9" style="text-align:center;color:#8899aa;padding:20px 0">暂无粉丝用户</td></tr>';
 const selectedCount = kwSelectedFanIds.size;
 if (meta) {
 const activeCount = kwFans.filter((fan) => fan.status === 'active').length;
 const pendingCount = kwFans.filter((fan) => fan.status === 'pending_approval').length;
 meta.innerHTML = `<span>共 ${kwFans.length} 位粉丝 · 正常 ${activeCount} · 待审批 ${pendingCount} · 已停用 ${kwFans.length - activeCount - pendingCount}</span><span>待审批账号通过后才能登录当前租户</span>`;
 }
 const selectAll = document.getElementById('kw-fans-select-all');
 if (selectAll) selectAll.checked = kwFans.length > 0 && kwFans.every((fan) => kwSelectedFanIds.has(Number(fan.id || 0)));
 const paidCount = kwFans.filter((fan) => fan.is_paid_sample).length;
 if (summary) summary.textContent = `当前共 ${kwFans.length} 位粉丝用户，其中 ${paidCount} 位已标记为付费样本；支持 CSV 批量导入、单个新增和批量表格式录入。`;
}

function closeKwFanStatusModal() {
 const modal = document.getElementById('kw-fan-status-modal');
 if (modal) modal.classList.remove('show');
}

function requestKwFanStatusChange(userId) {
 const fan = kwFans.find((item) => Number(item.id || 0) === Number(userId || 0));
 const modal = document.getElementById('kw-fan-status-modal');
 const host = document.getElementById('kw-fan-status-modal-content');
 if (!fan || !modal || !host) return;
 const nextStatus = fan.status === 'disabled' || fan.status === 'pending_approval' ? 'active' : 'disabled';
 const action = fan.status === 'pending_approval' ? '审批通过' : (nextStatus === 'disabled' ? '停用' : '启用');
 host.innerHTML = `
 <div class="kw-review-modal-head">
 <div>
 <div class="kw-review-modal-title">${action}粉丝账号</div>
 <div class="kw-review-modal-subtitle">当前租户：${escapeHtml((window.ACTIVE_TENANT && window.ACTIVE_TENANT.name) || '--')}</div>
 </div>
 </div>
 <div class="kw-card" style="margin-top:12px">
 <div class="kw-card-title">确认${action}“${escapeHtml(fan.username || '该粉丝')}”吗？</div>
 <div class="kw-card-desc" style="margin-top:8px">${fan.status === 'pending_approval' ? '审批通过后，该粉丝才能登录 H5、使用 Hermes 和访问当前租户服务。' : (nextStatus === 'disabled' ? '停用后该粉丝将无法登录 H5、使用 Hermes 或访问当前租户服务，但其自选股、评论、标注和历史数据都会保留。' : '启用后该粉丝可以重新登录当前租户，原有自选股、评论、标注和历史数据会恢复可用。')}</div>
 <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:16px">
 <button class="btn-outline" type="button" style="padding:8px 12px;font-size:12px" onclick="closeKwFanStatusModal()">取消</button>
 <button class="btn-gold" type="button" style="padding:8px 12px;font-size:12px" onclick="confirmKwFanStatusChange(${Number(fan.id || 0)}, '${nextStatus}')">确认${action}</button>
 </div>
 </div>
 `;
 modal.classList.add('show');
}

async function confirmKwFanStatusChange(userId, status) {
 const tenantSlug = (window.ACTIVE_TENANT && window.ACTIVE_TENANT.slug) || '';
 if (!tenantSlug) return;
 const host = document.getElementById('kw-fan-status-modal-content');
 if (host) host.innerHTML += '<div class="kw-dashboard-panel-note" style="margin-top:10px">正在更新账号状态，请稍候...</div>';
 try {
 const response = await fetch(`/api/kol/users/status?tenant=${encodeURIComponent(tenantSlug)}`, {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({user_id: userId, status}),
 });
 const data = await response.json();
 if (!response.ok || data.ok === false) {
 const messages = { tenant_user_not_found: '未找到当前租户下的粉丝账号。', database_unavailable: '数据库当前不可用，请稍后重试。' };
 throw new Error(messages[data.error] || data.error || '账号状态更新失败');
 }
 kwFans = Array.isArray(data.users) ? data.users.map(normalizeKwFan) : kwFans;
 renderKwFans();
 closeKwFanStatusModal();
 await refreshKwBusinessAnalytics();
 showToast(status === 'disabled' ? '粉丝账号已停用' : '粉丝账号已启用');
 } catch (error) {
 if (host) host.innerHTML += `<div style="font-size:12px;color:#F2B8B5;margin-top:10px">${escapeHtml(error.message || '账号状态更新失败')}</div>`;
 showToast(error.message || '账号状态更新失败');
 }
}

function normalizeKwFan(user) {
 const fan = user || {};
 return {
 id: Number(fan.id || 0),
 username: fan.username || fan.name || '',
 membership: fan.membership || fan.tier || '投资者视角',
 is_paid_sample: !!fan.is_paid_sample,
 source: fan.source || fan.source_label || '用户导入',
 created_at: fan.created_at || fan.joined || '--',
 paid_sample_note: fan.paid_sample_note || '',
 labels: Array.isArray(fan.labels) ? fan.labels : (fan.is_paid_sample ? ['付费用户'] : []),
 phone_masked: fan.phone_masked || fan.value || '--',
 status: fan.status || 'active',
 };
}

function toggleKwFanSelection(userId, checked) {
 const normalizedId = Number(userId || 0);
 if (!normalizedId) return;
 if (checked) kwSelectedFanIds.add(normalizedId);
 else kwSelectedFanIds.delete(normalizedId);
 renderKwFans();
}

function toggleKwFanSelectAll(checked) {
 kwSelectedFanIds = checked
 ? new Set(kwFans.map((fan) => Number(fan.id || 0)).filter(Boolean))
 : new Set();
 renderKwFans();
}

async function applyKwFanLabel(labelOverride) {
 const tenantSlug = (window.ACTIVE_TENANT && window.ACTIVE_TENANT.slug) || '';
 const input = document.getElementById('kw-fan-label-input');
 const label = String(labelOverride || (input && input.value) || '').trim();
 const userIds = Array.from(kwSelectedFanIds);
 if (!label) {
 showToast('请输入标签');
 return;
 }
 if (!userIds.length) {
 showToast('请先选择粉丝');
 return;
 }
 try {
 const res = await fetch(`/api/kol/users/labels?tenant=${encodeURIComponent(tenantSlug)}`, {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({user_ids: userIds, label, action: 'add'}),
 });
 const data = await res.json();
 if (!res.ok || data.ok === false) throw new Error(data.error || 'save_user_label_failed');
 kwFans = Array.isArray(data.users) ? data.users.map(normalizeKwFan) : kwFans;
 kwSelectedFanIds = new Set();
 if (input) input.value = '';
 renderKwFans();
 await refreshKwBusinessAnalytics();
 showToast(`已标注 ${label}`);
 } catch (error) {
 showToast(error.message || '标签保存失败');
 }
}

async function loadKwFans() {
 const tenantSlug = (window.ACTIVE_TENANT && window.ACTIVE_TENANT.slug) || '';
 if (!tenantSlug) {
 showToast('tenant_missing');
 return;
 }
 try {
 const res = await fetch(`/api/kol/users?tenant=${encodeURIComponent(tenantSlug)}`);
 const data = await res.json();
 if (!res.ok) throw new Error((data && data.error) || 'load_kol_users_failed');
 kwFans = Array.isArray(data.users) ? data.users.map(normalizeKwFan) : [];
 if (window.WORKBENCH_DATA && data.summary) {
 window.WORKBENCH_DATA.fan_management = {
 ...(window.WORKBENCH_DATA.fan_management || {}),
 settings: data.summary.settings || ((window.WORKBENCH_DATA.fan_management || {}).settings) || {},
 stats: {
 ...((window.WORKBENCH_DATA.fan_management || {}).stats || {}),
 total_fans: Number(data.summary.total_users || kwFans.length),
 paying_fans: Number(data.summary.paying_users || kwFans.filter((fan) => fan.is_paid_sample).length),
 },
 };
 }
 renderKwFans();
 await refreshKwBusinessAnalytics();
 renderKwOpsStats();
 } catch (error) {
 showToast(error.message || '粉丝列表加载失败');
 }
}

function closeKwOpsMetricModal() {
 const modal = document.getElementById('kw-ops-metric-modal');
 if (modal) modal.classList.remove('show');
}

