 <div class="stat-card"><div class="stat-label">涉及个股</div><div class="stat-value">${Number(summary.stock_count || 0)}</div><div class="stat-change up">有讨论的标的</div></div>
 <div class="stat-card"><div class="stat-label">粉丝留言</div><div class="stat-value">${Number(summary.investor_comments || 0)}</div><div class="stat-change up">普通用户输入</div></div>
 <div class="stat-card"><div class="stat-label">大V留言</div><div class="stat-value">${Number(summary.dav_comments || 0)}</div><div class="stat-change up">投顾侧观点</div></div>
 </div>
 <div class="config-card" style="margin-top:16px">
 <div class="config-card-title">关键词云图</div>
 <div class="keyword-cloud">
 ${keywordCloud.length ? keywordCloud.slice(0, 24).map((item) => `<span class="keyword-tag">${escapeHtml(item.keyword || '')} · ${Number(item.value || 0)}</span>`).join('') : '<span style="font-size:12px;color:var(--gray-400)">暂无评论关键词</span>'}
 </div>
 </div>
 <div class="config-grid" style="margin-top:16px">
 <div class="config-card">
 <div class="config-card-title">标签分布</div>
 <div id="kw-ops-comment-label-chart" style="width:100%;height:220px"></div>
 </div>
 <div class="config-card">
 <div class="config-card-title">情绪分布</div>
 <div id="kw-ops-comment-sentiment-chart" style="width:100%;height:220px"></div>
 </div>
 </div>
 <div class="config-card" style="margin-top:16px">
 <div class="config-card-title">行业板块分布</div>
 <div id="kw-ops-comment-sector-chart" style="width:100%;height:240px"></div>
 </div>
 `;
 modal.classList.add('show');
 renderWorkbenchBarChart('kw-ops-comment-label-chart', labelDistribution.map((item) => ({ label: item.label, value: item.value })));
 renderWorkbenchBarChart('kw-ops-comment-sentiment-chart', sentimentDistribution.map((item) => ({ label: item.label, value: item.value })));
 renderWorkbenchBarChart('kw-ops-comment-sector-chart', sectorDistribution.map((item) => ({ label: item.label, value: item.value })));
}

