async function createKwFanQrInvite(registrationType = 'free') {
 try {
 const selected = document.getElementById('kw-fan-registration-qr-input')?.files?.[0];
 const body = new FormData();
 body.append('source_label', registrationType === 'subscriber' ? '订阅用户二维码' : '普通用户二维码');
 body.append('expiry_days', '0');
 body.append('registration_type', registrationType);
 if (selected) body.append('file', selected);
 const response = await fetch(`/api/kol/commerce/qr-invites?tenant=${encodeURIComponent(kwCommerceTenantSlug())}`, {method:'POST', body});
 const data = await response.json(); if (!response.ok || !data.ok) throw new Error(data.error || 'qr_create_failed');
 const invite = data.invite || {};
 document.getElementById('kw-commerce-qr-result').innerHTML = `<div class="kw-side-card"><strong>${registrationType === 'subscriber' ? '订阅用户二维码已保存' : '普通用户二维码已保存'}</strong><div class="kw-card-desc" style="margin-top:6px">注册地址：${escapeHtml(invite.registration_url || '')}</div><button class="btn-outline" type="button" style="margin-top:8px;padding:6px 10px;font-size:11px" onclick="navigator.clipboard?.writeText(${JSON.stringify(invite.registration_url || '')})">复制注册地址</button><img src="${escapeAttr(invite.qr_data_uri || '')}" alt="粉丝扫码注册" style="display:block;width:180px;height:180px;object-fit:contain;background:#fff;padding:8px;margin-top:10px"><div class="kw-card-desc">扫码后提交注册申请，审批通过后才能登录。</div></div>`;
 loadKwCommerce();
 } catch (error) { showToast(error.message || '生成二维码失败'); }
}

function buildKwFanImportRow(row = {}) {
 return `
 <tr>
 <td><input data-field="username" type="text" value="${escapeAttr(row.username || '')}" placeholder="用户名"></td>
 <td><input data-field="password" type="text" value="${escapeAttr(row.password || '')}" placeholder="密码"></td>
 <td><input data-field="phone" type="text" value="${escapeAttr(row.phone || '')}" placeholder="手机号"></td>
 <td>
 <select data-field="status">
 <option value="active" ${String(row.status || 'active') === 'active' ? 'selected' : ''}>正常</option>
 <option value="disabled" ${String(row.status || '') === 'disabled' ? 'selected' : ''}>禁用</option>
 </select>
 </td>
 <td>
 <select data-field="is_paid_sample">
 <option value="0" ${String(row.is_paid_sample || '0') === '1' ? '' : 'selected'}>否</option>
 <option value="1" ${String(row.is_paid_sample || '0') === '1' ? 'selected' : ''}>是</option>
 </select>
 </td>
 <td><input data-field="source_label" type="text" value="${escapeAttr(row.source_label || '用户导入')}" placeholder="来源"></td>
 <td><input data-field="paid_sample_note" type="text" value="${escapeAttr(row.paid_sample_note || '')}" placeholder="备注"></td>
 <td><button class="btn-outline" type="button" style="padding:4px 10px;font-size:11px" onclick="removeKwFanImportRow(this)">删除</button></td>
 </tr>
 `;
}

function addKwFanImportRow(row) {
 const body = document.getElementById('kw-fan-import-tbody');
 if (!body) return;
 body.insertAdjacentHTML('beforeend', buildKwFanImportRow(row || {}));
}

function removeKwFanImportRow(button) {
 const row = button ? button.closest('tr') : null;
 if (row) row.remove();
}

function collectKwFanImportRows() {
 return Array.from(document.querySelectorAll('#kw-fan-import-tbody tr')).map((row) => {
 const item = {};
 KW_FAN_IMPORT_COLUMNS.forEach((field) => {
 const node = row.querySelector(`[data-field="${field}"]`);
 item[field] = node ? String(node.value || '').trim() : '';
 });
 return item;
 }).filter((item) => item.username || item.phone);
}

