async function handleKwFanCsvImport(file) {
 const tenantSlug = (window.ACTIVE_TENANT && window.ACTIVE_TENANT.slug) || '';
 if (!file) return;
 if (!tenantSlug) {
 showToast('tenant_missing');
 return;
 }
 const formData = new FormData();
 formData.append('file', file);
 try {
