function renderWorkbenchHermesUsageOverview() {
 const stats = kwHermesUsageState.stats || {};
 const summary = stats.summary || {};
 const tokenUsageAvailable = summary.token_usage_available !== false;
 const todayTokenNote = tokenUsageAvailable
 ? `今日 token ${Number(summary.today_tokens || 0).toLocaleString('zh-CN')}`
 : 'Token 用量未记录';
 const monthTokenNote = tokenUsageAvailable
 ? `本月 token ${Number(summary.month_tokens || 0).toLocaleString('zh-CN')}`
 : 'Token 用量未记录';
 const summaryHost = document.getElementById('kw-hermes-usage-summary');
 const modeBody = document.getElementById('kw-hermes-mode-tbody');
 const actionBody = document.getElementById('kw-hermes-action-tbody');
 if (summaryHost) {
 const cards = [
 ['今日调用', Number(summary.today_calls || 0), todayTokenNote],
 ['本月调用', Number(summary.month_calls || 0), monthTokenNote],
 ['活跃用户人均调用', `${Number(summary.avg_calls_per_user || 0).toFixed(2)} 次`, `平均延迟 ${Number(summary.avg_latency_ms || 0).toFixed(0)} ms`],
 ['本月算力消耗', Number(summary.compute_consumed || 0).toLocaleString('zh-CN'), '按已落库 Hermes 调用聚合'],
 ];
 summaryHost.innerHTML = cards.map(([label, value, note]) => `
 <div class="stat-card"><div class="stat-label">${escapeHtml(label)}</div><div class="stat-value">${escapeHtml(String(value))}</div><div class="stat-change up">${escapeHtml(note)}</div></div>
 `).join('');
 }
 if (modeBody) {
 const rows = Array.isArray(stats.tool_modes) ? stats.tool_modes : [];
 modeBody.innerHTML = rows.length ? rows.map((row) => `
 <tr><td style="color:var(--text-main);font-weight:500">${escapeHtml(row.mode_label || '')}</td><td>${escapeHtml(String(row.today_calls || 0))}</td><td>${escapeHtml(String(row.month_calls || 0))}</td><td>${escapeHtml(`${Number(row.share_ratio || 0).toFixed(1)}%`)}</td><td>${escapeHtml(`${Number(row.avg_latency_ms || 0).toFixed(0)}ms`)}</td><td><span class="tag ${escapeAttr(row.status_class || 'tag-green')}">${escapeHtml(row.status_label || '正常')}</span></td></tr>
 `).join('') : '<tr><td colspan="6" style="color:#9A9590">当前没有可展示的真实调用记录。</td></tr>';
 }
 if (actionBody) {
 const rows = Array.isArray(stats.tool_actions) ? stats.tool_actions : [];
 actionBody.innerHTML = rows.length ? rows.map((row) => `
 <tr><td style="color:var(--text-main);font-weight:500">${escapeHtml(row.tool_name || '')}</td><td>${escapeHtml(String(row.today_calls || 0))}</td><td>${escapeHtml(String(row.month_calls || 0))}</td><td>${escapeHtml(`${Number(row.success_ratio || 0).toFixed(1)}%`)}</td><td><span class="tag ${escapeAttr(row.status_class || 'tag-green')}">${escapeHtml(row.status_label || '正常')}</span></td></tr>
 `).join('') : '<tr><td colspan="5" style="color:#9A9590">当前没有可展示的真实工具动作。</td></tr>';
 }
}

function renderWorkbenchHermesMemoryOverview() {
 const summaryNode = document.getElementById('kw-hermes-memory-summary');
 const summary = kwHermesMemoryState.summary || {};
 if (!summaryNode) return;
 const turns = Number(summary.turn_count || 0);
 const sessions = Number(summary.session_count || 0);
 const users = Number(summary.user_count || 0);
 const profiles = Number(summary.profile_count || 0);
 const recentTurns = Number(summary.recent_30d_turn_count || 0);
 const recentUsers = Number(summary.recent_30d_active_user_count || 0);
 const turnsPerSession = sessions ? turns / sessions : 0;
 const profileCoverage = users ? Math.min(100, Math.round((profiles / users) * 100)) : 0;
 const recentActivity = turns ? Math.min(100, Math.round((recentTurns / turns) * 100)) : 0;
 const healthLabel = !turns ? '尚未形成记忆' : profileCoverage < 100 ? '记忆正在沉淀' : recentTurns ? '记忆持续活跃' : '记忆待激活';
 const healthNote = !turns
 ? '当前没有可用的真实对话记录。'
 : profileCoverage < 100
 ? '已有对话沉淀，但仍有用户未形成稳定画像。'
 : recentTurns
 ? '近期仍有真实调用，记忆上下文持续参与后续对话。'
 : '已有历史沉淀，近 30 天暂无新的真实调用。';
 const cards = [
 { label: '会话沉淀', value: `${turnsPerSession.toFixed(1)} 轮 / 会话`, ratio: Math.min(100, Math.round(turnsPerSession / 8 * 100)), note: `${sessions} 个会话累计 ${turns} 轮真实对话` },
 { label: '画像覆盖', value: `${profileCoverage}%`, ratio: profileCoverage, note: `${profiles} 个画像 / ${users} 位有对话用户` },
 { label: '近期活跃', value: `${recentTurns} 轮`, ratio: recentActivity, note: `近 30 天 ${recentUsers} 位活跃用户` },
 ];
 summaryNode.className = '';
 summaryNode.innerHTML = `
 <div class="kw-hermes-memory-hero">
 <div>
 <div class="kw-hermes-memory-kicker">CURRENT TENANT MEMORY</div>
 <div class="kw-hermes-memory-title">${escapeHtml(healthLabel)}</div>
 <div class="kw-hermes-memory-copy">${escapeHtml(healthNote)}</div>
 <div class="kw-hermes-memory-meta">覆盖时间：${escapeHtml(summary.first_turn_at || '--')} 至 ${escapeHtml(summary.last_turn_at || '--')}</div>
 </div>
 <div class="kw-hermes-memory-signal">
 <div class="kw-hermes-memory-signal-label">当前记忆规模</div>
 <div class="kw-hermes-memory-signal-value">${escapeHtml(String(turns))}<span style="font-size:13px;font-weight:600;margin-left:5px">轮</span></div>
 <div class="kw-hermes-memory-signal-note">${escapeHtml(`${sessions} 个会话 · ${users} 位用户 · ${profiles} 个画像`)}</div>
 </div>
 </div>
 <div class="kw-hermes-memory-health-grid">
 ${cards.map((item) => `
 <div class="kw-hermes-memory-health-card">
 <div class="kw-hermes-memory-health-top"><div class="kw-hermes-memory-health-label">${escapeHtml(item.label)}</div><div class="kw-hermes-memory-health-value">${escapeHtml(item.value)}</div></div>
 <div class="kw-hermes-memory-track"><div class="kw-hermes-memory-fill" style="width:${Math.max(0, Math.min(100, item.ratio))}%"></div></div>
 <div class="kw-hermes-memory-health-note">${escapeHtml(item.note)}</div>
 </div>
 `).join('')}
 </div>
 <div class="kw-hermes-memory-footnote">仅使用本租户已落库的聚合计数生成本页；不展示粉丝对话正文、问题内容或个人画像字段。</div>
 `;
}

function renderWorkbenchHermesUsageUnavailable(message) {
 const text = message || '当前无法读取 Hermes 真实调用数据。';
 const summaryHost = document.getElementById('kw-hermes-usage-summary');
 const modeBody = document.getElementById('kw-hermes-mode-tbody');
 const actionBody = document.getElementById('kw-hermes-action-tbody');
 if (summaryHost) summaryHost.innerHTML = `<div class="stat-card" style="grid-column:1/-1"><div class="stat-label">Hermes 使用数据</div><div class="stat-change" style="color:#F1948A">${escapeHtml(text)}</div></div>`;
 if (modeBody) modeBody.innerHTML = `<tr><td colspan="6" style="color:#F1948A">${escapeHtml(text)}</td></tr>`;
