 </div>
 <div class="pool-card">
 <div class="pool-card-label">剩余可用</div>
 <div class="pool-card-value">${escapeHtml(Number(pool.remaining || 0).toLocaleString('zh-CN'))}</div>
 <div class="pool-card-sub">${escapeHtml(`${Math.max(0, 100 - Number(pool.usage_ratio || 0)).toFixed(1)}% 剩余`)}</div>
 </div>
 `;
 }
 if (rankingBody) {
 const rows = Array.isArray(stats.user_ranking) ? stats.user_ranking : [];
 rankingBody.innerHTML = rows.length ? rows.map((row) => `
 <tr>
 <td><span class="rank-badge ${row.rank === 1 ? 'rank-1' : row.rank === 2 ? 'rank-2' : row.rank === 3 ? 'rank-3' : 'rank-n'}">${escapeHtml(String(row.rank || ''))}</span></td>
 <td style="color:var(--text-main)">${escapeHtml(row.user_name || '')}</td>
 <td><span class="${escapeAttr(row.level_class || 'tag tag-blue')}">${escapeHtml(row.level_label || '普通用户')}</span></td>
