 const previewNode = document.getElementById('kw-hermes-memory-preview');
 const backupRange = document.getElementById('kw-hermes-memory-backup-range');
 const clearRange = document.getElementById('kw-hermes-memory-clear-range');
 const confirmWrap = document.getElementById('kw-hermes-memory-clear-confirm-wrap');
 if (!tenantSelect || !summaryNode || !previewNode || !backupRange || !clearRange) return;

 const tenants = getWorkbenchHermesMemoryTenantOptions();
 const currentTenant = getWorkbenchHermesMemorySelectedTenant();
 tenantSelect.innerHTML = tenants.map((tenant) => `
 <option value="${escapeAttr(tenant.slug || '')}" ${(tenant.slug || '') === currentTenant ? 'selected' : ''}>${escapeHtml(tenant.name || tenant.slug || '')}</option>
 `).join('') || '<option value="">暂无租户</option>';
 if (!tenantSelect.value && tenants.length) tenantSelect.value = tenants[0].slug || '';

 const options = getWorkbenchHermesMemoryRangeOptions();
 const currentBackupRange = backupRange.value || '3m';
 const currentClearRange = clearRange.value || '3m';
 backupRange.innerHTML = options.map((item) => `
 <option value="${escapeAttr(item.key || '')}" ${(item.key || '') === currentBackupRange ? 'selected' : ''}>${escapeHtml(item.label || item.key || '')}</option>
 `).join('');
 clearRange.innerHTML = options.map((item) => `
 <option value="${escapeAttr(item.key || '')}" ${(item.key || '') === currentClearRange ? 'selected' : ''}>${escapeHtml(item.label || item.key || '')}</option>
 `).join('');

 const summary = kwHermesMemoryState.summary || {};
 const cards = [
 {label: '对话总轮次', value: Number(summary.turn_count || 0), desc: summary.first_turn_at ? `首轮：${summary.first_turn_at}` : '暂无对话'},
