 {label: '画像数', value: Number(summary.profile_count || 0), desc: summary.last_turn_at ? `最近：${summary.last_turn_at}` : '暂无最近时间'},
 {label: '近 30 天轮次', value: Number(summary.recent_30d_turn_count || 0), desc: `活跃用户 ${Number(summary.recent_30d_active_user_count || 0)}`},
 ];
 summaryNode.innerHTML = cards.map((item) => `
 <div class="hermes-memory-summary-card">
 <div class="hermes-memory-summary-label">${escapeHtml(item.label)}</div>
 <div class="hermes-memory-summary-value">${escapeHtml(String(item.value))}</div>
 <div class="hermes-memory-summary-meta">${escapeHtml(item.desc)}</div>
 </div>
 `).join('');

 const preview = kwHermesMemoryState.preview || null;
 if (!preview) {
