async function loadWorkbenchHermesUsageStats() {
 if (kwHermesUsageState.loading) return;
 const tenantSlug = String(((window.ACTIVE_TENANT || {}).slug) || '').trim();
 kwHermesUsageState.loading = true;
 try {
 const resp = await fetch(`/api/kol/hermes/usage-stats?tenant=${encodeURIComponent(tenantSlug)}`);
 const data = await resp.json();
 if (!resp.ok || !data.ok) throw new Error((data && data.error) || 'hermes_usage_stats_failed');
 kwHermesUsageState.stats = data.stats || null;
 renderWorkbenchHermesUsageOverview();
 } catch (error) {
 const message = error.message || 'Hermes 使用数据加载失败';
 renderWorkbenchHermesUsageUnavailable(message);
 showToast(message);
 } finally {
 kwHermesUsageState.loading = false;
 }
}

async function loadWorkbenchHermesMemorySummary(forceReload = false) {
 if (kwHermesMemoryState.loading) return;
 const tenantSlug = String(((window.ACTIVE_TENANT || {}).slug) || '').trim();
 if (!tenantSlug) {
 setWorkbenchHermesMemoryStatus('当前没有可管理的租户。', true);
 return;
 }
 kwHermesMemoryState.loading = true;
 setWorkbenchHermesMemoryStatus('正在加载 Hermes 记忆汇总...');
 try {
 const resp = await fetch(`/api/kol/hermes/memory-summary?tenant=${encodeURIComponent(tenantSlug)}`);
 const data = await resp.json();
 if (!resp.ok || !data.ok) throw new Error((data && data.error) || 'hermes_memory_summary_failed');
 kwHermesMemoryState.summary = data.summary || null;
 kwHermesMemoryState.loaded = true;
 renderWorkbenchHermesMemoryOverview();
 setWorkbenchHermesMemoryStatus(`Hermes 记忆汇总已加载 · 租户 ${tenantSlug}`);
 } catch (error) {
 setWorkbenchHermesMemoryStatus(error.message || 'Hermes 记忆汇总加载失败', true);
 throw error;
 } finally {
 kwHermesMemoryState.loading = false;
 }
}

