 .points-bs-shell .points-bs-kpi-row { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:18px; margin:0 0 26px; }
 .points-bs-shell .points-bs-kpi-card { min-height:126px; padding:20px 21px; border-radius:8px; display:flex; flex-direction:column; justify-content:space-between; }
 .points-bs-shell .points-bs-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:24px; margin-top:24px; }
 .points-bs-shell .points-bs-panel { padding:20px 22px; border-radius:8px; }
 .points-bs-shell .points-bs-panel .table-header { padding:0 0 15px; margin-bottom:8px; }
 .points-bs-shell .points-bs-table { margin-top:24px; padding:20px 22px; border-radius:8px; overflow:hidden; }
 .points-bs-shell .points-bs-table th, .points-bs-shell .points-bs-table td { padding-top:13px; padding-bottom:13px; vertical-align:middle; }
 .points-bs-shell .points-bs-disabled { border:1px solid rgba(200,169,110,0.15); background:rgba(200,169,110,0.05); border-radius:8px; padding:18px; color:var(--text-sub); line-height:1.8; }
 @media (max-width:1100px) { .points-bs-shell .points-bs-kpi-row { grid-template-columns:repeat(2,minmax(0,1fr)); } }
 @media (max-width:760px) {
 .points-bs-shell.container-fluid { padding:12px 12px 28px; }
 .points-bs-shell .points-bs-kpi-row, .points-bs-shell .points-bs-grid { grid-template-columns:1fr; gap:14px; }
 .points-bs-shell .points-bs-kpi-card, .points-bs-shell .points-bs-panel, .points-bs-shell .points-bs-table { padding:17px 16px; }
 }
 .compute-packages { display:grid; grid-template-columns:repeat(auto-fill,minmax(180px,1fr)); gap:12px; margin-top:16px; }
 .compute-pkg { background:rgba(200,169,110,0.06); border:1px solid rgba(200,169,110,0.2); border-radius:10px; padding:14px; text-align:center; }
 .compute-pkg-name { font-size:12px; color:var(--text-sub); margin-bottom:6px; }
 .compute-pkg-cost { font-size:20px; color:var(--gold); font-weight:700; }
 .compute-pkg-unit { font-size:11px; color:var(--text-sub); margin-bottom:8px; }
 .compute-pkg-compute { font-size:13px; color:var(--text-main); }
 .pool-cards { display:grid; grid-template-columns:repeat(3,1fr); gap:16px; margin-bottom:20px; }
 .pool-card { background:var(--surface-2); border:1px solid rgba(200,169,110,0.2); border-radius:10px; padding:16px; text-align:center; }
 .pool-card-label { font-size:11px; color:var(--text-sub); margin-bottom:6px; }
 .pool-card-value { font-size:22px; color:var(--gold); font-weight:700; }
 .pool-card-sub { font-size:11px; color:var(--text-sub); margin-top:4px; }
 .search-bar { display:flex; gap:10px; margin-bottom:16px; align-items:center; flex-wrap:wrap; }
 .search-bar input { background:var(--surface); border:1px solid rgba(200,169,110,0.2); border-radius:6px; padding:8px 12px; color:var(--text-main); font-size:13px; width:220px; }
 .search-bar input:focus { outline:none; border-color:rgba(200,169,110,0.5); }
 .search-bar select { background:var(--surface); border:1px solid rgba(200,169,110,0.2); border-radius:6px; padding:8px 12px; color:var(--text-main); font-size:13px; cursor:pointer; }
 .search-bar select:focus { outline:none; }
 .btn-sm-red { background:transparent; border:1px solid rgba(220,50,50,0.4); color:#ff7070; border-radius:5px; padding:3px 9px; font-size:11px; cursor:pointer; }
 .btn-sm-red:hover { background:rgba(220,50,50,0.1); }
 .btn-sm-blue { background:transparent; border:1px solid rgba(100,160,255,0.4); color:#7ab0ff; border-radius:5px; padding:3px 9px; font-size:11px; cursor:pointer; }
 .btn-sm-blue:hover { background:rgba(100,160,255,0.1); }
 .status-gold { color:#C8A96E; font-weight:500; }
 .status-blue { color:#7ab0ff; font-weight:500; }
 .status-green { color:#4caf7d; font-weight:500; }
 .rank-badge { display:inline-flex; align-items:center; justify-content:center; width:22px; height:22px; border-radius:50%; font-size:11px; font-weight:700; }
 .rank-1 { background:#C8A96E; color:#0D1B2A; }
 .rank-2 { background:#a0a0a0; color:#0D1B2A; }
 .rank-3 { background:#cd7f32; color:#0D1B2A; }
 .rank-n { background:rgba(200,169,110,0.08); color:var(--text-sub); }
 .audit-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:16px; margin-bottom:20px; }
 .audit-table { width:100%; border-collapse:collapse; }
 .audit-table th, .audit-table td { padding:10px 12px; border-bottom:1px solid rgba(200,169,110,0.08); font-size:12px; }
 .audit-table th { color:var(--text-sub); background:rgba(200,169,110,0.06); text-align:left; }
 .audit-table td { color:var(--text-main); }
 .audit-chart-wrap { height:280px; }
 .sync-grid { display:grid; grid-template-columns:1fr 1fr; gap:16px; }
 .sync-card { background:var(--surface-2); border:1px solid rgba(200,169,110,0.15); border-radius:12px; padding:18px; }
 .sync-title { font-size:14px; color:var(--gold); font-weight:600; margin-bottom:8px; }
 .sync-desc { font-size:12px; color:var(--text-sub); line-height:1.7; margin-bottom:12px; }
 .sync-chip-row { display:flex; gap:8px; flex-wrap:wrap; }
 .sync-chip { font-size:11px; color:var(--gold-dark); background:rgba(200,169,110,0.10); border:1px solid rgba(200,169,110,0.18); border-radius:999px; padding:4px 10px; }
