 border-radius:10px;
 background:var(--surface-2);
 font-size:12px;
 color:var(--text-sub);
 }
 .compact-row strong { color:var(--text-main); }
 .workflow-shell { display:grid; grid-template-columns:260px minmax(0,1fr) 320px; gap:20px; margin-top:16px; }
 .workflow-catalog { display:grid; gap:10px; }
 .workflow-catalog-item {
 text-align:left;
 padding:12px 14px;
 border-radius:12px;
 border:1px solid rgba(200,169,110,0.14);
 background:var(--surface);
 color:var(--text-main);
 cursor:pointer;
 transition:all 0.18s ease;
 }
 .workflow-catalog-item:hover {
 border-color:rgba(47,116,192,0.32);
 box-shadow:0 10px 24px rgba(47,116,192,0.08);
 transform:translateY(-1px);
 }
 .workflow-catalog-item strong { display:block; font-size:13px; margin-bottom:4px; color:var(--text-main); }
 .workflow-catalog-item span { display:block; font-size:11px; line-height:1.6; color:var(--text-sub); }
 .agent-workflow-list { display:grid; gap:10px; }
 .agent-workflow-item {
 text-align:left;
 padding:12px 14px;
 border-radius:12px;
 border:1px solid rgba(200,169,110,0.12);
 background:var(--surface);
 color:var(--text-main);
 cursor:pointer;
 transition:all 0.18s ease;
 }
 .agent-workflow-item.is-active {
 border-color:rgba(47,116,192,0.35);
 box-shadow:0 10px 24px rgba(47,116,192,0.08);
 }
 .agent-workflow-item-title { font-size:13px; font-weight:700; color:var(--text-main); }
 .agent-workflow-item-desc { font-size:11px; line-height:1.6; color:var(--text-sub); margin-top:5px; }
 .agent-workflow-chip-row { display:flex; flex-wrap:wrap; gap:6px; margin-top:8px; }
 .agent-workflow-chip {
 font-size:10px;
 color:var(--gold);
 border:1px solid rgba(200,169,110,0.14);
 border-radius:999px;
 padding:3px 8px;
 background:var(--surface-2);
 }
 .workflow-node-copy { margin-top:8px; font-size:11px; line-height:1.65; color:var(--text-sub); }
 .agent-workflow-metric-grid { display:grid; gap:10px; }
 .agent-workflow-metric {
 padding:12px 14px;
 border:1px solid var(--border-soft);
 border-radius:10px;
 background:var(--surface-2);
 }
 .agent-workflow-metric-label { font-size:11px; color:var(--text-sub); }
 .agent-workflow-metric-value { font-size:18px; font-weight:700; color:var(--text-main); margin-top:6px; }
 .workflow-toolbar {
 display:flex;
 justify-content:space-between;
 align-items:center;
 gap:12px;
 flex-wrap:wrap;
 margin-bottom:14px;
 }
 .workflow-toolbar-left,
 .workflow-toolbar-right { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
 .workflow-stage {
 position:relative;
 overflow:auto;
 border-radius:14px;
 border:1px solid rgba(200,169,110,0.12);
 min-height:760px;
 background:
 linear-gradient(90deg, rgba(47,116,192,0.06) 1px, transparent 1px) 0 0 / 24px 24px,
 linear-gradient(rgba(47,116,192,0.06) 1px, transparent 1px) 0 0 / 24px 24px,
 var(--surface-2);
 }
 body.theme-dark .workflow-stage {
 background:
 linear-gradient(90deg, rgba(102,161,223,0.06) 1px, transparent 1px) 0 0 / 24px 24px,
 linear-gradient(rgba(102,161,223,0.06) 1px, transparent 1px) 0 0 / 24px 24px,
 var(--surface-3);
 }
 .workflow-stage-viewport {
 position:relative;
 min-width:100%;
 min-height:760px;
 transform-origin:0 0;
 isolation:isolate;
 }
 .workflow-edge-layer {
 position:absolute;
 top:0;
 left:0;
 pointer-events:none;
 overflow:visible;
 z-index:1;
 }
 .workflow-edge {
 fill:none;
 stroke:rgba(47,116,192,0.96);
 stroke-width:4;
 stroke-linecap:round;
 stroke-linejoin:round;
 filter:drop-shadow(0 0 10px rgba(47,116,192,0.18));
 }
 .workflow-edge-shadow {
 fill:none;
 stroke:rgba(255,255,255,0.96);
 stroke-width:8;
 stroke-linecap:round;
 stroke-linejoin:round;
 opacity:0.96;
 }
 body.theme-dark .workflow-edge-shadow { stroke:rgba(8,16,30,0.94); }
 .workflow-edge-anchor {
 fill:var(--surface);
 stroke:rgba(47,116,192,0.98);
 stroke-width:3;
 }
 .workflow-board { position:relative; min-height:760px; z-index:2; }
 .workflow-board-canvas { min-width:100%; }
 .workflow-node {
 position:absolute;
 width:220px;
 padding:12px;
 background:var(--surface);
 border:1px solid var(--border-soft);
 border-radius:14px;
 box-shadow:0 10px 26px rgba(14,33,55,0.08);
 cursor:grab;
 user-select:none;
 z-index:3;
 }
 body.theme-dark .workflow-node { background:var(--surface-2); }
 .workflow-node.is-selected {
 border-color:var(--gold);
 box-shadow:0 12px 28px rgba(47,116,192,0.15);
 }
 .workflow-node.is-link-source {
 border-color:rgba(47,116,192,0.52);
 box-shadow:0 12px 28px rgba(47,116,192,0.18);
 }
 .workflow-node:hover { border-color:rgba(47,116,192,0.35); }
 .workflow-node-head { display:flex; justify-content:space-between; align-items:center; gap:8px; }
 .workflow-node-head strong { font-size:13px; color:var(--text-main); }
 .workflow-node-type {
 font-size:10px;
 color:var(--gold);
 border:1px solid var(--border-soft);
 border-radius:999px;
 padding:3px 8px;
 }
 .workflow-node-ports { display:flex; justify-content:space-between; margin-top:12px; }
 .workflow-port {
 border:1px solid var(--border-soft);
 background:var(--surface-2);
 color:var(--text-main);
 border-radius:999px;
 padding:4px 10px;
 font-size:11px;
 cursor:pointer;
 font-family:inherit;
 position:relative;
 }
 .workflow-port::before {
 content:"";
 width:8px;
 height:8px;
 border-radius:50%;
 background:var(--gold);
 display:inline-block;
 margin-right:6px;
 box-shadow:0 0 0 3px rgba(47,116,192,0.14);
 }
 #section-agent-workflows .workflow-stage {
 min-height:760px;
 background:
 linear-gradient(180deg, rgba(47,116,192,0.03), rgba(47,116,192,0.01)),
 var(--surface-2);
 }
 #section-agent-workflows .workflow-stage-viewport {
 min-height:760px;
 padding:0;
 }
 #section-agent-workflows .workflow-edge-layer {
 display:block;
 }
 #section-agent-workflows .workflow-board {
 position:relative;
 min-height:760px;
 }
 .agent-workflow-node {
 height:118px;
 box-sizing:border-box;
 cursor:pointer;
 }
 .agent-workflow-node.is-visual-only {
 border-style:dashed;
 background:color-mix(in srgb, var(--surface) 92%, rgba(47,116,192,0.08));
 }
 .agent-workflow-node-copy {
 margin-top:8px;
 font-size:10px;
 line-height:1.55;
 color:var(--text-sub);
 display:-webkit-box;
 -webkit-box-orient:vertical;
 -webkit-line-clamp:2;
 overflow:hidden;
 }
 .agent-workflow-node .workflow-node-type.is-visual {
 color:var(--text-sub);
 border-style:dashed;
 }
 .agent-workflow-edge-label {
 fill:var(--text-main);
 font-family:inherit;
 font-size:11px;
 font-weight:700;
 paint-order:stroke;
 stroke:var(--surface-2);
 stroke-width:5px;
 stroke-linejoin:round;
 }
 .agent-workflow-edge-condition {
 fill:var(--text-sub);
 font-family:inherit;
 font-size:9px;
 paint-order:stroke;
 stroke:var(--surface-2);
 stroke-width:4px;
 stroke-linejoin:round;
 }
 .agent-workflow-scenario-list {
 display:grid;
 gap:7px;
 margin-top:10px;
 }
 .agent-workflow-scenario-item {
 width:100%;
 display:grid;
 grid-template-columns:24px minmax(0, 1fr);
 gap:9px;
 align-items:start;
 padding:9px 10px;
 border:1px solid var(--border-soft);
 border-radius:8px;
 background:var(--surface-2);
 color:var(--text-main);
 text-align:left;
 font:inherit;
 cursor:pointer;
 }
 .agent-workflow-scenario-item:hover,
 .agent-workflow-scenario-item.is-active {
 border-color:rgba(200,169,110,0.52);
 background:rgba(200,169,110,0.08);
 }
 .agent-workflow-scenario-index {
 color:var(--gold);
 font-size:11px;
 font-weight:700;
 line-height:20px;
 }
 .agent-workflow-scenario-title {
 font-size:11px;
 font-weight:700;
 line-height:1.35;
 }
 .agent-workflow-scenario-route {
 margin-top:3px;
 color:var(--text-sub);
 font-size:10px;
 line-height:1.45;
 }
 .workflow-tool-button {
 padding:6px 10px !important;
 font-size:11px !important;
 color:var(--text-sub);
 border-color:rgba(47,116,192,0.12);
 background:transparent;
 }
 .workflow-tool-button:hover {
 color:var(--text-main);
 border-color:rgba(47,116,192,0.22);
 background:var(--surface-2);
 }
 .forecast-config-section-title { margin:2px 0 8px; font-size:12px; color:var(--text-main); font-weight:700; }
 .workflow-inspector-actions { display:flex; justify-content:flex-end; margin-top:10px; }
 .forecast-config-board { display:grid; gap:12px; }
 .forecast-config-field {
 display:grid;
 gap:6px;
 padding:12px 14px;
 border:1px solid var(--border-soft);
 border-radius:10px;
 background:var(--surface-2);
 }
 body.theme-dark .forecast-config-field { background:var(--surface-3); }
 .forecast-config-field span { font-size:12px; color:var(--text-sub); }
 .forecast-config-input { display:flex; align-items:center; gap:10px; }
 .forecast-config-input input {
 flex:1;
 min-width:0;
 border:1px solid var(--border-soft);
 border-radius:8px;
 background:var(--surface);
 color:var(--text-main);
 padding:10px 12px;
 font-size:13px;
 }
 .forecast-config-input em {
 min-width:28px;
 font-style:normal;
 font-size:12px;
 color:var(--gold);
 text-align:right;
 }
 .forecast-debug-value,
 .forecast-debug-copy,
 .forecast-debug-list,
 .result-line { font-size:12px; color:var(--text-main); line-height:1.7; }
 .result-line strong { color:var(--gold); }
 .forecast-inspector-section { display:grid; gap:12px; }
 .workflow-guide {
 margin:8px 0 0;
 font-size:12px;
 color:var(--text-sub);
 line-height:1.7;
 }
 .workflow-guide strong { color:var(--text-main); }
 .forecast-advanced-toggle {
 cursor:pointer;
 font-size:12px;
 color:var(--text-main);
 font-weight:700;
 list-style:none;
 }
 .forecast-advanced-toggle::-webkit-details-marker { display:none; }
 .forecast-advanced-toggle::before {
 content:"+";
 display:inline-block;
 margin-right:6px;
 color:var(--gold);
 }
 details[open] > .forecast-advanced-toggle::before { content:"-"; }

 @media (max-width: 1280px) {
 .workflow-shell { grid-template-columns:1fr; }
 }

