 body.theme-light .admin-layout [style*="border:1px solid rgba(200,169,110,0.12)"],
 body.theme-light .admin-layout [style*="border: 1px solid rgba(200,169,110,0.12)"],
 body.theme-light .admin-layout [style*="border:1px solid rgba(200,169,110,0.15)"],
 body.theme-light .admin-layout [style*="border: 1px solid rgba(200,169,110,0.15)"] {
 border-color: rgba(47, 116, 192, 0.16) !important;
 }

 body.theme-light .admin-layout input,
 body.theme-light .admin-layout select,
 body.theme-light .admin-layout textarea,
 body.theme-light .admin-layout [contenteditable="true"] {
 color: var(--text-main) !important;
 caret-color: var(--text-main);
 }

 body.theme-light .admin-layout input::placeholder,
 body.theme-light .admin-layout textarea::placeholder {
 color: var(--text-sub);
 }

 body.theme-dark .admin-layout input,
 body.theme-dark .admin-layout select,
 body.theme-dark .admin-layout textarea,
 body.theme-dark .admin-layout [contenteditable="true"] {
 color: var(--text-main) !important;
 caret-color: var(--text-main);
 }
 .admin-modal-overlay {
 position:fixed;
 inset:0;
 display:none;
 align-items:center;
 justify-content:center;
 padding:24px;
 background:rgba(7,18,31,0.56);
 z-index:10000;
 }
 .admin-modal-overlay.show { display:flex; }
 .admin-modal-sheet {
 width:min(900px, 100%);
 max-height:min(88vh, 920px);
 overflow:auto;
 background:var(--surface);
 border:1px solid rgba(200,169,110,0.16);
 border-radius:18px;
 box-shadow:0 24px 80px rgba(9,22,37,0.28);
 padding:22px;
 }
 .admin-modal-head {
 display:flex;
 justify-content:space-between;
 align-items:flex-start;
 gap:16px;
 margin-bottom:18px;
 }
 .admin-modal-title { font-size:20px; color:var(--text-main); font-weight:700; }
 .admin-modal-subtitle { font-size:12px; color:var(--text-sub); line-height:1.7; margin-top:4px; }
 .admin-modal-close {
 width:34px;
 height:34px;
