 background:#163A63;
 color:#FFFFFF;
 font-size:22px;
 cursor:pointer;
 }
 .admin-modal-close:hover { color:#FFFFFF; border-color:#66A1DF; background:#1D4B7C; }
 .admin-modal-grid {
 display:grid;
 gap:16px;
 }
 .admin-modal-card {
