 border:1px solid rgba(200,169,110,0.12);
 border-radius:14px;
 padding:16px;
 }
 .admin-modal-card-title { font-size:13px; color:var(--gold); font-weight:600; margin-bottom:10px; }
 .admin-modal-list { display:grid; gap:10px; }
 .admin-modal-item {
 border:1px solid rgba(200,169,110,0.1);
 border-radius:10px;
 padding:12px;
 background:var(--surface);
 }
 .admin-modal-item-top {
