 .admin-knowledge-readable-desc { margin-top:4px; font-size:11px; color:var(--text-sub); line-height:1.7; }
 .admin-knowledge-readable-list { margin-top:12px; display:grid; gap:10px; }
 .admin-knowledge-readable-item {
 width:100%;
 text-align:left;
 padding:12px 14px;
 border-radius:14px;
 background:#F8FBFF;
 border:1px solid rgba(47,116,192,0.08);
