 }
 .admin-knowledge-readable-item-title { font-size:13px; font-weight:700; color:var(--text-main); }
 .admin-knowledge-readable-item-meta { margin-top:4px; font-size:11px; color:var(--text-sub); line-height:1.65; }
 .admin-knowledge-readable-item-summary { margin-top:8px; font-size:12px; color:var(--text-main); line-height:1.75; }
 .admin-knowledge-readable-item-foot { margin-top:10px; font-size:11px; color:#245B96; font-weight:700; }
 .admin-kg-shell {
 background:linear-gradient(180deg, #FFFFFF, #FBFDFF);
 border:1px solid rgba(47,116,192,0.12);
 border-radius:18px;
 padding:16px;
 margin-bottom:16px;
 }
 .admin-ka-shell {
 margin-top:14px;
 padding:14px;
 border-radius:16px;
 background:rgba(47,116,192,0.03);
 border:1px solid rgba(47,116,192,0.10);
 }
 .admin-ka-head { display:flex; justify-content:space-between; align-items:flex-start; gap:12px; flex-wrap:wrap; }
 .admin-ka-title { font-size:15px; font-weight:700; color:var(--text-main); }
 .admin-ka-desc { margin-top:4px; font-size:12px; color:var(--text-sub); line-height:1.75; max-width:780px; }
 .admin-ka-summary-grid {
 margin-top:12px;
 display:grid;
 grid-template-columns:repeat(6, minmax(0, 1fr));
 gap:8px;
 }
 .admin-ka-card {
 background:#FFFFFF;
 border:1px solid rgba(47,116,192,0.10);
 border-radius:14px;
 padding:12px;
 }
 .admin-ka-label { font-size:11px; color:var(--text-sub); }
 .admin-ka-value { margin-top:6px; font-size:20px; font-weight:800; color:var(--text-main); }
 .admin-ka-meta { margin-top:4px; font-size:11px; color:var(--text-sub); line-height:1.65; }
 .admin-ka-layout {
 margin-top:12px;
 display:grid;
 grid-template-columns:minmax(0, 1.05fr) minmax(0, 0.95fr);
 gap:12px;
 }
 .admin-ka-panel {
 background:#FFFFFF;
 border:1px solid rgba(47,116,192,0.10);
 border-radius:14px;
 padding:14px;
 }
 .admin-ka-panel-title { font-size:13px; font-weight:700; color:var(--text-main); }
 .admin-ka-panel-desc { margin-top:4px; font-size:11px; color:var(--text-sub); line-height:1.7; }
 .admin-ka-rel-grid,
 .admin-ka-entry-list { margin-top:12px; display:grid; gap:10px; }
 .admin-ka-rel-list { display:grid; gap:8px; }
 .admin-ka-rel-item,
 .admin-ka-entry {
 background:#F8FBFF;
 border:1px solid rgba(47,116,192,0.09);
 border-radius:12px;
 padding:10px 12px;
 }
 .admin-ka-entry {
 width:100%;
 text-align:left;
 cursor:pointer;
 }
 .admin-ka-rel-top,
 .admin-ka-entry-top { display:flex; justify-content:space-between; gap:10px; align-items:flex-start; }
 .admin-ka-rel-title,
 .admin-ka-entry-title { font-size:12px; font-weight:700; color:var(--text-main); }
 .admin-ka-rel-count {
 font-size:11px;
