 }
 .admin-ka-entry-stat {
 background:#FFFFFF;
 border:1px solid rgba(47,116,192,0.08);
 border-radius:10px;
 padding:8px 10px;
 }
 .admin-ka-entry-stat-label { font-size:10px; color:var(--text-sub); }
