 }
 .admin-ka-maturity.tone-seed { background:rgba(143,166,196,0.16); color:#416287; }
 .admin-ka-maturity.tone-growing { background:rgba(200,169,110,0.16); color:#9A6B10; }
 .admin-ka-maturity.tone-ready { background:rgba(81,169,118,0.14); color:#2E7D4F; }
 .admin-ka-entry-meta { margin-top:8px; font-size:11px; color:var(--text-sub); line-height:1.65; }
 .admin-kg-top { display:flex; justify-content:space-between; align-items:flex-start; gap:14px; flex-wrap:wrap; }
 .admin-kg-title { font-size:16px; font-weight:700; color:var(--text-main); }
 .admin-kg-desc { margin-top:4px; font-size:12px; color:var(--text-sub); line-height:1.7; max-width:760px; }
 .admin-kg-controls { display:flex; gap:8px; flex-wrap:wrap; align-items:center; }
 .admin-kg-search,
 .admin-kg-select {
 border:none;
 outline:none;
