 background:#FFFFFF;
 border:1px solid rgba(47,116,192,0.12);
 color:var(--text-main);
 font-size:13px;
 padding:10px 12px;
 box-sizing:border-box;
 }
 .admin-kg-search { min-width:280px; flex:1; }
 .admin-kg-select { min-width:132px; }
 .admin-kg-stage { margin-top:12px; font-size:11px; color:var(--gold); }
 .admin-kg-stats {
 margin-top:12px;
 display:grid;
 grid-template-columns:repeat(6, minmax(0, 1fr));
 gap:8px;
 }
 .admin-kg-stat { background:var(--surface); border:1px solid rgba(47,116,192,0.10); border-radius:12px; padding:10px; }
 .admin-kg-stat-label { font-size:10px; color:var(--text-sub); }
 .admin-kg-stat-value { margin-top:6px; font-size:18px; font-weight:800; color:var(--text-main); }
 .admin-kg-legend { margin-top:10px; display:flex; flex-wrap:wrap; gap:8px; }
 .admin-kg-legend-chip {
 display:inline-flex;
 align-items:center;
 gap:6px;
 padding:5px 10px;
 border-radius:999px;
 background:#FFFFFF;
 border:1px solid rgba(47,116,192,0.10);
 color:var(--text-sub);
 font-size:11px;
 }
 .admin-kg-legend-dot {
 width:8px;
 height:8px;
 border-radius:50%;
 background:#8FA6C4;
 flex:0 0 auto;
 }
 .admin-kg-legend-dot.kind-root { background:#C8A96E; }
 .admin-kg-legend-dot.kind-tenant { background:#D9E9FF; }
 .admin-kg-legend-dot.kind-topic { background:#8FCCFF; }
 .admin-kg-legend-dot.kind-entity { background:#F6D38B; }
 .admin-kg-legend-dot.kind-method { background:#B9F0D2; }
 .admin-kg-legend-dot.kind-claim { background:#DCEBFA; }
 .admin-kg-legend-dot.kind-signal { background:#97B6D9; }
 .admin-kg-layout { margin-top:14px; display:grid; grid-template-columns:minmax(0, 1.65fr) minmax(320px, 0.85fr); gap:14px; }
 .admin-kg-board-shell,
 .admin-kg-detail {
 border-radius:18px;
 border:1px solid rgba(47,116,192,0.10);
 }
 .admin-kg-board-shell {
 background:
 radial-gradient(circle at top, rgba(47,116,192,0.16), transparent 34%),
 linear-gradient(180deg, #09131F, #102033);
 overflow:auto;
 }
 .admin-kg-board {
 position:relative;
 min-height:760px;
 background-image:
 linear-gradient(rgba(126,153,184,0.07) 1px, transparent 1px),
 linear-gradient(90deg, rgba(126,153,184,0.07) 1px, transparent 1px);
 background-size:26px 26px;
 overflow:hidden;
 }
 .admin-kg-svg { position:absolute; inset:0; width:100%; height:100%; pointer-events:none; }
 .admin-kg-edge { fill:none; stroke:rgba(126,153,184,0.30); stroke-width:1.2; }
 .admin-kg-node {
 position:absolute;
 transform:translate(-50%, -50%);
 border:none;
 cursor:pointer;
 text-align:left;
 color:#E8EEF5;
 background:rgba(17,32,49,0.86);
 border:1px solid rgba(92,126,164,0.28);
 border-radius:999px;
 padding:8px 12px;
 min-width:72px;
 max-width:180px;
 box-shadow:0 12px 30px rgba(3,10,18,0.28);
 }
 .admin-kg-node:hover { transform:translate(-50%, calc(-50% - 1px)); }
 .admin-kg-node.is-active {
 border-color:rgba(200,169,110,0.56);
 box-shadow:0 0 0 2px rgba(200,169,110,0.18), 0 16px 34px rgba(3,10,18,0.32);
 }
 .admin-kg-node.kind-root { background:linear-gradient(135deg, #355D8A, #20405F); color:#FFFFFF; min-width:168px; border-color:rgba(200,169,110,0.34); }
 .admin-kg-node.kind-tenant { color:#D9E9FF; min-width:150px; }
 .admin-kg-node.kind-topic { color:#A8D2FF; }
 .admin-kg-node.kind-entity { color:#F6D38B; }
 .admin-kg-node.kind-method { color:#B9F0D2; }
 .admin-kg-node.kind-claim { border-radius:16px; max-width:220px; color:#F3F7FB; }
 .admin-kg-node.kind-signal { padding:7px 10px; background:rgba(13,24,38,0.92); color:#D6E5F7; }
 .admin-kg-node-kind { font-size:10px; opacity:0.68; }
 .admin-kg-node-label { margin-top:4px; font-size:12px; font-weight:700; line-height:1.4; overflow:hidden; text-overflow:ellipsis; }
 .admin-kg-detail { background:#FFFFFF; padding:16px; }
 .admin-kg-detail-empty { min-height:240px; display:flex; align-items:center; justify-content:center; text-align:center; padding:24px; color:var(--text-sub); font-size:12px; line-height:1.8; }
 .admin-kg-detail-kicker { font-size:10px; color:var(--gold); letter-spacing:0.04em; }
 .admin-kg-detail-title { margin-top:6px; font-size:18px; font-weight:800; color:var(--text-main); line-height:1.35; }
 .admin-kg-detail-summary { margin-top:10px; font-size:12px; color:var(--text-sub); line-height:1.8; }
 .admin-kg-chip-row { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; }
 .admin-kg-chip { display:inline-flex; align-items:center; gap:6px; padding:5px 10px; border-radius:999px; background:rgba(47,116,192,0.08); border:1px solid rgba(47,116,192,0.12); color:#245B96; font-size:11px; }
 .admin-kg-detail-section { margin-top:16px; }
 .admin-kg-detail-section-title { font-size:12px; font-weight:700; color:var(--text-main); }
 .admin-kg-detail-list { margin-top:8px; display:flex; flex-direction:column; gap:8px; }
 .admin-kg-detail-item { padding:10px 12px; border-radius:12px; background:#F8FBFF; border:1px solid rgba(47,116,192,0.10); }
 .admin-kg-detail-item-title { font-size:12px; font-weight:700; color:var(--text-main); }
 .admin-kg-detail-item-meta { margin-top:4px; font-size:11px; color:var(--text-sub); line-height:1.7; }
 @media (max-width: 980px) {
 .admin-modal-overlay { padding:12px; }
 .admin-modal-sheet { padding:18px; border-radius:16px; }
 .admin-modal-grid { grid-template-columns:1fr; }
 .indicator-hero,
 .llm-admin-hero,
 .llm-admin-model-grid,
 .tenant-admin-shell,
 .tenant-admin-detail-grid,
 .tenant-dashboard-grid,
 .admin-knowledge-hub-grid,
 .admin-knowledge-overview-grid,
 .admin-knowledge-readable-shell,
 .admin-ka-summary-grid,
 .admin-ka-layout,
 .admin-ka-entry-grid,
 .admin-kg-stats,
 .admin-kg-layout { grid-template-columns:1fr; }
 .tenant-admin-sidebar { position:static; }
 }
</style>
</head>
