 <button class="btn-outline" style="padding:8px 14px;font-size:12px" type="button" onclick="expandAdminKnowledgeMapAll()">全部展示</button>
 <button class="btn-outline" style="padding:8px 14px;font-size:12px" type="button" onclick="adjustAdminKnowledgeMapDepth(-1)">-</button>
 <button class="btn-outline" style="padding:8px 14px;font-size:12px" type="button" onclick="adjustAdminKnowledgeMapDepth(1)">+</button>
