<script src="/static/js/charts.js?v=20260828-2"></script>
<script>
const sectionTitles = {
 overview:'运营概览', users:'用户列表', segments:'用户分层', points:'积分管理',
 kols:'大V投顾管理', commission:'收益结算', community:'帖子审核',
 events:'活动管理', hermes:'Hermes使用统计', 'agent-workflows':'智能体工作流中心', 'forecast-model':'预测模型', channels:'渠道管理',
 'indicator-overview':'指标专区 · 总览控制台',
 'indicator-smart':'指标专区 · 智能指标',
 'indicator-lake':'指标专区 · 数据湖指标',
 'indicator-anomalies':'指标专区 · 异动报告',
 'indicator-sources':'指标专区 · API 源接入',
 'news-sources':'指标专区 · 新闻数据源',
 'indicator-definitions':'指标专区 · 指标定义',
 'indicator-pipeline':'指标专区 · 清洗流水线',
 analytics:'数据分析',
 'settings-appearance':'系统专区 · 系统配置',
 'settings-brand':'系统专区 · 系统配置',
 'settings-features':'系统专区 · 系统配置',
 'settings-policy':'系统专区 · 发布与隔离',
 'knowledge-overview':'知识专区 · 知识总览',
 'knowledge-intake':'知识专区 · 知识治理',
 'knowledge-encyclopedia':'知识专区 · 百科结构',
 'knowledge-entries':'知识专区 · 百科词条',
 'knowledge-graph':'知识专区 · 知识图谱',
 'settings-knowledge':'知识专区 · 知识总览',
 'settings-knowledge-graph':'知识专区 · 知识图谱',
 'knowledge-items':'知识专区 · 知识治理',
 'settings-llm':'系统专区 · 大模型专区',
 'settings-llm-features':'系统专区 · 功能级模型映射',
 'token-usage':'系统专区 · Token 监控',
 'task-center':'系统专区 · 定时任务专区',
 access:'访问审计'
};
const analyticsTitles = {
 funnel: '数据分析 · 转化漏斗',
 channel: '数据分析 · 渠道分析',
 kol: '数据分析 · 大V协同效能',
 revenue: '数据分析 · 营收趋势',
};
const ADMIN_NAV_STORAGE_KEY = 'gangtise-admin-nav-groups-v1';
const ADMIN_UNIFIED_SETTINGS_REDIRECTS = Object.freeze({
 settings: 'settings-features',
 'settings-appearance': 'settings-features',
 'settings-brand': 'settings-features',
 'settings-policy': 'settings-features',
 'settings-knowledge': 'knowledge-overview',
 'knowledge-items': 'knowledge-intake',
 'settings-knowledge-graph': 'knowledge-graph',
 'settings-llm': 'settings-features',
 'settings-llm-features': 'settings-features',
});
const ADMIN_UNIFIED_SETTINGS_PANEL_MAP = Object.freeze({
 settings: 'theme',
 'settings-appearance': 'theme',
 'settings-brand': 'brand',
 'settings-policy': 'login-access',
 'settings-knowledge': '',
 'knowledge-items': '',
 'settings-knowledge-graph': '',
 'settings-llm': 'llm-models',
 'settings-llm-features': 'llm-feature-map',
});

function normalizeAdminSection(name) {
 const raw = String(name || '').trim();
 if (!raw) return { section: '', panel: '' };
 if (raw === 'indicator-hub') return { section: 'indicator-overview', panel: '' };
 if (ADMIN_UNIFIED_SETTINGS_REDIRECTS[raw]) {
 return {
 section: ADMIN_UNIFIED_SETTINGS_REDIRECTS[raw],
 panel: ADMIN_UNIFIED_SETTINGS_PANEL_MAP[raw] || '',
 };
 }
 return { section: raw, panel: '' };
}

function updateAdminQuery(name) {
 const url = new URL(window.location.href);
 url.searchParams.set('section', name);
 if (name !== 'settings-features') {
 url.searchParams.delete('settings_panel');
 }
 window.history.replaceState({}, '', url);
}

function readAdminNavState() {
 try {
 return JSON.parse(localStorage.getItem(ADMIN_NAV_STORAGE_KEY) || '{}');
 } catch (error) {
 return {};
 }
}

function writeAdminNavState(state) {
 try {
 localStorage.setItem(ADMIN_NAV_STORAGE_KEY, JSON.stringify(state || {}));
 } catch (error) {
 // ignore storage write failures
 }
}

function setAdminNavGroupCollapsed(groupEl, collapsed) {
 if (!groupEl) return;
 groupEl.classList.toggle('is-collapsed', !!collapsed);
 const toggle = groupEl.querySelector('.admin-nav-group-toggle');
 if (toggle) toggle.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
}

function toggleAdminNavGroup(toggleEl) {
 const groupEl = toggleEl ? toggleEl.closest('.admin-nav-group') : null;
 if (!groupEl) return;
 const collapsed = !groupEl.classList.contains('is-collapsed');
 setAdminNavGroupCollapsed(groupEl, collapsed);
 const state = readAdminNavState();
 const key = groupEl.dataset.navGroup;
 if (key) {
 state[key] = collapsed;
 writeAdminNavState(state);
 }
}

function initAdminNavGroups() {
 const state = readAdminNavState();
 document.querySelectorAll('.admin-nav-group[data-nav-group]').forEach((groupEl) => {
 const key = groupEl.dataset.navGroup;
 const collapsed = !!state[key];
 setAdminNavGroupCollapsed(groupEl, collapsed);
 });
}

function setActiveAdminNav(target) {
 document.querySelectorAll('.admin-nav-item').forEach(i => i.classList.remove('active'));
 if (!target) return;
 target.classList.add('active');
 const groupEl = target.closest('.admin-nav-group');
 if (!groupEl) return;
 setAdminNavGroupCollapsed(groupEl, false);
 const state = readAdminNavState();
 const key = groupEl.dataset.navGroup;
 if (key) {
 state[key] = false;
 writeAdminNavState(state);
 }
}

function syncAdminSettingsSubmenu(panelKey) {
 const normalized = String(panelKey || '').trim();
 document.querySelectorAll('.admin-settings-menu-btn[data-settings-panel-trigger]').forEach((node) => {
 node.classList.toggle('active', !!normalized && node.dataset.settingsPanelTrigger === normalized);
 });
 document.querySelectorAll('.admin-settings-panel[data-settings-panel]').forEach((node) => {
 node.classList.toggle('active', !!normalized && node.dataset.settingsPanel === normalized);
 });
}

function openAdminSettingsSubmenu(panelKey, options) {
 const normalized = String(panelKey || '').trim() || 'theme';
 syncAdminSettingsSubmenu(normalized);
 if (normalized === 'market-data') loadGangtiseCredentials();
 if (options && options.updateQuery === false) return;
 const url = new URL(window.location.href);
 url.searchParams.set('section', 'settings-features');
 url.searchParams.set('settings_panel', normalized);
 window.history.replaceState({}, '', url);
}

function mountUnifiedSystemSettingsSection(sourceId, targetId) {
 const source = document.getElementById(sourceId);
 const target = document.getElementById(targetId);
 if (!source || !target || source.dataset.unifiedMounted === '1') return;
 const fragment = document.createDocumentFragment();
 Array.from(source.children).forEach((child) => fragment.appendChild(child));
 target.appendChild(fragment);
 source.dataset.unifiedMounted = '1';
}

function mountUnifiedSystemSettings() {
 if (window.__adminUnifiedSystemSettingsMounted) return;
 mountUnifiedSystemSettingsSection('section-settings-appearance', 'settings-panel-theme');
 mountUnifiedSystemSettingsSection('section-settings-brand', 'settings-panel-brand');
 mountUnifiedSystemSettingsSection('section-settings-policy', 'settings-panel-login-access');
 mountUnifiedSystemSettingsSection('section-settings-llm', 'settings-panel-llm-models');
 mountUnifiedSystemSettingsSection('section-settings-llm-features', 'settings-panel-llm-feature-map');
 window.__adminUnifiedSystemSettingsMounted = true;
}

const adminDatabaseReleaseState = { overview: null, pollTimer: null, pendingAction: null, startController: null, startInFlight: false, passwordVerificationInFlight: false };

function databaseReleaseStatusLabel(status) {
 return ({ idle: '空闲', queued: '排队中', running: '执行中', cancelling: '取消中', cancelled: '已取消', succeeded: '已完成', failed: '失败' })[String(status || '')] || '--';
}

function renderAdminDatabaseReleaseTimeline(job) {
 const host = document.getElementById('admin-database-release-timeline');
 if (!host) return;
 const events = Array.isArray((job || {}).events) ? job.events : [];
 if (!events.length) {
 host.innerHTML = '<div style="font-size:12px;color:#C7D7E8;line-height:1.6">等待发布任务创建后显示实时执行轨迹。任务创建后，此区域会持续显示每一个执行步骤与结果。</div>';
 return;
 }
 const eventStyle = {
 active: ['#77B7FF', '执行中'],
 succeeded: ['#7CCF9B', '已完成'],
 failed: ['#FF8278', '失败'],
 cancelled: ['#FFB66E', '已取消'],
 info: ['#C9D8E8', '明细'],
 };
 host.innerHTML = events.map((event) => {
 const style = eventStyle[String(event.status || 'info')] || eventStyle.info;
 const detail = String(event.detail || '');
 const title = String(event.title || '执行明细');
 return `<div style="display:grid;grid-template-columns:76px 10px minmax(0,1fr) auto;gap:8px;align-items:start;padding:8px 0;border-bottom:1px solid rgba(119,183,255,0.14)">
 <div style="font:11px/1.45 ui-monospace,SFMono-Regular,Menlo,monospace;color:#AFC3D8">${escapeHtml(event.at || '--')}</div>
 <span style="width:8px;height:8px;border-radius:50%;background:${style[0]};margin-top:4px"></span>
 <div style="min-width:0"><div style="font-size:12px;font-weight:700;color:#F7FBFF;line-height:1.45">${escapeHtml(title)}</div>${detail && detail !== title ? `<div style="font-size:11px;line-height:1.5;color:#C7D7E8;word-break:break-word;margin-top:2px">${escapeHtml(detail)}</div>` : ''}</div>
 <div style="font-size:11px;color:${style[0]};white-space:nowrap">${style[1]}</div>
 </div>`;
 }).join('');
 host.scrollTop = host.scrollHeight;
}

function renderAdminDatabaseRelease() {
 const data = adminDatabaseReleaseState.overview || {};
 const job = data.job || {};
 const progress = job.progress || {};
 const packageSelect = document.getElementById('admin-database-release-package');
 const targetHost = document.getElementById('admin-database-release-targets');
 const summaryHost = document.getElementById('admin-database-release-summary');
 const cancelButton = document.getElementById('admin-database-release-cancel');
 const stagingButton = document.getElementById('admin-database-release-staging');
 const productionButton = document.getElementById('admin-database-release-production');
 if (!packageSelect || !targetHost || !summaryHost) return;
 renderAdminDatabaseReleaseTimeline(job);
 const currentPackage = packageSelect.value || '__pending__';
 const packages = Array.isArray(data.packages) ? data.packages : [];
 const packageTypeLabel = {schema: '表结构增量', master_data: '主数据增量', data: '业务数据增量'};
 packageSelect.innerHTML = `<option value="__pending__" ${currentPackage === '__pending__' ? 'selected' : ''}>全部剩余增量（推荐，已执行自动跳过）</option><option value="__full__" ${currentPackage === '__full__' ? 'selected' : ''}>当前完整数据库（全量替换，可回滚）</option>${packages.map((item) => `<option value="${escapeAttr(item.id || '')}" ${item.id === currentPackage ? 'selected' : ''}>${escapeHtml(`${item.date || '--'} · ${item.version || '--'} · ${packageTypeLabel[item.type] || '增量包'} · ${item.title || ''}`)}</option>`).join('')}`;
 const targets = Array.isArray(data.targets) ? data.targets : [];
 targetHost.textContent = targets.length ? `已配置发布目标：${targets.map((item) => `${item.label} (${item.host}/${item.database})`).join('；')}` : '暂无可用发布目标，请检查数据库发布环境配置。';
 summaryHost.innerHTML = [
 ['任务状态', databaseReleaseStatusLabel(job.status), job.target ? `${job.operation || 'release'} · ${job.target}` : '尚未执行任务'],
 ['任务编号', job.id || '--', job.started_at || '暂无开始时间'],
 ['返回码', job.returncode == null ? '--' : String(job.returncode), job.finished_at || '等待完成'],
 ['操作授权', data.operation_unlocked ? '已解锁' : '未解锁', data.operation_unlocked ? '当前会话可执行数据库动作' : '执行动作时需要输入操作口令'],
 ['可用增量包', String(packages.length), '按版本顺序执行，已发布包自动跳过'],
 ['本次计划', (job.package_plan || []).length ? `${(job.package_plan || []).length} 个增量包` : (job.operation === 'release' ? '当前完整数据库' : '--'), (job.package_plan || []).map((item) => item.version || item.id).join(' · ') || '选择“全部剩余增量”可自动计算'],
 ['实时进度', Number(progress.total_steps || 0) > 0 ? `${progress.completed_steps || 0} / ${progress.total_steps}` : (job.status === 'running' ? '执行中' : '--'), progress.message || (progress.state === 'queued' ? '等待启动发布进程' : (progress.updated_at || '等待任务日志'))],
 ].map(([label, value, note]) => `<div class="stat-card"><div class="stat-label">${escapeHtml(label)}</div><div class="stat-value">${escapeHtml(value)}</div><div class="stat-change ${['failed', 'cancelled'].includes(job.status) ? '' : 'up'}" style="${['failed', 'cancelled'].includes(job.status) ? 'color:#C43D36' : ''}">${escapeHtml(note)}</div></div>`).join('');
 if (cancelButton) {
 const cancellable = ['queued', 'running'].includes(String(job.status || '')) && job.cancellable !== false;
 cancelButton.hidden = !cancellable;
 cancelButton.disabled = String(job.status || '') === 'cancelling';
 cancelButton.textContent = String(job.status || '') === 'cancelling' ? '正在取消...' : '取消当前任务';
 }
 const releaseBusy = adminDatabaseReleaseState.startInFlight || ['queued', 'running', 'cancelling'].includes(String(job.status || ''));
 [stagingButton, productionButton].filter(Boolean).forEach((button) => { button.disabled = releaseBusy; });
}

async function loadAdminDatabaseRelease(showMessage) {
 const resp = await fetch('/api/admin/database-release/overview');
 const data = await resp.json();
 if (!resp.ok || !data.ok) throw new Error(data.error || 'database_release_overview_failed');
 adminDatabaseReleaseState.overview = data;
 renderAdminDatabaseRelease();
 await loadAdminDatabaseReleaseLog();
 // These panels use remote database connections and may be slow. Do not make
 // release-log polling wait for them.
 loadAdminDatabaseReleaseRollbacks().catch(() => {});
 const status = String((data.job || {}).status || '');
 if (adminDatabaseReleaseState.pollTimer) window.clearTimeout(adminDatabaseReleaseState.pollTimer);
 if (status === 'queued' || status === 'running' || status === 'cancelling') adminDatabaseReleaseState.pollTimer = window.setTimeout(() => loadAdminDatabaseRelease(false).catch(() => {}), 1000);
 if (showMessage) showToast('数据库发布状态已刷新');
}

async function loadAdminDatabaseReleaseLog() {
 const host = document.getElementById('admin-database-release-log');
 if (!host) return;
 try {
 const resp = await fetch('/api/admin/database-release/log', { cache: 'no-store' });
 host.textContent = resp.ok ? await resp.text() : `任务日志读取失败（HTTP ${resp.status}）`;
 host.scrollTop = host.scrollHeight;
 } catch (error) {
 host.textContent = `任务日志读取失败：${error.message || '网络连接不可用'}`;
 }
}

function openAdminDatabaseReleasePasswordModal(pendingAction) {
 adminDatabaseReleaseState.pendingAction = pendingAction;
 const modal = document.getElementById('admin-database-release-password-modal');
 const input = document.getElementById('admin-database-release-password');
 const error = document.getElementById('admin-database-release-password-error');
 if (!modal || !input || !error) return;
 input.value = '';
 error.textContent = '';
 modal.classList.add('show');
 window.setTimeout(() => input.focus(), 0);
}

function closeAdminDatabaseReleasePasswordModal() {
 const modal = document.getElementById('admin-database-release-password-modal');
 if (modal) modal.classList.remove('show');
 adminDatabaseReleaseState.pendingAction = null;
}

async function confirmAdminDatabaseReleasePassword() {
 const input = document.getElementById('admin-database-release-password');
 const error = document.getElementById('admin-database-release-password-error');
 const button = document.getElementById('admin-database-release-password-confirm');
 if (!input || !error || !button || adminDatabaseReleaseState.passwordVerificationInFlight) return;
 const password = input.value || '';
 if (!password) { error.textContent = '请输入操作口令。'; return; }
 button.disabled = true;
 adminDatabaseReleaseState.passwordVerificationInFlight = true;
 error.textContent = '';
 try {
 const resp = await fetch('/api/admin/database-release/unlock', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ password }) });
 const data = await resp.json();
 if (!resp.ok || !data.ok) { error.textContent = data.error === 'database_release_password_invalid' ? '操作口令错误。' : (data.error || '验证失败，请稍后重试。'); return; }
 adminDatabaseReleaseState.overview = { ...(adminDatabaseReleaseState.overview || {}), operation_unlocked: true };
 renderAdminDatabaseRelease();
 const pendingAction = adminDatabaseReleaseState.pendingAction;
 const modal = document.getElementById('admin-database-release-password-modal');
 if (modal) modal.classList.remove('show');
 adminDatabaseReleaseState.pendingAction = null;
 if (typeof pendingAction === 'function') await pendingAction();
 } finally {
 adminDatabaseReleaseState.passwordVerificationInFlight = false;
 button.disabled = false;
 }
}

function handleAdminDatabaseReleaseActionError(data, retryAction) {
 if (data && data.error === 'database_release_password_required') {
 openAdminDatabaseReleasePasswordModal(retryAction);
 return true;
 }
 return false;
}

async function diagnoseAdminDatabaseReleaseStartFailure(target, originalError) {
 const controller = new AbortController();
 const timeout = window.setTimeout(() => controller.abort(), 5000);
 try {
 const resp = await fetch('/api/admin/database-release/overview', { cache: 'no-store', signal: controller.signal });
 const data = await resp.json().catch(() => ({}));
 if (!resp.ok || !data.ok) return `诊断请求返回 HTTP ${resp.status}：${data.error || '无法读取发布状态'}`;
 adminDatabaseReleaseState.overview = data;
 renderAdminDatabaseRelease();
 const job = data.job || {};
 const isTargetJob = job.id && String(job.target || '') === String(target || '');
 if (isTargetJob && ['queued', 'running', 'cancelling'].includes(String(job.status || ''))) {
 await loadAdminDatabaseReleaseLog();
 return `创建请求的页面连接已中断，但后台任务 ${job.id} 已存在，当前状态：${databaseReleaseStatusLabel(job.status)}。日志已切换为后台实时日志。`;
 }
 if (isTargetJob && ['failed', 'cancelled'].includes(String(job.status || ''))) {
 await loadAdminDatabaseReleaseLog();
 return `后台已创建任务 ${job.id}，但任务在启动阶段变为“${databaseReleaseStatusLabel(job.status)}”。请直接查看当前任务日志；服务端异常会显示为具体错误。`;
 }
 return `后台未记录 ${target} 的新任务，说明请求在任务创建前中断。原始错误：${originalError || '网络连接不可用'}。请检查 Flask 服务是否正在热重载或浏览器网络是否断开。`;
 } catch (diagnosticError) {
 const reason = diagnosticError && diagnosticError.name === 'AbortError' ? '诊断接口 5 秒内未响应' : (diagnosticError.message || '诊断接口不可达');
 return `无法连接发布状态接口：${reason}。原始错误：${originalError || '网络连接不可用'}。`;
 } finally {
 window.clearTimeout(timeout);
 }
}

async function startAdminDatabaseRelease(target, skipConfirmation = false, passwordVerified = false) {
 if (adminDatabaseReleaseState.startInFlight) {
 showToast('已有发布请求正在创建，请勿重复提交');
 return;
 }
 const packageSelect = document.getElementById('admin-database-release-package');
 const packageId = packageSelect ? packageSelect.value : '';
 const packageLabel = packageId === '__pending__' ? '全部剩余增量包' : (packageId === '__full__' ? '当前完整数据库' : '选中的数据库增量包');
 const confirmProduction = target === 'production';
 // Every target submission requires an explicit operator confirmation. The
 // server-side unlock still protects the API, but must not silently carry a
 // previous Staging confirmation into a Production submission.
 if (!passwordVerified) {
 if (adminDatabaseReleaseState.pendingAction) {
 showToast('请先完成当前操作口令验证');
 return;
 }
 openAdminDatabaseReleasePasswordModal(() => startAdminDatabaseRelease(target, skipConfirmation, true));
 return;
 }
 if (!skipConfirmation && !window.confirm(`确认向 ${target} 发布${packageLabel}？发布会替换或更新目标数据库。`)) return;
 const button = document.getElementById(`admin-database-release-${target}`);
 const logHost = document.getElementById('admin-database-release-log');
 const cancelButton = document.getElementById('admin-database-release-cancel');
 const originalText = button ? button.textContent : '';
 adminDatabaseReleaseState.startInFlight = true;
 renderAdminDatabaseRelease();
 if (button) { button.disabled = true; button.textContent = '正在创建任务...'; }
 if (cancelButton) { cancelButton.hidden = false; cancelButton.disabled = false; cancelButton.textContent = '取消创建请求'; }
 if (logHost) logHost.textContent = `正在向 ${target} 创建数据库发布任务，请稍候...`;
 let taskCreated = false;
 let creationTimedOut = false;
 const controller = new AbortController();
 const creationTimeout = window.setTimeout(() => {
 creationTimedOut = true;
 controller.abort();
 }, 12000);
 adminDatabaseReleaseState.startController = controller;
 try {
 const resp = await fetch('/api/admin/database-release', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ target, package_id: packageId, confirm_production: confirmProduction }), signal: controller.signal });
 const data = await resp.json().catch(() => ({}));
 if (!resp.ok || !data.ok) {
 if (handleAdminDatabaseReleaseActionError(data, () => startAdminDatabaseRelease(target, true))) return;
 const message = data.detail ? `${data.error || 'database_release_start_failed'}：${data.detail}` : (data.error || `database_release_start_failed (HTTP ${resp.status})`);
 if (logHost) logHost.textContent = `未能创建发布任务：${message}`;
 showToast(`数据库发布未启动：${message}`);
 return;
 }
 taskCreated = true;
 adminDatabaseReleaseState.overview = { ...(adminDatabaseReleaseState.overview || {}), job: data.job || {} };
 renderAdminDatabaseReleaseTimeline(data.job || {});
 const plan = Array.isArray((data.job || {}).package_plan) ? data.job.package_plan : [];
 if (logHost) logHost.textContent = `任务已创建：${target} · ${packageLabel}${plan.length ? `\n计划执行 ${plan.length} 个增量包：${plan.map((item) => item.version || item.id).join(' → ')}` : ''}\n正在连接目标数据库并获取实时日志...`;
 showToast('数据库发布任务已创建');
 try {
 await loadAdminDatabaseRelease(false);
 } catch (refreshError) {
 if (logHost) logHost.textContent += `\n状态刷新暂不可用：${refreshError.message || '网络波动'}。任务已提交，正在自动重试...`;
 window.setTimeout(() => loadAdminDatabaseRelease(false).catch(() => {}), 1000);
 }
 } catch (error) {
 if (error && error.name === 'AbortError') {
 if (creationTimedOut) {
 const diagnosis = await diagnoseAdminDatabaseReleaseStartFailure(target, '创建任务请求超过 12 秒未返回');
 if (logHost) logHost.textContent = `创建数据库发布任务超时（12 秒）。\n\n${diagnosis}`;
 showToast('发布控制器响应超时，已读取诊断状态');
 return;
 }
 if (logHost) logHost.textContent = '已取消等待创建任务，正在读取后台实际任务状态...';
 window.setTimeout(() => loadAdminDatabaseRelease(false).catch(() => {}), 400);
 return;
 }
 const message = error.message || '网络连接不可用';
 if (taskCreated) {
 if (logHost) logHost.textContent += `\n任务已创建，但页面暂时无法刷新：${message}。请保留此页面，系统会自动重试。`;
 showToast('任务已创建，正在重试读取日志');
 } else {
 const diagnosis = await diagnoseAdminDatabaseReleaseStartFailure(target, message);
 if (logHost && !String(logHost.textContent || '').includes('后台实时日志')) logHost.textContent = `未能创建数据库发布任务：${message}\n\n${diagnosis}`;
 showToast(`数据库发布未启动：${message}`);
 }
 } finally {
 window.clearTimeout(creationTimeout);
 if (adminDatabaseReleaseState.startController === controller) adminDatabaseReleaseState.startController = null;
 adminDatabaseReleaseState.startInFlight = false;
 if (button) button.textContent = originalText;
 renderAdminDatabaseRelease();
 }
}

async function cancelAdminDatabaseRelease() {
 const logHost = document.getElementById('admin-database-release-log');
 const cancelButton = document.getElementById('admin-database-release-cancel');
 if (adminDatabaseReleaseState.startController) {
 adminDatabaseReleaseState.startController.abort();
 if (cancelButton) { cancelButton.disabled = true; cancelButton.textContent = '正在取消等待...'; }
 showToast('已取消等待创建任务，正在核对后台状态');
 return;
 }
 const job = ((adminDatabaseReleaseState.overview || {}).job || {});
 if (!job.id || !['queued', 'running'].includes(String(job.status || ''))) {
 if (logHost) logHost.textContent = '当前没有可取消的数据库任务。';
 if (cancelButton) cancelButton.hidden = true;
 return;
 }
 if (!window.confirm(`确认取消 ${job.target || '当前'} 的数据库任务 ${job.id}？已完成的增量包不会自动回退。`)) return;
 if (cancelButton) { cancelButton.disabled = true; cancelButton.textContent = '正在取消...'; }
 try {
 const resp = await fetch('/api/admin/database-release/cancel', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ job_id: job.id }) });
 const data = await resp.json().catch(() => ({}));
 if (!resp.ok || !data.ok) {
 if (handleAdminDatabaseReleaseActionError(data, () => cancelAdminDatabaseRelease())) return;
 throw new Error(data.error || `database_release_cancel_failed (HTTP ${resp.status})`);
 }
 if (logHost) logHost.textContent = `已发出取消请求：${job.id}\n正在终止发布进程并等待最终状态...`;
 showToast('已发出取消请求');
 await loadAdminDatabaseRelease(false);
 } catch (error) {
 if (logHost) logHost.textContent = `取消任务失败：${error.message || '网络连接不可用'}`;
 showToast(`取消任务失败：${error.message || '网络连接不可用'}`);
 } finally {
 if (cancelButton) cancelButton.disabled = false;
 }
}

async function loadAdminDatabaseReleaseRollbacks() {
 const host = document.getElementById('admin-database-release-rollbacks');
 const targets = ((adminDatabaseReleaseState.overview || {}).targets || []);
 if (!host) return;
 if (!targets.length) { host.textContent = '暂无可读取的回滚目标。'; return; }
 const rows = await Promise.all(targets.map(async (target) => {
 try {
 const resp = await fetch(`/api/admin/database-release/rollbacks?target=${encodeURIComponent(target.name || '')}`);
 const data = await resp.json();
 return { target, records: resp.ok && data.ok ? (data.records || []) : [], error: data.error || '' };
 } catch (error) { return { target, records: [], error: error.message || '读取失败' }; }
 }));
 host.innerHTML = rows.map(({ target, records, error }) => `<div style="padding:10px 0;border-top:1px solid rgba(200,169,110,0.1)"><div style="font-weight:600;color:var(--text-main);margin-bottom:6px">${escapeHtml(target.label || target.name || '--')}</div>${error ? `<div style="color:#E74C3C">${escapeHtml(error)}</div>` : (records.length ? records.map((record) => `<div style="display:flex;justify-content:space-between;gap:10px;align-items:center;margin:6px 0"><span style="font-family:ui-monospace,SFMono-Regular,Menlo,monospace">${escapeHtml(record.name || '--')} · ${escapeHtml(record.size || '--')}</span><button class="btn-outline" style="padding:4px 9px;font-size:11px" onclick="startAdminDatabaseRollback('${escapeAttr(target.name || '')}','${escapeAttr(record.name || '')}')">回滚</button></div>`).join('') : '<div style="color:#8899aa">暂无可用回滚记录</div>')}</div>`).join('');
}

async function startAdminDatabaseRollback(target, backupName, skipConfirmation = false) {
 const confirmProduction = target === 'production';
 if (!skipConfirmation && !window.confirm(`确认将 ${target} 回滚到 ${backupName}？当前数据库会保留为新的回滚点。`)) return;
 const resp = await fetch('/api/admin/database-release/rollback', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ target, backup_name: backupName, confirm_production: confirmProduction }) });
 const data = await resp.json();
 if (!resp.ok || !data.ok) {
 if (handleAdminDatabaseReleaseActionError(data, () => startAdminDatabaseRollback(target, backupName, true))) return;
 throw new Error(data.error || 'database_rollback_start_failed');
 }
 showToast('数据库回滚任务已创建');
 await loadAdminDatabaseRelease(false);
}

function adminSegmentRoleLabel(role) {
 return ({ investor: '粉丝用户', dav: '大V投顾', admin: '平台管理员' })[String(role || '').toLowerCase()] || '未标注角色';
}

function renderAdminUserSegments(payload) {
 const host = document.getElementById('section-segments');
 if (!host) return;
 host.classList.add('segment-bs-shell', 'container-fluid');
 const data = payload || {};
 const summary = data.summary || {};
 const roles = Array.isArray(data.roles) ? data.roles : [];
 const tenants = Array.isArray(data.tenants) ? data.tenants : [];
 const sources = Array.isArray(data.sources) ? data.sources : [];
 const labels = Array.isArray(data.labels) ? data.labels : [];
 const recentUsers = Array.isArray(data.recent_users) ? data.recent_users : [];
 const maxRoleCount = Math.max(...roles.map((item) => Number(item.count || 0)), 1);
 const renderBars = (rows, emptyText) => rows.length ? rows.map((item) => {
 const width = Math.max(4, Math.round((Number(item.count || 0) / Math.max(...rows.map((row) => Number(row.count || 0)), 1)) * 100));
 return `<div style="display:grid;grid-template-columns:minmax(90px,150px) minmax(80px,1fr) 42px;gap:10px;align-items:center;padding:8px 0"><div style="font-size:12px;color:var(--text-main);overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${escapeAttr(item.label || '')}">${escapeHtml(item.label || '未标注')}</div><div style="height:7px;background:rgba(47,116,192,0.10);border-radius:6px;overflow:hidden"><div style="width:${width}%;height:100%;background:#2F74C0;border-radius:6px"></div></div><div style="text-align:right;font:12px ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--text-sub)">${formatAdminNumber(item.count)}</div></div>`;
 }).join('') : `<div style="padding:20px 0;color:#8899aa;font-size:12px">${emptyText}</div>`;
 host.innerHTML = `
 <div class="section-header segment-bs-header">
 <div><div class="section-title">用户分群</div><div class="section-subtitle">按用户主数据实时汇总账号状态、角色、租户、来源、标签与付费样本；不使用虚构的会员等级、ARPU、LTV 或留存率。</div></div>
 <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn-outline" type="button" style="padding:8px 14px;font-size:12px" onclick="loadAdminUserSegments(true)">刷新</button><button class="btn-gold" type="button" style="padding:8px 14px;font-size:12px" onclick="showSection('users')">查看用户列表</button></div>
 </div>
 <div class="segment-bs-kpi-row row">
 ${[['全部账号', summary.total_users, '包含正常与禁用账号'], ['正常账号', summary.active_users, `禁用 ${formatAdminNumber(summary.disabled_users)} 个`], ['粉丝用户', summary.fan_users, `付费样本 ${formatAdminNumber(summary.paid_fans)} 个`], ['已标注用户', summary.labelled_users, '至少拥有一个用户标签']].map(([label, value, note]) => `<div class="stat-card card segment-bs-kpi-card"><div class="stat-label">${label}</div><div class="stat-value">${formatAdminNumber(value)}</div><div class="stat-change up">${note}</div></div>`).join('')}
 </div>
 <div class="segment-bs-grid cols-2">
 <div class="table-wrap segment-bs-panel"><div class="table-header"><div><div class="table-title">角色分群</div><div style="font-size:12px;color:#8899aa;margin-top:6px">正常账号按系统角色统计。</div></div><span class="tag tag-blue">身份</span></div>
 <div style="padding:4px 0">${roles.map((item) => `<div style="padding:12px 0;border-bottom:1px solid rgba(200,169,110,0.10)"><div style="display:flex;justify-content:space-between;gap:12px"><div style="font-size:13px;font-weight:700;color:var(--text-main)">${escapeHtml(item.label)}</div><div style="font:12px ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--text-sub)">${formatAdminNumber(item.count)}</div></div><div style="margin-top:9px;height:7px;background:rgba(47,116,192,0.10);border-radius:6px;overflow:hidden"><div style="width:${Math.max(4, Math.round((Number(item.count || 0) / maxRoleCount) * 100))}%;height:100%;background:#C8A96E;border-radius:6px"></div></div></div>`).join('') || '<div style="padding:20px 0;color:#8899aa;font-size:12px">暂无用户数据</div>'}</div>
 </div>
 <div class="table-wrap segment-bs-panel"><div class="table-header"><div><div class="table-title">标签覆盖</div><div style="font-size:12px;color:#8899aa;margin-top:6px">只统计已写入用户主数据的标签。</div></div><span class="tag tag-gold">标签</span></div><div style="padding:4px 0">${renderBars(labels, '当前没有已标注的用户标签。')}</div></div>
 </div>
 <div class="segment-bs-grid cols-2">
 <div class="table-wrap segment-bs-panel"><div class="table-header"><div><div class="table-title">租户归属</div><div style="font-size:12px;color:#8899aa;margin-top:6px">正常账号按所属租户汇总。</div></div></div><div style="padding:4px 0">${renderBars(tenants, '暂无租户归属数据。')}</div></div>
 <div class="table-wrap segment-bs-panel"><div class="table-header"><div><div class="table-title">来源归因</div><div style="font-size:12px;color:#8899aa;margin-top:6px">来自用户导入、注册或运营录入时的来源字段。</div></div></div><div style="padding:4px 0">${renderBars(sources, '暂无来源字段数据。')}</div></div>
 </div>
 <div class="table-wrap segment-bs-table"><div class="table-header"><div><div class="table-title">最近创建的用户</div><div style="font-size:12px;color:#8899aa;margin-top:6px">便于核对导入、注册与标签写入是否已进入用户主数据。</div></div><div style="font-size:11px;color:#8899aa">更新于 ${escapeHtml(data.generated_at || '--')}</div></div>
 <table><thead><tr><th>用户</th><th>角色</th><th>租户</th><th>来源</th><th>标签 / 付费样本</th><th>状态</th><th>创建时间</th></tr></thead><tbody>${recentUsers.length ? recentUsers.map((item) => `<tr><td>${escapeHtml(item.username)}</td><td>${escapeHtml(adminSegmentRoleLabel(item.role))}</td><td>${escapeHtml(item.tenant_slug || '未归属')}</td><td>${escapeHtml(item.source_label || '未标注来源')}</td><td>${[...(item.labels || []), ...(item.is_paid_sample ? ['付费样本'] : [])].length ? [...(item.labels || []), ...(item.is_paid_sample ? ['付费样本'] : [])].map((label) => `<span class="tag tag-blue" style="margin:0 4px 4px 0">${escapeHtml(label)}</span>`).join('') : '<span style="color:#8899aa">未标注</span>'}</td><td>${escapeHtml(item.status === 'active' ? '正常' : '已禁用')}</td><td>${escapeHtml(item.created_at || '--')}</td></tr>`).join('') : '<tr><td colspan="7" style="text-align:center;color:#8899aa;padding:20px 0">暂无用户主数据</td></tr>'}</tbody></table>
 </div>`;
}

async function loadAdminUserSegments(showMessage) {
 const host = document.getElementById('section-segments');
 if (!host) return;
 host.classList.add('segment-bs-shell', 'container-fluid');
 host.innerHTML = '<div style="padding:36px 0;text-align:center;color:#8899aa;font-size:12px">正在读取用户主数据并生成分群...</div>';
