 <table><thead><tr><th>用户</th><th>角色</th><th>租户</th><th>状态</th><th>创建时间</th></tr></thead><tbody>${recentUsers.length ? recentUsers.map((item) => `<tr><td>${escapeHtml(item.username || '--')}</td><td>${escapeHtml(adminSegmentRoleLabel(item.role))}</td><td>${escapeHtml(item.tenant_slug || '未归属')}</td><td>${escapeHtml(item.status === 'active' ? '正常' : '已禁用')}</td><td>${escapeHtml(item.created_at || '--')}</td></tr>`).join('') : '<tr><td colspan="5" style="text-align:center;color:#8899aa;padding:20px 0">暂无用户主数据</td></tr>'}</tbody></table>
