function adminIndicatorStatusBadge(status) {
 if (status === 'warning') return '<span class="tag tag-red">预警</span>';
 if (status === 'attention') return '<span class="tag tag-gold">关注</span>';
 return '<span class="tag tag-green">正常</span>';
}

function indicatorStatusLabel(status) {
 if (status === 'warning') return '预警';
 if (status === 'attention') return '关注';
 return '正常';
}

function buildAdminInlineChartShell(prefix, height, mountFn) {
 const chartId = window.GangtiseEcharts ? window.GangtiseEcharts.nextId(prefix) : `${prefix}-${Date.now()}`;
 if (window.GangtiseEcharts && typeof mountFn === 'function') {
 window.GangtiseEcharts.enqueue(chartId, mountFn);
 }
 return `<div id="${chartId}" style="width:100%;height:${height};min-height:${height}"></div>`;
}

function buildIndicatorKlineSvg(klinePayload) {
 const candles = Array.isArray(klinePayload?.candles) ? klinePayload.candles : [];
 if (!candles.length) {
 return '<div class="admin-modal-copy">暂无趋势数据。</div>';
 }
 const chartHtml = buildAdminInlineChartShell('admin-indicator-kline', '220px', (element) => {
 window.GangtiseEcharts.render(element, window.GangtiseEcharts.buildKlineOption({
 candles,
 ma5: Array.isArray(klinePayload?.ma5) ? klinePayload.ma5 : [],
 ma10: Array.isArray(klinePayload?.ma10) ? klinePayload.ma10 : [],
 ma20: Array.isArray(klinePayload?.ma20) ? klinePayload.ma20 : [],
 anomalies: Array.isArray(klinePayload?.anomalies) ? klinePayload.anomalies : [],
 }, {
 candleLabel: '指标K线',
 }));
 });
 return `
 <div style="background:var(--navy);border:1px solid rgba(200,169,110,0.08);border-radius:12px;padding:12px">
 <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:8px">
 <div style="font-size:12px;font-weight:700;color:var(--white)">K线走势</div>
 <div style="display:flex;gap:8px;flex-wrap:wrap;font-size:10px;color:var(--gray-400)">
 <span style="display:inline-flex;align-items:center;gap:4px"><span style="width:10px;height:2px;background:#F6C453;display:inline-block"></span>MA5</span>
 <span style="display:inline-flex;align-items:center;gap:4px"><span style="width:10px;height:2px;background:#5DADE2;display:inline-block"></span>MA10</span>
 <span style="display:inline-flex;align-items:center;gap:4px"><span style="width:10px;height:2px;background:#AF7AC5;display:inline-block"></span>MA20</span>
 </div>
 </div>
 ${chartHtml}
 </div>
 `;
}

function buildIndicatorTrendSummary(series) {
 const list = Array.isArray(series) ? series : [];
 if (!list.length) return [];
 return list.map((entry, index) => {
 const numeric = Number(entry.value || 0);
 const previous = index > 0 ? Number(list[index - 1].value || 0) : numeric;
 const delta = Number((numeric - previous).toFixed(2));
 return {
 date: entry.date || '--',
 value: entry.value || '--',
 status: entry.status || 'good',
 delta,
 direction: delta > 0 ? '上行' : delta < 0 ? '下行' : '持平',
 };
 });
}

