 <button class="btn-outline" style="padding:3px 9px;font-size:11px;margin-right:4px" onclick="previewIndicatorSource('${escapeHtml(source.source_code)}')">预览</button>
 <button class="btn-outline" style="padding:3px 9px;font-size:11px;margin-right:4px" onclick="createRawRecord('${escapeHtml(source.source_code)}', false)">蓝图落地</button>
 <button class="btn-outline" style="padding:3px 9px;font-size:11px;margin-right:4px" onclick="createRawRecord('${escapeHtml(source.source_code)}', true)">实时落地</button>
 <button class="btn-outline" style="padding:3px 9px;font-size:11px;margin-right:4px" onclick="openMappingRuleModal('', '${escapeHtml(source.source_code)}', '${escapeHtml(source.indicator_code)}')">映射规则</button>
 <button class="btn-sm-blue" style="padding:3px 9px;font-size:11px" onclick="openIndicatorSourceModal('${escapeHtml(source.source_code)}')">编辑</button>
 </td>
 </tr>
 `).join('') || '<tr><td colspan="8" style="color:#8899aa">暂无 API 定义。</td></tr>';
 }
 if (definitionHost) {
 definitionHost.innerHTML = (adminIndicatorHub.definitions || []).slice(0, 20).map((item) => `
 <tr>
 <td style="color:#F8F6F0;font-weight:600">${escapeHtml(item.indicator_code || '')}</td>
