function adminTaskStatusBadge(status) {
 if (status === 'success') return '<span class="tag tag-green">成功</span>';
 if (status === 'failed') return '<span class="tag tag-red">失败</span>';
 if (status === 'running') return '<span class="tag tag-gold">运行中</span>';
 return `<span class="tag tag-blue">${escapeHtml(status || '--')}</span>`;
}

function renderAdminTaskCenter() {
 const summary = adminTaskCenter.summary || {};
 const groupFilter = String(document.getElementById('task-center-group-filter')?.value || '').trim();
 const statusFilter = String(document.getElementById('task-center-status-filter')?.value || '').trim();
 const setText = (id, value) => {
 const node = document.getElementById(id);
 if (node) node.textContent = String(value ?? 0);
 };
 setText('task-center-total', summary.total || 0);
 setText('task-center-enabled', summary.enabled || 0);
 setText('task-center-running', summary.running || 0);
 setText('task-center-failed', summary.failed || 0);
 const filteredTasks = (adminTaskCenter.tasks || []).filter((task) => {
 if (groupFilter && task.task_group !== groupFilter) return false;
 if (statusFilter && String(task.last_run_status || '') !== statusFilter) return false;
 return true;
 });
 const taskBody = document.getElementById('admin-task-center-tbody');
 if (taskBody) {
 taskBody.innerHTML = filteredTasks.map((task) => `
 <tr>
 <td>
 <div style="color:#F8F6F0;font-weight:600">${escapeHtml(task.task_name || '')}</div>
 <div style="font-size:11px;color:#8899aa;margin-top:4px">${escapeHtml(task.task_code || '')} · ${escapeHtml(task.description || '')}</div>
 </td>
 <td>${escapeHtml(task.task_type || '')}</td>
 <td>${escapeHtml(task.schedule_type || '')}${task.schedule_value ? ` / ${escapeHtml(task.schedule_value)}` : ''}</td>
 <td>${task.enabled ? '<span class="tag tag-green">启用</span>' : '<span class="tag tag-red">关闭</span>'}</td>
 <td>${adminTaskStatusBadge(task.last_run_status || '--')}</td>
 <td>${escapeHtml(task.last_next_run_at || '--')}</td>
 <td style="max-width:220px;color:#8899aa">${escapeHtml(task.last_error_message || '--')}</td>
 <td>
 <button class="btn-outline" style="padding:3px 9px;font-size:11px;margin-right:4px" onclick="openAdminTaskDetail('${escapeHtml(task.task_code || '')}')">详情</button>
 <button class="btn-outline" style="padding:3px 9px;font-size:11px;margin-right:4px" onclick="openAdminTaskEditor('${escapeHtml(task.task_code || '')}')">编辑</button>
 <button class="btn-outline" style="padding:3px 9px;font-size:11px;margin-right:4px" onclick="runAdminTask('${escapeHtml(task.task_code || '')}', false)">执行</button>
 <button class="btn-sm-blue" style="padding:3px 9px;font-size:11px" onclick="runAdminTask('${escapeHtml(task.task_code || '')}', true)">${task.task_code === 'market_snapshot_sync' ? '人工刷新' : '强制刷新'}</button>
 <button class="btn-outline" style="padding:3px 9px;font-size:11px;color:#F3A6A6;border-color:rgba(243,166,166,0.35)" onclick="stopAdminTask('${escapeHtml(task.task_code || '')}')">停止</button>
 </td>
 </tr>
 `).join('') || '<tr><td colspan="8" style="text-align:center;color:#8899aa;padding:20px 0">暂无任务</td></tr>';
 }
 const runBody = document.getElementById('admin-task-run-tbody');
 if (runBody) {
 runBody.innerHTML = (adminTaskCenter.runs || []).map((run) => `
 <tr>
 <td>${escapeHtml(run.started_at || '--')}</td>
 <td style="color:#F8F6F0;font-weight:600">${escapeHtml(run.task_code || '')}</td>
 <td>${escapeHtml(run.trigger_mode || '')}</td>
 <td>${adminTaskStatusBadge(run.run_status || '--')}</td>
 <td>${escapeHtml(String(run.duration_ms || 0))} ms</td>
 <td style="color:#8899aa">${escapeHtml(run.summary || '--')}</td>
 <td style="max-width:260px;color:#8899aa">${escapeHtml(run.error_message || '--')}</td>
 </tr>
 `).join('') || '<tr><td colspan="7" style="text-align:center;color:#8899aa;padding:20px 0">暂无运行记录</td></tr>';
 }
 const userJobBody = document.getElementById('admin-user-job-tbody');
 if (userJobBody) {
 userJobBody.innerHTML = (adminTaskCenter.user_jobs || []).map((job) => `
 <tr>
 <td>${escapeHtml(job.created_at || '--')}</td>
 <td style="color:#F8F6F0;font-weight:600">${escapeHtml(job.job_type || '')}</td>
 <td>${escapeHtml(job.tenant_slug || '--')} / ${escapeHtml(job.entry_point || '--')}</td>
 <td>${adminTaskStatusBadge(job.status || '--')}</td>
 <td>${escapeHtml(job.progress_stage || '--')} / ${escapeHtml(String(job.progress_percent || 0))}%</td>
 <td style="color:#8899aa">${escapeHtml(job.summary || '--')}</td>
 <td style="max-width:260px;color:#8899aa">${escapeHtml(job.error_message || '--')}</td>
 <td>
 <button class="btn-outline" style="padding:3px 9px;font-size:11px;margin-right:4px" onclick="openAdminUserJobDetail('${escapeHtml(job.job_code || '')}')">详情</button>
 <button class="btn-sm-blue" style="padding:3px 9px;font-size:11px" onclick="retryAdminUserJob('${escapeHtml(job.job_code || '')}')">重试</button>
 </td>
 </tr>
 `).join('') || '<tr><td colspan="8" style="text-align:center;color:#8899aa;padding:20px 0">暂无用户异步任务</td></tr>';
 }
}

function applyAdminTaskCenterPayload(data) {
 Object.keys(adminTaskCenter).forEach((key) => delete adminTaskCenter[key]);
 Object.assign(adminTaskCenter, {
 summary: data.summary || {},
 tasks: data.tasks || [],
 runs: data.runs || [],
 runtime: data.runtime || {},
 user_jobs: data.user_jobs || [],
 user_job_runtime: data.user_job_runtime || {},
 });
 renderAdminTaskCenter();
}

function getAdminKnowledgeTenantFilters() {
 return Array.from(document.querySelectorAll('[data-admin-knowledge-tenant-filter]'));
}

function renderAdminKnowledgeTenantFilter() {
 const filters = getAdminKnowledgeTenantFilters();
 const tenants = Array.isArray((adminSiteConfig && adminSiteConfig.tenants)) ? adminSiteConfig.tenants : [];
 const knownSlugs = new Set(tenants.map((tenant) => String(tenant.slug || '').trim()).filter(Boolean));
 if (adminKnowledgeState.tenantFilter && !knownSlugs.has(adminKnowledgeState.tenantFilter)) {
 adminKnowledgeState.tenantFilter = '';
 }
 filters.forEach((select) => {
 select.innerHTML = ['<option value="">全部租户</option>'].concat(
 tenants.map((tenant) => `<option value="${escapeAttr(tenant.slug || '')}">${escapeHtml(tenant.name || tenant.slug || '未命名租户')}</option>`)
 ).join('');
 select.value = adminKnowledgeState.tenantFilter || '';
 if (!select.dataset.bound) {
 select.addEventListener('change', () => {
 adminKnowledgeState.tenantFilter = select.value || '';
 adminKnowledgeMapState.tenantFilter = adminKnowledgeState.tenantFilter;
 getAdminKnowledgeTenantFilters().forEach((item) => {
 item.value = adminKnowledgeState.tenantFilter;
 });
 const activeSection = (document.querySelector('.admin-nav-item.active') && document.querySelector('.admin-nav-item.active').dataset.section) || '';
 if (activeSection === 'knowledge-overview') {
 Promise.all([loadAdminKnowledgeItems(false), loadAdminKnowledgeAssets(false)]).catch((error) => showToast(error.message || '加载失败'));
 return;
 }
 if (activeSection === 'knowledge-encyclopedia') {
 Promise.all([loadAdminKnowledgeItems(false), loadAdminKnowledgeAssets(false)]).catch((error) => showToast(error.message || '加载失败'));
 return;
 }
 if (activeSection === 'knowledge-graph') {
 Promise.all([loadAdminKnowledgeItems(false), loadAdminKnowledgeMap(false)]).catch((error) => showToast(error.message || '加载失败'));
 return;
 }
 loadAdminKnowledgeItems(false).catch((error) => showToast(error.message || '加载失败'));
 });
 select.dataset.bound = '1';
 }
 });
 return adminKnowledgeState.tenantFilter || '';
}

function adminKnowledgeTypeLabel(type) {
 const normalized = String(type || '').trim().toLowerCase();
 if (normalized === 'voice') return '语音资料';
 if (normalized === 'file') return '文件资料';
 if (normalized === 'url') return '网页资料';
 return '手写观点';
}

function renderAdminKnowledgeItems() {
 renderAdminKnowledgeTenantFilter();
 const markup = (adminKnowledgeState.items || []).map((item) => {
 const previewText = truncateText(item.raw_input || item.body || item.summary || '', 120) || '--';
 const createdAt = item.time || (item.vector_record && item.vector_record.created_at) || '--';
 const syncMeta = getAdminKnowledgeSyncMeta(item);
 return `
 <tr>
 <td>${escapeHtml(createdAt)}</td>
 <td>${escapeHtml(item.tenant_name || item.tenant_slug || '--')}</td>
 <td><span class="tag tag-blue">${escapeHtml(item.type || '--')}</span></td>
 <td style="color:#F8F6F0;font-weight:600">${escapeHtml(item.title || '--')}</td>
 <td style="color:#8899aa">${escapeHtml(item.source_detail || item.source || '--')} · ${escapeHtml(syncMeta.label)} · ${escapeHtml(syncMeta.target)}${syncMeta.queuedAt ? ` · 入队 ${escapeHtml(syncMeta.queuedAt)}` : ''}${syncMeta.syncedAt && syncMeta.label === '已同步' ? ` · 完成 ${escapeHtml(syncMeta.syncedAt)}` : ''}${syncMeta.failedAt ? ` · 失败 ${escapeHtml(syncMeta.failedAt)}` : ''}</td>
 <td style="max-width:360px;color:#8899aa">${escapeHtml(previewText)}</td>
 <td><button class="btn-outline" style="padding:3px 9px;font-size:11px" onclick="openAdminKnowledgeItemDetail('${escapeAttr(item.id || '')}','${escapeAttr(item.tenant_slug || '')}')">详情</button></td>
 </tr>
 `;
 }).join('') || '<tr><td colspan="7" style="text-align:center;color:#8899aa;padding:20px 0">暂无知识内容</td></tr>';
 document.querySelectorAll('[data-admin-knowledge-items-body]').forEach((body) => {
 body.innerHTML = markup;
 });
}

async function loadAdminKnowledgeItems(showMessage = false) {
 const currentTenant = renderAdminKnowledgeTenantFilter();
 const query = new URLSearchParams();
 if (currentTenant) query.set('tenant_slug', currentTenant);
 query.set('limit', '300');
 const res = await fetch(`/api/admin/knowledge-items${query.toString() ? `?${query.toString()}` : ''}`);
 const data = await res.json();
 if (!res.ok || !data.ok) {
 showToast((data && data.error) || '知识内容加载失败');
 return;
 }
 adminKnowledgeState.items = Array.isArray(data.items) ? data.items : [];
 renderAdminKnowledgeItems();
 renderAdminKnowledgeOverview();
 if (showMessage) showToast('知识内容已刷新');
}

function openAdminKnowledgeAssetEntry(entryId, tenantSlug) {
 if (!entryId) return;
 openAdminKnowledgeEncyclopediaDetail(entryId, tenantSlug || '');
}

function renderAdminKnowledgeAssets() {
 const summaryHost = document.getElementById('admin-knowledge-assets-summary');
 const relationHost = document.getElementById('admin-knowledge-assets-relationships');
 const entriesHost = document.getElementById('admin-knowledge-assets-entries');
 const payload = adminKnowledgeAssetState.payload || {};
 const summary = payload.summary || {};
 if (summaryHost) {
 const cards = [
 ['知识词条', summary.entry_count || 0, `已成型 ${summary.ready_count || 0}`],
 ['平均成熟度', summary.avg_maturity_score || 0, '用于衡量可复用度'],
 ['平均关系数', summary.avg_relation_count || 0, '每条知识的关系丰富度'],
 ['主题数', summary.topic_count || 0, `实体 ${summary.entity_count || 0}`],
 ['方法数', summary.method_count || 0, `信号 ${summary.signal_count || 0}`],
 ['来源类型', summary.source_type_count || 0, payload.mode === 'platform' ? `租户 ${summary.tenant_count || 0}` : `平均关键词 ${summary.avg_keyword_count || 0}`],
 ];
 summaryHost.innerHTML = cards.map(([label, value, meta]) => `
 <div class="admin-ka-card">
 <div class="admin-ka-label">${escapeHtml(String(label))}</div>
 <div class="admin-ka-value">${escapeHtml(String(value))}</div>
 <div class="admin-ka-meta">${escapeHtml(String(meta))}</div>
 </div>
 `).join('');
 }
 if (relationHost) {
 const sourceRows = Array.isArray(payload.source_breakdown) ? payload.source_breakdown : [];
 const tenantRows = Array.isArray(payload.tenant_breakdown) ? payload.tenant_breakdown : [];
 const groups = payload.relationship_groups || {};
 const sections = [
 { title: '来源分布', rows: sourceRows, labelKey: 'label', countKey: 'count' },
 ...(payload.mode === 'platform' ? [{ title: '租户分布', rows: tenantRows.slice(0, 6), labelKey: 'label', countKey: 'count' }] : []),
 { title: '高频主题', rows: Array.isArray(groups.topics) ? groups.topics.slice(0, 5) : [], labelKey: 'label', countKey: 'count' },
 { title: '高频实体', rows: Array.isArray(groups.entities) ? groups.entities.slice(0, 5) : [], labelKey: 'label', countKey: 'count' },
 { title: '高频方法', rows: Array.isArray(groups.methods) ? groups.methods.slice(0, 4) : [], labelKey: 'label', countKey: 'count' },
 { title: '高频验证信号', rows: Array.isArray(groups.signals) ? groups.signals.slice(0, 5) : [], labelKey: 'label', countKey: 'count' },
 ];
 relationHost.innerHTML = sections.map((section) => `
 <div class="admin-ka-rel-list">
 <div class="admin-ka-panel-title">${escapeHtml(section.title)}</div>
 ${(section.rows || []).length ? section.rows.map((item) => `
 <div class="admin-ka-rel-item">
 <div class="admin-ka-rel-top">
 <div class="admin-ka-rel-title">${escapeHtml(item[section.labelKey] || '--')}</div>
 <span class="admin-ka-rel-count">${escapeHtml(String(item[section.countKey] || 0))} 条</span>
 </div>
 ${Array.isArray(item.entry_titles) && item.entry_titles.length ? `<div class="admin-ka-meta">${escapeHtml(item.entry_titles.slice(0, 3).join(' / '))}</div>` : ''}
 ${Array.isArray(item.keywords) && item.keywords.length ? `<div class="admin-ka-chip-row">${item.keywords.slice(0, 5).map((keyword) => `<span class="admin-ka-chip">${escapeHtml(keyword)}</span>`).join('')}</div>` : ''}
 </div>
 `).join('') : '<div class="admin-ka-rel-item"><div class="admin-ka-meta">当前还没有形成稳定关系。</div></div>'}
 </div>
 `).join('');
 }
 renderAdminKnowledgeAssetCharts(payload);
 if (entriesHost) {
 const entries = Array.isArray(payload.entries) ? payload.entries.slice(0, 12) : [];
 entriesHost.innerHTML = entries.length ? entries.map((entry) => `
 <button class="admin-knowledge-readable-item" type="button" onclick="openAdminKnowledgeAssetEntry('${escapeAttr(entry.id || '')}','${escapeAttr(entry.tenant_slug || '')}')">
 <div class="admin-ka-entry-top">
 <div>
 <div class="admin-knowledge-readable-item-title">${escapeHtml(entry.title || '未命名知识')}</div>
 <div class="admin-knowledge-readable-item-meta">${escapeHtml(entry.source || '--')} · ${escapeHtml(entry.time || '--')}${entry.tenant_name ? ` · ${escapeHtml(entry.tenant_name)}` : ''}</div>
 </div>
 <span class="admin-ka-maturity tone-${escapeAttr(entry.maturity_tone || 'seed')}">${escapeHtml(entry.maturity_label || '种子')} ${escapeHtml(String(entry.maturity_score || 0))}</span>
 </div>
 <div class="admin-knowledge-readable-item-summary">${escapeHtml(entry.summary || '暂无摘要')}</div>
 <div class="admin-ka-chip-row">
 ${(((entry.relations || {}).topics || []).slice(0, 2)).map((item) => `<span class="admin-ka-chip">${escapeHtml(item)}</span>`).join('')}
 ${(((entry.relations || {}).entities || []).slice(0, 2)).map((item) => `<span class="admin-ka-chip">${escapeHtml(item)}</span>`).join('')}
 ${(((entry.relations || {}).methods || []).slice(0, 1)).map((item) => `<span class="admin-ka-chip">${escapeHtml(item)}</span>`).join('')}
 </div>
 <div class="admin-knowledge-readable-item-foot">点击查看词条详情与治理信息</div>
 </button>
 `).join('') : '<div class="admin-knowledge-readable-item"><div class="admin-knowledge-readable-item-meta">当前还没有可展示的知识词条，请先完成知识录入。</div></div>';
 }
}

function renderAdminKnowledgeAssetEmptyChart(targetId, message) {
 const host = document.getElementById(targetId);
 if (!host) return;
 if (window.GangtiseEcharts) window.GangtiseEcharts.dispose(targetId);
 host.innerHTML = `<div class="admin-ka-rel-item"><div class="admin-ka-meta">${escapeHtml(message || '暂无可视化数据')}</div></div>`;
}

function renderAdminKnowledgeAssetCharts(payload) {
 const section = document.getElementById('section-knowledge-encyclopedia');
 if (!section || section.style.display === 'none' || !window.GangtiseEcharts) return;
 const summary = payload && payload.summary && typeof payload.summary === 'object' ? payload.summary : {};
 const entries = Array.isArray(payload && payload.entries) ? payload.entries : [];
 const groups = payload && payload.relationship_groups && typeof payload.relationship_groups === 'object' ? payload.relationship_groups : {};
 const sourceRows = Array.isArray(payload && payload.source_breakdown) ? payload.source_breakdown : [];
 const tenantRows = Array.isArray(payload && payload.tenant_breakdown) ? payload.tenant_breakdown : [];
 const sourceChartId = 'admin-knowledge-source-chart';
 const maturityChartId = 'admin-knowledge-maturity-chart';
 const hotspotChartId = 'admin-knowledge-hotspot-chart';
 const coverageChartId = 'admin-knowledge-coverage-chart';
 const coverageSubtitle = document.getElementById('admin-knowledge-coverage-subtitle');
 const axis = (overrides) => window.GangtiseEcharts.axisBase(Object.assign({
 axisLabel: { color: '#445468', fontSize: 11 },
 }, overrides || {}));
 const grid = (overrides) => window.GangtiseEcharts.gridBase(Object.assign({
 top: 28,
 left: 18,
 right: 18,
 bottom: 38,
 }, overrides || {}));
 [sourceChartId, maturityChartId, hotspotChartId, coverageChartId].forEach((id) => window.GangtiseEcharts.dispose(id));

 if (sourceRows.length) {
 const topRows = sourceRows.slice(0, 8);
 window.GangtiseEcharts.render(sourceChartId, {
 color: ['#2F74C0'],
 tooltip: window.GangtiseEcharts.tooltipBase((params) => `${params.name}<br>词条：${params.value}`),
 grid: grid({ top: 18, left: 18, right: 18, bottom: 48 }),
 xAxis: {
 ...axis({ splitLine: { show: false } }),
 type: 'category',
 data: topRows.map((item) => item.label || '--'),
 axisLabel: { color: '#445468', fontSize: 11, interval: 0, rotate: topRows.length > 4 ? 20 : 0 },
 },
 yAxis: {
 ...axis({ axisLabel: { color: '#445468', fontSize: 11 } }),
 type: 'value',
 },
 series: [{
 type: 'bar',
 data: topRows.map((item) => Number(item.count || 0)),
 barWidth: 18,
 itemStyle: { color: '#2F74C0', borderRadius: [8, 8, 0, 0] },
 }],
 });
 } else {
 renderAdminKnowledgeAssetEmptyChart(sourceChartId, '当前没有来源分布数据。');
 }

 const maturityRows = (() => {
 const counter = new Map();
 entries.forEach((entry) => {
 const label = String(entry && entry.maturity_label || '未分层').trim() || '未分层';
 counter.set(label, (counter.get(label) || 0) + 1);
 });
 return Array.from(counter.entries()).map(([label, value]) => ({ label, value }));
 })();
 if (maturityRows.length) {
 const colorMap = { '可复用': '#3DAA77', '就绪': '#3DAA77', '成长': '#2F74C0', '成长中': '#2F74C0', '构建': '#C8A96E', '构建中': '#C8A96E', '种子': '#8FA6C4', '未分层': '#D7E3F3' };
 window.GangtiseEcharts.render(maturityChartId, {
 color: maturityRows.map((item) => colorMap[item.label] || '#8FA6C4'),
