 }

 if (payload && payload.mode === 'platform' && tenantRows.length) {
 if (coverageSubtitle) coverageSubtitle.textContent = '按租户观察知识沉淀是否过度集中。';
 const topTenantRows = tenantRows.slice(0, 8);
 window.GangtiseEcharts.render(coverageChartId, {
