 }
 }
}

async function loadAdminKnowledgeAssets(showMessage = false) {
 const tenantSlug = adminKnowledgeState.tenantFilter || renderAdminKnowledgeTenantFilter() || adminKnowledgeMapState.tenantFilter || '';
 adminKnowledgeAssetState.tenantFilter = tenantSlug || '';
 try {
 const query = new URLSearchParams();
 if (tenantSlug) query.set('tenant_slug', tenantSlug);
 const resp = await fetch(`/api/admin/knowledge-assets${query.toString() ? `?${query.toString()}` : ''}`);
 const data = await resp.json();
 if (!resp.ok || !data.ok) throw new Error((data && data.error) || 'knowledge_assets_load_failed');
 adminKnowledgeAssetState.payload = data.assets || {};
 adminKnowledgeAssetState.loaded = true;
 renderAdminKnowledgeAssets();
 renderAdminKnowledgeOverview();
 if (showMessage) showToast('知识资产已刷新');
 } catch (error) {
 adminKnowledgeAssetState.payload = { summary: {}, relationship_groups: {}, source_breakdown: [], tenant_breakdown: [], entries: [] };
 renderAdminKnowledgeAssets();
 renderAdminKnowledgeOverview();
 if (showMessage) showToast(error.message || '知识资产加载失败');
 }
}

function renderAdminKnowledgeOverview() {
 const host = document.getElementById('admin-knowledge-overview-summary');
 if (!host) return;
 const payload = adminKnowledgeAssetState.payload || {};
 const summary = payload.summary || {};
 const latestEntry = (adminKnowledgeState.items || [])[0] || {};
 const cards = [
 ['知识词条', summary.entry_count || 0, `已成型 ${summary.ready_count || 0}`],
 ['平均成熟度', summary.avg_maturity_score || 0, '衡量是否足够稳定可复用'],
 ['主题 / 实体', `${summary.topic_count || 0} / ${summary.entity_count || 0}`, '反映知识是否长出结构'],
 ['最新入库', latestEntry.title || '暂无', latestEntry.summary || '当前还没有最近知识摘要'],
 ];
 host.innerHTML = cards.map(([label, value, note]) => `
 <div class="admin-knowledge-overview-card">
 <div class="admin-knowledge-overview-label">${escapeHtml(String(label))}</div>
 <div class="admin-knowledge-overview-value">${escapeHtml(String(value))}</div>
 <div class="admin-knowledge-overview-note">${escapeHtml(String(note))}</div>
 </div>
 `).join('');
}

