async function refreshAdminKnowledgeIntelligence(showMessage = false) {
 adminKnowledgeState.tenantFilter = adminKnowledgeMapState.tenantFilter || '';
 getAdminKnowledgeTenantFilters().forEach((item) => {
 item.value = adminKnowledgeState.tenantFilter;
 });
 await Promise.all([
 loadAdminKnowledgeItems(false),
 loadAdminKnowledgeAssets(false),
 loadAdminKnowledgeMap(false),
 ]);
 if (showMessage) showToast('知识专区已刷新');
}

function renderAdminKnowledgeMapTenantFilter() {
 const select = document.getElementById('admin-kg-tenant-filter');
 if (!select) return '';
 const tenants = Array.isArray((adminSiteConfig && adminSiteConfig.tenants)) ? adminSiteConfig.tenants : [];
 const knownSlugs = new Set(tenants.map((tenant) => String(tenant.slug || '').trim()).filter(Boolean));
 if (adminKnowledgeMapState.tenantFilter && !knownSlugs.has(adminKnowledgeMapState.tenantFilter)) {
 adminKnowledgeMapState.tenantFilter = '';
 }
 select.innerHTML = ['<option value="">平台总图</option>'].concat(
 tenants.map((tenant) => `<option value="${escapeAttr(tenant.slug || '')}">${escapeHtml(tenant.name || tenant.slug || '未命名租户')}</option>`)
 ).join('');
 select.value = adminKnowledgeMapState.tenantFilter || '';
 if (!select.dataset.bound) {
 select.addEventListener('change', () => {
 adminKnowledgeMapState.tenantFilter = select.value || '';
 adminKnowledgeAssetState.tenantFilter = adminKnowledgeMapState.tenantFilter;
 refreshAdminKnowledgeIntelligence(false).catch((error) => showToast(error.message || '加载失败'));
 });
 select.dataset.bound = '1';
 }
 return adminKnowledgeMapState.tenantFilter || '';
}

function adminKnowledgeMapKindLabel(kind) {
 if (kind === 'root') return '平台根节点';
 if (kind === 'tenant') return '租户';
 if (kind === 'topic') return '主题';
 if (kind === 'entity') return '实体';
 if (kind === 'method') return '方法';
 if (kind === 'claim') return '观点';
 if (kind === 'signal') return '验证信号';
 return '知识节点';
}

function adminKnowledgeMapNodeWidth(kind) {
 if (kind === 'root') return 176;
 if (kind === 'tenant') return 156;
 if (kind === 'claim') return 196;
 if (kind === 'signal') return 136;
 return 144;
}

function handleAdminKnowledgeMapSearch(value) {
 adminKnowledgeMapState.query = String(value || '').trim();
 renderAdminKnowledgeMap();
}

function handleAdminKnowledgeMapTypeChange(value) {
 adminKnowledgeMapState.type = value || 'all';
 renderAdminKnowledgeMap();
}

function adjustAdminKnowledgeMapDepth(delta) {
 const payload = adminKnowledgeMapState.payload || {};
 const maxDepth = Number(payload.max_depth || 5);
 adminKnowledgeMapState.depth = Math.max(2, Math.min(maxDepth, Number(adminKnowledgeMapState.depth || payload.default_depth || 3) + Number(delta || 0)));
 renderAdminKnowledgeMap();
}

function expandAdminKnowledgeMapAll() {
 const payload = adminKnowledgeMapState.payload || {};
 adminKnowledgeMapState.depth = Number(payload.max_depth || 5);
 renderAdminKnowledgeMap();
}

function collapseAdminKnowledgeMap() {
 const payload = adminKnowledgeMapState.payload || {};
 adminKnowledgeMapState.depth = Number(payload.default_depth || 3);
 renderAdminKnowledgeMap();
}

function selectAdminKnowledgeMapNode(nodeId) {
 adminKnowledgeMapState.selectedNodeId = nodeId || '';
 adminKnowledgeMapState.centerNodeId = nodeId || '';
 renderAdminKnowledgeMap();
}

function openAdminKnowledgeMapSource(entryId, tenantSlug) {
 if (!entryId) return;
 openAdminKnowledgeItemDetail(entryId, tenantSlug || '');
}

function getAdminKnowledgeMapNodeRelations(nodeId) {
 const payload = adminKnowledgeMapState.payload || {};
 const nodes = Array.isArray(payload.nodes) ? payload.nodes : [];
 const edges = Array.isArray(payload.edges) ? payload.edges : [];
 const nodeMap = new Map(nodes.map((node) => [node.id, node]));
 const parents = [];
 const children = [];
 edges.forEach((edge) => {
 if (edge.to === nodeId && nodeMap.has(edge.from)) parents.push(nodeMap.get(edge.from));
 if (edge.from === nodeId && nodeMap.has(edge.to)) children.push(nodeMap.get(edge.to));
 });
 return {
 parents: parents.filter(Boolean).slice(0, 8),
 children: children.filter(Boolean).slice(0, 8),
 };
}

function centerAdminKnowledgeMapNode(nodeId, positions) {
 const shell = document.querySelector('.admin-kg-board-shell');
 const point = positions && positions[nodeId];
 if (!shell || !point) return;
 shell.scrollTo({
 left: Math.max(0, Math.round(point.x - shell.clientWidth / 2)),
 top: Math.max(0, Math.round(point.y - shell.clientHeight / 2)),
 behavior: 'smooth',
 });
}

function getAdminKnowledgeMapFilteredPayload() {
 const payload = adminKnowledgeMapState.payload || {};
 const allNodes = Array.isArray(payload.nodes) ? payload.nodes : [];
 const allEdges = Array.isArray(payload.edges) ? payload.edges : [];
 const depth = Math.max(2, Math.min(Number(payload.max_depth || 5), Number(adminKnowledgeMapState.depth || payload.default_depth || 3)));
 const type = adminKnowledgeMapState.type || 'all';
 const query = String(adminKnowledgeMapState.query || '').trim().toLowerCase();
 const depthNodes = allNodes.filter((node) => Number(node.level || 99) <= depth);
 const visibleIds = new Set();
 depthNodes.forEach((node) => {
 if (node.kind !== 'root' && type !== 'all' && node.kind !== type) return;
 const haystack = [
 node.label,
 node.full_label,
 node.summary,
 Array.isArray(node.keywords) ? node.keywords.join(' ') : '',
 ].join(' ').toLowerCase();
 if (query && !haystack.includes(query)) return;
 visibleIds.add(node.id);
 });
 const rootNode = depthNodes.find((node) => node.kind === 'root');
 if (rootNode) visibleIds.add(rootNode.id);
 if (query) {
 allEdges.forEach((edge) => {
 if (visibleIds.has(edge.from) || visibleIds.has(edge.to)) {
 visibleIds.add(edge.from);
 visibleIds.add(edge.to);
 }
 });
 } else if (type !== 'all') {
 allEdges.forEach((edge) => {
 if (visibleIds.has(edge.to)) visibleIds.add(edge.from);
 });
 } else {
 depthNodes.forEach((node) => visibleIds.add(node.id));
 }
 return {
 payload,
 depth,
 nodes: depthNodes.filter((node) => visibleIds.has(node.id)),
 edges: allEdges.filter((edge) => visibleIds.has(edge.from) && visibleIds.has(edge.to)),
 };
}

