 </div>
 <div class="admin-kg-detail-item">
 <div class="admin-kg-detail-item-title">下游节点</div>
 <div class="admin-kg-detail-item-meta">${relations.children.length ? relations.children.map((item) => escapeHtml(item.full_label || item.label || '')).join(' / ') : '当前节点暂无继续展开的下游关系。'}</div>
 </div>
 <div class="admin-kg-detail-item">
 <div class="admin-kg-detail-item-title">来源规模</div>
 <div class="admin-kg-detail-item-meta">当前节点关联 ${Number(node.source_count || sources.length || 0)} 条知识来源。</div>
 </div>
 </div>
 </div>
 <div class="admin-kg-detail-section">
 <div class="admin-kg-detail-section-title">QKV 视角</div>
 <div class="admin-kg-detail-list">
 ${(Array.isArray(qkv.questions) ? qkv.questions : []).slice(0, 2).map((item) => `<div class="admin-kg-detail-item"><div class="admin-kg-detail-item-title">Q</div><div class="admin-kg-detail-item-meta">${escapeHtml(item)}</div></div>`).join('')}
 ${(Array.isArray(qkv.values) ? qkv.values : []).slice(0, 2).map((item) => `<div class="admin-kg-detail-item"><div class="admin-kg-detail-item-title">V</div><div class="admin-kg-detail-item-meta">${escapeHtml(item)}</div></div>`).join('') || '<div class="admin-kg-detail-item"><div class="admin-kg-detail-item-title">V</div><div class="admin-kg-detail-item-meta">当前节点暂无可展示的知识值。</div></div>'}
 </div>
 </div>
 <div class="admin-kg-detail-section">
 <div class="admin-kg-detail-section-title">来源证据</div>
 <div class="admin-kg-detail-list">
 ${sources.length ? sources.slice(0, 6).map((entry) => `
 <div class="admin-kg-detail-item">
 <div class="admin-kg-detail-item-title">${escapeHtml(entry.title || '知识条目')}</div>
 <div class="admin-kg-detail-item-meta">${escapeHtml(entry.summary || '暂无摘要')}${entry.time ? ` · ${escapeHtml(entry.time)}` : ''}${entry.tenant_name ? ` · ${escapeHtml(entry.tenant_name)}` : ''}</div>
 <div class="modal-actions" style="margin-top:8px;justify-content:flex-start">
 <button class="btn-outline" type="button" onclick="openAdminKnowledgeMapSource('${escapeAttr(entry.id || '')}','${escapeAttr(entry.tenant_slug || '')}')">查看知识详情</button>
 </div>
 </div>
 `).join('') : '<div class="admin-kg-detail-item"><div class="admin-kg-detail-item-meta">当前节点暂无来源证据。</div></div>'}
 </div>
 </div>
 `;
}

function renderAdminKnowledgeMap() {
 const board = document.getElementById('admin-kg-board');
 const stage = document.getElementById('admin-kg-stage');
 const stats = document.getElementById('admin-kg-stats');
 const legend = document.getElementById('admin-kg-legend');
 if (!board || !stage || !stats || !legend) return;
 if (!adminKnowledgeMapState.payload) {
 board.innerHTML = '<div class="admin-kg-detail-empty" style="min-height:760px;background:transparent;color:#C6D3E2">知识图谱尚未加载。</div>';
 renderAdminKnowledgeMapDetail(null);
 return;
 }
 const filtered = getAdminKnowledgeMapFilteredPayload();
 const payload = filtered.payload;
 const maxDepth = Number(payload.max_depth || 5);
 adminKnowledgeMapState.depth = filtered.depth;
 adminKnowledgeMapState.defaultDepth = Number(payload.default_depth || 3);
 stage.textContent = `当前显示 ${filtered.depth} 层 / 共 ${maxDepth} 层。平台总图默认只看租户与知识主题，继续展开后才进入观点和验证信号。`;
 const statPayload = payload.stats || {};
 stats.innerHTML = `
 <div class="admin-kg-stat"><div class="admin-kg-stat-label">租户</div><div class="admin-kg-stat-value">${statPayload.tenant_count || 0}</div></div>
 <div class="admin-kg-stat"><div class="admin-kg-stat-label">知识条目</div><div class="admin-kg-stat-value">${statPayload.artifact_count || 0}</div></div>
 <div class="admin-kg-stat"><div class="admin-kg-stat-label">主题</div><div class="admin-kg-stat-value">${statPayload.topic_count || 0}</div></div>
 <div class="admin-kg-stat"><div class="admin-kg-stat-label">实体</div><div class="admin-kg-stat-value">${statPayload.entity_count || 0}</div></div>
 <div class="admin-kg-stat"><div class="admin-kg-stat-label">观点</div><div class="admin-kg-stat-value">${statPayload.claim_count || 0}</div></div>
 <div class="admin-kg-stat"><div class="admin-kg-stat-label">验证信号</div><div class="admin-kg-stat-value">${statPayload.signal_count || 0}</div></div>
 `;
 legend.innerHTML = [
 ['root', '平台根节点'],
 ['tenant', '租户'],
 ['topic', '主题'],
 ['entity', '实体'],
 ['method', '方法'],
 ['claim', '观点'],
 ['signal', '验证信号'],
 ].map(([kind, label]) => `<span class="admin-kg-legend-chip"><span class="admin-kg-legend-dot kind-${kind}"></span>${escapeHtml(label)}</span>`).join('');
 if (!filtered.nodes.length) {
 board.innerHTML = '<div class="admin-kg-detail-empty" style="min-height:760px;background:transparent;color:#C6D3E2">当前没有匹配的知识对象。可以清空搜索词，或先补充结构化知识内容。</div>';
 renderAdminKnowledgeMapDetail(null);
 return;
 }
 const shell = document.querySelector('.admin-kg-board-shell');
 const groups = {};
 filtered.nodes.forEach((node) => {
 const level = Number(node.level || 1);
 if (!groups[level]) groups[level] = [];
 groups[level].push(node);
 });
 Object.keys(groups).forEach((key) => groups[key].sort((a, b) => String(a.label || '').localeCompare(String(b.label || ''), 'zh-Hans-CN')));
 const levelList = Object.keys(groups).map(Number).sort((a, b) => a - b);
 const perRing = 20;
 const baseRadius = 150;
 const levelGap = 118;
 const ringGap = 60;
 let maxRadius = 0;
 levelList.forEach((level) => {
 if (level <= 1) return;
 const groupSize = (groups[level] || []).length;
 const ringIndex = Math.max(0, Math.ceil(groupSize / perRing) - 1);
 maxRadius = Math.max(maxRadius, baseRadius + (level - 2) * levelGap + ringIndex * ringGap);
 });
 const viewportWidth = Math.max(1180, shell ? shell.clientWidth : 1180);
 const viewportHeight = Math.max(760, shell ? shell.clientHeight : 760);
 const width = Math.max(viewportWidth, maxRadius * 2 + 420);
 const height = Math.max(viewportHeight, maxRadius * 2 + 340);
 const centerX = width / 2;
 const centerY = height / 2;
 const positions = {};
 levelList.forEach((level) => {
 const group = groups[level] || [];
 if (level === 1) {
 if (group[0]) positions[group[0].id] = { x: centerX, y: centerY };
 return;
 }
 group.forEach((node, index) => {
 const ringIndex = Math.floor(index / perRing);
 const ringRadius = baseRadius + (level - 2) * levelGap + ringIndex * ringGap;
 const ringSize = Math.min(perRing, Math.max(group.length - ringIndex * perRing, 1));
 const angle = ((index % perRing) / ringSize) * Math.PI * 2 - Math.PI / 2;
 positions[node.id] = {
 x: centerX + Math.cos(angle) * ringRadius,
 y: centerY + Math.sin(angle) * ringRadius,
 };
 });
 });
 const nodeMap = new Map(filtered.nodes.map((node) => [node.id, node]));
 const edgeMarkup = filtered.edges.map((edge) => {
 const from = positions[edge.from];
 const to = positions[edge.to];
 if (!from || !to) return '';
 return `<line class="admin-kg-edge" x1="${Math.round(from.x)}" y1="${Math.round(from.y)}" x2="${Math.round(to.x)}" y2="${Math.round(to.y)}"></line>`;
 }).join('');
 board.innerHTML = `
 <svg class="admin-kg-svg" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none">${edgeMarkup}</svg>
 ${filtered.nodes.map((node) => {
 const pos = positions[node.id] || { x: centerX, y: centerY };
 return `
 <button
 type="button"
 class="admin-kg-node kind-${escapeAttr(node.kind || 'topic')}${adminKnowledgeMapState.selectedNodeId === node.id ? ' is-active' : ''}"
 style="left:${Math.round(pos.x)}px;top:${Math.round(pos.y)}px;width:${adminKnowledgeMapNodeWidth(node.kind)}px"
 data-node-id="${escapeAttr(node.id || '')}"
 >
 <div class="admin-kg-node-kind">${escapeHtml(adminKnowledgeMapKindLabel(node.kind || ''))}</div>
 <div class="admin-kg-node-label">${escapeHtml(node.full_label || node.label || '')}</div>
 </button>
 `;
 }).join('')}
 `;
 board.style.width = `${Math.round(width)}px`;
 board.style.height = `${Math.round(height)}px`;
 Array.from(board.querySelectorAll('[data-node-id]')).forEach((nodeEl) => {
 nodeEl.addEventListener('click', () => selectAdminKnowledgeMapNode(nodeEl.getAttribute('data-node-id') || ''));
 });
 const activeNode = nodeMap.get(adminKnowledgeMapState.selectedNodeId) || filtered.nodes.find((node) => node.kind === 'root') || filtered.nodes[0];
 adminKnowledgeMapState.selectedNodeId = activeNode ? activeNode.id : '';
 renderAdminKnowledgeMapDetail(activeNode || null);
 const centerTarget = adminKnowledgeMapState.centerNodeId || '';
 if (centerTarget && positions[centerTarget]) centerAdminKnowledgeMapNode(centerTarget, positions);
 adminKnowledgeMapState.centerNodeId = '';
}

async function loadAdminKnowledgeMap(showMessage = false) {
 renderAdminKnowledgeMapTenantFilter();
 const stage = document.getElementById('admin-kg-stage');
 if (stage) stage.textContent = '正在加载知识图谱…';
 try {
 const tenantSlug = renderAdminKnowledgeMapTenantFilter();
 const query = new URLSearchParams();
 if (tenantSlug) query.set('tenant_slug', tenantSlug);
 const resp = await fetch(`/api/admin/knowledge-graph${query.toString() ? `?${query.toString()}` : ''}`);
 const data = await resp.json();
 if (!resp.ok || !data.ok) throw new Error((data && data.error) || 'knowledge_graph_load_failed');
 adminKnowledgeMapState.payload = data.graph || {};
 adminKnowledgeMapState.depth = Number((data.graph && data.graph.default_depth) || 3);
 adminKnowledgeMapState.defaultDepth = Number((data.graph && data.graph.default_depth) || 3);
 if (!adminKnowledgeMapState.selectedNodeId) {
 adminKnowledgeMapState.selectedNodeId = String((data.graph && data.graph.root_id) || '');
 adminKnowledgeMapState.centerNodeId = adminKnowledgeMapState.selectedNodeId;
 }
 renderAdminKnowledgeMap();
 if (showMessage) showToast('知识图谱已刷新');
 } catch (error) {
 if (stage) stage.textContent = '知识图谱加载失败，当前无法展示。';
 const board = document.getElementById('admin-kg-board');
 if (board) board.innerHTML = '<div class="admin-kg-detail-empty" style="min-height:760px;background:transparent;color:#C6D3E2">知识图谱加载失败。请稍后重试，或先检查知识条目是否已成功同步。</div>';
 renderAdminKnowledgeMapDetail(null);
 showToast(error.message || '知识图谱加载失败');
 }
}

function applyAdminTokenUsagePayload(data) {
 Object.keys(adminTokenUsage).forEach((key) => delete adminTokenUsage[key]);
 Object.assign(adminTokenUsage, {
 summary_24h: data.summary_24h || {request_count: 0, input_tokens: 0, output_tokens: 0, total_tokens: 0, avg_tokens_per_request: 0, avg_latency_ms: 0, total_latency_ms: 0, total_latency_seconds: 0, avg_total_tokens_per_second: 0, avg_input_tokens_per_second: 0, avg_output_tokens_per_second: 0, p95_latency_ms: 0, max_latency_ms: 0},
 summary_30d: data.summary_30d || {request_count: 0, input_tokens: 0, output_tokens: 0, total_tokens: 0, avg_tokens_per_request: 0, avg_latency_ms: 0, total_latency_ms: 0, total_latency_seconds: 0, avg_total_tokens_per_second: 0, avg_input_tokens_per_second: 0, avg_output_tokens_per_second: 0, p95_latency_ms: 0, max_latency_ms: 0},
 hourly: Array.isArray(data.hourly) ? data.hourly : [],
 daily: Array.isArray(data.daily) ? data.daily : [],
 monthly: Array.isArray(data.monthly) ? data.monthly : [],
 features: Array.isArray(data.features) ? data.features : [],
 models: Array.isArray(data.models) ? data.models : [],
 model_daily: Array.isArray(data.model_daily) ? data.model_daily : [],
 recent_logs: Array.isArray(data.recent_logs) ? data.recent_logs : [],
 generated_at: data.generated_at || '',
 });
}

function renderAdminTokenSummary() {
 const s24 = adminTokenUsage.summary_24h || {};
 const s30 = adminTokenUsage.summary_30d || {};
 const totalNode = document.getElementById('token-summary-24h-total');
 const inputNode = document.getElementById('token-summary-24h-input');
 const outputNode = document.getElementById('token-summary-24h-output');
 const requestNode = document.getElementById('token-summary-30d-requests');
 const avgLatencyNode = document.getElementById('token-summary-24h-avg-latency');
 const p95LatencyNode = document.getElementById('token-summary-24h-p95');
 const maxLatencyNode = document.getElementById('token-summary-24h-max-latency');
 const avgThroughputNode = document.getElementById('token-summary-24h-avg-throughput');
 const outputThroughputNode = document.getElementById('token-summary-24h-output-throughput');
 const totalLatencyNode = document.getElementById('token-summary-30d-total-latency');
 const monthThroughputNode = document.getElementById('token-summary-30d-avg-throughput');
 if (totalNode) totalNode.textContent = formatAdminNumber(s24.total_tokens || 0);
 if (inputNode) inputNode.textContent = formatAdminNumber(s24.input_tokens || 0);
 if (outputNode) outputNode.textContent = formatAdminNumber(s24.output_tokens || 0);
 if (requestNode) requestNode.textContent = formatAdminNumber(s30.request_count || 0);
 if (avgLatencyNode) avgLatencyNode.textContent = `${formatAdminNumber(s24.avg_latency_ms || 0)} ms`;
 if (p95LatencyNode) p95LatencyNode.textContent = `${formatAdminNumber(s24.p95_latency_ms || 0)} ms`;
 if (maxLatencyNode) maxLatencyNode.textContent = `峰值 ${formatAdminNumber(s24.max_latency_ms || 0)} ms`;
 if (avgThroughputNode) avgThroughputNode.textContent = `${formatAdminMetric(s24.avg_total_tokens_per_second || 0)} token/s`;
 if (outputThroughputNode) outputThroughputNode.textContent = `输出 ${formatAdminMetric(s24.avg_output_tokens_per_second || 0)} token/s`;
 if (totalLatencyNode) totalLatencyNode.textContent = `${formatAdminNumber(s30.total_latency_seconds || 0)} s`;
 if (monthThroughputNode) monthThroughputNode.textContent = `均速 ${formatAdminMetric(s30.avg_total_tokens_per_second || 0)} token/s`;
}

