 { name: '请求数', type: 'bar', yAxisIndex: 1, barWidth: '38%', itemStyle: { color: 'rgba(31,73,125,0.78)', borderRadius: [8, 8, 0, 0] }, data: (adminTokenUsage.daily || []).map((item) => item.request_count || 0) },
 ],
