function renderAdminTokenUsage() {
 renderAdminTokenSummary();
 renderAdminTokenTables();
 renderAdminTokenCharts();
}

async function refreshAdminTokenUsage(showMessage = true) {
 const resp = await fetch('/api/admin/token-usage');
 const data = await resp.json();
 if (!resp.ok || !data.ok) throw new Error((data && data.error) || 'token_usage_failed');
 applyAdminTokenUsagePayload(data);
 renderAdminTokenUsage();
 if (showMessage !== false) showToast('Token 监控已刷新');
}

function openAdminKnowledgeItemDetail(itemId, tenantSlug) {
 const item = (adminKnowledgeState.items || []).find((entry) => entry.id === itemId && (!tenantSlug || entry.tenant_slug === tenantSlug))
 || (adminKnowledgeState.items || []).find((entry) => entry.id === itemId);
 const host = document.getElementById('admin-task-modal-content');
 const modal = document.getElementById('admin-task-modal');
 if (!item || !host || !modal) {
 showToast('未找到知识详情');
 return;
 }
 const parseMetaJson = item.parse_meta ? JSON.stringify(item.parse_meta, null, 2) : '';
 const syncMeta = getAdminKnowledgeSyncMeta(item);
 host.innerHTML = `
 <div class="admin-modal-head">
 <div>
 <div class="admin-modal-title">知识原始内容详情</div>
 <div class="admin-modal-subtitle">${escapeHtml(item.title || '')} · ${escapeHtml(item.tenant_name || item.tenant_slug || '')}</div>
 </div>
 <button class="admin-modal-close" type="button" onclick="closeAdminTaskModal()">×</button>
 </div>
 <div class="admin-modal-grid">
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">基础信息</div>
 <div class="admin-modal-list">
 <div class="admin-modal-item"><div class="admin-modal-item-top"><strong>类型</strong><span class="tag tag-blue">${escapeHtml(item.type || '--')}</span></div><div class="admin-modal-copy">${escapeHtml(item.source_detail || item.source || '--')}</div></div>
 <div class="admin-modal-item"><div class="admin-modal-item-top"><strong>URL / 文件 / 语音</strong><span class="tag tag-gold">${escapeHtml(item.voice_minutes ? `${item.voice_minutes} 分钟` : '原始来源')}</span></div><div class="admin-modal-copy">${escapeHtml(item.url || (Array.isArray(item.files) ? item.files.join(' / ') : '') || '无 URL / 文件信息')}</div></div>
 <div class="admin-modal-item"><div class="admin-modal-item-top"><strong>同步状态</strong><span class="tag tag-blue">${escapeHtml(syncMeta.label || '--')}</span></div><div class="admin-modal-copy">${escapeHtml(syncMeta.detail || `同步去向：${syncMeta.target || '知识专区'}`)}${syncMeta.queuedAt ? ` · 入队 ${escapeHtml(syncMeta.queuedAt)}` : ''}${syncMeta.syncedAt && syncMeta.label === '已同步' ? ` · 完成 ${escapeHtml(syncMeta.syncedAt)}` : ''}${syncMeta.failedAt ? ` · 失败 ${escapeHtml(syncMeta.failedAt)}` : ''}</div></div>
 <div class="admin-modal-item"><div class="admin-modal-item-top"><strong>摘要</strong><span class="tag tag-blue">${escapeHtml(syncMeta.target || '知识专区')}</span></div><div class="admin-modal-copy">${escapeHtml(item.summary || '暂无摘要')}</div></div>
 </div>
 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">原始输入</div>
 <pre style="margin:0;white-space:pre-wrap;word-break:break-word;font-size:11px;line-height:1.7;color:#F8F6F0">${escapeHtml(item.raw_input || '暂无原始输入')}</pre>
 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">当前入库正文</div>
 <pre style="margin:0;white-space:pre-wrap;word-break:break-word;font-size:11px;line-height:1.7;color:#F8F6F0">${escapeHtml(item.body || '暂无正文')}</pre>
 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">解析元数据</div>
 <pre style="margin:0;white-space:pre-wrap;word-break:break-word;font-size:11px;line-height:1.7;color:#8899aa">${escapeHtml(parseMetaJson || '暂无解析元数据')}</pre>
 </div>
 </div>
 `;
 modal.classList.add('show');
 if (window.GangtiseEcharts) window.GangtiseEcharts.flush(host);
}

function openAdminUserJobDetail(jobCode) {
 const job = (adminTaskCenter.user_jobs || []).find((item) => item.job_code === jobCode);
 const host = document.getElementById('admin-task-modal-content');
 const modal = document.getElementById('admin-task-modal');
 if (!job || !host || !modal) {
 showToast('未找到任务详情');
 return;
 }
 const parseMeta = job.payload && job.payload.parse_meta ? job.payload.parse_meta : null;
 const parsePreview = Array.isArray(parseMeta) ? parseMeta[0] : parseMeta;
 const extractionModes = Array.isArray(parsePreview?.extraction_modes) ? parsePreview.extraction_modes.join(', ') : '--';
 const parseStats = parsePreview && typeof parsePreview.parse_stats === 'object' ? parsePreview.parse_stats : {};
 const pageSummaries = Array.isArray(parsePreview?.page_summaries) ? parsePreview.page_summaries : [];
 const rawSourceText = String((job.payload && (job.payload.body || job.payload.summary || '')) || '').trim();
 host.innerHTML = `
 <div class="admin-modal-head">
 <div>
 <div class="admin-modal-title">用户异步任务</div>
 <div class="admin-modal-subtitle">${escapeHtml(job.job_code || '')} · ${escapeHtml(job.job_type || '')}</div>
 </div>
 <button class="admin-modal-close" type="button" onclick="closeAdminTaskModal()">×</button>
 </div>
 <div class="admin-modal-grid">
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">当前状态</div>
 <div class="admin-modal-list">
 <div class="admin-modal-item"><div class="admin-modal-item-top"><strong>状态</strong>${adminTaskStatusBadge(job.status || '--')}</div><div class="admin-modal-copy">阶段：${escapeHtml(job.progress_stage || '--')} · 进度：${escapeHtml(String(job.progress_percent || 0))}%</div></div>
 <div class="admin-modal-item"><div class="admin-modal-item-top"><strong>租户 / 入口</strong><span class="tag tag-blue">${escapeHtml(job.tenant_slug || '--')}</span></div><div class="admin-modal-copy">${escapeHtml(job.entry_point || '--')} · owner: ${escapeHtml(job.owner_label || '--')}</div></div>
 <div class="admin-modal-item"><div class="admin-modal-item-top"><strong>异常详情</strong><span class="tag tag-red">${job.error_message ? '有异常' : '无异常'}</span></div><div class="admin-modal-copy">${escapeHtml(job.error_message || '暂无异常')}</div></div>
 </div>
 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">任务载荷</div>
 <pre style="margin:0;white-space:pre-wrap;word-break:break-word;font-size:11px;line-height:1.7;color:#8899aa">${escapeHtml(JSON.stringify(job.payload || {}, null, 2))}</pre>
 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">解析概况</div>
 <div class="admin-modal-list">
 <div class="admin-modal-item"><div class="admin-modal-item-top"><strong>解析方式</strong><span class="tag tag-blue">${escapeHtml(extractionModes)}</span></div><div class="admin-modal-copy">OCR：${parsePreview?.ocr_used ? '是' : '否'} · 页数：${escapeHtml(String(parseStats.pages_processed || 0))}</div></div>
 <div class="admin-modal-item"><div class="admin-modal-item-top"><strong>表格命中</strong><span class="tag tag-gold">${escapeHtml(String(parseStats.tables_found || 0))}</span></div><div class="admin-modal-copy">图片数：${escapeHtml(String(parseStats.images_found || 0))} · OCR 页数：${escapeHtml(String(parseStats.ocr_pages || 0))}</div></div>
 </div>
 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">原始内容</div>
 <pre style="margin:0;white-space:pre-wrap;word-break:break-word;font-size:11px;line-height:1.7;color:#F8F6F0">${escapeHtml(rawSourceText || '暂无原始内容')}</pre>
 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">分页摘要</div>
 <div class="admin-modal-history-list">
 ${pageSummaries.length ? pageSummaries.map((item) => `
 <div class="admin-modal-history-row">
 <div class="admin-modal-history-date">第 ${escapeHtml(String(item.page || '-'))} 页</div>
 <div class="admin-modal-history-text">${escapeHtml(item.summary || '--')}${item.used_ocr ? ' · OCR' : ''}</div>
 <span class="tag ${item.used_ocr ? 'tag-gold' : 'tag-blue'}">${item.used_ocr ? 'OCR' : '文本层'}</span>
 </div>
 `).join('') : '<div class="admin-modal-copy">当前没有分页摘要</div>'}
 </div>
 </div>
 <div class="admin-modal-card" style="grid-column:1 / -1">
 <div class="admin-modal-card-title">执行结果</div>
 <pre style="margin:0;white-space:pre-wrap;word-break:break-word;font-size:11px;line-height:1.7;color:#8899aa">${escapeHtml(JSON.stringify(job.result || {}, null, 2))}</pre>
 </div>
 </div>
 <div style="display:flex;justify-content:flex-end;gap:10px;margin-top:18px">
 <button class="btn-sm-blue" type="button" style="padding:8px 16px;font-size:12px" onclick="retryAdminUserJob('${escapeAttr(job.job_code || '')}')">重试任务</button>
 </div>
 `;
 modal.classList.add('show');
}

async function retryAdminUserJob(jobCode) {
 const res = await fetch(`/api/jobs/${encodeURIComponent(jobCode)}/retry`, {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 });
 const data = await res.json();
 if (!res.ok || !data.ok) {
 showToast((data && data.error) || '用户任务重试失败');
 return;
 }
 await refreshAdminTaskCenter(false);
 showToast(`用户任务 ${jobCode} 已重新排队`);
}

async function refreshAdminTaskCenter(showMessage = true) {
 const res = await fetch('/api/admin/tasks');
 const data = await res.json();
 if (!res.ok || !data.ok) {
 showToast((data && data.error) || '任务中心刷新失败');
 return;
 }
 applyAdminTaskCenterPayload(data);
 if (showMessage) showToast('任务中心已刷新');
}

async function saveAdminTaskConfig(payload) {
 const res = await fetch('/api/admin/tasks', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify(payload),
 });
 const data = await res.json();
 if (!res.ok || !data.ok) {
 showToast((data && data.error) || '任务保存失败');
 return false;
 }
 applyAdminTaskCenterPayload(data);
 showToast('任务配置已保存');
 return true;
}

function closeAdminTaskModal() {
 const modal = document.getElementById('admin-task-modal');
 if (modal) modal.classList.remove('show');
}

function getAdminTaskRunsForTask(taskCode, limit = 6) {
 return (adminTaskCenter.runs || []).filter((item) => item.task_code === taskCode).slice(0, limit);
}

function openAdminTaskEditor(taskCode) {
 const task = (adminTaskCenter.tasks || []).find((item) => item.task_code === taskCode);
 if (!task) {
 showToast('未找到任务');
 return;
 }
 const host = document.getElementById('admin-task-modal-content');
 const modal = document.getElementById('admin-task-modal');
 if (!host || !modal) return;
 const paramsJson = JSON.stringify(task.task_params || {}, null, 2);
 const params = task.task_params || {};
 const structuredFields = (() => {
 if (task.task_type === 'indicator_source_landing') {
 return `
 <div class="config-field"><label>source_code</label><input id="task-edit-source-code" value="${escapeAttr(params.source_code || '')}"></div>
 <div class="toggle-wrap"><span class="toggle-label">prefer_live</span><label class="toggle"><input id="task-edit-prefer-live" type="checkbox" ${params.prefer_live ? 'checked' : ''}><span class="toggle-slider"></span></label></div>
 `;
 }
 if (task.task_type === 'indicator_clean_pipeline') {
 return `
 <div class="config-field"><label>source_code</label><input id="task-edit-source-code" value="${escapeAttr(params.source_code || '')}"></div>
 <div class="config-field"><label>rule_code</label><input id="task-edit-rule-code" value="${escapeAttr(params.rule_code || '')}"></div>
 <div class="config-field"><label>raw_record_id</label><input id="task-edit-raw-record-id" value="${escapeAttr(params.raw_record_id || '')}"></div>
 `;
 }
 if (task.task_type === 'knowledge_manual_sync') {
 return `
 <div class="config-field"><label>tenant_slug</label><input id="task-edit-tenant-slug" value="${escapeAttr(params.tenant_slug || '')}"></div>
 <div class="config-field"><label>title</label><input id="task-edit-title" value="${escapeAttr(params.title || '')}"></div>
 <div class="config-field"><label>summary</label><input id="task-edit-summary" value="${escapeAttr(params.summary || '')}"></div>
 <div class="config-field"><label>body</label><textarea id="task-edit-body" rows="6">${escapeHtml(params.body || '')}</textarea></div>
 `;
 }
 if (task.task_type === 'review_publish_embed') {
 return `
 <div class="config-field"><label>tenant_slug</label><input id="task-edit-tenant-slug" value="${escapeAttr(params.tenant_slug || '')}"></div>
 <div class="config-field"><label>speaker_name</label><input id="task-edit-speaker-name" value="${escapeAttr(params.speaker_name || '')}"></div>
 <div class="config-field"><label>review_period</label><input id="task-edit-review-period" value="${escapeAttr(params.review_period || '')}"></div>
 <div class="config-field"><label>text</label><textarea id="task-edit-text" rows="6">${escapeHtml(params.text || '')}</textarea></div>
 `;
 }
 if (task.task_type === 'knowledge_query_batch') {
 return `
 <div class="config-field"><label>tenant_slug</label><input id="task-edit-tenant-slug" value="${escapeAttr(params.tenant_slug || '')}"></div>
 <div class="config-field"><label>queries（每行一个）</label><textarea id="task-edit-queries" rows="6">${escapeHtml(Array.isArray(params.queries) ? params.queries.join('\n') : (params.queries || ''))}</textarea></div>
 <div class="config-field"><label>limit</label><input id="task-edit-limit" type="number" value="${escapeAttr(String(params.limit || 5))}"></div>
 <div class="toggle-wrap"><span class="toggle-label">submit_to_model</span><label class="toggle"><input id="task-edit-submit-to-model" type="checkbox" ${params.submit_to_model ? 'checked' : ''}><span class="toggle-slider"></span></label></div>
 `;
 }
 return '';
 })();
 host.innerHTML = `
 <div class="admin-modal-head">
 <div>
 <div class="admin-modal-title">编辑任务</div>
 <div class="admin-modal-subtitle">${escapeHtml(task.task_name || '')} · ${escapeHtml(task.task_code || '')}</div>
 </div>
 <button class="admin-modal-close" type="button" onclick="closeAdminTaskModal()">×</button>
 </div>
 <div class="admin-modal-grid">
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">基础配置</div>
 <div class="config-field"><label>任务名称</label><input id="task-edit-name" value="${escapeAttr(task.task_name || '')}"></div>
 <div class="config-field"><label>任务分组</label><input id="task-edit-group" value="${escapeAttr(task.task_group || '')}"></div>
 <div class="config-field"><label>任务类型</label><input id="task-edit-type" value="${escapeAttr(task.task_type || '')}" disabled></div>
 <div class="config-field"><label>任务描述</label><textarea id="task-edit-desc" rows="4">${escapeHtml(task.description || '')}</textarea></div>
 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">调度与参数</div>
 <div class="config-field"><label>调度类型</label><select id="task-edit-schedule-type"><option value="manual" ${task.schedule_type === 'manual' ? 'selected' : ''}>manual</option><option value="interval" ${task.schedule_type === 'interval' ? 'selected' : ''}>interval</option><option value="daily" ${task.schedule_type === 'daily' ? 'selected' : ''}>daily</option></select></div>
 <div class="config-field"><label>调度值</label><input id="task-edit-schedule-value" value="${escapeAttr(task.schedule_value || '')}" placeholder="interval 填秒数；daily 填 10:15,14:15"></div>
 <div class="config-field"><label>超时秒数</label><input id="task-edit-timeout" type="number" value="${escapeAttr(String(task.timeout_seconds || 600))}"></div>
 ${structuredFields}
 <div class="config-field"><label>任务参数 JSON</label><textarea id="task-edit-params" rows="8">${escapeHtml(paramsJson)}</textarea></div>
 <div class="toggle-wrap"><span class="toggle-label">启用任务</span><label class="toggle"><input id="task-edit-enabled" type="checkbox" ${task.enabled ? 'checked' : ''}><span class="toggle-slider"></span></label></div>
 </div>
 </div>
 <div style="display:flex;justify-content:flex-end;gap:10px;margin-top:18px">
 <button class="btn-outline" type="button" style="padding:8px 16px;font-size:12px" onclick="closeAdminTaskModal()">取消</button>
 <button class="btn-gold" type="button" style="padding:8px 16px;font-size:12px" onclick="submitAdminTaskEditor('${escapeAttr(task.task_code || '')}')">保存任务</button>
 </div>
 `;
 modal.classList.add('show');
}

async function submitAdminTaskEditor(taskCode) {
 const task = (adminTaskCenter.tasks || []).find((item) => item.task_code === taskCode);
 let taskParams = {};
 if (task) {
 if (task.task_type === 'indicator_source_landing') {
 taskParams = {
 source_code: document.getElementById('task-edit-source-code')?.value || '',
 prefer_live: Boolean(document.getElementById('task-edit-prefer-live')?.checked),
 };
 } else if (task.task_type === 'indicator_clean_pipeline') {
 taskParams = {
 source_code: document.getElementById('task-edit-source-code')?.value || '',
 rule_code: document.getElementById('task-edit-rule-code')?.value || '',
 raw_record_id: document.getElementById('task-edit-raw-record-id')?.value || '',
 };
 } else if (task.task_type === 'knowledge_manual_sync') {
 taskParams = {
 tenant_slug: document.getElementById('task-edit-tenant-slug')?.value || '',
 title: document.getElementById('task-edit-title')?.value || '',
 summary: document.getElementById('task-edit-summary')?.value || '',
 body: document.getElementById('task-edit-body')?.value || '',
 };
 } else if (task.task_type === 'review_publish_embed') {
 taskParams = {
 tenant_slug: document.getElementById('task-edit-tenant-slug')?.value || '',
 speaker_name: document.getElementById('task-edit-speaker-name')?.value || '',
 review_period: document.getElementById('task-edit-review-period')?.value || '',
 text: document.getElementById('task-edit-text')?.value || '',
 };
 } else if (task.task_type === 'knowledge_query_batch') {
 taskParams = {
 tenant_slug: document.getElementById('task-edit-tenant-slug')?.value || '',
 queries: String(document.getElementById('task-edit-queries')?.value || '').split('\n').map((item) => item.trim()).filter(Boolean),
 limit: Number(document.getElementById('task-edit-limit')?.value || 5),
 submit_to_model: Boolean(document.getElementById('task-edit-submit-to-model')?.checked),
 };
 } else {
 try {
 taskParams = JSON.parse(document.getElementById('task-edit-params')?.value || '{}');
 } catch (error) {
 showToast('任务参数 JSON 格式不正确');
 return;
 }
 }
 }
 const paramsNode = document.getElementById('task-edit-params');
 if (paramsNode) paramsNode.value = JSON.stringify(taskParams, null, 2);
 const saved = await saveAdminTaskConfig({
 task_code: taskCode,
 task_name: document.getElementById('task-edit-name')?.value || taskCode,
 task_group: document.getElementById('task-edit-group')?.value || 'system',
 task_type: document.getElementById('task-edit-type')?.value || '',
 description: document.getElementById('task-edit-desc')?.value || '',
 schedule_type: document.getElementById('task-edit-schedule-type')?.value || 'manual',
 schedule_value: document.getElementById('task-edit-schedule-value')?.value || '',
 enabled: Boolean(document.getElementById('task-edit-enabled')?.checked),
 timeout_seconds: Number(document.getElementById('task-edit-timeout')?.value || 600),
 task_params: taskParams,
 });
 if (saved) closeAdminTaskModal();
}

function openAdminTaskDetail(taskCode) {
 const task = (adminTaskCenter.tasks || []).find((item) => item.task_code === taskCode);
 const host = document.getElementById('admin-task-modal-content');
 const modal = document.getElementById('admin-task-modal');
 if (!task || !host || !modal) {
 showToast('未找到任务详情');
 return;
 }
 const runs = getAdminTaskRunsForTask(taskCode, 8);
 host.innerHTML = `
 <div class="admin-modal-head">
 <div>
 <div class="admin-modal-title">${escapeHtml(task.task_name || '')}</div>
 <div class="admin-modal-subtitle">${escapeHtml(task.task_code || '')} · ${escapeHtml(task.task_group || '')} · ${escapeHtml(task.task_type || '')}</div>
 </div>
 <button class="admin-modal-close" type="button" onclick="closeAdminTaskModal()">×</button>
 </div>
 <div class="admin-modal-grid">
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">当前状态</div>
 <div class="admin-modal-list">
 <div class="admin-modal-item"><div class="admin-modal-item-top"><strong>最近状态</strong>${adminTaskStatusBadge(task.last_run_status || '--')}</div><div class="admin-modal-copy">最近开始：${escapeHtml(task.last_run_started_at || '--')}；最近完成：${escapeHtml(task.last_run_finished_at || '--')}</div></div>
 <div class="admin-modal-item"><div class="admin-modal-item-top"><strong>下次执行</strong><span class="tag tag-blue">${escapeHtml(task.last_next_run_at || '--')}</span></div><div class="admin-modal-copy">调度：${escapeHtml(task.schedule_type || '')} / ${escapeHtml(task.schedule_value || '--')}</div></div>
 <div class="admin-modal-item"><div class="admin-modal-item-top"><strong>最近异常</strong><span class="tag tag-red">${task.last_error_message ? '有异常' : '无异常'}</span></div><div class="admin-modal-copy">${escapeHtml(task.last_error_message || '暂无异常')}</div></div>
 </div>
 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">任务参数</div>
 <pre style="margin:0;white-space:pre-wrap;word-break:break-word;font-size:11px;line-height:1.7;color:#8899aa">${escapeHtml(JSON.stringify(task.task_params || {}, null, 2))}</pre>
 </div>
 <div class="admin-modal-card" style="grid-column:1 / -1">
 <div class="admin-modal-card-title">最近运行记录</div>
 <div class="admin-modal-history-list">
 ${runs.length ? runs.map((run) => `
 <div class="admin-modal-history-row">
 <div class="admin-modal-history-date">${escapeHtml(run.started_at || '--')}</div>
 <div class="admin-modal-history-text">${escapeHtml(run.trigger_mode || '')} · ${escapeHtml(run.summary || '--')} · ${escapeHtml(String(run.duration_ms || 0))} ms${run.error_message ? ` · 错误：${escapeHtml(run.error_message)}` : ''}</div>
 ${adminTaskStatusBadge(run.run_status || '--')}
 </div>
 `).join('') : '<div class="admin-modal-copy">暂无运行记录</div>'}
 </div>
 </div>
 </div>
 <div style="display:flex;justify-content:flex-end;gap:10px;margin-top:18px">
 <button class="btn-outline" type="button" style="padding:8px 16px;font-size:12px" onclick="openAdminTaskEditor('${escapeAttr(task.task_code || '')}')">编辑任务</button>
 <button class="btn-gold" type="button" style="padding:8px 16px;font-size:12px" onclick="runAdminTask('${escapeAttr(task.task_code || '')}', false)">立即执行</button>
 </div>
 `;
 modal.classList.add('show');
}

async function runAdminTask(taskCode, forceRun) {
 const res = await fetch(`/api/admin/tasks/${encodeURIComponent(taskCode)}/run`, {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({force: !!forceRun}),
 });
 const data = await res.json();
 if (!res.ok || !data.ok) {
 showToast((data && data.error) || '任务执行失败');
 return;
 }
 applyAdminTaskCenterPayload(data);
 if (taskCode === 'indicator_prepare' || taskCode === 'indicator_gangtise_openapi_sync' || taskCode === 'indicator_market_cache_sync') {
 await refreshAdminIndicatorHub(false);
 }
 showToast(`任务 ${taskCode} 已执行`);
}

async function stopAdminTask(taskCode) {
 if (!window.confirm(`确认停止任务 ${taskCode} 的自动调度吗？正在执行的行业同步会在当前请求结束后停止后续请求。`)) return;
 const res = await fetch(`/api/admin/tasks/${encodeURIComponent(taskCode)}/stop`, {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 });
 const data = await res.json();
 if (!res.ok || !data.ok) {
 showToast((data && data.error) || '任务停止失败');
 return;
 }
 applyAdminTaskCenterPayload(data);
 showToast(`任务 ${taskCode} 已停止`);
}

async function refreshAdminIndicatorHub(showMessage) {
 const resp = await fetch('/api/admin/indicator-hub');
 const data = await resp.json();
 if (!resp.ok || !data.ok) {
 showToast('指标湖数据刷新失败');
 return;
 }
 Object.keys(adminIndicatorHub).forEach((key) => delete adminIndicatorHub[key]);
 Object.assign(adminIndicatorHub, data.hub || {});
 renderAdminIndicatorHubAll();
 if (showMessage !== false) showToast('指标湖数据已刷新');
}

function renderAdminNewsSources() {
 const host = document.getElementById('admin-news-source-tbody');
 const rows = Array.isArray(adminNewsSources.sources) ? adminNewsSources.sources : [];
 const activeNode = document.getElementById('admin-news-source-active-count');
 const eventNode = document.getElementById('admin-news-source-event-count');
 const cacheNode = document.getElementById('admin-news-source-cache-at');
 if (activeNode) activeNode.textContent = `${Number(adminNewsSources.active_sources || 0)} 个已准入`;
 if (eventNode) eventNode.textContent = `${Number(adminNewsSources.total_events || 0)} 条入湖事件`;
 if (cacheNode) cacheNode.textContent = adminNewsSources.cached_at ? `最近抓取 ${adminNewsSources.cached_at}` : '尚未完成真实抓取';
 if (!host) return;
 host.innerHTML = rows.map((source) => {
 const status = source.last_fetch_included
 ? '<span class="tag tag-green">已入湖</span>'
 : (source.last_fetch_count > 0 ? '<span class="tag tag-gold">待清洗</span>' : '<span class="tag tag-red">待抓取</span>');
 const reason = source.last_fetch_reason || '等待首次抓取';
 return `<tr>
 <td><span style="color:#F8F6F0;font-weight:600">${escapeHtml(source.name || source.code || '--')}</span><div style="font-size:11px;color:#8899aa;margin-top:4px">${escapeHtml(source.code || '')}</div></td>
 <td>${escapeHtml(source.category || '--')}<div style="font-size:11px;color:#8899aa;margin-top:4px">${escapeHtml(source.source_group || '')}</div></td>
 <td style="color:#C8A96E">${escapeHtml(source.indicator_code || '--')}</td>
 <td>${escapeHtml(String(source.admission_count || 0))} 条</td>
 <td>${escapeHtml(String(source.last_fetch_count || 0))} 条</td>
 <td>${status}</td>
 <td style="max-width:340px;color:#8899aa">${escapeHtml(reason)}</td>
 </tr>`;
 }).join('') || '<tr><td colspan="7" style="color:#8899aa">未配置新闻数据源。</td></tr>';
}

async function loadAdminNewsSources(showMessage) {
 const resp = await fetch('/api/admin/news-sources');
 const data = await resp.json();
 if (!resp.ok || !data.ok) throw new Error((data && data.error) || '新闻源加载失败');
 Object.keys(adminNewsSources).forEach((key) => delete adminNewsSources[key]);
 Object.assign(adminNewsSources, data.news_sources || {});
 renderAdminNewsSources();
 if (showMessage) showToast('新闻数据源已加载');
}

async function refreshAdminNewsSources(showMessage) {
 const resp = await fetch('/api/admin/news-sources/refresh', { method: 'POST' });
 const data = await resp.json();
 if (!resp.ok || !data.ok) {
 showToast((data && data.error) || '真实新闻刷新失败');
 return;
 }
 Object.keys(adminNewsSources).forEach((key) => delete adminNewsSources[key]);
 Object.assign(adminNewsSources, data.news_sources || {});
 renderAdminNewsSources();
 if (showMessage !== false) showToast(`已刷新 ${Number(adminNewsSources.total_events || 0)} 条真实新闻事件`);
}

function formatCommissionAmount(value) {
 return `¥${Number(value || 0).toLocaleString('zh-CN', {minimumFractionDigits: 0, maximumFractionDigits: 2})}`;
}

function renderAdminCommission(payload) {
 const data = payload || {};
 const setText = (id, value) => {
 const node = document.getElementById(id);
 if (node) node.textContent = value;
 };
 setText('admin-commission-pending', formatCommissionAmount(data.pending_total));
 setText('admin-commission-settled', formatCommissionAmount(data.settled_total));
 setText('admin-commission-advisor-count', String(data.advisor_count || 0));
 setText('admin-commission-average', formatCommissionAmount(data.average_payable));
 const host = document.getElementById('admin-commission-tbody');
 if (!host) return;
 const rows = Array.isArray(data.rows) ? data.rows : [];
 host.innerHTML = rows.map((row) => `
 <tr>
 <td><input type="checkbox" style="accent-color:#C8A96E" ${row.payable > 0 ? '' : 'disabled'}></td>
 <td style="color:#F8F6F0;font-weight:600">${escapeHtml(row.advisor || '--')}<div style="font-size:11px;color:#8899aa;margin-top:4px">${escapeHtml(row.tenant_name || row.tenant_slug || '')}</div></td>
 <td><span class="tier-s">${escapeHtml(row.tier || '未分层')}</span></td>
 <td>${escapeHtml(row.source || '--')}<div style="font-size:11px;color:#8899aa;margin-top:4px">${Number(row.paid_count || 0)} 位付费用户</div></td>
 <td>${formatCommissionAmount(row.revenue)}<div style="font-size:11px;color:#8899aa;margin-top:4px">单价 ${formatCommissionAmount(row.registration_price)}</div></td>
 <td>${Number(row.share_rate || 0).toFixed(2)}%</td>
 <td style="color:#C8A96E">${formatCommissionAmount(row.payable)}</td>
 <td>${row.status === '待结算' ? '<span class="status-gold">待结算</span>' : '<span class="status-blue">暂无应结算</span>'}</td>
 <td><button class="btn-outline" style="padding:3px 9px;font-size:11px" onclick="showToast('结算流水功能尚未启用，当前仅展示真实应结算估算')">查看口径</button></td>
 </tr>
 `).join('') || '<tr><td colspan="9" style="color:#8899aa">当前没有租户或真实付费数据。</td></tr>';
}

