function renderAdminUsersTable() {
 const body = document.getElementById('admin-user-table-body');
 const meta = document.getElementById('admin-user-table-meta');
 if (!body || !meta) return;
 const search = String(document.getElementById('admin-user-search')?.value || '').trim().toLowerCase();
 const role = String(document.getElementById('admin-user-role-filter')?.value || '').trim();
 const status = String(document.getElementById('admin-user-status-filter')?.value || '').trim();
 const filtered = adminUsers.filter((user) => {
 if (role && user.role !== role) return false;
 if (status && user.status !== status) return false;
 if (!search) return true;
 const corpus = `${user.username} ${user.phone} ${user.advisor_name || ''} ${user.tenant?.name || ''}`.toLowerCase();
 return corpus.includes(search);
 });
 body.innerHTML = filtered.map((user) => `
 <tr>
 <td><span style="color:#F8F6F0;font-weight:500">${escapeHtml(user.username)}</span></td>
 <td><span style="font-size:10px;color:#8899aa">${escapeHtml(user.phone_masked || user.phone || '')}</span></td>
 <td><span class="tag ${user.role === 'admin' ? 'tag-red' : (user.role === 'dav' ? 'tag-gold' : 'tag-blue')}">${escapeHtml(user.role)}</span></td>
 <td>${user.role === 'investor' ? (user.is_paid_sample ? '<span class="tag tag-gold">付费样本</span>' : '<span class="tag tag-blue">普通粉丝</span>') : '<span style="color:#8899aa">--</span>'}</td>
 <td>${escapeHtml(user.source_label || '--')}</td>
 <td>${escapeHtml(user.advisor_name || '--')}</td>
 <td>${escapeHtml(user.tenant?.name || '--')}</td>
 <td><span class="tag ${user.status === 'active' ? 'tag-green' : 'tag-red'}">${escapeHtml(user.status === 'active' ? '正常' : '已禁用')}</span></td>
 <td>${escapeHtml(user.created_at || '--')}</td>
 <td style="white-space:nowrap"><button class="btn-outline" style="padding:3px 9px;font-size:11px;margin-right:4px" onclick="openAdminUserDetail(${Number(user.id || 0)})">详情</button><button class="btn-outline" style="padding:3px 9px;font-size:11px;color:${user.status === 'active' ? '#F2B8B5' : '#9DE0BE'};border-color:${user.status === 'active' ? 'rgba(180,35,24,0.28)' : 'rgba(22,112,74,0.28)'}" onclick="openAdminUserDetail(${Number(user.id || 0)});requestAdminUserStatusChange(${Number(user.id || 0)})">${user.status === 'active' ? '停用' : '启用'}</button></td>
 </tr>
 `).join('') || '<tr><td colspan="10" style="text-align:center;color:#8899aa;padding:20px 0">暂无用户</td></tr>';
 const activeCount = filtered.filter((user) => user.status === 'active').length;
 const disabledCount = filtered.length - activeCount;
 meta.innerHTML = `<span>共 ${filtered.length} 条记录 · 正常 ${activeCount} · 已停用 ${disabledCount}</span><span>状态变更会立即影响登录权限 · 数据来自本地 Postgres 用户表</span>`;
}

