function requestAdminUserStatusChange(userId) {
 const user = adminUsers.find((item) => Number(item.id || 0) === Number(userId || 0));
 const confirmNode = document.getElementById('admin-user-status-confirm');
 if (!user || !confirmNode) return;
 const nextStatus = user.status === 'active' ? 'disabled' : 'active';
 const action = nextStatus === 'disabled' ? '停用' : '启用';
 confirmNode.innerHTML = `<div style="font-size:12px;font-weight:700;color:#F8F6F0">确认${action}“${escapeHtml(user.username || '该账号')}”吗？</div><div style="font-size:11px;color:#8899aa;line-height:1.7;margin-top:5px">${nextStatus === 'disabled' ? '停用后该账号将无法登录 H5、Hermes 或大V工作台，历史数据会保留。' : '启用后该账号可以重新登录，历史数据会保留。'}</div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:10px"><button class="btn-outline" type="button" style="padding:6px 10px;font-size:11px" onclick="cancelAdminUserStatusChange()">取消</button><button class="btn-gold" type="button" style="padding:6px 10px;font-size:11px" onclick="confirmAdminUserStatusChange(${Number(user.id || 0)}, '${nextStatus}')">确认${action}</button></div>`;
 confirmNode.style.display = 'block';
}

function cancelAdminUserStatusChange() {
 const confirmNode = document.getElementById('admin-user-status-confirm');
 if (confirmNode) {
 confirmNode.innerHTML = '';
 confirmNode.style.display = 'none';
 }
}

async function confirmAdminUserStatusChange(userId, status) {
 const confirmNode = document.getElementById('admin-user-status-confirm');
 const buttons = confirmNode ? confirmNode.querySelectorAll('button') : [];
 buttons.forEach((button) => { button.disabled = true; button.style.opacity = '0.6'; });
 try {
 const response = await fetch('/api/admin/users/status', {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify({ user_id: userId, status }),
 });
 const payload = await response.json();
 if (!response.ok || !payload.ok) {
 const messages = {
 cannot_disable_current_user: '不能停用当前登录的管理员账号。',
 cannot_disable_last_admin: '平台至少需要保留一个正常的管理员账号。',
 user_not_found: '未找到该用户。',
 database_unavailable: '数据库当前不可用，请稍后重试。',
 };
 throw new Error(messages[payload.error] || payload.error || '账号状态更新失败');
 }
 adminUsers = Array.isArray(payload.users) ? payload.users : adminUsers;
 renderAdminUsersTable();
 openAdminUserDetail(userId);
 showToast(status === 'disabled' ? '账号已停用' : '账号已启用');
 } catch (error) {
 if (confirmNode) confirmNode.innerHTML = `<div style="font-size:12px;color:#F2B8B5">${escapeHtml(error.message || '账号状态更新失败')}</div>`;
 showToast(error.message || '账号状态更新失败');
 }
}

async function loadAdminUsers() {
 try {
 const res = await fetch('/api/admin/users');
 const data = await res.json();
 adminUsers = Array.isArray(data.users) ? data.users : [];
 renderAdminUsersTable();
 } catch (error) {
 showToast('加载用户列表失败');
 }
}

async function openAdminUserCreator() {
 openAdminUserImportModal('single');
}

function closeAdminUserImportModal() {
 const modal = document.getElementById('admin-user-import-modal');
 if (modal) modal.classList.remove('show');
}

function buildAdminUserImportRow(row = {}) {
 const configuredRoles = Object.keys((adminSiteConfig && adminSiteConfig.role_capabilities) || {
 investor: ['h5', 'investor'],
 dav: ['h5', 'dav', 'hermes', 'workbench'],
 admin: ['admin', 'h5', 'dav', 'hermes', 'workbench'],
 });
 const roleOptions = configuredRoles.map((role) => `<option value="${escapeAttr(role)}" ${String(row.role || 'investor') === role ? 'selected' : ''}>${escapeHtml(role)}</option>`).join('');
 return `
 <tr>
 <td><input data-field="username" type="text" value="${escapeAttr(row.username || '')}" placeholder="用户名"></td>
 <td><input data-field="password" type="text" value="${escapeAttr(row.password || '')}" placeholder="密码"></td>
 <td><input data-field="phone" type="text" value="${escapeAttr(row.phone || '')}" placeholder="手机号"></td>
 <td>
 <select data-field="role">
 ${roleOptions}
 </select>
 </td>
 <td><input data-field="tenant_slug" type="text" value="${escapeAttr(row.tenant_slug || adminSiteConfig.default_tenant_slug || '')}" placeholder="租户 slug"></td>
 <td><input data-field="advisor_name" type="text" value="${escapeAttr(row.advisor_name || '')}" placeholder="所属大V"></td>
 <td>
 <select data-field="status">
 <option value="active" ${String(row.status || 'active') === 'active' ? 'selected' : ''}>正常</option>
 <option value="disabled" ${String(row.status || '') === 'disabled' ? 'selected' : ''}>禁用</option>
 </select>
 </td>
 <td>
 <select data-field="is_paid_sample">
 <option value="0" ${String(row.is_paid_sample || '0') === '1' ? '' : 'selected'}>否</option>
 <option value="1" ${String(row.is_paid_sample || '0') === '1' ? 'selected' : ''}>是</option>
 </select>
 </td>
 <td><input data-field="source_label" type="text" value="${escapeAttr(row.source_label || '管理录入')}" placeholder="来源"></td>
 <td><input data-field="paid_sample_note" type="text" value="${escapeAttr(row.paid_sample_note || '')}" placeholder="备注"></td>
 <td><button class="btn-outline" type="button" style="padding:4px 10px;font-size:11px" onclick="removeAdminUserImportRow(this)">删除</button></td>
 </tr>
 `;
}

function removeAdminUserImportRow(button) {
 const row = button ? button.closest('tr') : null;
 if (row) row.remove();
}

function addAdminUserImportRow(row) {
 const body = document.getElementById('admin-user-import-tbody');
 if (!body) return;
 body.insertAdjacentHTML('beforeend', buildAdminUserImportRow(row || {}));
}

function collectAdminUserImportRows() {
 return Array.from(document.querySelectorAll('#admin-user-import-tbody tr')).map((row) => {
 const payload = {};
 ADMIN_USER_IMPORT_COLUMNS.forEach((field) => {
 const node = row.querySelector(`[data-field="${field}"]`);
 payload[field] = node ? String(node.value || '').trim() : '';
 });
 return payload;
 }).filter((item) => item.username || item.phone);
}

function openAdminUserBulkEditor() {
 openAdminUserImportModal('bulk');
}

function openAdminUserImportModal(mode = 'bulk') {
 const modal = document.getElementById('admin-user-import-modal');
 const content = document.getElementById('admin-user-import-modal-content');
 if (!modal || !content) return;
 const isSingle = mode === 'single';
 content.innerHTML = `
 <div class="admin-modal-head">
 <div>
 <div class="admin-modal-title">${isSingle ? '新增用户' : '批量手工录入用户'}</div>
 <div class="admin-modal-subtitle">Admin 可创建粉丝用户、大V 和 admin。批量录入风格参考在线表格。</div>
 </div>
 <button class="admin-modal-close" type="button" onclick="closeAdminUserImportModal()">×</button>
 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">录入表格</div>
 <div class="feature-note" style="margin-bottom:10px">角色含义：investor = 粉丝用户，dav = 大V，admin = 管理员。</div>
 <div style="overflow:auto">
 <table>
 <thead><tr><th>用户名</th><th>密码</th><th>手机号</th><th>角色</th><th>租户 slug</th><th>所属大V</th><th>状态</th><th>付费样本</th><th>来源</th><th>备注</th><th>操作</th></tr></thead>
 <tbody id="admin-user-import-tbody"></tbody>
 </table>
 </div>
 <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px">
 <button class="btn-outline" type="button" style="padding:8px 14px;font-size:12px" onclick="addAdminUserImportRow()">新增一行</button>
 <button class="btn-gold" type="button" style="padding:8px 14px;font-size:12px" onclick="submitAdminUserImportRows()">${isSingle ? '保存用户' : '批量创建用户'}</button>
 </div>
 </div>
 `;
 modal.classList.add('show');
 addAdminUserImportRow(isSingle ? {role: 'investor', status: 'active', is_paid_sample: '0', source_label: '管理录入'} : {role: 'investor', status: 'active', is_paid_sample: '0', source_label: '管理录入'});
 if (!isSingle) addAdminUserImportRow({role: 'investor', status: 'active', is_paid_sample: '0', source_label: '管理录入'});
}

async function submitAdminUserImportRows() {
 const users = collectAdminUserImportRows();
 if (!users.length) {
 showToast('请至少填写一行用户');
 return;
 }
 try {
 const res = await fetch('/api/admin/users/import', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({users}),
 });
 const data = await res.json();
 if (!res.ok || data.ok === false) throw new Error(data.error || 'import_users_failed');
 adminUsers = Array.isArray(data.users) ? data.users : adminUsers;
 renderAdminUsersTable();
 closeAdminUserImportModal();
 const skipped = Array.isArray(data.skipped) ? data.skipped.length : 0;
 showToast(`已创建 ${Array.isArray(data.created) ? data.created.length : 0} 个用户${skipped ? `，跳过 ${skipped} 条` : ''}`);
 } catch (error) {
 showToast(error.message || '用户导入失败');
 }
}

