function buildAgentWorkflowTopDownLayout(nodes, edges) {
 const nodeList = Array.isArray(nodes) ? nodes : [];
 const nodeMap = new Map(nodeList.map((item) => [item.id, item]));
 const incoming = new Map(nodeList.map((item) => [item.id, 0]));
 const outgoing = new Map(nodeList.map((item) => [item.id, []]));
 const depth = new Map(nodeList.map((item) => [item.id, 0]));
 (Array.isArray(edges) ? edges : []).forEach((edge) => {
 if (!nodeMap.has(edge.from) || !nodeMap.has(edge.to)) return;
 incoming.set(edge.to, Number(incoming.get(edge.to) || 0) + 1);
 outgoing.get(edge.from).push(edge.to);
 });
 const queue = nodeList.filter((item) => Number(incoming.get(item.id) || 0) === 0).map((item) => item.id);
 const orderedIds = [];
 while (queue.length) {
 const current = queue.shift();
 orderedIds.push(current);
 (outgoing.get(current) || []).forEach((target) => {
 depth.set(target, Math.max(Number(depth.get(target) || 0), Number(depth.get(current) || 0) + 1));
 incoming.set(target, Number(incoming.get(target) || 0) - 1);
 if (Number(incoming.get(target) || 0) === 0) queue.push(target);
 });
 }
 nodeList.forEach((item) => {
 if (!orderedIds.includes(item.id)) orderedIds.push(item.id);
 });
 const layers = new Map();
 orderedIds.forEach((nodeId) => {
 const level = Number(depth.get(nodeId) || 0);
 if (!layers.has(level)) layers.set(level, []);
 layers.get(level).push(nodeMap.get(nodeId));
 });
 const nodeWidth = 220;
 const nodeHeight = 118;
 const horizontalGap = 44;
 const verticalGap = 86;
 const paddingX = 38;
 const paddingY = 32;
 const maxLayerCount = Math.max(1, ...Array.from(layers.values()).map((items) => items.length));
 const canvasWidth = Math.max(760, paddingX * 2 + maxLayerCount * nodeWidth + Math.max(0, maxLayerCount - 1) * horizontalGap);
 const maxLevel = Math.max(0, ...Array.from(layers.keys()));
 const positionedNodes = [];
 Array.from(layers.entries()).sort(([left], [right]) => left - right).forEach(([level, layer]) => {
 const layerWidth = layer.length * nodeWidth + Math.max(0, layer.length - 1) * horizontalGap;
 const startX = Math.round((canvasWidth - layerWidth) / 2);
 layer.forEach((item, index) => {
 positionedNodes.push({...item, x: startX + index * (nodeWidth + horizontalGap), y: paddingY + level * (nodeHeight + verticalGap)});
 });
 });
 return {
 nodes: positionedNodes,
 width: canvasWidth,
 height: Math.max(760, paddingY * 2 + (maxLevel + 1) * nodeHeight + maxLevel * verticalGap),
 };
}

function renderAgentWorkflowGraph() {
 const titleNode = document.getElementById('agent-workflow-title');
 const summaryNode = document.getElementById('agent-workflow-summary');
 const board = document.getElementById('agent-workflow-board');
 const layer = document.getElementById('agent-workflow-edge-layer');
 const viewport = document.getElementById('agent-workflow-stage-viewport');
 const workflow = getSelectedAgentWorkflow();
 if (!workflow || !board || !layer || !viewport) return;
 const graph = workflow.graph || {};
 const nodes = Array.isArray(graph.nodes) ? graph.nodes : [];
 const edges = Array.isArray(graph.edges) ? graph.edges : [];
 if (titleNode) titleNode.textContent = workflow.title || '工作流详情';
 if (summaryNode) {
 const preview = workflow.preview && typeof workflow.preview === 'object' ? workflow.preview.result || {} : {};
 summaryNode.textContent = preview.predicted_change_pct !== undefined
 ? `${workflow.summary || ''} 当前预览目标 ${Number(preview.predicted_change_pct || 0).toFixed(2)}%，波动上限 ${Number(preview.volatility_cap || 0).toFixed(2)}。`
 : (workflow.summary || '这里展示智能体的设计流转和关键节点职责。');
 }
 if (!selectedAgentWorkflowNodeId && nodes.length) {
 selectedAgentWorkflowNodeId = (nodes[0] || {}).id || '';
 }
 if (!nodes.length) {
 board.innerHTML = '<div class="compact-row"><strong>暂无节点</strong><span>0</span></div>';
 layer.innerHTML = '';
 return;
 }
 const layout = buildAgentWorkflowTopDownLayout(nodes, edges);
 const positionedNodes = layout.nodes;
 const width = layout.width;
 const height = layout.height;
 board.style.width = `${width}px`;
 board.style.height = `${height}px`;
 viewport.style.width = `${width}px`;
 viewport.style.height = `${height}px`;
 board.innerHTML = positionedNodes.map((item) => `
 <article class="workflow-node agent-workflow-node ${item.id === selectedAgentWorkflowNodeId ? 'is-selected' : ''} ${item.visual_only ? 'is-visual-only' : ''}" data-agent-node-id="${escapeAttr(item.id || '')}" title="${escapeAttr(item.description || item.label || item.id || '')}" style="left:${Number(item.x || 0)}px;top:${Number(item.y || 0)}px;">
 <div class="workflow-node-head">
 <strong>${escapeHtml(item.label || item.id || '-')}</strong>
 <span class="workflow-node-type ${item.visual_only ? 'is-visual' : ''}">${escapeHtml(item.visual_only ? '条件节点' : (item.processor || item.kind || ''))}</span>
 </div>
 <div class="agent-workflow-node-copy">${escapeHtml(item.description || '暂无节点说明')}</div>
 </article>
 `).join('');
 renderAgentWorkflowEdges(positionedNodes, edges, width, height);
 board.querySelectorAll('[data-agent-node-id]').forEach((node) => {
 node.addEventListener('click', () => {
 selectedAgentWorkflowNodeId = node.dataset.agentNodeId || '';
 renderAgentWorkflowGraph();
 renderAgentWorkflowInspector();
 });
 });
}

function renderAgentWorkflowEdges(nodes, edges, width, height) {
 const layer = document.getElementById('agent-workflow-edge-layer');
 if (!layer) return;
 layer.setAttribute('width', String(width));
 layer.setAttribute('height', String(height));
 layer.setAttribute('viewBox', `0 0 ${width} ${height}`);
 layer.innerHTML = `
 <defs>
 <marker id="agent-workflow-arrowhead" viewBox="0 0 12 12" refX="10" refY="6" markerWidth="12" markerHeight="12" markerUnits="userSpaceOnUse" orient="auto">
 <path d="M 0 1 L 11 6 L 0 11 z" fill="rgba(47, 116, 192, 0.96)"></path>
 </marker>
 </defs>
 ${edges.map((edge) => {
 const fromNode = nodes.find((item) => item.id === edge.from);
 const toNode = nodes.find((item) => item.id === edge.to);
 if (!fromNode || !toNode) return '';
 const startX = Number(fromNode.x || 0) + 110;
 const startY = Number(fromNode.y || 0) + 118;
 const endX = Number(toNode.x || 0) + 110;
 const endY = Number(toNode.y || 0);
 const deltaY = endY - startY;
 const controlOffset = Math.max(42, Math.min(120, Math.abs(deltaY) * 0.42));
 const controlA = startY + controlOffset;
 const controlB = endY - controlOffset;
 const path = `M ${startX} ${startY} C ${startX} ${controlA}, ${endX} ${controlB}, ${endX} ${endY}`;
 const label = String(edge.label || '').trim();
 const condition = String(edge.condition || '').trim();
 const labelX = Math.round((startX + endX) / 2);
 const labelY = Math.round((startY + endY) / 2 - (startX === endX ? 6 : 4));
 return `
 <g data-agent-edge-id="${escapeAttr(edge.id || '')}">
 <path class="workflow-edge-shadow" d="${path}"></path>
 <path class="workflow-edge" d="${path}" marker-end="url(#agent-workflow-arrowhead)"></path>
 <circle class="workflow-edge-anchor" cx="${startX}" cy="${startY}" r="4"></circle>
 ${label ? `<text class="agent-workflow-edge-label" x="${labelX}" y="${labelY}" text-anchor="middle">${escapeHtml(label)}</text>` : ''}
 ${condition ? `<text class="agent-workflow-edge-condition" x="${labelX}" y="${labelY + 13}" text-anchor="middle">${escapeHtml(condition)}</text>` : ''}
 </g>
 `;
 }).join('')}
 `;
}

