 ];
 const previewLines = preview.result && typeof preview.result === 'object'
 ? Object.entries(preview.result).map(([key, value]) => `<div class="result-line"><strong>${escapeHtml(key)}</strong> · ${escapeHtml(String(value))}</div>`).join('')
 : '<div class="result-line">当前工作流暂无运行预览。</div>';
 host.innerHTML = `
 <div class="agent-workflow-metric-grid">
 <div class="agent-workflow-metric">
 <div class="agent-workflow-metric-label">执行框架</div>
 <div class="agent-workflow-metric-value">${escapeHtml(workflow.execution_mode || 'workflow')}</div>
 </div>
 <div class="agent-workflow-metric">
 <div class="agent-workflow-metric-label">节点数量</div>
 <div class="agent-workflow-metric-value">${nodes.length}</div>
 </div>
 </div>
 <div class="forecast-inspector-section" style="margin-top:12px">
 <div class="forecast-config-section-title">工作流说明</div>
 <div class="forecast-debug-copy">${escapeHtml(workflow.summary || '暂无说明')}</div>
 <div class="agent-workflow-chip-row">
 ${(Array.isArray(workflow.tags) ? workflow.tags : []).map((item) => `<span class="agent-workflow-chip">${escapeHtml(item)}</span>`).join('') || '<span class="agent-workflow-chip">暂无标签</span>'}
 </div>
 </div>
 ${workflow.id === 'hermes_agent' ? `
 <div class="forecast-inspector-section" style="margin-top:12px">
 <div class="forecast-config-section-title">六类场景路由</div>
 <div class="feature-note">点击场景可在上方图中定位对应节点。</div>
 <div class="agent-workflow-scenario-list">
 ${scenarioDefinitions.map((item) => `
 <button type="button" class="agent-workflow-scenario-item ${selectedNode?.id === item.id ? 'is-active' : ''}" data-agent-scenario-id="${escapeAttr(item.id)}">
 <span class="agent-workflow-scenario-index">${escapeHtml(item.number)}</span>
 <span>
 <span class="agent-workflow-scenario-title">${escapeHtml(item.title)}</span>
 <span class="agent-workflow-scenario-route">${escapeHtml(item.route)}</span>
 </span>
 </button>
 `).join('')}
 </div>
 </div>
 ` : ''}
 <div class="forecast-inspector-section" style="margin-top:12px">
 <div class="forecast-config-section-title">当前节点</div>
 ${selectedNode ? `
 <div class="forecast-config-field">
 <span>节点名称</span>
 <div class="forecast-debug-copy">${escapeHtml(selectedNode.label || selectedNode.id || '-')}</div>
 </div>
 <div class="forecast-config-field">
 <span>节点职责</span>
 <div class="forecast-debug-copy">${escapeHtml(selectedNode.description || '暂无')}</div>
 </div>
 <div class="forecast-config-field">
 <span>节点类型</span>
 <div class="forecast-debug-copy">${escapeHtml(selectedNode.processor || selectedNode.kind || '-')}</div>
 </div>
 ` : '<div class="compact-row"><strong>暂无节点</strong><span>0</span></div>'}
 ${nodeDebug ? `
 <div class="forecast-config-field">
 <span>最近执行说明</span>
 <div class="forecast-debug-copy">${escapeHtml(nodeDebug.detail || '暂无')}</div>
