async function loadAdminHermesUsageStats() {
 if (adminHermesUsageState.loading) return;
 const tenantSlug = getAdminHermesMemorySelectedTenant();
 adminHermesUsageState.loading = true;
 try {
 const resp = await fetch(`/api/admin/hermes/usage-stats?tenant_slug=${encodeURIComponent(tenantSlug || '')}`);
 const data = await resp.json();
 if (!resp.ok || !data.ok) throw new Error((data && data.error) || 'hermes_usage_stats_failed');
 adminHermesUsageState.stats = data.stats || null;
 renderAdminHermesUsageStats();
 } catch (error) {
 console.error(error);
 } finally {
 adminHermesUsageState.loading = false;
 }
}

function renderAdminHermesInterceptionAudits() {
 const body = document.getElementById('admin-hermes-interception-audit-tbody');
 if (!body) return;
 const items = Array.isArray(adminHermesInterceptionAuditState.items) ? adminHermesInterceptionAuditState.items : [];
 body.innerHTML = items.length ? items.map((item) => {
 const skillResults = Array.isArray(item.skill_results) ? item.skill_results : [];
 const matchedIds = Array.isArray(item.matched_skill_ids) ? item.matched_skill_ids : [];
 const matched = skillResults.filter((skill) => matchedIds.includes(skill.skill_id));
 const matchedText = matched.map((skill) => `${skill.label || skill.skill_id || '--'} v${skill.rule_version || '1'}`).join('、') || '未命中';
 const actionClass = item.action === 'block' || item.action === 'human_review' ? 'tag-red' : (item.action === 'clarify' || item.action === 'redirect' ? 'tag-gold' : 'tag-green');
 return `<tr>
 <td>${escapeHtml(item.created_at || '--')}</td>
 <td>${escapeHtml(item.user_profile_id || '--')}<br><span style="font-size:10px;color:#8899aa">${escapeHtml(item.user_role || '')}</span></td>
 <td style="min-width:240px;max-width:420px;white-space:normal;line-height:1.6">${escapeHtml(item.question_text || '--')}</td>
 <td>${escapeHtml(item.planner_intent || '--')}${item.planner_tasks?.length ? `<br><span style="font-size:10px;color:#8899aa">${escapeHtml(item.planner_tasks.join('、'))}</span>` : ''}</td>
 <td style="min-width:150px;white-space:normal">${escapeHtml(matchedText)}</td>
 <td><span class="tag ${actionClass}">${escapeHtml(item.action || item.decision_status || '--')}</span><br><span style="font-size:10px;color:#8899aa">${escapeHtml(item.decision_status || '')}</span></td>
 <td>${item.tool_called ? '<span class="tag tag-red">是</span>' : '<span class="tag tag-green">否</span>'}</td>
 <td style="min-width:220px;max-width:360px;white-space:normal;line-height:1.6">${escapeHtml(item.final_reason || '--')}</td>
 </tr>`;
 }).join('') : '<tr><td colspan="8" style="color:#9A9590">暂无语义拦截审计记录</td></tr>';
}

async function loadAdminHermesInterceptionAudits(forceReload = false) {
 if (adminHermesInterceptionAuditState.loading && !forceReload) return;
 const status = document.getElementById('admin-hermes-interception-audit-status');
 const tenantSlug = getAdminHermesMemorySelectedTenant();
 const action = document.getElementById('admin-hermes-interception-audit-action')?.value || '';
 adminHermesInterceptionAuditState.loading = true;
 if (status) status.textContent = '正在加载语义拦截审计...';
 try {
 const query = new URLSearchParams({tenant_slug: tenantSlug || '', action, limit: '100'});
 const response = await fetch(`/api/admin/hermes/interception-audits?${query.toString()}`, {cache: 'no-store'});
 const data = await response.json();
 if (!response.ok || !data.ok) throw new Error((data && data.error) || 'hermes_interception_audits_failed');
 adminHermesInterceptionAuditState.items = Array.isArray(data.items) ? data.items : [];
 renderAdminHermesInterceptionAudits();
 if (status) status.textContent = `已加载 ${adminHermesInterceptionAuditState.items.length} 条审计记录 · ${tenantSlug || '全部租户'}`;
 } catch (error) {
 if (status) status.textContent = error.message || '语义拦截审计加载失败';
 throw error;
 } finally {
 adminHermesInterceptionAuditState.loading = false;
 }
}

function renderAdminHermesMemoryPanel() {
 const tenantSelect = document.getElementById('admin-hermes-memory-tenant');
 const summaryNode = document.getElementById('admin-hermes-memory-summary');
 const previewNode = document.getElementById('admin-hermes-memory-preview');
 const backupRange = document.getElementById('admin-hermes-memory-backup-range');
 const clearRange = document.getElementById('admin-hermes-memory-clear-range');
 const confirmWrap = document.getElementById('admin-hermes-memory-clear-confirm-wrap');
 if (!tenantSelect || !summaryNode || !previewNode || !backupRange || !clearRange) return;

 const tenants = getAdminHermesMemoryTenantOptions();
 const currentTenant = getAdminHermesMemorySelectedTenant();
 tenantSelect.innerHTML = tenants.map((tenant) => `
 <option value="${escapeAttr(tenant.slug || '')}" ${(tenant.slug || '') === currentTenant ? 'selected' : ''}>${escapeHtml(tenant.name || tenant.slug || '')}</option>
 `).join('') || '<option value="">暂无租户</option>';
 if (!tenantSelect.value && tenants.length) {
 tenantSelect.value = tenants[0].slug || '';
 }

 const options = getAdminHermesMemoryRangeOptions();
 const currentBackupRange = backupRange.value || '3m';
 const currentClearRange = clearRange.value || '3m';
 backupRange.innerHTML = options.map((item) => `
 <option value="${escapeAttr(item.key || '')}" ${(item.key || '') === currentBackupRange ? 'selected' : ''}>${escapeHtml(item.label || item.key || '')}</option>
 `).join('');
 clearRange.innerHTML = options.map((item) => `
 <option value="${escapeAttr(item.key || '')}" ${(item.key || '') === currentClearRange ? 'selected' : ''}>${escapeHtml(item.label || item.key || '')}</option>
 `).join('');

 const summary = adminHermesMemoryState.summary || {};
 const cards = [
 {label: '对话总轮次', value: Number(summary.turn_count || 0), desc: summary.first_turn_at ? `首轮：${summary.first_turn_at}` : '暂无对话'},
 {label: '会话数', value: Number(summary.session_count || 0), desc: `会话记忆行 ${Number(summary.session_memory_count || 0)}`},
 {label: '用户数', value: Number(summary.user_count || 0), desc: `用户记忆行 ${Number(summary.user_memory_count || 0)}`},
 {label: '画像数', value: Number(summary.profile_count || 0), desc: summary.last_turn_at ? `最近：${summary.last_turn_at}` : '暂无最近时间'},
 {label: '近 30 天轮次', value: Number(summary.recent_30d_turn_count || 0), desc: `活跃用户 ${Number(summary.recent_30d_active_user_count || 0)}`},
 ];
 summaryNode.innerHTML = cards.map((item) => `
 <div class="hermes-memory-summary-card">
 <div class="hermes-memory-summary-label">${escapeHtml(item.label)}</div>
 <div class="hermes-memory-summary-value">${escapeHtml(String(item.value))}</div>
 <div class="hermes-memory-summary-meta">${escapeHtml(item.desc)}</div>
 </div>
 `).join('');

 const preview = adminHermesMemoryState.preview || null;
 if (!preview) {
 previewNode.innerHTML = '请选择租户和清理范围后查看影响预览。';
 } else {
 previewNode.innerHTML = `
 <div style="display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap">
 <div>
 <div class="hermes-memory-preview-title">清理预览 · ${escapeHtml(preview.range_label || preview.range_key || '')}</div>
 <div style="font-size:12px;color:var(--text-sub);line-height:1.8;margin-top:6px">
 ${preview.cutoff ? `将删除 ${escapeHtml(preview.cutoff)} 之后的 Hermes 记忆。` : '将清空该租户全部 Hermes 记忆。'}
 </div>
 </div>
 <div class="hermes-memory-preview-time">生成时间：${escapeHtml(preview.generated_at || '--')}</div>
 </div>
 <div class="hermes-memory-preview-metrics">
 <div class="hermes-memory-preview-metric"><div class="hermes-memory-preview-metric-label">待删轮次</div><div class="hermes-memory-preview-metric-value">${escapeHtml(String(preview.turns_to_clear || 0))}</div></div>
 <div class="hermes-memory-preview-metric"><div class="hermes-memory-preview-metric-label">受影响会话</div><div class="hermes-memory-preview-metric-value">${escapeHtml(String(preview.sessions_affected || 0))}</div></div>
 <div class="hermes-memory-preview-metric"><div class="hermes-memory-preview-metric-label">受影响用户</div><div class="hermes-memory-preview-metric-value">${escapeHtml(String(preview.users_affected || 0))}</div></div>
 <div class="hermes-memory-preview-metric"><div class="hermes-memory-preview-metric-label">受影响画像</div><div class="hermes-memory-preview-metric-value">${escapeHtml(String(preview.profiles_affected || 0))}</div></div>
 </div>
 <div class="hermes-memory-preview-footnote">
 时间覆盖：${escapeHtml(preview.first_turn_at || '--')} 至 ${escapeHtml(preview.last_turn_at || '--')}
 ${preview.requires_strong_confirm ? ' · 全量清理需要手动输入 CONFIRM。' : ''}
 </div>
 `;
 }

 const showConfirm = clearRange.value === 'all';
 if (confirmWrap) confirmWrap.style.display = showConfirm ? 'block' : 'none';
}

async function loadAdminHermesMemorySummary(forceReload = false) {
 if (adminHermesMemoryState.loading) return;
 renderAdminHermesMemoryPanel();
 const tenantSlug = getAdminHermesMemorySelectedTenant();
 if (!tenantSlug) {
 setAdminHermesMemoryStatus('当前没有可管理的租户。', true);
 return;
 }
 adminHermesMemoryState.loading = true;
 setAdminHermesMemoryStatus('正在加载 Hermes 记忆汇总...');
 try {
 const resp = await fetch(`/api/admin/hermes/memory-summary?tenant_slug=${encodeURIComponent(tenantSlug)}`);
 const data = await resp.json();
 if (!resp.ok || !data.ok) throw new Error((data && data.error) || 'hermes_memory_summary_failed');
 adminHermesMemoryState.summary = data.summary || null;
 adminHermesMemoryState.loaded = true;
 if (forceReload || !adminHermesMemoryState.preview || adminHermesMemoryState.preview.tenant_slug !== tenantSlug) {
 adminHermesMemoryState.preview = null;
 }
 renderAdminHermesMemoryPanel();
 loadAdminHermesUsageStats();
 await previewAdminHermesMemoryClear(false);
 setAdminHermesMemoryStatus(`Hermes 记忆汇总已加载 · 租户 ${tenantSlug}`);
 } catch (error) {
 setAdminHermesMemoryStatus(error.message || 'Hermes 记忆汇总加载失败', true);
 throw error;
 } finally {
 adminHermesMemoryState.loading = false;
 }
}

async function previewAdminHermesMemoryClear(showToastOnSuccess = true) {
 const tenantSlug = getAdminHermesMemorySelectedTenant();
 const rangeKey = document.getElementById('admin-hermes-memory-clear-range')?.value || '3m';
 const confirmWrap = document.getElementById('admin-hermes-memory-clear-confirm-wrap');
 if (confirmWrap) confirmWrap.style.display = rangeKey === 'all' ? 'block' : 'none';
 if (!tenantSlug) return;
 setAdminHermesMemoryStatus('正在预览 Hermes 记忆清理影响...');
 const resp = await fetch('/api/admin/hermes/memory-clear-preview', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({tenant_slug: tenantSlug, range_key: rangeKey}),
 });
 const data = await resp.json();
 if (!resp.ok || !data.ok) {
 setAdminHermesMemoryStatus((data && data.error) || 'hermes_memory_preview_failed', true);
 throw new Error((data && data.error) || 'hermes_memory_preview_failed');
 }
 adminHermesMemoryState.preview = data.preview || null;
 renderAdminHermesMemoryPanel();
 setAdminHermesMemoryStatus(`已生成清理预览 · ${tenantSlug} · ${rangeKey}`);
 if (showToastOnSuccess !== false) showToast('已更新 Hermes 记忆清理预览');
}

async function backupAdminHermesMemory() {
 const tenantSlug = getAdminHermesMemorySelectedTenant();
 const rangeKey = document.getElementById('admin-hermes-memory-backup-range')?.value || '3m';
 if (!tenantSlug) {
 showToast('请先选择租户');
 return false;
 }
 setAdminHermesMemoryStatus('正在生成 Hermes 记忆 ZIP 备份...');
 const resp = await fetch('/api/admin/hermes/memory-backup', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({tenant_slug: tenantSlug, range_key: rangeKey}),
 });
 if (!resp.ok) {
 let errorMessage = 'hermes_memory_backup_failed';
 try {
 const data = await resp.json();
 errorMessage = (data && data.error) || errorMessage;
 } catch (error) {}
 setAdminHermesMemoryStatus(errorMessage, true);
 showToast(errorMessage);
 return false;
 }
 const blob = await resp.blob();
 const downloadUrl = URL.createObjectURL(blob);
 const link = document.createElement('a');
 link.href = downloadUrl;
 link.download = (() => {
 const contentDisposition = resp.headers.get('Content-Disposition') || '';
 const matched = contentDisposition.match(/filename=\"([^\"]+)\"/);
 return matched ? matched[1] : `hermes_memory_${tenantSlug}_${rangeKey}.zip`;
 })();
 document.body.appendChild(link);
 link.click();
 link.remove();
 URL.revokeObjectURL(downloadUrl);
 setAdminHermesMemoryStatus(`Hermes 记忆备份已生成 · ${tenantSlug} · ${rangeKey}`);
 showToast('Hermes 记忆 ZIP 备份已下载');
 return true;
}

async function clearAdminHermesMemory(backupFirst) {
 const tenantSlug = getAdminHermesMemorySelectedTenant();
 const rangeKey = document.getElementById('admin-hermes-memory-clear-range')?.value || '3m';
 const confirmText = document.getElementById('admin-hermes-memory-clear-confirm')?.value || '';
 if (!tenantSlug) {
 showToast('请先选择租户');
 return;
 }
 if (rangeKey === 'all' && String(confirmText).trim() !== 'CONFIRM') {
 showToast('全量清理前请输入 CONFIRM');
 return;
 }
 if (backupFirst) {
 const backupOk = await backupAdminHermesMemory();
 if (!backupOk) return;
 }
 const preview = adminHermesMemoryState.preview || {};
 const turnCount = Number(preview.turns_to_clear || 0);
 const confirmed = window.confirm(
 rangeKey === 'all'
 ? `确认清空租户 ${tenantSlug} 的全部 Hermes 记忆吗？当前预估删除 ${turnCount} 轮对话。`
 : `确认清理租户 ${tenantSlug} 的 Hermes 记忆吗？当前预估删除 ${turnCount} 轮对话。`
 );
 if (!confirmed) return;
 setAdminHermesMemoryStatus('正在执行 Hermes 记忆清理...');
 const resp = await fetch('/api/admin/hermes/memory-clear', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({tenant_slug: tenantSlug, range_key: rangeKey, confirm_text: confirmText}),
 });
 const data = await resp.json();
 if (!resp.ok || !data.ok) {
 const errorMessage = (data && data.error) || 'hermes_memory_clear_failed';
 setAdminHermesMemoryStatus(errorMessage, true);
 showToast(errorMessage);
 return;
 }
 adminHermesMemoryState.summary = data.result && data.result.post_summary ? data.result.post_summary : adminHermesMemoryState.summary;
 adminHermesMemoryState.preview = null;
 if (document.getElementById('admin-hermes-memory-clear-confirm')) {
 document.getElementById('admin-hermes-memory-clear-confirm').value = '';
 }
 renderAdminHermesMemoryPanel();
 await previewAdminHermesMemoryClear(false);
 setAdminHermesMemoryStatus(`Hermes 记忆清理完成 · ${tenantSlug} · ${rangeKey}`);
 showToast('Hermes 记忆已清理并完成重建');
}

function renderForecastWorkflow() {
 const board = document.getElementById('forecast-workflow-board');
 const summary = document.getElementById('forecast-workflow-summary');
 const stats = document.getElementById('forecast-graph-stats');
 const preview = forecastWorkflowMeta.preview || {};
 if (summary) {
 const result = preview.result || {};
 summary.textContent = result.predicted_change_pct !== undefined
 ? `当前示例预览目标 ${Number(result.predicted_change_pct || 0).toFixed(2)}%，波动上限 ${Number(result.volatility_cap || 0).toFixed(2)}%。`
 : (forecastWorkflowMeta.summary || '展示目标价是怎么计算出来的，并允许在后台调整自动收敛参数。');
 }
 if (stats) {
 stats.textContent = `${(forecastGraph.nodes || []).length} 节点 · ${(forecastGraph.edges || []).length} 连线 · 当前算法`;
 }
 if (!board) return;
 const graph = forecastWorkflowMeta.graph || forecastGraph;
 const nodes = Array.isArray(graph.nodes) ? graph.nodes : [];
 applyForecastZoom();
 if (!nodes.length) {
 board.innerHTML = `<div class="compact-row"><strong>暂无工作流节点</strong><span>0</span></div>`;
 const edgeLayer = document.getElementById('forecast-edge-layer');
 if (edgeLayer) edgeLayer.innerHTML = '';
 return;
 }
 board.innerHTML = nodes.map((item) => `
 <article class="workflow-node ${item.id === selectedForecastNodeId ? 'is-selected' : ''} ${forecastLinkState?.from === item.id ? 'is-link-source' : ''}" data-node-id="${escapeAttr(item.id || '')}" style="left:${Number(item.x || 0)}px;top:${Number(item.y || 0)}px;">
 <div class="workflow-node-head">
 <strong>${escapeHtml(item.label || item.id || '-')}</strong>
 <span class="workflow-node-type">${escapeHtml(item.processor || '')}</span>
 </div>
 <div class="workflow-node-ports">
 <button type="button" class="workflow-port" data-port-action="select" data-node-id="${escapeAttr(item.id || '')}">接入</button>
 <button type="button" class="workflow-port" data-port-action="link" data-node-id="${escapeAttr(item.id || '')}">连出</button>
 </div>
 </article>
 `).join('');
 bindForecastGraphEvents();
 renderForecastEdges();
 renderForecastCatalog();
}

function renderForecastConfigBoard() {
 const board = document.getElementById('forecast-config-board');
 if (!board) return;
 const selectedNode = (forecastGraph.nodes || []).find((item) => item.id === selectedForecastNodeId) || null;
 const catalog = Array.isArray(forecastWorkflowMeta.catalog) ? forecastWorkflowMeta.catalog : [];
 const nodeSpec = selectedNode ? catalog.find((item) => item.processor === selectedNode.processor) : null;
 const tuningEntries = Object.entries(forecastConfig || {});
 const paramFields = Array.isArray(nodeSpec?.params) ? nodeSpec.params : [];
 const debugBlock = renderForecastNodeDebug();
 const selectedBlock = selectedNode ? `
 <div class="forecast-inspector-section">
 <div class="forecast-config-section-title">节点参数</div>
 <label class="forecast-config-field">
 <span>节点名称</span>
 <div class="forecast-config-input">
 <input data-node-label value="${escapeAttr(String(selectedNode.label || ''))}">
 <em>label</em>
 </div>
 </label>
 ${paramFields.length ? paramFields.map((field) => `
 <label class="forecast-config-field">
 <span>${escapeHtml(field.label || field.key || '-')}</span>
 <div class="forecast-config-input">
 <input data-node-param="${escapeAttr(field.key || '')}" value="${escapeAttr(String(selectedNode.params?.[field.key] ?? ''))}">
 <em>${escapeHtml(field.kind || '')}</em>
 </div>
 </label>
 `).join('') : `<div class="compact-row"><strong>当前节点无独立参数</strong><span>${escapeHtml(selectedNode.processor || '')}</span></div>`}
 </div>
 ` : `<div class="compact-row"><strong>未选中节点</strong><span>点击画布节点后编辑参数</span></div>`;
 board.innerHTML = `
 ${selectedBlock}
 <div class="forecast-inspector-section">
 <div class="forecast-config-section-title">节点预览</div>
 ${debugBlock}
 </div>
 <details class="forecast-inspector-section">
 <summary class="forecast-advanced-toggle">高级参数</summary>
 ${tuningEntries.map(([key, value]) => `
 <label class="forecast-config-field">
 <span>${escapeHtml(key)}</span>
 <div class="forecast-config-input">
 <input data-forecast-field="${escapeAttr(key)}" inputmode="decimal" step="0.05" value="${escapeAttr(String(value ?? ''))}">
 <em>tuning</em>
 </div>
 </label>
 `).join('')}
 </details>
 ${selectedNode ? `
 <div class="workflow-inspector-actions">
 <button type="button" class="btn-outline workflow-tool-button" id="forecast-delete-node">删除节点</button>
 </div>
 ` : ''}
 `;
 document.getElementById('forecast-delete-node')?.addEventListener('click', deleteSelectedForecastNode);
}

function renderForecastNodeDebug() {
 const selectedNode = (forecastGraph.nodes || []).find((item) => item.id === selectedForecastNodeId) || null;
 const nodeResults = forecastWorkflowMeta.preview?.node_results || forecastWorkflowMeta.graph?.node_results || {};
 if (!selectedNode) {
 return `<div class="compact-row"><strong>未选中节点</strong><span>暂无调试信息</span></div>`;
 }
 const debug = nodeResults[selectedNode.id];
 if (!debug) {
 return `<div class="compact-row"><strong>${escapeHtml(selectedNode.label || selectedNode.id || '-')}</strong><span>暂无运行结果</span></div>`;
 }
 const preview = debug.context_preview && typeof debug.context_preview === 'object'
 ? Object.entries(debug.context_preview).map(([key, value]) => `<div class="result-line"><strong>${escapeHtml(key)}</strong> · ${escapeHtml(String(value))}</div>`).join('')
 : `<div class="result-line">暂无上下文预览</div>`;
 return `
 <div class="forecast-config-field">
 <span>当前输出</span>
 <div class="forecast-debug-value">${escapeHtml(String(debug.value ?? '--'))}</div>
 </div>
 <div class="forecast-config-field">
 <span>计算公式</span>
 <div class="forecast-debug-copy">${escapeHtml(debug.formula || '暂无')}</div>
 </div>
 <div class="forecast-config-field">
 <span>说明</span>
 <div class="forecast-debug-copy">${escapeHtml(debug.note || '暂无')}</div>
 </div>
 <div class="forecast-config-field">
 <span>上下文预览</span>
 <div class="forecast-debug-list">${preview}</div>
 </div>
 `;
}

function renderForecastCatalog() {
 const host = document.getElementById('forecast-node-catalog');
 if (!host) return;
 const catalog = Array.isArray(forecastWorkflowMeta.catalog) ? forecastWorkflowMeta.catalog : [];
 host.innerHTML = catalog.map((item) => `
 <button type="button" class="workflow-catalog-item" data-add-processor="${escapeAttr(item.processor || '')}">
 <strong>${escapeHtml(item.label || item.processor || '-')}</strong>
 <span>${escapeHtml(item.description || '')}</span>
 </button>
 `).join('');
 host.querySelectorAll('[data-add-processor]').forEach((node) => {
 node.addEventListener('click', () => addForecastNode(node.dataset.addProcessor || 'source'));
 });
}

function renderForecastEdges() {
 const layer = document.getElementById('forecast-edge-layer');
 const board = document.getElementById('forecast-workflow-board');
 const viewport = document.getElementById('forecast-stage-viewport');
 if (!layer || !board) return;
 const nodes = Array.isArray(forecastGraph.nodes) ? forecastGraph.nodes : [];
 const edges = Array.isArray(forecastGraph.edges) ? forecastGraph.edges : [];
 const width = Math.max(1800, ...nodes.map((item) => Number(item.x || 0) + 280));
 const height = Math.max(760, ...nodes.map((item) => Number(item.y || 0) + 180));
 board.style.width = `${width}px`;
 board.style.height = `${height}px`;
 if (viewport) {
 viewport.style.width = `${width}px`;
 viewport.style.height = `${height}px`;
 }
 layer.setAttribute('width', String(width));
 layer.setAttribute('height', String(height));
 layer.setAttribute('viewBox', `0 0 ${width} ${height}`);
 layer.innerHTML = `
 <defs>
 <marker id="workflow-arrowhead" viewBox="0 0 12 12" refX="10" refY="6" markerWidth="12" markerHeight="12" markerUnits="userSpaceOnUse" orient="auto">
 <path d="M 0 1 L 11 6 L 0 11 z" fill="rgba(47, 116, 192, 0.96)"></path>
 </marker>
 </defs>
 ${edges.map((edge) => {
 const fromNode = nodes.find((item) => item.id === edge.from);
 const toNode = nodes.find((item) => item.id === edge.to);
 if (!fromNode || !toNode) return '';
 const startX = Number(fromNode.x || 0) + 220;
 const startY = Number(fromNode.y || 0) + 52;
 const endX = Number(toNode.x || 0);
 const endY = Number(toNode.y || 0) + 52;
 const deltaX = endX - startX;
 const controlOffset = Math.max(80, Math.min(180, Math.abs(deltaX) * 0.45));
 const controlA = startX + (deltaX >= 0 ? controlOffset : -controlOffset);
 const controlB = endX - (deltaX >= 0 ? controlOffset : -controlOffset);
 const path = `M ${startX} ${startY} C ${controlA} ${startY}, ${controlB} ${endY}, ${endX} ${endY}`;
 return `
 <g data-edge-id="${escapeAttr(edge.id || '')}">
 <path class="workflow-edge-shadow" d="${path}"></path>
 <path class="workflow-edge" d="${path}" marker-end="url(#workflow-arrowhead)"></path>
 <circle class="workflow-edge-anchor" cx="${startX}" cy="${startY}" r="5"></circle>
 <circle class="workflow-edge-anchor" cx="${endX}" cy="${endY}" r="5"></circle>
 </g>
 `;
 }).join('')}
 `;
}

function applyForecastZoom() {
 const viewport = document.getElementById('forecast-stage-viewport');
 if (!viewport) return;
 viewport.style.transform = `scale(${forecastZoom})`;
 viewport.dataset.zoom = String(forecastZoom);
}

function bindForecastGraphEvents() {
 document.querySelectorAll('.workflow-node').forEach((node) => {
 node.addEventListener('click', (event) => {
 if (event.target instanceof HTMLElement && event.target.dataset.portAction) return;
 selectedForecastNodeId = node.dataset.nodeId || '';
 renderForecastWorkflow();
 renderForecastConfigBoard();
 renderForecastNodeDebug();
 });
 node.addEventListener('pointerdown', (event) => {
 if (event.target instanceof HTMLElement && event.target.dataset.portAction) return;
 const nodeId = node.dataset.nodeId || '';
 const item = (forecastGraph.nodes || []).find((row) => row.id === nodeId);
 if (!item) return;
 selectedForecastNodeId = nodeId;
 forecastDragState = {
 nodeId,
 startX: event.clientX,
 startY: event.clientY,
 originX: Number(item.x || 0),
 originY: Number(item.y || 0),
 };
 node.setPointerCapture?.(event.pointerId);
 });
 });
 document.querySelectorAll('[data-port-action="link"]').forEach((node) => {
 node.addEventListener('pointerdown', (event) => {
 const target = event.currentTarget;
 if (!(target instanceof HTMLElement)) return;
 forecastLinkState = {from: target.dataset.nodeId || ''};
 renderForecastWorkflow();
 renderForecastConfigBoard();
 event.preventDefault();
 });
 node.addEventListener('click', (event) => {
 const target = event.currentTarget;
 if (!(target instanceof HTMLElement)) return;
 forecastLinkState = {from: target.dataset.nodeId || ''};
 renderForecastWorkflow();
 renderForecastConfigBoard();
 });
 });
 document.querySelectorAll('[data-port-action="select"]').forEach((node) => {
 node.addEventListener('pointerup', (event) => {
 const target = event.currentTarget;
 if (!(target instanceof HTMLElement)) return;
 const nodeId = target.dataset.nodeId || '';
 if (forecastLinkState?.from && forecastLinkState.from !== nodeId) {
 addForecastEdge(forecastLinkState.from, nodeId);
 forecastLinkState = null;
 renderForecastWorkflow();
 renderForecastConfigBoard();
 renderForecastNodeDebug();
 showToast('连线已完成');
 event.preventDefault();
 }
 });
 node.addEventListener('click', (event) => {
 const target = event.currentTarget;
 if (!(target instanceof HTMLElement)) return;
 const nodeId = target.dataset.nodeId || '';
 if (forecastLinkState?.from && forecastLinkState.from !== nodeId) {
 addForecastEdge(forecastLinkState.from, nodeId);
 forecastLinkState = null;
 renderForecastWorkflow();
 renderForecastConfigBoard();
 renderForecastNodeDebug();
 showToast('连线已完成');
 return;
 }
 selectedForecastNodeId = nodeId;
 renderForecastWorkflow();
 renderForecastConfigBoard();
 renderForecastNodeDebug();
 });
 });
}

window.addEventListener('pointermove', (event) => {
 if (!forecastDragState) return;
 const item = (forecastGraph.nodes || []).find((row) => row.id === forecastDragState.nodeId);
 if (!item) return;
 const zoom = forecastZoom || 1;
 item.x = Math.max(8, forecastDragState.originX + (event.clientX - forecastDragState.startX) / zoom);
 item.y = Math.max(8, forecastDragState.originY + (event.clientY - forecastDragState.startY) / zoom);
 renderForecastWorkflow();
 renderForecastConfigBoard();
 renderForecastNodeDebug();
});

window.addEventListener('pointerup', () => {
 forecastDragState = null;
});

function addForecastNode(processor) {
 const catalog = Array.isArray(forecastWorkflowMeta.catalog) ? forecastWorkflowMeta.catalog : [];
 const spec = catalog.find((item) => item.processor === processor) || {label: processor, params: []};
 const nextIndex = (forecastGraph.nodes || []).length + 1;
 const nodeId = `${processor}_${Date.now()}_${nextIndex}`;
 const params = {};
 (spec.params || []).forEach((item) => {
 params[item.key] = '';
 });
 forecastGraph.nodes.push({
 id: nodeId,
 label: spec.label || processor,
 processor,
 x: 120 + (nextIndex % 3) * 260,
 y: 120 + Math.floor(nextIndex / 3) * 120,
 params,
 });
 selectedForecastNodeId = nodeId;
 renderForecastWorkflow();
 renderForecastConfigBoard();
 renderForecastNodeDebug();
}

function addForecastEdge(fromId, toId) {
 if (!fromId || !toId || fromId === toId) return;
 if ((forecastGraph.edges || []).some((item) => item.from === fromId && item.to === toId)) return;
 forecastGraph.edges.push({id: `edge_${Date.now()}_${forecastGraph.edges.length + 1}`, from: fromId, to: toId});
}

function deleteSelectedForecastNode() {
 if (!selectedForecastNodeId) return;
 forecastGraph.nodes = (forecastGraph.nodes || []).filter((item) => item.id !== selectedForecastNodeId);
 forecastGraph.edges = (forecastGraph.edges || []).filter((item) => item.from !== selectedForecastNodeId && item.to !== selectedForecastNodeId);
 selectedForecastNodeId = (forecastGraph.nodes || [])[0]?.id || '';
 renderForecastWorkflow();
 renderForecastConfigBoard();
 renderForecastNodeDebug();
}

function centerForecastView() {
 const stage = document.querySelector('#section-forecast-model .workflow-stage');
 const viewport = document.getElementById('forecast-stage-viewport');
 if (!stage) return;
 const targetWidth = viewport ? viewport.offsetWidth * forecastZoom : stage.scrollWidth;
 const targetHeight = viewport ? viewport.offsetHeight * forecastZoom : stage.scrollHeight;
 stage.scrollLeft = Math.max(0, (targetWidth - stage.clientWidth) / 2);
 stage.scrollTop = Math.max(0, (targetHeight - stage.clientHeight) / 2);
}

function collectForecastConfig() {
 document.querySelectorAll('[data-forecast-field]').forEach((fieldNode) => {
 const field = fieldNode.dataset.forecastField;
 if (!field) return;
 forecastConfig[field] = Number(fieldNode.value || 0);
 });
 const selectedNode = (forecastGraph.nodes || []).find((item) => item.id === selectedForecastNodeId);
 if (selectedNode) {
 const labelNode = document.querySelector('[data-node-label]');
 if (labelNode instanceof HTMLInputElement) {
 selectedNode.label = labelNode.value || selectedNode.label;
 }
 document.querySelectorAll('[data-node-param]').forEach((fieldNode) => {
 const field = fieldNode.dataset.nodeParam;
 if (!field) return;
 selectedNode.params = selectedNode.params || {};
 selectedNode.params[field] = fieldNode.value;
 });
 }
 forecastGraph.tuning = {...forecastConfig};
}

async function loadAdminForecastModel(forceReload) {
 if (forecastLoaded && !forceReload && forecastEditorBootstrapped) return;
 const payload = await fetch('/api/admin/forecast-config');
 const data = await payload.json();
 if (!payload.ok || data.ok === false) throw new Error(data.error || 'forecast_config_failed');
 forecastConfig = data.config || {};
 forecastWorkflowMeta = data.workflow_meta || {};
 forecastGraph = forecastWorkflowMeta.graph || {nodes: [], edges: [], tuning: forecastConfig};
 forecastGraph.tuning = {...forecastConfig};
 selectedForecastNodeId = (forecastGraph.nodes || [])[0]?.id || '';
 forecastLoaded = true;
 renderForecastWorkflow();
 renderForecastConfigBoard();
 renderForecastNodeDebug();
 centerForecastView();
}

async function resetAdminForecastGraph() {
 const statusNode = document.getElementById('forecast-save-status');
 if (statusNode) statusNode.textContent = '正在恢复推荐模板...';
 const res = await fetch('/api/admin/forecast-config', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({reset_default: true}),
 });
 const data = await res.json();
 if (!res.ok || data.ok === false) throw new Error(data.error || 'reset_failed');
 forecastConfig = data.config || {};
 forecastWorkflowMeta = data.workflow_meta || {};
 forecastGraph = forecastWorkflowMeta.graph || {nodes: [], edges: [], tuning: forecastConfig};
 forecastGraph.tuning = {...forecastConfig};
 selectedForecastNodeId = (forecastGraph.nodes || [])[0]?.id || '';
 forecastLoaded = true;
 renderForecastWorkflow();
 renderForecastConfigBoard();
 renderForecastNodeDebug();
 centerForecastView();
 if (statusNode) statusNode.textContent = '已恢复推荐模板';
 showToast('已恢复推荐模板');
}

async function saveForecastConfigs() {
 collectForecastConfig();
 const statusNode = document.getElementById('forecast-save-status');
 if (statusNode) statusNode.textContent = '保存中...';
 const res = await fetch('/api/admin/forecast-config', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({graph: {...forecastGraph, tuning: forecastConfig}, config: forecastConfig}),
 });
 const data = await res.json();
 if (!res.ok || data.ok === false) throw new Error(data.error || 'save_failed');
 forecastConfig = data.config || {};
 forecastWorkflowMeta = data.workflow_meta || {};
 forecastGraph = forecastWorkflowMeta.graph || forecastGraph;
 forecastGraph.tuning = {...forecastConfig};
 selectedForecastNodeId = (forecastGraph.nodes || [])[0]?.id || '';
 renderForecastWorkflow();
 renderForecastConfigBoard();
 renderForecastNodeDebug();
 if (statusNode) statusNode.textContent = '预测算法配置已保存';
 showToast('预测算法配置已保存');
}

function initForecastEditorEvents() {
 if (forecastEditorBootstrapped) return;
 forecastEditorBootstrapped = true;
 document.getElementById('save-forecast-configs')?.addEventListener('click', async () => {
 try {
 await saveForecastConfigs();
 } catch (error) {
 showToast(error.message || '保存失败');
 }
 });
 document.getElementById('forecast-reset-graph')?.addEventListener('click', async () => {
 try {
 await resetAdminForecastGraph();
 } catch (error) {
 showToast(error.message || '恢复失败');
 }
 });
 document.getElementById('forecast-center-view')?.addEventListener('click', () => {
 centerForecastView();
 });
 document.getElementById('forecast-zoom-in')?.addEventListener('click', () => {
 forecastZoom = Math.min(1.8, Number((forecastZoom + 0.1).toFixed(2)));
 applyForecastZoom();
 });
 document.getElementById('forecast-zoom-out')?.addEventListener('click', () => {
 forecastZoom = Math.max(0.6, Number((forecastZoom - 0.1).toFixed(2)));
 applyForecastZoom();
 });
}

let adminSiteConfig = JSON.parse(JSON.stringify(window.SITE_CONFIG || {}));
let adminSiteConfigLoaded = false;

function ensureAdminLlmRegistry() {
 if (!adminSiteConfig.llm_registry || typeof adminSiteConfig.llm_registry !== 'object') {
 adminSiteConfig.llm_registry = { default_model_key: '', models: [], feature_model_keys: {} };
 }
 if (!Array.isArray(adminSiteConfig.llm_registry.models)) {
 adminSiteConfig.llm_registry.models = [];
 }
 if (!adminSiteConfig.llm_registry.feature_model_keys || typeof adminSiteConfig.llm_registry.feature_model_keys !== 'object') {
 adminSiteConfig.llm_registry.feature_model_keys = {};
 }
 return adminSiteConfig.llm_registry;
}

function addAdminLlmModel() {
 const registry = ensureAdminLlmRegistry();
 const nextIndex = registry.models.length + 1;
 registry.models.push({
 key: `model_${nextIndex}`,
 label: `模型 ${nextIndex}`,
 provider: 'openai',
 model_name: '',
 base_url: '',
 api_key: '',
 purpose: 'general',
 enabled: true,
 });
 if (!registry.default_model_key) {
 registry.default_model_key = registry.models[registry.models.length - 1].key;
 }
 renderSiteConfigForm();
}

function updateAdminLlmModel(index, field, value) {
 const registry = ensureAdminLlmRegistry();
 if (!registry.models[index]) return;
 const previousKey = registry.models[index].key || '';
 registry.models[index][field] = field === 'enabled' ? Boolean(value) : value;
 if (field === 'key' && registry.default_model_key === previousKey) {
 registry.default_model_key = value;
 }
 renderSiteConfigForm();
}

function updateAdminLlmApiKey(index, value) {
 const registry = ensureAdminLlmRegistry();
 if (!registry.models[index]) return;
 // Keep the secret input mounted while typing. Re-rendering the whole model
 // list on every keystroke loses focus and makes the field appear unusable.
 registry.models[index].api_key = String(value || '');
 registry.models[index].clear_api_key = false;
}

async function toggleAdminLlmApiKeyVisibility(index) {
 const input = document.getElementById(`llm-api-key-${index}`);
 const button = document.getElementById(`llm-api-key-toggle-${index}`);
 if (!input) return;
 const registry = ensureAdminLlmRegistry();
 const model = registry.models[index] || {};
 if (!input.value && model.api_key_configured) {
 await revealAdminLlmApiKey(index, button);
 return;
 }
 const visible = input.type === 'text';
 input.type = visible ? 'password' : 'text';
 if (button) button.textContent = visible ? '显示' : '隐藏';
}

async function revealAdminLlmApiKey(index, buttonOverride) {
 const registry = ensureAdminLlmRegistry();
 const model = registry.models[index];
 const input = document.getElementById(`llm-api-key-${index}`);
 const button = buttonOverride || document.getElementById(`llm-api-key-toggle-${index}`);
 if (!model || !input || !button) return;
 if (input.value) {
 input.type = 'text';
 document.getElementById(`llm-api-key-toggle-${index}`).textContent = '隐藏';
 return;
 }
 const originalText = button.textContent;
 button.disabled = true;
 button.textContent = '读取中';
 try {
 const response = await fetch('/api/admin/llm-credentials/reveal', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 cache: 'no-store',
 body: JSON.stringify({model_key: String(model.key || '')}),
 });
 const rawResponse = await response.text();
 let data = {};
 try {
 data = rawResponse ? JSON.parse(rawResponse) : {};
 } catch (parseError) {
 if (response.redirected || response.status === 401 || response.status === 403) {
 throw new Error('管理员登录已失效，请重新登录后再查看 API Key');
 }
 throw new Error(`服务器未返回有效结果（HTTP ${response.status}），请重启或重新部署 5001 服务`);
 }
 if (!response.ok || !data.ok) {
 const messages = {
 llm_api_key_not_configured: '该模型尚未配置 API Key',
 model_key_required: '模型配置无效',
 };
 throw new Error(messages[data && data.error] || (data && data.error) || '读取 API Key 失败');
 }
 input.value = String(data.api_key || '');
 model.api_key = input.value;
 input.type = 'text';
 document.getElementById(`llm-api-key-toggle-${index}`).textContent = '隐藏';
 } catch (error) {
 if (typeof showToast === 'function') showToast(String(error && error.message || '读取 API Key 失败'));
 } finally {
 button.disabled = false;
 button.textContent = originalText;
 }
}

function removeAdminLlmModel(index) {
 const registry = ensureAdminLlmRegistry();
 const current = registry.models[index];
 if (!current) return;
 const removedKey = current.key;
 registry.models.splice(index, 1);
 if (registry.default_model_key === removedKey) {
 registry.default_model_key = registry.models[0] ? registry.models[0].key : '';
 }
 renderSiteConfigForm();
}

function renderAdminLlmRegistry() {
 const registry = ensureAdminLlmRegistry();
 const featureCatalog = Array.isArray(adminSiteConfig.llm_feature_catalog) ? adminSiteConfig.llm_feature_catalog : [];
 if (!registry.default_model_key && registry.models.length) {
 const generalModels = registry.models.filter(model => model.purpose === 'general' && model.enabled !== false);
 registry.default_model_key = ((generalModels[0] || registry.models[0] || {}).key || '');
 }
 const defaultSelect = document.getElementById('llm-default-model-key');
 if (defaultSelect) {
 const options = registry.models.map(model => `<option value="${escapeAttr(model.key || '')}">${escapeHtml(model.label || model.key || '未命名模型')} · ${escapeHtml(model.purpose || 'general')}</option>`).join('');
 defaultSelect.innerHTML = options || '<option value="">暂无模型配置</option>';
 if (registry.default_model_key && !registry.models.some(model => model.key === registry.default_model_key)) {
 registry.default_model_key = registry.models[0] ? (registry.models[0].key || '') : '';
 }
 defaultSelect.value = registry.default_model_key || '';
 defaultSelect.onchange = function () {
 registry.default_model_key = this.value || '';
 renderSiteConfigForm();
 };
 }
 const quickSwitch = document.getElementById('llm-default-switcher');
 if (quickSwitch) {
 const enabledModels = registry.models.filter(model => model.enabled !== false);
 quickSwitch.innerHTML = enabledModels.length ? enabledModels.map((model) => `
 <button
 type="button"
 class="llm-admin-default-pill ${registry.default_model_key === model.key ? 'active' : ''}"
 onclick="updateAdminLlmDefaultModel('${escapeAttr(model.key || '')}')"
 >
 ${escapeHtml(model.label || model.key || '未命名模型')}
 </button>
 `).join('') : '<span class="llm-admin-chip is-muted">当前没有可切换的已启用模型</span>';
 }
 document.querySelectorAll('[data-llm-summary]').forEach((statsHost) => {
 const total = registry.models.length;
 const enabledCount = registry.models.filter(model => model.enabled !== false).length;
 const defaultModel = registry.models.find(model => model.key === registry.default_model_key) || null;
 statsHost.innerHTML = `
 <div class="llm-admin-chip-row">
 <span class="llm-admin-chip is-gold">模型总数 ${total}</span>
 <span class="llm-admin-chip">已启用 ${enabledCount}</span>
 <span class="llm-admin-chip">功能映射 ${Object.keys(registry.feature_model_keys || {}).length}</span>
 <span class="llm-admin-chip is-muted">用途标签 ${Array.from(new Set(registry.models.map(model => model.purpose || 'general'))).join(' / ') || 'general'}</span>
 </div>
 <div class="llm-admin-panel-note">
 当前通用模型：${escapeHtml(defaultModel ? (defaultModel.label || defaultModel.model_name || defaultModel.key || '未命名模型') : '尚未指定')}。
 推荐只把真正可用的模型设为启用，避免工作台误选到未完成配置的模型。
 </div>
 `;
 });
 const host = document.getElementById('llm-model-list');
 if (!host) return;
 host.innerHTML = registry.models.length ? `<div class="llm-admin-model-stack">${registry.models.map((model, index) => {
 const isDefault = registry.default_model_key === model.key;
 const enabled = model.enabled !== false;
 const title = model.label || `模型 ${index + 1}`;
 const provider = model.provider || 'openai';
 const purpose = model.purpose || 'general';
 const modelName = model.model_name || '待填写模型名';
 const baseUrlHint = model.base_url || '将沿用平台默认 OpenAI Compatible 地址';
 return `
 <div class="llm-admin-model-card ${isDefault ? 'is-default' : ''}">
 <div class="llm-admin-model-top">
 <div>
 <div class="llm-admin-model-title">${escapeHtml(title)}</div>
 <div class="llm-admin-model-sub">${escapeHtml(modelName)} · ${escapeHtml(provider)} · ${escapeHtml(baseUrlHint)}</div>
 <div class="llm-admin-chip-row" style="margin-top:10px">
 ${isDefault ? '<span class="llm-admin-chip is-gold">当前默认</span>' : `<button type="button" class="llm-admin-default-pill" onclick="updateAdminLlmDefaultModel('${escapeAttr(model.key || '')}')">设为默认</button>`}
 <span class="llm-admin-chip">${enabled ? '已启用' : '未启用'}</span>
 <span class="llm-admin-chip is-muted">用途 ${escapeHtml(purpose)}</span>
 <span class="llm-admin-chip is-muted">接口 OpenAI Compatible</span>
 <span class="llm-admin-chip ${model.api_key_configured ? 'is-gold' : 'is-muted'}">密钥 ${model.api_key_configured ? '已加密配置' : '未配置'}</span>
 </div>
 </div>
 <div class="llm-admin-inline-actions">
 <button class="btn-outline" type="button" style="padding:8px 12px;font-size:12px" onclick="removeAdminLlmModel(${index})">删除配置</button>
 </div>
 </div>
 <div class="llm-admin-model-grid">
 <div class="config-field">
 <label>模型 key</label>
 <input type="text" value="${escapeAttr(model.key || '')}" oninput="updateAdminLlmModel(${index}, 'key', this.value)">
 </div>
 <div class="config-field">
 <label>显示名称</label>
 <input type="text" value="${escapeAttr(model.label || '')}" oninput="updateAdminLlmModel(${index}, 'label', this.value)">
 </div>
 <div class="config-field">
 <label>Provider</label>
 <input type="text" value="${escapeAttr(provider)}" oninput="updateAdminLlmModel(${index}, 'provider', this.value)">
 </div>
 <div class="config-field">
 <label>用途标签</label>
 <div class="llm-admin-tag-input-shell">
 ${purpose ? `
 <span class="llm-admin-tag-token">
 ${escapeHtml(purpose)}
 <button type="button" class="llm-admin-tag-remove" onclick="clearAdminLlmPurpose(${index})">×</button>
 </span>
 ` : ''}
 <input
 type="text"
 class="llm-admin-tag-input"
 value=""
 placeholder="${purpose ? '输入新标签后回车 / 空格 / 失焦提交' : '输入用途标签，回车 / 空格 / 失焦生成标签'}"
 onkeydown="handleAdminLlmPurposeKeydown(${index}, event)"
 onblur="commitAdminLlmPurposeInput(${index}, this)"
 >
 </div>
 <div class="llm-admin-tag-picker">
 <button type="button" class="llm-admin-tag-option ${purpose === 'general' ? 'active' : ''}" onclick="applyAdminLlmPurposePreset(${index}, 'general')">general</button>
 </div>
 </div>
 <div class="config-field">
 <label>模型名</label>
 <input type="text" value="${escapeAttr(model.model_name || '')}" placeholder="例如 gpt-4o / deepseek-chat" oninput="updateAdminLlmModel(${index}, 'model_name', this.value)">
 </div>
 <div class="config-field">
 <label>Base URL</label>
 <input type="text" value="${escapeAttr(model.base_url || '')}" placeholder="例如 https://api.openai.com/v1" oninput="updateAdminLlmModel(${index}, 'base_url', this.value)">
 </div>
 <div class="config-field">
 <label>API Key</label>
 <div style="display:flex;gap:8px;align-items:center">
 <input id="llm-api-key-${index}" type="password" value="${escapeAttr(model.api_key || '')}" autocomplete="new-password" placeholder="${model.api_key_configured ? '已配置，留空不修改' : '填写后加密保存到 PostgreSQL'}" oninput="updateAdminLlmApiKey(${index}, this.value)" style="flex:1;min-width:0">
 <button id="llm-api-key-toggle-${index}" class="btn-outline" type="button" style="padding:8px 10px;font-size:11px;white-space:nowrap" onclick="toggleAdminLlmApiKeyVisibility(${index})">显示</button>
 </div>
 <label style="display:flex;align-items:center;gap:8px;margin-top:8px;font-size:12px;font-weight:400">
 <input type="checkbox" ${model.clear_api_key ? 'checked' : ''} onchange="updateAdminLlmModel(${index}, 'clear_api_key', this.checked)">
 清除该模型已保存的 API Key
 </label>
 </div>
 <div class="config-field">
 <label>启用状态</label>
 <select onchange="updateAdminLlmModel(${index}, 'enabled', this.value === 'true')">
 <option value="true" ${enabled ? 'selected' : ''}>启用</option>
 <option value="false" ${!enabled ? 'selected' : ''}>停用</option>
 </select>
 </div>
 </div>
 <div class="llm-admin-model-footer">
 API Key 仅写入当前 PostgreSQL 的加密凭证区。已保存的密钥不会回显；如需更换，直接输入新值后保存。删除模型时会同步清理其密钥。
 </div>
 </div>
 `;
 }).join('')}</div>` : '<div class="llm-admin-empty">当前还没有模型配置。先新增一个通用模型，把 Provider、模型名、Base URL 和 API Key 配完整，再设成默认。</div>';

 const featureHost = document.getElementById('llm-feature-model-mapping');
 if (featureHost) {
 const modelOptions = registry.models.map((model) => ({
 key: String(model.key || '').trim(),
 label: String(model.label || model.key || '未命名模型').trim(),
 purpose: String(model.purpose || 'general').trim(),
 enabled: model.enabled !== false,
 })).filter((item) => item.key);
 featureHost.innerHTML = featureCatalog.length ? `
 <div class="llm-admin-model-stack">
 ${featureCatalog.map((feature) => {
 const featureCode = String((feature || {}).feature_code || '').trim();
 const featureLabel = String((feature || {}).feature_label || featureCode || '未命名功能').trim();
 const defaultPurpose = String((feature || {}).default_purpose || 'general').trim();
 const currentValue = String((registry.feature_model_keys || {})[featureCode] || '').trim();
 const options = ['<option value="">跟随默认模型</option>'].concat(
 modelOptions.map((model) => `<option value="${escapeAttr(model.key)}">${escapeHtml(model.label)} · ${escapeHtml(model.purpose || 'general')}${model.enabled ? '' : ' · 已停用'}</option>`)
 ).join('');
 return `
 <div class="llm-admin-model-card">
 <div class="llm-admin-model-top">
 <div>
 <div class="llm-admin-model-title">${escapeHtml(featureLabel)}</div>
 <div class="llm-admin-model-sub">${escapeHtml(featureCode)} · 默认用途 ${escapeHtml(defaultPurpose)}</div>
 </div>
 </div>
 <div class="llm-admin-model-grid">
 <div class="config-field">
 <label>绑定模型</label>
 <select data-llm-feature-code="${escapeAttr(featureCode)}" onchange="updateAdminLlmFeatureModel('${escapeAttr(featureCode)}', this.value)">
 ${options}
 </select>
 </div>
 </div>
 </div>
 `;
 }).join('')}
 </div>
 ` : '<div class="llm-admin-empty">当前还没有功能级模型目录。</div>';
 featureCatalog.forEach((feature) => {
 const featureCode = String((feature || {}).feature_code || '').trim();
 if (!featureCode) return;
 const select = featureHost.querySelector(`select[data-llm-feature-code="${featureCode}"]`);
 if (select) select.value = String((registry.feature_model_keys || {})[featureCode] || '').trim();
 });
 }
}

function updateAdminLlmFeatureModel(featureCode, modelKey) {
 const registry = ensureAdminLlmRegistry();
 const code = String(featureCode || '').trim();
 const key = String(modelKey || '').trim();
 if (!code) return;
 if (!key) {
 delete registry.feature_model_keys[code];
 } else {
 registry.feature_model_keys[code] = key;
 }
 renderSiteConfigForm();
}

function updateAdminLlmDefaultModel(key) {
 const registry = ensureAdminLlmRegistry();
 registry.default_model_key = key || '';
 renderSiteConfigForm();
}

function applyAdminLlmPurposePreset(index, purpose) {
 updateAdminLlmModel(index, 'purpose', purpose || 'general');
}

function commitAdminLlmPurposeInput(index, inputEl) {
 if (!inputEl) return;
 const nextValue = String(inputEl.value || '').trim().toLowerCase();
 if (!nextValue) {
 inputEl.value = '';
 return;
 }
 updateAdminLlmModel(index, 'purpose', nextValue);
}

function handleAdminLlmPurposeKeydown(index, event) {
 if (!event) return;
 if (event.key === 'Enter' || event.key === ' ') {
 event.preventDefault();
 commitAdminLlmPurposeInput(index, event.target);
 }
}

function clearAdminLlmPurpose(index) {
 updateAdminLlmModel(index, 'purpose', '');
}
let selectedAdminTenantIndex = 0;
let adminSiteConfigDirty = false;
const SITE_CONFIG_BROADCAST_KEY = 'gangtise-site-config-updated-at';

function isAdminFeatureEnabled(featureName) {
 const flags = (adminSiteConfig && adminSiteConfig.feature_flags) || {};
 if (featureName === 'knowledge' && flags.knowledge_module_enabled !== true) return false;
 if (featureName === 'core_indicators') return flags.core_indicators === true;
 return flags[featureName] !== false;
}

function markAdminSiteConfigDirty(message) {
 adminSiteConfigDirty = true;
 const status = document.getElementById('site-config-status');
 const featureStatus = document.getElementById('feature-config-status');
 const nextMessage = message || '有未保存的修改。点击保存后才会同步到 Admin、大V工作台和 H5。';
 if (status) status.textContent = nextMessage;
 if (featureStatus) featureStatus.textContent = nextMessage;
}

function markAdminSiteConfigSaved(message) {
 adminSiteConfigDirty = false;
 const status = document.getElementById('site-config-status');
 const featureStatus = document.getElementById('feature-config-status');
 const nextMessage = message || '已保存。功能开关会同步影响 Admin、大V工作台和 H5。';
 if (status) status.textContent = nextMessage;
 if (featureStatus) featureStatus.textContent = nextMessage;
}

function broadcastSiteConfigUpdate() {
 try {
 window.localStorage.setItem(SITE_CONFIG_BROADCAST_KEY, String(Date.now()));
 } catch (error) {
 // ignore storage write failures
 }
}

function isAdminSiteConfigField(target) {
 if (!target || !target.closest) return false;
 return Boolean(target.closest('#section-settings-features, #section-settings-appearance, #section-settings-brand, #section-settings-policy, #section-settings-knowledge, #section-settings-llm, #section-settings-llm-features'));
}

function updateAdminFeatureFlagPreview(target) {
 if (!target || !target.id || !target.id.startsWith('feature-')) return;
 if (!adminSiteConfig || typeof adminSiteConfig !== 'object') return;
 adminSiteConfig.feature_flags = adminSiteConfig.feature_flags || {};
 const key = target.id.replace(/^feature-/, '');
 adminSiteConfig.feature_flags[key] = Boolean(target.checked);
 if (key === 'knowledge') {
 adminSiteConfig.feature_flags.knowledge_module_enabled = Boolean(target.checked);
 }
 refreshAdminNavVisibility();
 if (key === 'tenant_portal') renderTenantConfigList();
 const forecastSection = document.getElementById('section-forecast-model');
 if (forecastSection && key === 'stock_forecast' && !target.checked && forecastSection.style.display !== 'none') {
 showSection('overview', document.querySelector('.admin-nav-item[data-section="overview"]'));
 }
 const hermesSection = document.getElementById('section-hermes');
 if (hermesSection && key === 'hermes' && !target.checked && hermesSection.style.display !== 'none') {
 showSection('overview', document.querySelector('.admin-nav-item[data-section="overview"]'));
 }
}

function refreshAdminNavVisibility() {
 document.querySelectorAll('.admin-nav-item[data-feature]').forEach((node) => {
 const featureName = node.dataset.feature;
 const forceHidden = node.dataset.unifiedHidden === 'true';
 node.style.display = isAdminFeatureEnabled(featureName) && !forceHidden ? '' : 'none';
 });
 document.querySelectorAll('.admin-nav-group').forEach((group) => {
 const items = Array.from(group.querySelectorAll('.admin-nav-item'));
 const visibleItems = items.filter((item) => item.style.display !== 'none');
 group.style.display = visibleItems.length ? '' : 'none';
 });
 const activeSection = document.querySelector('.admin-nav-item.active[data-section]');
 if (activeSection && activeSection.style.display === 'none') {
 showSection('overview', document.querySelector('.admin-nav-item[data-section="overview"]'));
 }
}

function ensureAdminTenants() {
 if (!Array.isArray(adminSiteConfig.tenants) || !adminSiteConfig.tenants.length) {
 adminSiteConfig.tenants = [];
 }
 adminSiteConfig.tenants.forEach((tenant) => ensureAdminTenantNewsAggregationAlgorithm(tenant));
 return adminSiteConfig.tenants;
}

function getAdminNewsAggregationAlgorithmDefaults() {
 const defaults = (adminSiteConfig && adminSiteConfig.news_aggregation_algorithm_defaults) || {};
 if (typeof defaults.script_js !== 'string' || !defaults.script_js.trim()) {
 defaults.script_js = [
 'function rankNews(input) {',
 " const normalize = (value) => String(value || '').replace(/[\s\u3000·•/|_|-]+/g, ' ').trim();",
 " const compact = (value) => String(value || '').replace(/[\s\u3000·•/|_|-.]/g, '').trim();",
 ' const tags = Array.isArray(input.item.tags) ? input.item.tags.map(normalize).filter(Boolean) : [];',
 " const text = normalize([input.item.title, input.item.content, input.item.summary].filter(Boolean).join(' '));",
 ' const compactText = compact(text);',
 ' const sectorTokens = Array.isArray(input.watchlistSectors) ? input.watchlistSectors.map(normalize).filter(Boolean) : [];',
 " const sectorAliases = {'港股互联网':['互联网','平台经济','港股','腾讯','阿里','美团','百度','快手'],'半导体制造':['半导体','芯片','集成电路','晶圆','存储','光刻'],'高端白酒':['白酒','贵州茅台','五粮液','泸州老窖'],'动力电池':['动力电池','锂电','新能源车','宁德时代'],'银行':['银行','信贷','息差','存款','贷款']};",
 ' const symbolTokens = Array.isArray(input.watchlistSymbols) ? input.watchlistSymbols.map(normalize).filter(Boolean) : [];',
 " const majorKeywords = ['重大利好','重大利空','重大风险','突发','紧急','重磅','立案调查','行政处罚','停牌','退市','暴雷','违约','降准','降息','加息','出口管制','关税上调','重大订单','中标','业绩预增','业绩预亏','回购','增持','减持','并购重组','重大资产重组'];",
 " const sectorMatch = sectorTokens.some(tag => [tag, ...(sectorAliases[tag] || [])].some(term => text.includes(term)));",
 " const symbolMatch = symbolTokens.some(tag => text.includes(tag) || compactText.includes(compact(tag)));",
 " const majorSignal = Boolean(input.item.isMajorPositive || input.item.isMajorNegative) || majorKeywords.some(keyword => text.includes(keyword));",
 ' return {',
 " score: ((sectorMatch || symbolMatch) ? 220 : 0) + (symbolMatch ? 65 : 0) + (majorSignal ? 100 : 0),",
 " bucket: (sectorMatch || symbolMatch) ? 'watchlist_sector' : (majorSignal ? 'major_market' : 'other'),",
 " reason: (sectorMatch || symbolMatch) ? '命中自选股行业板块或标的' : (majorSignal ? '命中社会性重大利好/利空或高影响事件' : '其他公开信息'),",
 ' matched_topics: [',
 ' ...new Set([',
 ' ...sectorTokens.filter(tag => [tag, ...(sectorAliases[tag] || [])].some(term => text.includes(term))),',
 ' ...symbolTokens.filter(tag => text.includes(tag) || compactText.includes(compact(tag))),',
 ' ...majorKeywords.filter(keyword => text.includes(keyword))',
 ' ])',
 ' ]',
 ' };',
 '}',
 ].join('\n');
 }
 if (!defaults.version) defaults.version = 'v3';
 if (!defaults.strategy) defaults.strategy = 'watchlist_sector_first';
 return defaults;
}

function ensureAdminTenantNewsAggregationAlgorithm(tenant) {
 if (!tenant || typeof tenant !== 'object') return { version: 'v3', strategy: 'watchlist_sector_first', script_js: '' };
 const defaults = getAdminNewsAggregationAlgorithmDefaults();
 if (!tenant.news_aggregation_algorithm || typeof tenant.news_aggregation_algorithm !== 'object') {
 tenant.news_aggregation_algorithm = {
 version: defaults.version || 'v3',
 strategy: defaults.strategy || 'watchlist_sector_first',
 script_js: defaults.script_js || '',
 source_prompt: '',
 updated_at: '',
 updated_by: 'admin',
 };
 }
 if (typeof tenant.news_aggregation_algorithm.script_js !== 'string') {
 tenant.news_aggregation_algorithm.script_js = String(tenant.news_aggregation_algorithm.script_js || '');
 }
 if (!tenant.news_aggregation_algorithm.script_js.trim()) {
 tenant.news_aggregation_algorithm.script_js = defaults.script_js || '';
 }
 if (!tenant.news_aggregation_algorithm.version) {
 tenant.news_aggregation_algorithm.version = defaults.version || 'v3';
 }
 if (!tenant.news_aggregation_algorithm.strategy) {
 tenant.news_aggregation_algorithm.strategy = defaults.strategy || 'watchlist_sector_first';
 }
 return tenant.news_aggregation_algorithm;
}

function buildNewAdminTenant(index) {
 const serial = index + 1;
 const algorithmDefaults = getAdminNewsAggregationAlgorithmDefaults();
 return {
 id: `tenant_custom_${serial}`,
 slug: `tenant-${serial}`,
 name: `新租户 ${serial}`,
 short_name: `租户${serial}`,
 logo_mark: '⭐',
 advisor: `待命名大V ${serial}`,
 tier: '观察租户',
 focus: '',
 rights: '',
 description: '',
 portal_headline: '',
 portal_description: '',
 dashboard_title: '',
 dashboard_description: '',
 news_aggregation_algorithm: {
 version: algorithmDefaults.version || 'v3',
 strategy: algorithmDefaults.strategy || 'watchlist_sector_first',
 script_js: algorithmDefaults.script_js || '',
 source_prompt: '',
 updated_at: '',
 updated_by: 'admin',
 },
 };
}

function sanitizeTenantSlug(value) {
 return String(value || '')
 .trim()
 .toLowerCase()
 .replace(/[^a-z0-9-_]+/g, '-')
 .replace(/-{2,}/g, '-')
 .replace(/^-|-$/g, '');
}

function updateTenantSummaryCards() {
 const tenants = ensureAdminTenants();
 const totalNode = document.getElementById('tenant-total-count');
 const defaultNode = document.getElementById('tenant-default-name');
 if (totalNode) totalNode.textContent = String(tenants.length);
 const defaultSlug = adminSiteConfig.default_tenant_slug || '';
 const defaultTenant = tenants.find((tenant) => tenant.slug === defaultSlug) || tenants[0];
 if (defaultNode) defaultNode.textContent = defaultTenant ? (defaultTenant.short_name || defaultTenant.name || '--') : '--';
}

function updateAdminTopEntryLinks() {
 const tenants = ensureAdminTenants();
 const defaultSlug = adminSiteConfig.default_tenant_slug || '';
 const defaultTenant = tenants.find((tenant) => tenant.slug === defaultSlug) || tenants[0];
 const slug = defaultTenant && defaultTenant.slug ? defaultTenant.slug : 'laowang';
 const workbenchLink = document.getElementById('admin-top-workbench-link');
 const h5Link = document.getElementById('admin-top-h5-link');
 if (workbenchLink) workbenchLink.href = `/kol-workbench?tenant=${encodeURIComponent(slug)}`;
 if (h5Link) h5Link.href = `/h5?tenant=${encodeURIComponent(slug)}`;
}

function updateDefaultTenantSlug(value) {
 adminSiteConfig.default_tenant_slug = value || '';
 renderTenantConfigList();
}

function selectAdminTenant(index) {
 const tenants = ensureAdminTenants();
 if (!tenants.length) {
 selectedAdminTenantIndex = 0;
 renderTenantConfigList();
 return;
 }
 selectedAdminTenantIndex = Math.max(0, Math.min(index, tenants.length - 1));
 renderTenantConfigList();
}

function addAdminTenant() {
 const tenants = ensureAdminTenants();
 const nextTenant = buildNewAdminTenant(tenants.length);
 tenants.push(nextTenant);
 if (!adminSiteConfig.default_tenant_slug) {
 adminSiteConfig.default_tenant_slug = nextTenant.slug;
 }
 selectedAdminTenantIndex = tenants.length - 1;
 renderTenantConfigList();
}

function updateAdminTenantField(field, value) {
 const tenants = ensureAdminTenants();
 const tenant = tenants[selectedAdminTenantIndex];
 if (!tenant) return;
 const previousSlug = tenant.slug || '';
 const nextValue = field === 'slug' ? sanitizeTenantSlug(value) : value;
 tenant[field] = nextValue;
 if (field === 'slug' && adminSiteConfig.default_tenant_slug === previousSlug) {
 adminSiteConfig.default_tenant_slug = nextValue;
 }
 renderTenantSidebar();
}

function updateAdminTenantNewsAggregationPrompt(value) {
 const tenants = ensureAdminTenants();
 const tenant = tenants[selectedAdminTenantIndex];
 if (!tenant) return;
 const algorithm = ensureAdminTenantNewsAggregationAlgorithm(tenant);
 algorithm.source_prompt = String(value || '').trim();
 algorithm.rule_plan = {};
 algorithm.rule_atoms = [];
 algorithm.updated_by = 'admin';
 algorithm.updated_at = new Date().toISOString();
 markAdminSiteConfigDirty('新闻聚合规则已修改，保存后将按受控原子重新编译。');
}

function adminNormalizeDashboardMode(mode) {
 return ['market', 'industry', 'signal-stock'].includes(mode) ? mode : 'market';
}

function adminNormalizeDashboardLayout(layout) {
 if (layout === '3x3') return '2x3';
 if (layout === '4x4') return '2x4';
 return ['2x2', '2x3', '2x4', '2x5'].includes(layout) ? layout : '2x2';
}

function adminGetDashboardCardTarget(layout) {
 if (layout === '2x3') return 6;
 if (layout === '2x4') return 8;
 if (layout === '2x5') return 10;
 return 4;
}

function adminGetDashboardSegmentConfig(mode) {
 const configs = {
 market: { title: '市场进攻意愿卡', note: '先回答今天市场是在追逐高弹性方向，还是更偏向防守。', formula: '总分 = 35%广度改善分 + 25%资金回流分 + 25%主线参与分 - 15%防御压力分' },
 industry: { title: '行业景气验证卡', note: '先判断这条主线是基本面继续验证，还是只有情绪热度。', formula: '总分 = 30%订单景气分 + 25%价格景气分 + 20%库存去化分 + 15%政策催化分 + 10%资本开支确认分' },
 'signal-stock': { title: '主线信号个股卡', note: '先判断哪些个股还在验证主线，哪些已经开始掉队。', formula: '总分 = 35%龙头强度分 + 30%业绩兑现分 + 20%资金承接分 + 15%估值安全分' },
 };
 return configs[adminNormalizeDashboardMode(mode)] || configs.market;
}

function adminGetDashboardComponentLibrary(mode) {
 const libraries = {
 market: [
 { id: 'market_breadth', label: '广度改善分', source: '全市场行情库', metric: '上涨/下跌家数、站上MA20占比、新高-新低差', window: '1D', aggregation: '0-100评分', defaultWeight: 0.35 },
 { id: 'northbound_flow', label: '资金回流分', source: '北向/南向资金库', metric: '净流入占成交比、3日累计、连续净流入天数', window: '1D / 3D', aggregation: '0-100评分', defaultWeight: 0.25 },
 { id: 'policy_heat', label: '防御压力分', source: '风格因子库', metric: '银行/红利相对成长超额、低波ETF净流入', window: '1D / 5D', aggregation: '0-100评分', defaultWeight: 0.15 },
 ],
 industry: [
 { id: 'industry_orders', label: '订单景气分', source: '行业指标库', metric: '新增订单同比、在手订单覆盖、开工率', window: '1W / 1M', aggregation: '0-100评分', defaultWeight: 0.3 },
 { id: 'industry_price', label: '价格景气分', source: '产业链价格库', metric: '产品价格指数、价差、提价持续性', window: '1W / 1M', aggregation: '0-100评分', defaultWeight: 0.25 },
 { id: 'industry_inventory', label: '库存去化分', source: '行业库存库', metric: '库存天数、主动/被动补库、去库斜率', window: '1M', aggregation: '0-100评分', defaultWeight: 0.2 },
 ],
 'signal-stock': [
 { id: 'leader_strength', label: '龙头强度分', source: '个股行情库', metric: '相对行业超额收益、回撤控制、成交额排名', window: '5D / 20D', aggregation: '0-100评分', defaultWeight: 0.35 },
 { id: 'valuation_band', label: '估值安全分', source: '估值与财报库', metric: 'PE/PS分位、PEG、相对历史分位', window: '1Q / 3Y', aggregation: '0-100评分', defaultWeight: 0.15 },
 { id: 'earnings_delivery', label: '业绩兑现分', source: '财报与预期库', metric: '营收/利润兑现率、指引上修、订单兑现', window: '1Q', aggregation: '0-100评分', defaultWeight: 0.3 },
 ],
 };
 return JSON.parse(JSON.stringify(libraries[adminNormalizeDashboardMode(mode)] || libraries.market));
}

function adminBuildDefaultDashboardComponents(mode) {
 return adminGetDashboardComponentLibrary(mode).map((item, index) => ({
 id: item.id,
 label: item.label,
 source: item.source,
 metric: item.metric,
 window: item.window,
 aggregation: item.aggregation,
 weight: item.defaultWeight,
 operator: index === 0 ? 'base' : '+',
 }));
}

function adminNormalizeDashboardComponents(components, mode) {
 const library = adminGetDashboardComponentLibrary(mode);
 const libraryMap = Object.fromEntries(library.map(item => [item.id, item]));
 const list = Array.isArray(components) && components.length ? components : adminBuildDefaultDashboardComponents(mode);
 return list.map((item, index) => {
 const raw = item && typeof item === 'object' ? item : {};
 const template = libraryMap[raw.id || raw.componentId] || library[Math.min(index, library.length - 1)];
 return {
 id: template.id,
 label: String(raw.label || template.label || '').trim() || template.label,
 source: String(raw.source || template.source || '').trim() || template.source,
 metric: String(raw.metric || template.metric || '').trim() || template.metric,
 window: String(raw.window || template.window || '').trim() || template.window,
 aggregation: String(raw.aggregation || template.aggregation || '').trim() || template.aggregation,
 weight: Number.isFinite(Number(raw.weight)) ? Number(Number(raw.weight).toFixed(2)) : template.defaultWeight,
 operator: index === 0 ? 'base' : (String(raw.operator || '+').trim() || '+'),
 };
 });
}

function adminBuildDashboardFormula(mode, components, explicitFormula) {
 const formula = String(explicitFormula || '').trim();
 if (formula) return formula;
 const list = Array.isArray(components) ? components : [];
 if (!list.length) return adminGetDashboardSegmentConfig(mode).formula;
 return list.map((item, index) => {
 const prefix = index > 0 && item.operator && item.operator !== 'base' ? ` ${item.operator} ` : '';
 const weightText = Math.abs(Number(item.weight || 1) - 1) < 0.01 ? '' : ` x ${Number(item.weight || 1)}`;
 return `${prefix}${item.label}${weightText}`;
 }).join('');
}

function adminBuildDashboardSources(mode, components, explicitSources) {
 const deduped = [];
 const pushSource = (source) => {
 const text = String(source || '').trim();
 if (text && !deduped.includes(text)) deduped.push(text);
 };
 (Array.isArray(explicitSources) ? explicitSources : []).forEach(pushSource);
 (Array.isArray(components) ? components : []).forEach(item => pushSource(item.source));
 if (!deduped.length) adminGetDashboardComponentLibrary(mode).forEach(item => pushSource(item.source));
 return deduped;
}

function adminBuildDashboardMetricSummaryList(components, limit) {
 const list = Array.isArray(components) ? components : [];
 const maxItems = Number(limit || 2);
 return list.slice(0, maxItems).map((item) => ({
 label: item.label || '组件',
 metric: item.metric || '--',
 }));
}

function adminBuildDashboardMetricCompactText(components, limit) {
 const list = Array.isArray(components) ? components : [];
 if (!list.length) return '点击查看详细指标构成';
 const maxItems = Number(limit || 2);
 const names = list.slice(0, maxItems).map((item) => item.label || '组件');
 const suffix = list.length > maxItems ? `等${list.length}项` : '';
 return `指标：${names.join('、')}${suffix}`;
}

function adminResolveTenantDashboardState(tenant) {
 const state = (tenant && tenant.fund_dashboard_config) || {};
 const published = state.published || {};
 const layout = adminNormalizeDashboardLayout(published.layout || '2x2');
 const cards = Array.from({ length: adminGetDashboardCardTarget(layout) }, (_, index) => {
 const raw = Array.isArray(published.cards) ? published.cards[index] : null;
 const mode = adminNormalizeDashboardMode((raw && (raw.mode || raw.segmentId)) || 'market');
 const components = adminNormalizeDashboardComponents(raw && raw.components, mode);
 return raw ? {
 ...raw,
 mode,
 segmentId: mode,
 components,
 formula: adminBuildDashboardFormula(mode, components, raw.formula),
 sources: adminBuildDashboardSources(mode, components, raw.sources),
 } : {
 mode,
 segmentId: mode,
 name: `${adminGetDashboardSegmentConfig(mode).title} ${index + 1}`,
 value: '--',
 assessment: '当前还没有发布这个格子的具体内容。',
 status: 'attention',
 prompt: '',
 components,
 formula: adminBuildDashboardFormula(mode, components),
 sources: adminBuildDashboardSources(mode, components),
 };
 });
 return {
 layout,
 title: published.title || tenant.dashboard_title || '今日核心指标面板',
 note: published.note || tenant.dashboard_description || '这里只展示当前租户已发布到 H5 基本面的格子。',
 cards,
 };
}

function renderAdminTenantDashboardPreview(tenant) {
 const dashboard = adminResolveTenantDashboardState(tenant);
 return `
 <div class="tenant-dashboard-preview">
 <div class="tenant-dashboard-preview-head">
 <div>
 <div class="tenant-dashboard-preview-title">智能 Dashboard 白盒预览</div>
 <div class="tenant-dashboard-preview-desc">这里看的是租户当前发布态，不是草稿。点击任一格子可以检查提示词、组件组合、公式和数据源。</div>
 </div>
 <span class="tenant-dashboard-layout-tag">${escapeHtml(dashboard.layout)} · 已发布</span>
 </div>
 <div class="tenant-dashboard-grid">
 ${dashboard.cards.map((card, index) => {
 const segment = adminGetDashboardSegmentConfig(card.mode);
 const metricCompactText = adminBuildDashboardMetricCompactText(card.components || [], 2);
 return `
 <div class="tenant-dashboard-card" onclick="openAdminTenantDashboardCard(${index})">
 <div class="tenant-dashboard-card-head">
 <div class="tenant-dashboard-card-title">${escapeHtml(card.name || `格子 ${index + 1}`)}</div>
