 <div class="tenant-dashboard-metric-compact">${escapeHtml(metricCompactText)}</div>
 </div>
 `;
 }).join('')}
 </div>
 </div>
 `;
}

function closeAdminTenantDashboardModal() {
 const modal = document.getElementById('admin-tenant-dashboard-modal');
 if (modal) modal.classList.remove('show');
}

function openAdminTenantDashboardCard(index) {
 const tenants = ensureAdminTenants();
 const tenant = tenants[selectedAdminTenantIndex];
 if (!tenant) return;
 const dashboard = adminResolveTenantDashboardState(tenant);
 const card = dashboard.cards[index];
 const host = document.getElementById('admin-tenant-dashboard-modal-content');
 const modal = document.getElementById('admin-tenant-dashboard-modal');
 if (!card || !host || !modal) return;
 const segment = adminGetDashboardSegmentConfig(card.mode);
 host.innerHTML = `
 <div class="admin-modal-head">
 <div>
 <div class="admin-modal-title">${escapeHtml(card.name || `格子 ${index + 1}`)}</div>
 <div class="admin-modal-subtitle">${escapeHtml(segment.title)} · 这里展示后台监督口径：提示词、组件、公式和数据源。</div>
 </div>
 <button class="admin-modal-close" type="button" onclick="closeAdminTenantDashboardModal()">×</button>
 </div>
 <div class="admin-modal-grid">
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">1. 当前结果</div>
 <div class="admin-modal-summary">
 <div class="admin-modal-stat">
 <div class="admin-modal-stat-label">当前值</div>
 <div class="admin-modal-stat-value">${escapeHtml(card.value || '--')}</div>
 </div>
 </div>
 <div class="admin-modal-copy">${escapeHtml(card.assessment || segment.note)}</div>
 <div class="admin-modal-section-note" style="margin-top:12px">
 <div class="admin-modal-section-title">提示词</div>
 <div class="admin-modal-section-copy">${escapeHtml(card.prompt || '当前没有额外提示词')}</div>
 </div>
 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">2. 组合公式</div>
 <div class="admin-modal-copy">${escapeHtml(card.formula || segment.formula)}</div>
 <div class="admin-modal-list" style="margin-top:12px">
 ${(card.components || []).map((item, componentIndex) => `
 <div class="admin-modal-item">
 <div class="admin-modal-item-top">
 <strong style="color:var(--text-main)">${escapeHtml(item.label || `组件 ${componentIndex + 1}`)}</strong>
 <span class="tenant-dashboard-chip">${componentIndex === 0 ? '起始项' : `组合符 ${escapeHtml(item.operator || '+')}`}</span>
 </div>
 <div class="admin-modal-copy">指标：${escapeHtml(item.metric || '--')} · 窗口：${escapeHtml(item.window || '--')} · 聚合：${escapeHtml(item.aggregation || '--')} · 权重：${escapeHtml(item.weight || 1)}</div>
 </div>
 `).join('')}
 </div>
 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">3. 数据源</div>
 <div class="admin-modal-list">
 ${(card.sources || []).map((item) => `
 <div class="admin-modal-item">
 <div class="admin-modal-copy">${escapeHtml(item)}</div>
 </div>
 `).join('')}
 </div>
 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">4. 解释口径</div>
 <div class="admin-modal-list">
 <div class="admin-modal-item">
 <div class="admin-modal-copy">${escapeHtml(segment.note)}</div>
 </div>
 </div>
 </div>
 </div>
 `;
 modal.classList.add('show');
}

function renderTenantSidebar() {
 const host = document.getElementById('tenant-config-list');
 const defaultSelect = document.getElementById('default-tenant-slug');
 const tenants = ensureAdminTenants();
 if (!host || !defaultSelect) return;
 if (!tenants.length) {
 host.innerHTML = '<div class="tenant-admin-empty">当前还没有租户。<br>点击“新增租户”开始配置。</div>';
 defaultSelect.innerHTML = '';
 updateTenantSummaryCards();
 updateAdminTopEntryLinks();
 return;
 }
 selectedAdminTenantIndex = Math.max(0, Math.min(selectedAdminTenantIndex, tenants.length - 1));
 defaultSelect.innerHTML = tenants.map((tenant) => `
 <option value="${escapeAttr(tenant.slug || '')}">${escapeHtml(tenant.name || tenant.slug || '未命名租户')}</option>
 `).join('');
 defaultSelect.value = adminSiteConfig.default_tenant_slug || (tenants[0] && tenants[0].slug) || '';
 host.innerHTML = tenants.map((tenant, index) => `
 <div class="tenant-admin-item ${index === selectedAdminTenantIndex ? 'active' : ''}" onclick="selectAdminTenant(${index})">
 <div class="tenant-admin-item-top">
 <div>
 <div class="tenant-admin-item-title">${escapeHtml(tenant.name || `租户 ${index + 1}`)}</div>
 <div class="tenant-admin-item-sub">${escapeHtml(tenant.advisor || '未设置主理人')} · ${escapeHtml(tenant.slug || '未设置 slug')}</div>
 </div>
 <span class="tenant-admin-badge ${adminSiteConfig.default_tenant_slug === tenant.slug ? 'tenant-admin-default' : ''}">${adminSiteConfig.default_tenant_slug === tenant.slug ? '默认门户' : (tenant.tier || '租户')}</span>
 </div>
 <div class="tenant-admin-item-meta">
 ${tenant.short_name ? `<span class="tenant-admin-badge">${escapeHtml(tenant.short_name)}</span>` : ''}
 ${tenant.focus ? `<span class="tenant-admin-badge">${escapeHtml(tenant.focus)}</span>` : ''}
 </div>
 </div>
 `).join('');
 updateTenantSummaryCards();
 updateAdminTopEntryLinks();
}

