function markActivePill(groupId, attr, value) {
 document.querySelectorAll(`#${groupId} .theme-pill`).forEach(btn => {
 btn.classList.toggle('active', btn.dataset[attr] === value);
 });
}

function stringifyAdminConfigJson(value, fallbackValue) {
 const target = value === undefined ? fallbackValue : value;
 try {
 return JSON.stringify(target, null, 2);
 } catch (error) {
 return JSON.stringify(fallbackValue, null, 2);
 }
}

function parseAdminConfigJsonField(fieldId, fallbackValue) {
 const field = document.getElementById(fieldId);
 const raw = field ? String(field.value || '').trim() : '';
 if (!raw) {
 return JSON.parse(JSON.stringify(fallbackValue));
 }
 try {
 return JSON.parse(raw);
 } catch (error) {
 throw new Error(`${fieldId} 不是有效 JSON，请检查格式后再保存。`);
 }
}

function parseAdminConfigListField(fieldId, fallbackValue) {
 const field = document.getElementById(fieldId);
 const raw = field ? String(field.value || '').trim() : '';
 if (!raw) {
 return Array.isArray(fallbackValue) ? fallbackValue.slice(0) : [];
 }
 return raw
 .split(/[,\n]+/)
 .map(item => String(item || '').trim())
 .filter((item, index, source) => item && source.indexOf(item) === index);
}

