<style>
 .toggle-wrap { display:flex; align-items:center; gap:10px; margin-bottom:12px; }
 .toggle-label { font-size:13px; color:var(--text-sub); flex:1; }
 .feature-toggle-title { font-size:12px; color:var(--text-main); font-weight:600; margin-bottom:4px; }
 .feature-toggle-desc { font-size:11px; color:var(--text-sub); line-height:1.65; max-width:680px; }
 .toggle { position:relative; display:inline-block; width:40px; height:22px; }
 .toggle input { opacity:0; width:0; height:0; }
 .toggle-slider { position:absolute; cursor:pointer; top:0; left:0; right:0; bottom:0; background:var(--surface-3); border-radius:22px; transition:.3s; border:1px solid rgba(200,169,110,0.2); }
 .toggle-slider:before { position:absolute; content:""; height:16px; width:16px; left:2px; bottom:2px; background:var(--gray-200); border-radius:50%; transition:.3s; }
 .toggle input:checked + .toggle-slider { background:rgba(200,169,110,0.2); border-color:rgba(200,169,110,0.5); }
 .toggle input:checked + .toggle-slider:before { transform:translateX(18px); background:var(--gold); }
 .progress-bar-bg { background:rgba(200,169,110,0.1); border-radius:4px; height:6px; width:100%; }
 .progress-bar-fill { height:6px; border-radius:4px; background:linear-gradient(90deg,#C8A96E,#e8c98e); }
 .funnel-wrap { display:flex; align-items:center; gap:0; margin-top:24px; overflow-x:auto; padding-bottom:8px; }
