 .sync-grid { display:grid; grid-template-columns:1fr 1fr; gap:16px; }
 .sync-card { background:var(--surface-2); border:1px solid rgba(200,169,110,0.15); border-radius:12px; padding:18px; }
 .sync-title { font-size:14px; color:var(--gold); font-weight:600; margin-bottom:8px; }
