 }

 body.theme-light .admin-layout [style*="color:#F8F6F0"],
 body.theme-light .admin-layout [style*="color: #F8F6F0"] {
 color: var(--text-main) !important;
 }

 body.theme-light .admin-layout [style*="color:#C8A96E"],
 body.theme-light .admin-layout [style*="color: #C8A96E"],
 body.theme-light .admin-layout [style*="color:#E2C98A"],
 body.theme-light .admin-layout [style*="color: #E2C98A"] {
