 }

 body.theme-light .admin-layout [style*="background:#0D1B2A"],
 body.theme-light .admin-layout [style*="background: #0D1B2A"],
 body.theme-light .admin-layout [style*="background:#1A2E45"],
 body.theme-light .admin-layout [style*="background: #1A2E45"],
 body.theme-light .admin-layout [style*="background:#0A1628"],
 body.theme-light .admin-layout [style*="background: #0A1628"] {
 background: var(--surface) !important;
 }

 body.theme-light .admin-layout [style*="background:rgba(255,255,255,0.03)"],
 body.theme-light .admin-layout [style*="background: rgba(255,255,255,0.03)"],
 body.theme-light .admin-layout [style*="background:rgba(255,255,255,0.05)"],
 body.theme-light .admin-layout [style*="background: rgba(255,255,255,0.05)"] {
 background: var(--surface-2) !important;
 }

 body.theme-light .admin-layout [style*="border:1px solid rgba(200,169,110,0.12)"],
 body.theme-light .admin-layout [style*="border: 1px solid rgba(200,169,110,0.12)"],
 body.theme-light .admin-layout [style*="border:1px solid rgba(200,169,110,0.15)"],
 body.theme-light .admin-layout [style*="border: 1px solid rgba(200,169,110,0.15)"] {
