 }

 body.theme-light .admin-layout input,
 body.theme-light .admin-layout select,
 body.theme-light .admin-layout textarea,
 body.theme-light .admin-layout [contenteditable="true"] {
 color: var(--text-main) !important;
 caret-color: var(--text-main);
 }

 body.theme-light .admin-layout input::placeholder,
 body.theme-light .admin-layout textarea::placeholder {
