 caret-color: var(--text-main);
 }
 .admin-modal-overlay {
 position:fixed;
 inset:0;
 display:none;
 align-items:center;
 justify-content:center;
 padding:24px;
 background:rgba(7,18,31,0.56);
 z-index:10000;
 }
 .admin-modal-overlay.show { display:flex; }
 .admin-modal-sheet {
 width:min(900px, 100%);
 max-height:min(88vh, 920px);
 overflow:auto;
 background:var(--surface);
 border:1px solid rgba(200,169,110,0.16);
 border-radius:18px;
 box-shadow:0 24px 80px rgba(9,22,37,0.28);
 padding:22px;
 }
 .admin-modal-head {
 display:flex;
 justify-content:space-between;
 align-items:flex-start;
 gap:16px;
 margin-bottom:18px;
 }
 .admin-modal-title { font-size:20px; color:var(--text-main); font-weight:700; }
 .admin-modal-subtitle { font-size:12px; color:var(--text-sub); line-height:1.7; margin-top:4px; }
 .admin-modal-close {
 width:34px;
 height:34px;
 border-radius:50%;
 border:1px solid #2F74C0;
 background:#163A63;
 color:#FFFFFF;
 font-size:22px;
 cursor:pointer;
 }
 .admin-modal-close:hover { color:#FFFFFF; border-color:#66A1DF; background:#1D4B7C; }
 .admin-modal-grid {
 display:grid;
 gap:16px;
 }
 .admin-modal-card {
 background:var(--surface-2);
 border:1px solid rgba(200,169,110,0.12);
 border-radius:14px;
 padding:16px;
 }
 .admin-modal-card-title { font-size:13px; color:var(--gold); font-weight:600; margin-bottom:10px; }
 .admin-modal-list { display:grid; gap:10px; }
 .admin-modal-item {
 border:1px solid rgba(200,169,110,0.1);
 border-radius:10px;
 padding:12px;
 background:var(--surface);
 }
 .admin-modal-item-top {
 display:flex;
 justify-content:space-between;
 align-items:center;
 gap:12px;
 margin-bottom:6px;
 }
 .admin-modal-copy { font-size:12px; color:var(--text-sub); line-height:1.7; white-space:pre-wrap; }
 .admin-modal-summary {
