async function refreshAdminKnowledgeIntelligence(showMessage = false) {
 adminKnowledgeState.tenantFilter = adminKnowledgeMapState.tenantFilter || '';
 getAdminKnowledgeTenantFilters().forEach((item) => {
 item.value = adminKnowledgeState.tenantFilter;
 });
 await Promise.all([
 loadAdminKnowledgeItems(false),
 loadAdminKnowledgeAssets(false),
 loadAdminKnowledgeMap(false),
 ]);
 if (showMessage) showToast('知识专区已刷新');
}

function renderAdminKnowledgeMapTenantFilter() {
 const select = document.getElementById('admin-kg-tenant-filter');
 if (!select) return '';
 const tenants = Array.isArray((adminSiteConfig && adminSiteConfig.tenants)) ? adminSiteConfig.tenants : [];
 const knownSlugs = new Set(tenants.map((tenant) => String(tenant.slug || '').trim()).filter(Boolean));
 if (adminKnowledgeMapState.tenantFilter && !knownSlugs.has(adminKnowledgeMapState.tenantFilter)) {
 adminKnowledgeMapState.tenantFilter = '';
 }
 select.innerHTML = ['<option value="">平台总图</option>'].concat(
 tenants.map((tenant) => `<option value="${escapeAttr(tenant.slug || '')}">${escapeHtml(tenant.name || tenant.slug || '未命名租户')}</option>`)
 ).join('');
 select.value = adminKnowledgeMapState.tenantFilter || '';
 if (!select.dataset.bound) {
 select.addEventListener('change', () => {
 adminKnowledgeMapState.tenantFilter = select.value || '';
 adminKnowledgeAssetState.tenantFilter = adminKnowledgeMapState.tenantFilter;
 refreshAdminKnowledgeIntelligence(false).catch((error) => showToast(error.message || '加载失败'));
 });
 select.dataset.bound = '1';
 }
 return adminKnowledgeMapState.tenantFilter || '';
}

function adminKnowledgeMapKindLabel(kind) {
 if (kind === 'root') return '平台根节点';
 if (kind === 'tenant') return '租户';
 if (kind === 'topic') return '主题';
 if (kind === 'entity') return '实体';
 if (kind === 'method') return '方法';
 if (kind === 'claim') return '观点';
 if (kind === 'signal') return '验证信号';
 return '知识节点';
}

function adminKnowledgeMapNodeWidth(kind) {
 if (kind === 'root') return 176;
 if (kind === 'tenant') return 156;
 if (kind === 'claim') return 196;
 if (kind === 'signal') return 136;
 return 144;
}

