 ${(Array.isArray(qkv.questions) ? qkv.questions : []).slice(0, 2).map((item) => `<div class="admin-kg-detail-item"><div class="admin-kg-detail-item-title">Q</div><div class="admin-kg-detail-item-meta">${escapeHtml(item)}</div></div>`).join('')}
 ${(Array.isArray(qkv.values) ? qkv.values : []).slice(0, 2).map((item) => `<div class="admin-kg-detail-item"><div class="admin-kg-detail-item-title">V</div><div class="admin-kg-detail-item-meta">${escapeHtml(item)}</div></div>`).join('') || '<div class="admin-kg-detail-item"><div class="admin-kg-detail-item-title">V</div><div class="admin-kg-detail-item-meta">当前节点暂无可展示的知识值。</div></div>'}
 </div>
 </div>
 <div class="admin-kg-detail-section">
 <div class="admin-kg-detail-section-title">来源证据</div>
 <div class="admin-kg-detail-list">
 ${sources.length ? sources.slice(0, 6).map((entry) => `
 <div class="admin-kg-detail-item">
 <div class="admin-kg-detail-item-title">${escapeHtml(entry.title || '知识条目')}</div>
 <div class="admin-kg-detail-item-meta">${escapeHtml(entry.summary || '暂无摘要')}${entry.time ? ` · ${escapeHtml(entry.time)}` : ''}${entry.tenant_name ? ` · ${escapeHtml(entry.tenant_name)}` : ''}</div>
 <div class="modal-actions" style="margin-top:8px;justify-content:flex-start">
 <button class="btn-outline" type="button" onclick="openAdminKnowledgeMapSource('${escapeAttr(entry.id || '')}','${escapeAttr(entry.tenant_slug || '')}')">查看知识详情</button>
