function renderAdminTokenUsage() {
 renderAdminTokenSummary();
 renderAdminTokenTables();
 renderAdminTokenCharts();
}

async function refreshAdminTokenUsage(showMessage = true) {
 const resp = await fetch('/api/admin/token-usage');
 const data = await resp.json();
 if (!resp.ok || !data.ok) throw new Error((data && data.error) || 'token_usage_failed');
 applyAdminTokenUsagePayload(data);
 renderAdminTokenUsage();
 if (showMessage !== false) showToast('Token 监控已刷新');
}

