 <div class="admin-modal-item"><div class="admin-modal-item-top"><strong>摘要</strong><span class="tag tag-blue">${escapeHtml(syncMeta.target || '知识专区')}</span></div><div class="admin-modal-copy">${escapeHtml(item.summary || '暂无摘要')}</div></div>
