function openAdminUserJobDetail(jobCode) {
 const job = (adminTaskCenter.user_jobs || []).find((item) => item.job_code === jobCode);
 const host = document.getElementById('admin-task-modal-content');
 const modal = document.getElementById('admin-task-modal');
 if (!job || !host || !modal) {
 showToast('未找到任务详情');
 return;
 }
 const parseMeta = job.payload && job.payload.parse_meta ? job.payload.parse_meta : null;
 const parsePreview = Array.isArray(parseMeta) ? parseMeta[0] : parseMeta;
 const extractionModes = Array.isArray(parsePreview?.extraction_modes) ? parsePreview.extraction_modes.join(', ') : '--';
 const parseStats = parsePreview && typeof parsePreview.parse_stats === 'object' ? parsePreview.parse_stats : {};
 const pageSummaries = Array.isArray(parsePreview?.page_summaries) ? parsePreview.page_summaries : [];
 const rawSourceText = String((job.payload && (job.payload.body || job.payload.summary || '')) || '').trim();
 host.innerHTML = `
