 <td>${Number(row.users || 0).toLocaleString('zh-CN')}</td>
 <td>${Number(row.new_users_month || 0).toLocaleString('zh-CN')}</td>
 <td>${Number(row.paid_users || 0).toLocaleString('zh-CN')}</td>
 <td>${Number(row.conversion || 0).toFixed(1)}%</td>
 <td style="color:#C8A96E">¥${Number(row.revenue || 0).toLocaleString('zh-CN')}</td>
 <td>¥${Number(row.average_paid_value || 0).toLocaleString('zh-CN')}</td>
 <td>--</td>
 <td>--</td>
 <td><span class="tag ${row.users > 0 ? 'tag-green' : 'tag-blue'}">${escapeHtml(row.status || '无数据')}</span></td>
 </tr>
 `).join('') || '<tr><td colspan="10" style="color:#8899aa">用户表中暂无渠道数据。</td></tr>';
 }
 const utmHost = document.getElementById('admin-channel-utm-tbody');
 if (utmHost) {
 utmHost.innerHTML = rows.map((row) => `
 <tr>
 <td style="color:#F8F6F0;font-weight:600">${escapeHtml(row.name || '--')}</td>
 <td style="font-family:monospace;color:#C8A96E">${escapeHtml(row.name || '--')}</td>
 <td style="font-family:monospace;color:#C8A96E">${Number(row.users || 0) > 0 ? 'user.source_label' : '--'}</td>
 <td style="font-family:monospace;color:#C8A96E">${Number(row.new_users_month || 0).toLocaleString('zh-CN')} 条本月记录</td>
 <td><span class="tag ${row.users > 0 ? 'tag-green' : 'tag-blue'}">${row.users > 0 ? '已入用户表' : '暂无记录'}</span></td>
 </tr>
 `).join('') || '<tr><td colspan="5" style="color:#8899aa">暂无渠道字段记录。</td></tr>';
 }
}

