async function openIndicatorDefinitionModal(indicatorCode) {
 const existing = indicatorCode ? getAdminIndicatorDefinition(indicatorCode) : null;
 const name = prompt('指标名称', existing ? existing.indicator_name : '');
 if (name === null) return;
 const category = prompt('指标分类', existing ? existing.category : '数据湖指标');
 if (category === null) return;
 const sourceType = prompt('来源类型（smart / lake / mock / api）', existing ? existing.source_type : 'mock');
 if (sourceType === null) return;
 const owner = prompt('Owner', existing ? existing.owner : '平台研究运营');
 if (owner === null) return;
 const payload = {
 indicator_code: existing ? existing.indicator_code : '',
 indicator_name: name,
 category,
 description: existing ? existing.description : '',
 unit: existing ? existing.unit : '',
 owner,
 source_type: sourceType,
 source_type_label: sourceType === 'smart' ? '智能指标' : (sourceType === 'lake' ? '数据湖指标' : '指标'),
 provider: existing ? existing.provider : '平台数据层',
 status_hint: existing ? existing.status_hint : 'attention',
 assessment_template: existing ? existing.assessment_template : '',
 alert_template: existing ? existing.alert_template : '',
 watchers: existing ? existing.watchers : [],
 display_config: existing ? existing.display_config : {},
 enabled: existing ? existing.enabled : true
 };
 const resp = await fetch('/api/admin/indicator-definitions', {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify(payload),
 });
 const data = await resp.json();
 if (!resp.ok || !data.ok) {
 showToast((data && data.error) || '保存失败');
 return;
 }
 await refreshAdminIndicatorHub(false);
 showToast('指标定义已保存');
}

