function closeAdminIndicatorHistory() {
 const modal = document.getElementById('admin-indicator-modal');
 if (modal) modal.classList.remove('show');
}

function buildTraceTimelineHtml(trace) {
 const timeline = Array.isArray(trace && trace.timeline) ? trace.timeline : [];
 if (!timeline.length) return '<div class="admin-modal-copy">暂无湖内追溯记录。</div>';
 return timeline.map((entry) => `
 <div class="admin-modal-history-row">
 <div class="admin-modal-history-date">${escapeHtml(entry.time || '--')}</div>
 <div class="admin-modal-history-text">${escapeHtml(entry.type || '--')} · ${escapeHtml(entry.summary || '--')}</div>
 </div>
 `).join('');
}

function buildTraceOpsHtml(trace) {
 const latest = trace && trace.latest ? trace.latest : null;
 const rawRecords = Array.isArray(trace && trace.raw_records) ? trace.raw_records.slice(0, 4) : [];
 const cleanJobs = Array.isArray(trace && trace.clean_jobs) ? trace.clean_jobs.slice(0, 4) : [];
 const series = Array.isArray(trace && trace.series) ? trace.series.slice(0, 4) : [];
 return `
 <div class="admin-modal-section-note">
 <div class="admin-modal-section-title">湖内追溯</div>
 <div class="admin-modal-section-copy">同一个指标的最新值、原始落地、清洗任务和入湖序列统一展示，便于排查展示和数据链路是否一致。</div>
 </div>
 <div class="admin-modal-list" style="margin-top:12px">
 <div class="admin-modal-item">
 <div class="admin-modal-item-top">
 <strong style="color:var(--text-main)">Latest</strong>
 <span class="tag tag-blue">${latest ? escapeHtml(latest.latest_status || '--') : '--'}</span>
 </div>
 <div class="admin-modal-copy">${latest ? `最新值 ${escapeHtml(latest.latest_value || '--')} · 更新时间 ${escapeHtml(latest.updated_at || '--')} · Source ${escapeHtml(latest.source_code || '--')}` : '暂无 latest 记录'}</div>
 </div>
 <div class="admin-modal-item">
 <div class="admin-modal-item-top">
 <strong style="color:var(--text-main)">Raw Landing</strong>
 <span class="tag tag-gold">${rawRecords.length} 条</span>
 </div>
 <div class="admin-modal-copy">${rawRecords.length ? rawRecords.map((item) => `${item.fetched_at || '--'} · ${item.fetch_mode || '--'} · ${item.success ? '成功' : '失败'}`).join(' | ') : '暂无原始落地记录'}</div>
 </div>
 <div class="admin-modal-item">
 <div class="admin-modal-item-top">
 <strong style="color:var(--text-main)">Clean Jobs</strong>
 <span class="tag tag-blue">${cleanJobs.length} 条</span>
 </div>
 <div class="admin-modal-copy">${cleanJobs.length ? cleanJobs.map((item) => `${item.finished_at || item.created_at || '--'} · ${item.job_status || '--'} · ${item.mapping_rule_code || '--'}`).join(' | ') : '暂无清洗任务记录'}</div>
 </div>
 <div class="admin-modal-item">
 <div class="admin-modal-item-top">
 <strong style="color:var(--text-main)">Series</strong>
 <span class="tag tag-gold">${series.length} 点</span>
 </div>
 <div class="admin-modal-copy">${series.length ? series.map((item) => `${item.point_time || '--'} · ${item.point_value || '--'} · ${item.point_status || '--'}`).join(' | ') : '暂无入湖序列点'}</div>
 </div>
 </div>
 <div class="admin-modal-history-list" style="margin-top:12px">
 ${buildTraceTimelineHtml(trace)}
 </div>
 `;
}

async function openAdminIndicatorHistory(indicatorId) {
 const item = typeof indicatorId === 'string' ? getAdminIndicatorItemById(indicatorId) : indicatorId;
 const host = document.getElementById('admin-indicator-modal-content');
 const modal = document.getElementById('admin-indicator-modal');
 if (!item || !host || !modal) {
 showToast('未找到指标详情');
 return;
 }
 const historySeries = Array.isArray(item.history_series) ? item.history_series : [];
 const klinePayload = item.history_kline || {};
 const anomalyPoints = Array.isArray(klinePayload.anomalies) ? klinePayload.anomalies : [];
 const trendSummary = buildIndicatorTrendSummary(historySeries);
 const currentValue = String(item.value || '--');
 const valueClass = /[A-Za-z]/.test(currentValue) || currentValue.length >= 9 ? 'admin-modal-stat-value compact' : 'admin-modal-stat-value';
 let trace = null;
 try {
 const resp = await fetch(`/api/admin/indicator-trace/${encodeURIComponent(item.id)}?limit=10`);
 const data = await resp.json();
 if (resp.ok && data.ok) trace = data.trace || null;
 } catch (error) {
 }
 host.innerHTML = `
 <div class="admin-modal-head">
 <div>
 <div class="admin-modal-title">${escapeHtml(item.name || '')}</div>
 <div class="admin-modal-subtitle">${escapeHtml(item.category || '')} · ${escapeHtml(item.owner || '')} · 最后更新 ${escapeHtml(item.last_updated || '--')}</div>
 </div>
 <button class="admin-modal-close" type="button" onclick="closeAdminIndicatorHistory()">×</button>
 </div>
 <div class="admin-modal-grid">
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">1. 趋势线图</div>
 ${buildIndicatorKlineSvg(klinePayload)}
 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">2. 异动情况（异动点标注）</div>
 <div class="admin-modal-list">
 ${anomalyPoints.length ? anomalyPoints.map((entry) => `
 <div class="admin-modal-item">
 <div class="admin-modal-item-top">
 <strong style="color:var(--text-main)">${escapeHtml(entry.date || '--')}</strong>
 ${adminIndicatorStatusBadge(entry.status)}
 </div>
 <div class="admin-modal-copy">异动点：${escapeHtml(entry.label || '异动')}</div>
 <div class="admin-modal-copy" style="margin-top:6px">指标值：${escapeHtml(entry.value || '--')}</div>
 </div>
 `).join('') : '<div class="admin-modal-copy">当前没有异动点标注。</div>'}
 </div>
 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">3. 数据口径</div>
 <div class="admin-modal-copy">当前详情页只展示纯数据分析视图，不做结果原因分析。可见范围包括趋势线、趋势状态和异动点标注。</div>
 <div class="admin-modal-copy" style="margin-top:8px">当前值代表最新观测结果；历史趋势压缩展示最近时间点，用于快速判断指标方向与波动节奏。</div>
 <div class="admin-chip-row" style="margin-top:12px">
 <span class="admin-chip">状态：${escapeHtml(indicatorStatusLabel(item.status))}</span>
 <span class="admin-chip">监测源：${escapeHtml(item.owner || '--')}</span>
 <span class="admin-chip">数据来源：${escapeHtml(item.data_mode_label || '--')}</span>
 <span class="admin-chip">记录数：${trendSummary.length}</span>
 </div>
 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">4. 趋势情况与历史趋势</div>
 <div class="admin-modal-summary">
 <div class="admin-modal-stat">
 <div>
 <div class="admin-modal-stat-label">当前值</div>
 <div class="${valueClass}">${escapeHtml(currentValue)}</div>
 </div>
 </div>
 <div class="admin-modal-stat">
 <div class="admin-modal-stat-label">当前状态</div>
 <div class="admin-modal-stat-badge">${adminIndicatorStatusBadge(item.status)}</div>
 </div>
 </div>
 <div class="admin-modal-section-note">
 <div class="admin-modal-section-title">历史趋势</div>
 <div class="admin-modal-section-copy">展示最近 ${trendSummary.length} 个观测点，改为细长条以减少占用空间并保留趋势判断。</div>
 </div>
 <div class="admin-modal-history-list">
 ${trendSummary.map((entry) => `
 <div class="admin-modal-history-row">
 <div class="admin-modal-history-date">${escapeHtml(entry.date)}</div>
 <div class="admin-modal-history-text">指标值 ${escapeHtml(entry.value)} · ${escapeHtml(entry.direction)} · 变动 ${entry.delta > 0 ? '+' : ''}${entry.delta}</div>
 ${adminIndicatorStatusBadge(entry.status)}
 </div>
 `).join('') || '<div class="admin-modal-copy">暂无趋势记录</div>'}
 </div>
 ${trace ? buildTraceOpsHtml(trace) : '<div class="admin-modal-copy" style="margin-top:12px">湖内追溯数据加载失败或暂无记录。</div>'}
 </div>
 </div>
 `;
 modal.classList.add('show');
}

let adminUsers = [];
