function requestAdminUserStatusChange(userId) {
 const user = adminUsers.find((item) => Number(item.id || 0) === Number(userId || 0));
 const confirmNode = document.getElementById('admin-user-status-confirm');
 if (!user || !confirmNode) return;
 const nextStatus = user.status === 'active' ? 'disabled' : 'active';
 const action = nextStatus === 'disabled' ? '停用' : '启用';
 confirmNode.innerHTML = `<div style="font-size:12px;font-weight:700;color:#F8F6F0">确认${action}“${escapeHtml(user.username || '该账号')}”吗？</div><div style="font-size:11px;color:#8899aa;line-height:1.7;margin-top:5px">${nextStatus === 'disabled' ? '停用后该账号将无法登录 H5、Hermes 或大V工作台，历史数据会保留。' : '启用后该账号可以重新登录，历史数据会保留。'}</div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:10px"><button class="btn-outline" type="button" style="padding:6px 10px;font-size:11px" onclick="cancelAdminUserStatusChange()">取消</button><button class="btn-gold" type="button" style="padding:6px 10px;font-size:11px" onclick="confirmAdminUserStatusChange(${Number(user.id || 0)}, '${nextStatus}')">确认${action}</button></div>`;
 confirmNode.style.display = 'block';
}

function cancelAdminUserStatusChange() {
 const confirmNode = document.getElementById('admin-user-status-confirm');
 if (confirmNode) {
 confirmNode.innerHTML = '';
 confirmNode.style.display = 'none';
 }
}

async function confirmAdminUserStatusChange(userId, status) {
 const confirmNode = document.getElementById('admin-user-status-confirm');
 const buttons = confirmNode ? confirmNode.querySelectorAll('button') : [];
 buttons.forEach((button) => { button.disabled = true; button.style.opacity = '0.6'; });
 try {
 const response = await fetch('/api/admin/users/status', {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify({ user_id: userId, status }),
 });
 const payload = await response.json();
 if (!response.ok || !payload.ok) {
 const messages = {
 cannot_disable_current_user: '不能停用当前登录的管理员账号。',
 cannot_disable_last_admin: '平台至少需要保留一个正常的管理员账号。',
 user_not_found: '未找到该用户。',
 database_unavailable: '数据库当前不可用，请稍后重试。',
 };
 throw new Error(messages[payload.error] || payload.error || '账号状态更新失败');
 }
 adminUsers = Array.isArray(payload.users) ? payload.users : adminUsers;
 renderAdminUsersTable();
 openAdminUserDetail(userId);
 showToast(status === 'disabled' ? '账号已停用' : '账号已启用');
 } catch (error) {
 if (confirmNode) confirmNode.innerHTML = `<div style="font-size:12px;color:#F2B8B5">${escapeHtml(error.message || '账号状态更新失败')}</div>`;
 showToast(error.message || '账号状态更新失败');
 }
}

