 try {
 const res = await fetch('/api/admin/users');
 const data = await res.json();
 adminUsers = Array.isArray(data.users) ? data.users : [];
 renderAdminUsersTable();
 } catch (error) {
 showToast('加载用户列表失败');
 }
}

