function buildAdminUserImportRow(row = {}) {
 const configuredRoles = Object.keys((adminSiteConfig && adminSiteConfig.role_capabilities) || {
 investor: ['h5', 'investor'],
 dav: ['h5', 'dav', 'hermes', 'workbench'],
 admin: ['admin', 'h5', 'dav', 'hermes', 'workbench'],
 });
 const roleOptions = configuredRoles.map((role) => `<option value="${escapeAttr(role)}" ${String(row.role || 'investor') === role ? 'selected' : ''}>${escapeHtml(role)}</option>`).join('');
 return `
 <tr>
 <td><input data-field="username" type="text" value="${escapeAttr(row.username || '')}" placeholder="用户名"></td>
 <td><input data-field="password" type="text" value="${escapeAttr(row.password || '')}" placeholder="密码"></td>
 <td><input data-field="phone" type="text" value="${escapeAttr(row.phone || '')}" placeholder="手机号"></td>
 <td>
 <select data-field="role">
 ${roleOptions}
 </select>
 </td>
 <td><input data-field="tenant_slug" type="text" value="${escapeAttr(row.tenant_slug || adminSiteConfig.default_tenant_slug || '')}" placeholder="租户 slug"></td>
 <td><input data-field="advisor_name" type="text" value="${escapeAttr(row.advisor_name || '')}" placeholder="所属大V"></td>
 <td>
 <select data-field="status">
 <option value="active" ${String(row.status || 'active') === 'active' ? 'selected' : ''}>正常</option>
 <option value="disabled" ${String(row.status || '') === 'disabled' ? 'selected' : ''}>禁用</option>
 </select>
 </td>
 <td>
 <select data-field="is_paid_sample">
 <option value="0" ${String(row.is_paid_sample || '0') === '1' ? '' : 'selected'}>否</option>
 <option value="1" ${String(row.is_paid_sample || '0') === '1' ? 'selected' : ''}>是</option>
 </select>
 </td>
 <td><input data-field="source_label" type="text" value="${escapeAttr(row.source_label || '管理录入')}" placeholder="来源"></td>
 <td><input data-field="paid_sample_note" type="text" value="${escapeAttr(row.paid_sample_note || '')}" placeholder="备注"></td>
 <td><button class="btn-outline" type="button" style="padding:4px 10px;font-size:11px" onclick="removeAdminUserImportRow(this)">删除</button></td>
 </tr>
 `;
}

function removeAdminUserImportRow(button) {
 const row = button ? button.closest('tr') : null;
 if (row) row.remove();
}

function addAdminUserImportRow(row) {
 const body = document.getElementById('admin-user-import-tbody');
 if (!body) return;
 body.insertAdjacentHTML('beforeend', buildAdminUserImportRow(row || {}));
}

function collectAdminUserImportRows() {
 return Array.from(document.querySelectorAll('#admin-user-import-tbody tr')).map((row) => {
 const payload = {};
 ADMIN_USER_IMPORT_COLUMNS.forEach((field) => {
 const node = row.querySelector(`[data-field="${field}"]`);
 payload[field] = node ? String(node.value || '').trim() : '';
 });
 return payload;
 }).filter((item) => item.username || item.phone);
}

