 </div>
 <div class="admin-modal-card">
 <div class="admin-modal-card-title">录入表格</div>
 <div class="feature-note" style="margin-bottom:10px">角色含义：investor = 粉丝用户，dav = 大V，admin = 管理员。</div>
 <div style="overflow:auto">
 <table>
 <thead><tr><th>用户名</th><th>密码</th><th>手机号</th><th>角色</th><th>租户 slug</th><th>所属大V</th><th>状态</th><th>付费样本</th><th>来源</th><th>备注</th><th>操作</th></tr></thead>
