 <button class="btn-gold" type="button" style="padding:8px 14px;font-size:12px" onclick="submitAdminUserImportRows()">${isSingle ? '保存用户' : '批量创建用户'}</button>
 </div>
 </div>
 `;
 modal.classList.add('show');
 addAdminUserImportRow(isSingle ? {role: 'investor', status: 'active', is_paid_sample: '0', source_label: '管理录入'} : {role: 'investor', status: 'active', is_paid_sample: '0', source_label: '管理录入'});
 if (!isSingle) addAdminUserImportRow({role: 'investor', status: 'active', is_paid_sample: '0', source_label: '管理录入'});
}

async function submitAdminUserImportRows() {
 const users = collectAdminUserImportRows();
 if (!users.length) {
 showToast('请至少填写一行用户');
 return;
 }
 try {
 const res = await fetch('/api/admin/users/import', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({users}),
 });
 const data = await res.json();
 if (!res.ok || data.ok === false) throw new Error(data.error || 'import_users_failed');
 adminUsers = Array.isArray(data.users) ? data.users : adminUsers;
 renderAdminUsersTable();
 closeAdminUserImportModal();
 const skipped = Array.isArray(data.skipped) ? data.skipped.length : 0;
 showToast(`已创建 ${Array.isArray(data.created) ? data.created.length : 0} 个用户${skipped ? `，跳过 ${skipped} 条` : ''}`);
 } catch (error) {
 showToast(error.message || '用户导入失败');
 }
}

