 const nodeResults = workflow.execution?.node_results || workflow.preview?.node_results || graph.node_results || {};
 const nodeDebug = selectedNode ? nodeResults[selectedNode.id] : null;
 const preview = workflow.preview && typeof workflow.preview === 'object' ? workflow.preview : {};
 const scenarioDefinitions = [
 {id: 'stock_today_capability', number: '1', title: '个股咨询分析', route: '今日行情、逻辑、要闻、风险 · Gangtise Agent SSE'},
