async function loadAdminAgentWorkflows(forceReload) {
 if (agentWorkflowLoaded && !forceReload) {
 renderAgentWorkflowCenter();
 return;
 }
 const response = await fetch('/api/admin/agent-workflows');
 const data = await response.json();
 if (!response.ok || data.ok === false) throw new Error(data.error || 'agent_workflows_failed');
 agentWorkflowCenter = data.center || {summary: {}, workflows: []};
 selectedAgentWorkflowId = selectedAgentWorkflowId || (((agentWorkflowCenter.workflows || [])[0] || {}).id || '');
 selectedAgentWorkflowNodeId = '';
 agentWorkflowLoaded = true;
 renderAgentWorkflowCenter();
}

