async function loadAdminHermesUsageStats() {
 if (adminHermesUsageState.loading) return;
 const tenantSlug = getAdminHermesMemorySelectedTenant();
 adminHermesUsageState.loading = true;
 try {
 const resp = await fetch(`/api/admin/hermes/usage-stats?tenant_slug=${encodeURIComponent(tenantSlug || '')}`);
 const data = await resp.json();
 if (!resp.ok || !data.ok) throw new Error((data && data.error) || 'hermes_usage_stats_failed');
 adminHermesUsageState.stats = data.stats || null;
 renderAdminHermesUsageStats();
 } catch (error) {
 console.error(error);
 } finally {
 adminHermesUsageState.loading = false;
 }
}

