function pickAdminThemeMode(mode) {
 adminSiteConfig.default_theme = mode;
 renderSiteConfigForm();
 setGangtiseTheme(mode);
}

function pickAdminAccent(accent) {
 adminSiteConfig.default_accent = accent;
 renderSiteConfigForm();
 setGangtiseAccent(accent);
}

async function loadSiteConfig(force = false) {
 if (adminSiteConfigLoaded && !force) {
 renderSiteConfigForm();
 renderAdminKnowledgeTenantFilter();
 return adminSiteConfig;
 }
 try {
 const res = await fetch('/api/admin/site-config');
 if (res.ok) {
 adminSiteConfig = await res.json();
 adminSiteConfigLoaded = true;
 } else {
 throw new Error(`site_config_load_failed_${res.status}`);
 }
 } catch (error) {
 renderSiteConfigForm();
 throw error;
 }
 renderSiteConfigForm();
 renderAdminKnowledgeTenantFilter();
 return adminSiteConfig;
}

let adminGangtiseCredentialStatus = null;

function renderGangtiseCredentialStatus() {
 const statusEl = document.getElementById('gangtise-credential-status');
 if (!statusEl) return;
 const status = adminGangtiseCredentialStatus;
 if (!status) {
 statusEl.textContent = '正在读取当前数据库中的凭证状态...';
 return;
 }
 const modeLabel = ({ access_key_secret: 'Access Key + Secret Key', long_token: 'Long Token', missing: '未配置', unreadable: '旧密文无法解密', database_unavailable: '数据库不可用' })[status.credential_mode] || '未配置';
 const storageLabel = status.token_storage === 'plaintext_postgres' ? 'Gangtise 凭证已明文保存到当前 PostgreSQL' : (status.stored_in_postgres ? 'Gangtise 凭证已保存到当前 PostgreSQL' : '当前 PostgreSQL 未保存凭证');
 const mismatchNote = status.encryption_status === 'unreadable' ? '当前仍是旧版密文记录，请重新填写并保存凭证。' : '';
 statusEl.textContent = `${storageLabel}。认证方式：${modeLabel}。Access Key：${status.has_access_key ? '已配置' : '未配置'}；Secret Key：${status.has_secret_key ? '已配置' : '未配置'}；Long Token：${status.has_long_token ? '已配置' : '未配置'}。${mismatchNote}${status.updated_at ? `最后更新：${status.updated_at}。` : ''}`;
 const baseUrl = document.getElementById('gangtise-credential-base-url');
 if (baseUrl && !baseUrl.value) baseUrl.value = status.base_url || 'https://openapi.gangtise.com';
 [['gangtise-credential-access-key', status.has_access_key], ['gangtise-credential-secret-key', status.has_secret_key], ['gangtise-credential-long-token', status.has_long_token]].forEach(([id, configured]) => {
 const input = document.getElementById(id);
 if (input) input.placeholder = configured ? '已配置，留空不修改' : '未配置；填写后保存';
 });
}

async function loadGangtiseCredentials() {
 const statusEl = document.getElementById('gangtise-credential-status');
 if (statusEl) statusEl.textContent = '正在读取当前数据库中的凭证状态...';
 try {
 const res = await fetch('/api/admin/gangtise-credentials');
 const data = await res.json();
 if (!res.ok || !data.ok) throw new Error((data && data.error) || 'credentials_load_failed');
 adminGangtiseCredentialStatus = data.credentials || {};
 renderGangtiseCredentialStatus();
 } catch (error) {
 if (statusEl) statusEl.textContent = '凭证状态读取失败，请检查 Admin 登录和当前数据库连接。';
 }
}

async function saveGangtiseCredentials() {
 const button = document.getElementById('gangtise-credential-save');
 const diagnosticEl = document.getElementById('gangtise-credential-diagnostic');
 const payload = {
 base_url: String(document.getElementById('gangtise-credential-base-url')?.value || '').trim(),
 access_key: String(document.getElementById('gangtise-credential-access-key')?.value || '').trim(),
 secret_key: String(document.getElementById('gangtise-credential-secret-key')?.value || '').trim(),
 long_token: String(document.getElementById('gangtise-credential-long-token')?.value || '').trim(),
 };
 if (button) {
 button.disabled = true;
 button.textContent = '正在保存...';
 }
 try {
 const res = await fetch('/api/admin/gangtise-credentials', {
 method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload),
 });
 const data = await res.json();
 if (!res.ok || !data.ok) throw new Error((data && data.error) || 'credentials_save_failed');
 adminGangtiseCredentialStatus = data.credentials || {};
 ['gangtise-credential-access-key', 'gangtise-credential-secret-key', 'gangtise-credential-long-token'].forEach((id) => {
 const input = document.getElementById(id);
 if (input) input.value = '';
 });
 renderGangtiseCredentialStatus();
 if (diagnosticEl) diagnosticEl.textContent = '凭证已明文保存到当前 PostgreSQL，已解除环境应用密钥依赖。可继续执行真实日 K 校验。';
 showToast('Gangtise 凭证已保存');
 } catch (error) {
 const message = String(error && error.message || 'credentials_save_failed');
 if (diagnosticEl) diagnosticEl.textContent = `保存失败：${message}`;
 showToast('凭证保存失败');
 } finally {
 if (button) {
 button.disabled = false;
 button.textContent = '保存凭证';
 }
 }
}

async function diagnoseGangtiseCredentials() {
 const button = document.getElementById('gangtise-credential-diagnose');
 const diagnosticEl = document.getElementById('gangtise-credential-diagnostic');
 const securityCode = String(document.getElementById('gangtise-credential-probe-code')?.value || '601988.SH').trim().toUpperCase();
 if (button) {
 button.disabled = true;
 button.textContent = '正在请求真实日 K...';
 }
 if (diagnosticEl) diagnosticEl.textContent = `正在用 ${securityCode} 请求 Gangtise 真实日 K 数据...`;
 try {
 const res = await fetch('/api/admin/gangtise-credentials/diagnose', {
 method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ security_code: securityCode }),
 });
 const data = await res.json();
 if (!res.ok || !data.ok) throw new Error((data && data.error) || 'credentials_diagnostic_failed');
 const diagnostic = data.diagnostic || {};
 const probe = diagnostic.probe || {};
 if (diagnosticEl) diagnosticEl.textContent = `${diagnostic.ok ? '校验成功' : '校验未通过'}：${diagnostic.message || '--'} HTTP ${probe.http_status || 0}，耗时 ${probe.duration_ms || 0} ms，数据点 ${probe.points || 0}，最新交易日 ${probe.latest_trade_date || '--'}。${probe.upstream_message ? `上游信息：${probe.upstream_message}` : ''}`;
 if (diagnostic.ok) showToast('Gangtise 真实日 K 校验成功');
 } catch (error) {
 if (diagnosticEl) diagnosticEl.textContent = `校验失败：${String(error && error.message || 'credentials_diagnostic_failed')}`;
 showToast('Gangtise 校验失败');
 } finally {
 if (button) {
 button.disabled = false;
 button.textContent = '保存后校验真实日 K';
 }
 }
}

async function syncLocalLlmRegistryFromStaging() {
 const status = document.getElementById('site-config-status');
 if (status) {
 status.textContent = '正在把 staging 的 LLM 配置同步到本地开发库...';
 }
 try {
 const res = await fetch('/api/admin/site-config/sync-llm-registry', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({}),
 });
 const data = await res.json();
 if (!res.ok || !data.success) throw new Error((data && data.error) || 'sync_failed');
 adminSiteConfig = data.site_config;
 window.SITE_CONFIG = data.site_config;
 renderSiteConfigForm();
 broadcastSiteConfigUpdate();
 const localTarget = data.local_db_target || {};
 const localLabel = localTarget.host
 ? `${localTarget.host}:${localTarget.port || 5432}/${localTarget.dbname || ''}`
 : '本地开发库';
 const modelCount = Number(data.synced_model_count || 0);
 markAdminSiteConfigSaved(`已把 staging 的 LLM 配置同步到本地。目标库：${localLabel}。同步模型数：${modelCount}。`);
 showToast('LLM 配置已同步到本地');
 } catch (e) {
 if (status) {
 status.textContent = '同步失败，请检查 staging 连接和本地数据库配置后重试。';
 }
 showToast('同步失败');
 }
}

async function saveHermesSettings() {
 const button = document.getElementById('save-hermes-settings');
 const currentHermesSettings = (adminSiteConfig && adminSiteConfig.hermes_settings) || {};
 let hermesIntentTree = [];
 let hermesRoutePriority = [];
 let hermesTemplateTree = {};
 let hermesChartTypesEnabled = [];
 let hermesInterceptionSkills = [];
 try {
 hermesIntentTree = parseAdminConfigJsonField('hermes-intent-tree', currentHermesSettings.intent_tree || []);
 hermesRoutePriority = parseAdminConfigListField('hermes-route-priority', currentHermesSettings.route_priority || []);
 hermesTemplateTree = parseAdminConfigJsonField('hermes-template-tree', currentHermesSettings.template_tree || {});
 hermesChartTypesEnabled = parseAdminConfigListField('hermes-chart-types-enabled', currentHermesSettings.chart_types_enabled || []);
 hermesInterceptionSkills = parseAdminConfigJsonField('hermes-interception-skills', currentHermesSettings.interception_skills || []);
 if (!Array.isArray(hermesInterceptionSkills)) throw new Error('hermes-interception-skills 必须是 JSON 数组。');
 } catch (error) {
 markAdminSiteConfigDirty((error && error.message) || 'Hermes 配置格式校验失败，请检查后再保存。');
 showToast('Hermes 配置格式有误');
 return;
 }
 if (button) {
 button.disabled = true;
 button.textContent = '保存中...';
 }
 try {
 const res = await fetch('/api/admin/site-config', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({
 hermes_settings: {
 ...currentHermesSettings,
 interception_skills_enabled: Boolean(document.getElementById('hermes-interception-skills-enabled') && document.getElementById('hermes-interception-skills-enabled').checked),
 interception_skills: hermesInterceptionSkills,
 dav_access_enabled: Boolean(document.getElementById('hermes-dav-access-enabled') && document.getElementById('hermes-dav-access-enabled').checked),
 investor_access_enabled: Boolean(document.getElementById('hermes-investor-access-enabled') && document.getElementById('hermes-investor-access-enabled').checked),
 thinking_process_enabled: Boolean(document.getElementById('hermes-thinking-process-enabled') && document.getElementById('hermes-thinking-process-enabled').checked),
 default_response_style: document.getElementById('hermes-default-response-style')
 ? String(document.getElementById('hermes-default-response-style').value || 'structured').trim() || 'structured'
 : (currentHermesSettings.default_response_style || 'structured'),
 chart_types_enabled: hermesChartTypesEnabled,
 route_priority: hermesRoutePriority,
 intent_tree: hermesIntentTree,
 template_tree: hermesTemplateTree,
 },
 }),
 });
 const data = await res.json();
 if (!res.ok || !data.success) throw new Error((data && data.error) || 'save_failed');
 adminSiteConfig = data.site_config;
 window.SITE_CONFIG = data.site_config;
 renderSiteConfigForm();
 broadcastSiteConfigUpdate();
 markAdminSiteConfigSaved('Hermes 全部能力配置已保存，新的请求会立即按最新配置生效。');
 showToast('Hermes 配置已保存');
 } catch (error) {
 markAdminSiteConfigDirty('Hermes 配置保存失败，请重试。');
 showToast('保存失败');
 } finally {
 if (button) {
 button.disabled = false;
 button.textContent = '保存并生效';
 }
 }
}

