let _currentEv = null;
function evShowDetail(id) {
 _currentEv = id;
 const d = EV_DATA[id]; if (!d) return;
 document.getElementById('ev-list').style.display = 'none';
 document.getElementById('ev-form').style.display = 'none';
 document.getElementById('ev-detail').style.display = 'block';
 document.getElementById('ev-detail-title').textContent = d.title;
 const sb = document.getElementById('ev-detail-status-badge');
 const sc = {进行中:'#2ECC71',报名中:'#C8A96E',已结束:'#9A9590',待发布:'#3498DB'};
 sb.innerHTML = `<span style="background:${sc[d.status]||'#9A9590'}22;color:${sc[d.status]||'#9A9590'};border:1px solid ${sc[d.status]||'#9A9590'}44;padding:3px 10px;border-radius:4px;font-size:12px">${d.status}</span>`;
 ['type','host','date','cap','pts','compute'].forEach(k => {
 const el = document.getElementById('ev-d-'+k); if(el) el.textContent = d[k]||'—';
 });
 document.getElementById('ev-d-joined').textContent = d.joined;
 document.getElementById('ev-d-checkin').textContent = d.checkin;
 document.getElementById('ev-d-pts-given').textContent = d.ptsGiven;
 document.getElementById('ev-d-share').textContent = d.share;
 document.getElementById('ev-d-desc').textContent = d.desc;
 document.getElementById('ev-d-agenda').innerHTML = d.agenda.split('\n').map(l=>`<div>#x1F4CD ${l}</div>`).join('');
 document.getElementById('page-title').textContent = '活动详情：' + d.title;
}
function evShowEdit(id) {
 if (id === 'current') id = _currentEv;
 _currentEv = id;
 document.getElementById('ev-list').style.display = 'none';
 document.getElementById('ev-detail').style.display = 'none';
 document.getElementById('ev-form').style.display = 'block';
 document.getElementById('ev-form-title').textContent = id ? '编辑活动' : '创建活动';
 document.getElementById('page-title').textContent = id ? '编辑活动' : '创建活动';
}
function evShowCreate() { evShowEdit(null); }
function evBack() {
 document.getElementById('ev-detail').style.display = 'none';
 document.getElementById('ev-form').style.display = 'none';
 document.getElementById('ev-list').style.display = 'block';
 document.getElementById('page-title').textContent = '活动管理';
 _currentEv = null;
}
