 window.GangtiseReleaseNotes?.init({ surface: 'admin', autoShow: true });
 initAdminNavGroups();
 mountUnifiedSystemSettings();
 renderAdminTaskCenter();
 renderAdminTokenUsage();
 document.addEventListener('input', (event) => {
 if (isAdminSiteConfigField(event.target)) {
 markAdminSiteConfigDirty();
 }
 });
 document.addEventListener('change', (event) => {
 if (isAdminSiteConfigField(event.target)) {
 updateAdminFeatureFlagPreview(event.target);
 markAdminSiteConfigDirty();
 }
 });
 const adminUserCsvInput = document.getElementById('admin-user-csv-input');
 if (adminUserCsvInput && !adminUserCsvInput.dataset.bound) {
 adminUserCsvInput.addEventListener('change', async (event) => {
 const file = event.target.files && event.target.files[0];
 await handleAdminUserCsvImport(file);
 event.target.value = '';
 });
 adminUserCsvInput.dataset.bound = '1';
 }
 renderAdminIndicatorHubAll();
 const section = new URLSearchParams(window.location.search).get('section');
 if (section && analyticsTitles[section]) {
 if (section === 'segment' && !isAdminFeatureEnabled('vip')) {
 showSection('overview');
 return;
 }
 if (!isAdminFeatureEnabled('analytics_module')) {
 showSection('overview');
 return;
 }
 showAnalyticsSection(section);
 return;
 }
 const normalizedSection = normalizeAdminSection(section || '');
 if (normalizedSection.section && sectionTitles[normalizedSection.section]) {
 showSection(section);
 if (normalizedSection.section === 'hermes') {
 const hermesTab = new URLSearchParams(window.location.search).get('hermes_tab') || 'overview';
 showHermesSubsection(hermesTab);
 }
 return;
 }
 initForecastEditorEvents();
});

